insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Esta lección practica Spell your name mediante ejemplos, comprensión y producción guiada.","communication_goal":"El estudiante puede decir su nombre, pedir cómo se deletrea y confirmar una letra.","language_focus":["What''s your name?","My name is...","How do you spell it?","It''s A-N-A.","Could you repeat that, please?","Is that B or V?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"What''s your name?","meaning_es":"nombre"},{"english":"How do you spell it?","meaning_es":"deletrear"},{"english":"The first letter is B.","meaning_es":"letra"},{"english":"What''s the first letter?","meaning_es":"primero / primera"},{"english":"What''s the last letter?","meaning_es":"último / última"},{"english":"Could you repeat that, please?","meaning_es":"repetir"},{"english":"Yes, that''s correct.","meaning_es":"correcto"}],"dialogue":[{"speaker":"Cashier","text":"What''s your name?"},{"speaker":"Customer","text":"My name is Ana."},{"speaker":"Cashier","text":"How do you spell it?"},{"speaker":"Customer","text":"A-N-A."},{"speaker":"Cashier","text":"Ana, right?"},{"speaker":"Customer","text":"Yes, that''s correct."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir los nombres de B y V y producir la frase ''How do you spell it?'' con ritmo comprensible.","models":[{"text":"B","ipa":"/biː/","contrast":"bee"},{"text":"V","ipa":"/viː/","contrast":"vee"},{"text":"How do you spell it?","stress":["How","spell"]}],"student_feedback":"Evalúa inteligibilidad, diferencia B/V y ritmo de la pregunta. No penalices el acento extranjero si el mensaje se entiende."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Cashier","text":"What''s your name?"},{"speaker":"Customer","text":"My name is Ana."},{"speaker":"Cashier","text":"How do you spell it?"},{"speaker":"Customer","text":"A-N-A."},{"speaker":"Cashier","text":"Ana, right?"},{"speaker":"Customer","text":"Yes, that''s correct."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A name for the order","text":"Ana is at a coffee shop. She orders a latte. The cashier asks for her name. Ana says, ''My name is Ana.'' The cashier asks, ''How do you spell it?'' Ana says, ''A-N-A.''","interactive_vocabulary":["coffee shop","orders","cashier","her name"],"questions":[{"prompt":"What does Ana order?","answer":"A latte","accepted_answers":["A latte","She orders a latte","Latte"]},{"prompt":"Why does Ana say A-N-A?","answer":"She spells her name","accepted_answers":["She spells her name","To spell her name","She is spelling her name"]}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Registrarse en una cafetería y aclarar el nombre para el pedido.","communication_goal":"El estudiante puede decir su nombre, pedir cómo se deletrea y confirmar una letra.","activities":[{"id":"A1-M1-T01-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es el cajero y te pedirá tu nombre. Dilo, deletréalo y aclara una letra si es necesario.","role":"cashier","student_goal":"Give a name, spell it, and clarify one letter if needed.","allowed_support":["Spanish hint","sentence starter","repeat question"],"success_criteria":["gives a name","spells a name","asks for repetition or confirms a letter"],"feedback_correct":"Completaste la interacción y lograste el objetivo comunicativo.","feedback_incorrect":"Usa: My name is... / How do you spell it? / Could you repeat that, please?","estimated_seconds":180,"prompt":"Responde al cajero: di tu nombre, deletréalo y aclara una letra si es necesario.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T01-L01"},{"id":"A1-M1-T01-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Nueva situación: una persona no entiende tu apellido. Deletrea y confirma la última letra.","prompt":"My last name is ____. It''s spelled ____. The last letter is ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses last name","spells letters in order","identifies last letter"],"feedback_correct":"Transferiste el aprendizaje a una situación nueva.","feedback_incorrect":"Escribe primero tu apellido y después di cada letra por separado.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T01-L01"}]}'::jsonb,6);
