insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Esta lección practica Find the missing letter mediante ejemplos, comprensión y producción guiada.","communication_goal":"El estudiante puede identificar letras en nombres y pedir aclaración cuando no las entiende.","language_focus":["What''s the first letter?","What''s the last letter?","Is that B or V?","Could you say that again?","I didn''t catch the last letter."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"What''s the first letter?","meaning_es":"primera letra"},{"english":"I didn''t catch the last letter.","meaning_es":"última letra"},{"english":"Could you say that again?","meaning_es":"otra vez"},{"english":"I didn''t catch that.","meaning_es":"entender / captar"},{"english":"What''s your email address?","meaning_es":"dirección"},{"english":"Find the missing letter.","meaning_es":"que falta"}],"dialogue":[{"speaker":"Receptionist","text":"What''s your email address?"},{"speaker":"Guest","text":"It''s luis.vera@example.com."},{"speaker":"Receptionist","text":"Is that B or V in Vera?"},{"speaker":"Guest","text":"V. V as in very."},{"speaker":"Receptionist","text":"And what''s the last letter?"},{"speaker":"Guest","text":"N. That''s N, not M."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir aclaraciones cortas con pausas y distinguir B, V, M y N.","models":[{"text":"B","ipa":"/biː/"},{"text":"V","ipa":"/viː/"},{"text":"M","ipa":"/em/"},{"text":"N","ipa":"/en/"},{"text":"I didn''t catch the last letter.","stress":["catch","last","letter"]}],"student_feedback":"Prioriza que el interlocutor pueda identificar la letra. Después trabaja el ritmo y la entonación."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Receptionist","text":"What''s your email address?"},{"speaker":"Guest","text":"It''s luis.vera@example.com."},{"speaker":"Receptionist","text":"Is that B or V in Vera?"},{"speaker":"Guest","text":"V. V as in very."},{"speaker":"Receptionist","text":"And what''s the last letter?"},{"speaker":"Guest","text":"N. That''s N, not M."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The registration form","text":"Luis is checking in at a hotel. The receptionist writes his email address. Luis says, ''luis.vera@example.com.'' The receptionist is not sure about the first letter of Vera. Luis repeats it and gives an example: ''V as in very.'' The receptionist checks the address again.","interactive_vocabulary":["checking in","receptionist","sure","repeats","example"],"questions":[{"prompt":"Where is Luis?","options":["At a hotel","At a school","At a restaurant"],"answer":"At a hotel","accepted_answers":["At a hotel","He is at a hotel","A hotel"]},{"prompt":"Why does Luis repeat the letter?","options":["The receptionist is not sure","He wants a drink","He is leaving"],"answer":"The receptionist is not sure","accepted_answers":["The receptionist is not sure","Because the receptionist is not sure","To clarify the letter"]}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Ayudar a un recepcionista a registrar correctamente un nombre y un correo electrónico.","communication_goal":"El estudiante puede identificar letras en nombres y pedir aclaración cuando no las entiende.","activities":[{"id":"A1-M1-T01-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA registra tu correo. En un momento, no entiende una letra y tú debes aclararla.","role":"receptionist","student_goal":"Say an email address, clarify B/V or M/N, and confirm the final version.","allowed_support":["slow mode","Spanish hint","example phrase"],"success_criteria":["spells an address","uses one clarification phrase","confirms the corrected letter"],"feedback_correct":"Resolviste la confusión sin abandonar la conversación.","feedback_incorrect":"Prueba: I didn''t catch the last letter. / Is that B or V? / That''s correct.","estimated_seconds":180,"prompt":"La IA registra tu correo. En un momento, no entiende una letra y tú debes aclararla.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T01-L02"},{"id":"A1-M1-T01-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Escribe o graba una aclaración para una reserva. La otra persona confundió M y N.","prompt":"The last letter is N, not M. N as in November.","response_type":"open_speech_or_text","evaluation_criteria":["identifies the correct letter","contrasts it with the wrong letter","speaks clearly"],"feedback_correct":"Usaste el idioma para reparar una confusión real.","feedback_incorrect":"Di primero la letra correcta, luego la incorrecta y finalmente un ejemplo.","estimated_seconds":100,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T01-L02"}]}'::jsonb,6);
