insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Esta lección practica Names, cities and email addresses mediante ejemplos, comprensión y producción guiada.","communication_goal":"El estudiante puede deletrear información personal y comprobar que otra persona la registró correctamente.","language_focus":["How do you spell your first name?","How do you spell your last name?","Is that right?","Yes, that''s right.","No, the first letter is...","Let me spell it again."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"My first name is Ana.","meaning_es":"nombre de pila"},{"english":"My last name is García.","meaning_es":"apellido"},{"english":"I live in a small city.","meaning_es":"ciudad"},{"english":"What country are you from?","meaning_es":"país"},{"english":"Please complete this form.","meaning_es":"formulario"},{"english":"Yes, that''s right.","meaning_es":"correcto"},{"english":"Let me spell it again.","meaning_es":"otra vez"}],"dialogue":[{"speaker":"Agent","text":"What''s your first name?"},{"speaker":"Customer","text":"Elena."},{"speaker":"Agent","text":"How do you spell it?"},{"speaker":"Customer","text":"E-L-E-N-A."},{"speaker":"Agent","text":"And your last name?"},{"speaker":"Customer","text":"García. G-A-R-C-I-A."},{"speaker":"Agent","text":"G-A-R-C-I-A. Is that right?"},{"speaker":"Customer","text":"Yes, that''s right."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Deletrear grupos de letras con ritmo constante y confirmar información con entonación natural.","models":[{"text":"E-L-E-N-A","note":"separa las letras con pausas breves"},{"text":"Is that right?","stress":["right"],"intonation":"rising"},{"text":"Yes, that''s right.","stress":["right"],"intonation":"falling"}],"student_feedback":"Evalúa claridad de cada letra, pausas breves y diferencia entre pregunta y confirmación."}'::jsonb,3);
