insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A travel form","text":"Elena is buying a train ticket. The agent asks for her first name, last name, city and email address. Elena spells each piece of information. The agent reads the information back to her. Elena listens and confirms that everything is right.","interactive_vocabulary":["buying","train ticket","piece of information","reads back","everything"],"questions":[{"prompt":"What is Elena buying?","options":["A train ticket","A hotel room","A coffee"],"answer":"A train ticket","accepted_answers":["A train ticket","She is buying a train ticket","Train ticket"]},{"prompt":"What does the agent do after writing the information?","options":["Reads it back","Deletes it","Changes the city"],"answer":"Reads it back","accepted_answers":["Reads it back","The agent reads it back","Reads the information back"]}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Completar un formulario de viaje cuando el nombre de una persona o ciudad necesita confirmación.","communication_goal":"El estudiante puede deletrear información personal y comprobar que otra persona la registró correctamente.","activities":[{"id":"A1-M1-T01-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA actúa como agente de viajes. Completa tus datos y confirma que están escritos correctamente.","role":"travel agent","student_goal":"Give first name, last name, city and email, then confirm or correct one detail.","allowed_support":["field-by-field mode","slow mode","Spanish hint"],"success_criteria":["spells at least two fields","confirms a correct detail","corrects one incorrect detail"],"feedback_correct":"Completaste un formulario real y reparaste la información cuando fue necesario.","feedback_incorrect":"Usa: How do you spell...? / Is that right? / No, the first letter is...","estimated_seconds":200,"prompt":"La IA actúa como agente de viajes. Completa tus datos y confirma que están escritos correctamente.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T01-L03"},{"id":"A1-M1-T01-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Crea una tarjeta de contacto y preséntala oralmente: nombre, apellido, ciudad y correo.","prompt":"My first name is ____. My last name is ____. I live in ____. My email is ____.","response_type":"open_speech_or_text","evaluation_criteria":["provides four fields","spells at least two","uses complete phrases"],"feedback_correct":"Convertiste vocabulario y deletreo en información personal útil.","feedback_incorrect":"Completa un campo cada vez y después vuelve a decir la tarjeta completa.","estimated_seconds":150,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T01-L03"}]}'::jsonb,6);
