insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I have a reservation.","meaning_es":"reserva"},{"english":"Here is your confirmation.","meaning_es":"confirmación"},{"english":"There is a lot of noise.","meaning_es":"ruido"},{"english":"Is this correct?","meaning_es":"correcto"},{"english":"That letter is wrong.","meaning_es":"equivocado"},{"english":"I need to clarify one letter.","meaning_es":"aclarar"}],"dialogue":[{"speaker":"Receptionist","text":"Welcome. What''s your name?"},{"speaker":"Guest","text":"My name is Victor Morales."},{"speaker":"Receptionist","text":"How do you spell your last name?"},{"speaker":"Guest","text":"M-O-R-A-L-E-S."},{"speaker":"Receptionist","text":"Sorry, I didn''t catch the first letter."},{"speaker":"Guest","text":"M as in Monday. M-O-R-A-L-E-S."},{"speaker":"Receptionist","text":"Morales. Is that right?"},{"speaker":"Guest","text":"Yes, that''s right."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Mantener claridad y ritmo al deletrear una palabra completa en una situación con interrupción.","models":[{"text":"M as in Monday.","stress":["M","Monday"]},{"text":"I didn''t catch the first letter.","stress":["catch","first","letter"]},{"text":"Yes, that''s right.","intonation":"falling"}],"student_feedback":"La prioridad es que la otra persona identifique las letras; después mejora ritmo y entonación."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Receptionist","text":"Welcome. What''s your name?"},{"speaker":"Guest","text":"My name is Victor Morales."},{"speaker":"Receptionist","text":"How do you spell your last name?"},{"speaker":"Guest","text":"M-O-R-A-L-E-S."},{"speaker":"Receptionist","text":"Sorry, I didn''t catch the first letter."},{"speaker":"Guest","text":"M as in Monday. M-O-R-A-L-E-S."},{"speaker":"Receptionist","text":"Morales. Is that right?"},{"speaker":"Guest","text":"Yes, that''s right."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A noisy hotel lobby","text":"Victor arrives at a hotel with a reservation. The lobby is busy and noisy. The receptionist cannot hear the first letter of his last name. Victor does not simply repeat the whole name quickly. He gives an example: ''M as in Monday.'' The receptionist writes the name correctly and confirms the reservation.","interactive_vocabulary":["arrives","busy","noisy","cannot hear","gives an example","confirms"],"questions":[{"prompt":"What makes the interaction difficult?","options":["The lobby is noisy","Victor has no reservation","The hotel is closed"],"answer":"The lobby is noisy","accepted_answers":["The lobby is noisy","Noise","The noise","It is noisy"]},{"prompt":"How does Victor clarify M?","options":["M as in Monday","M as in music","He changes his name"],"answer":"M as in Monday","accepted_answers":["M as in Monday","He says M as in Monday","With M as in Monday"]}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Registrar una reserva internacional cuando hay ruido y una letra se confunde.","communication_goal":"El estudiante puede completar una interacción nueva que requiere deletrear, confirmar y corregir información.","activities":[{"id":"A1-M1-T01-L04-E08","type":"ai_roleplay","skill":"conversation","instruction":"Completa el registro de una reserva. La IA debe confundirse una vez; resuelve la confusión con claridad.","role":"hotel receptionist","student_goal":"Give first name and last name, spell them, clarify one letter and confirm the final information.","allowed_support":["slow mode","sentence starter","Spanish hint","repeat prompt"],"success_criteria":["gives first and last name","spells both or one long field","repairs a misunderstanding","confirms information"],"feedback_correct":"Completaste la reserva y resolviste un malentendido real.","feedback_incorrect":"Usa: Could you repeat that? / M as in Monday. / Is that right?","estimated_seconds":220,"prompt":"Completa el registro de una reserva. La IA debe confundirse una vez; resuelve la confusión con claridad.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T01-L04"}]}'::jsonb,6);
