insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"I significa yo y se usa para hablar de uno mismo. You se usa para hablar directamente con otra persona o con varias personas. En inglés el pronombre normalmente aparece; no se omite como ocurre a menudo en español.","communication_goal":"El estudiante puede presentarse, preguntar el nombre de otra persona y mantener un intercambio inicial.","language_focus":["I''m Carlos.","What''s your name?","I''m Ana.","Nice to meet you.","Nice to meet you, too."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I''m Carlos.","meaning_es":"yo"},{"english":"What''s your name?","meaning_es":"tú / usted / ustedes"},{"english":"What''s your name?","meaning_es":"nombre"},{"english":"Nice to meet you.","meaning_es":"agradable / qué bueno"},{"english":"Nice to meet you.","meaning_es":"conocer"},{"english":"Nice to meet you, too.","meaning_es":"también"}],"dialogue":[{"speaker":"Ana","text":"Hi! I''m Ana. What''s your name?"},{"speaker":"Carlos","text":"I''m Carlos. Nice to meet you."},{"speaker":"Ana","text":"Nice to meet you, too."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir I y you dentro de frases completas y usar la contracción I''m con ritmo natural.","models":[{"text":"I","ipa":"/aɪ/"},{"text":"you","ipa":"/juː/"},{"text":"I''m Carlos.","stress":["Carlos"]},{"text":"What''s your name?","stress":["name"],"intonation":"rising"}],"student_feedback":"Prioriza que I y you se distingan y que la frase completa suene conectada."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Ana","text":"Hi! I''m Ana. What''s your name?"},{"speaker":"Carlos","text":"I''m Carlos. Nice to meet you."},{"speaker":"Ana","text":"Nice to meet you, too."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Two new classmates","text":"Ana is early for class. She sees Carlos at the door. Ana says hello and introduces herself. Carlos gives his name. They are new classmates and they are happy to meet.","interactive_vocabulary":["early","class","door","introduces","classmate"],"questions":[{"prompt":"Where are Ana and Carlos?","options":["At an English class","At a hotel","At a store"],"answer":"At an English class"},{"prompt":"Are they meeting for the first time?","options":["Yes","No","The text does not say"],"answer":"Yes"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Conocer a una persona nueva en una clase de inglés.","communication_goal":"El estudiante puede presentarse, preguntar el nombre de otra persona y mantener un intercambio inicial.","activities":[{"id":"A1-M1-T02-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu nuevo compañero de clase. Preséntate, pregunta su nombre y responde al saludo.","role":"new classmate","student_goal":"Introduce yourself, ask the other person''s name, and respond politely.","allowed_support":["sentence starter","Spanish hint","slow mode"],"success_criteria":["uses I or I''m","asks What''s your name?","responds with Nice to meet you, too"],"feedback_correct":"Completaste una presentación básica con turnos reales.","feedback_incorrect":"Usa: I''m... / What''s your name? / Nice to meet you, too.","estimated_seconds":180,"prompt":"La IA es tu nuevo compañero de clase. Preséntate, pregunta su nombre y responde al saludo.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T02-L01"},{"id":"A1-M1-T02-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Graba un saludo para una persona que conocerás en un evento internacional.","prompt":"Hi! I''m ____. What''s your name? Nice to meet you.","response_type":"open_speech_or_text","evaluation_criteria":["introduces self","asks a question","uses a polite closing"],"feedback_correct":"Puedes iniciar una interacción básica con una persona nueva.","feedback_incorrect":"Incluye tu nombre, una pregunta y la expresión Nice to meet you.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T02-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"He se usa para un hombre o niño, she para una mujer o niña e it normalmente para un objeto, animal o situación. En inglés no usamos he o she para objetos.","communication_goal":"El estudiante puede identificar a una persona o un objeto y hablar de él o ella en frases sencillas.","language_focus":["He is my friend.","She is my teacher.","It is my phone.","Who is he?","Who is she?","What is it?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"He is my friend.","meaning_es":"él"},{"english":"She is my teacher.","meaning_es":"ella"},{"english":"It is my phone.","meaning_es":"ello / eso / esto"},{"english":"He is my friend.","meaning_es":"amigo / amiga"},{"english":"She is my teacher.","meaning_es":"profesor / profesora"},{"english":"It is my phone.","meaning_es":"teléfono"},{"english":"The phone is on the desk.","meaning_es":"escritorio"}],"dialogue":[{"speaker":"Maya","text":"This is Daniel. He is my friend."},{"speaker":"Maya","text":"This is Sofia. She is my manager."},{"speaker":"Colleague","text":"What is it?"},{"speaker":"Maya","text":"It is my phone."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir he, she e it en frases cortas y evitar añadir una vocal antes de he o she.","models":[{"text":"he","ipa":"/hiː/"},{"text":"she","ipa":"/ʃiː/"},{"text":"it","ipa":"/ɪt/"},{"text":"She is my manager.","stress":["She","manager"]}],"student_feedback":"La prioridad es distinguir /h/ en he, /ʃ/ en she y la vocal corta /ɪ/ en it."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Maya","text":"This is Daniel. He is my friend."},{"speaker":"Maya","text":"This is Sofia. She is my manager."},{"speaker":"Colleague","text":"What is it?"},{"speaker":"Maya","text":"It is my phone."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"People and things at work","text":"Maya works in a small office. Daniel is her friend. He works near the window. Sofia is her manager. She has a desk next to Maya. Maya has a new phone. It is on her desk.","interactive_vocabulary":["office","near","window","manager","next to"],"questions":[{"prompt":"Who works near the window?","options":["Daniel","Sofia","The phone"],"answer":"Daniel"},{"prompt":"What is on Maya''s desk?","options":["Her phone","A window","A manager"],"answer":"Her phone"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Presentar a compañeros de trabajo y describir objetos de una mesa.","communication_goal":"El estudiante puede identificar a una persona o un objeto y hablar de él o ella en frases sencillas.","activities":[{"id":"A1-M1-T02-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA visita tu oficina. Presenta a dos personas y describe un objeto.","role":"new colleague","student_goal":"Use he, she and it to identify people and one object.","allowed_support":["picture cards","sentence starter","Spanish hint"],"success_criteria":["uses he for a man","uses she for a woman","uses it for an object"],"feedback_correct":"Identificaste personas y objetos con los pronombres adecuados.","feedback_incorrect":"Prueba: He is... / She is... / It is...","estimated_seconds":180,"prompt":"La IA visita tu oficina. Presenta a dos personas y describe un objeto.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T02-L02"},{"id":"A1-M1-T02-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe una foto imaginaria: una persona masculina, una femenina y un objeto.","prompt":"He is ____. She is ____. It is ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses three pronouns","identifies two people and one object","produces understandable sentences"],"feedback_correct":"Transferiste los pronombres a una escena nueva.","feedback_incorrect":"Primero identifica si cada referente es una persona o un objeto.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T02-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"We incluye a la persona que habla y a una o más personas. They habla de otras personas que no están incluidas en we. Ambos pronombres pueden referirse a grupos de hombres, mujeres o grupos mixtos.","communication_goal":"El estudiante puede hablar de su grupo y de otros grupos usando we y they.","language_focus":["We are students.","They are our teachers.","Who are they?","We are from Colombia.","They are in the next room."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"We are students.","meaning_es":"nosotros / nosotras"},{"english":"They are our teachers.","meaning_es":"ellos / ellas"},{"english":"We are a team.","meaning_es":"equipo"},{"english":"They are a group of students.","meaning_es":"grupo"},{"english":"We study together.","meaning_es":"juntos"},{"english":"They are in the next room.","meaning_es":"habitación / sala de al lado"}],"dialogue":[{"speaker":"Teacher","text":"Who are they?"},{"speaker":"Student","text":"They are my classmates."},{"speaker":"Teacher","text":"And who are we?"},{"speaker":"Student","text":"We are the beginner English class."},{"speaker":"Teacher","text":"Great. We are a team."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir we y they y producir grupos de palabras sin separar cada palabra excesivamente.","models":[{"text":"we","ipa":"/wiː/"},{"text":"they","ipa":"/ðeɪ/"},{"text":"We are a team.","stress":["We","team"]},{"text":"They are my classmates.","stress":["They","classmates"]}],"student_feedback":"En they, coloca suavemente la lengua entre los dientes para el sonido /ð/; no lo reemplaces siempre por /d/."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Teacher","text":"Who are they?"},{"speaker":"Student","text":"They are my classmates."},{"speaker":"Teacher","text":"And who are we?"},{"speaker":"Student","text":"We are the beginner English class."},{"speaker":"Teacher","text":"Great. We are a team."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Two groups at school","text":"We are in an English class. We study together and practice every day. They are the advanced class. They study in the next room. We are beginners, but we are a team.","interactive_vocabulary":["practice","advanced","beginners","together","every day"],"questions":[{"prompt":"Who studies in the next room?","options":["The advanced class","The beginners","The teacher only"],"answer":"The advanced class"},{"prompt":"What does we refer to in the text?","options":["The speakers and their class","The advanced class","A room"],"answer":"The speakers and their class"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Presentar un equipo de trabajo y explicar quiénes participan en una actividad.","communication_goal":"El estudiante puede hablar de su grupo y de otros grupos usando we y they.","activities":[{"id":"A1-M1-T02-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es una visitante de tu escuela. Presenta tu grupo y otro grupo que está cerca.","role":"visitor","student_goal":"Use we for your group and they for another group.","allowed_support":["group cards","sentence starter","Spanish hint"],"success_criteria":["describes own group with we","describes another group with they","answers Who are we/they?"],"feedback_correct":"Explicaste claramente la diferencia entre tu grupo y otro grupo.","feedback_incorrect":"Usa: We are... / They are... / Who are they?","estimated_seconds":180,"prompt":"La IA es una visitante de tu escuela. Presenta tu grupo y otro grupo que está cerca.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T02-L03"},{"id":"A1-M1-T02-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Presenta tu equipo de trabajo o estudio y menciona a otro equipo.","prompt":"We are ____. They are ____. We work/study together.","response_type":"open_speech_or_text","evaluation_criteria":["uses we for own group","uses they for another group","communicates two group facts"],"feedback_correct":"Usaste los pronombres para organizar información social real.","feedback_incorrect":"Comprueba quién está dentro de tu grupo y quién está fuera antes de elegir el pronombre.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T02-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Los pronombres indican quién habla, quién escucha, una persona, un objeto o un grupo. La elección depende del referente y de si el hablante está incluido: I, you, he, she, it, we o they.","communication_goal":"El estudiante puede presentar personas, grupos y objetos usando los siete pronombres personales en una interacción nueva.","language_focus":["I am...","You are...","He is...","She is...","It is...","We are...","They are..."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"She is a participant.","meaning_es":"participante"},{"english":"He is the organizer.","meaning_es":"organizador / organizadora"},{"english":"We are the blue team.","meaning_es":"equipo"},{"english":"It is your badge.","meaning_es":"credencial"},{"english":"We are at an event.","meaning_es":"evento"},{"english":"Everyone is here.","meaning_es":"todos"}],"dialogue":[{"speaker":"Host","text":"Hi! I''m Leo. You are Maya, right?"},{"speaker":"Maya","text":"Yes, I am. Nice to meet you."},{"speaker":"Host","text":"He is Omar, the organizer. She is Nina, a participant."},{"speaker":"Maya","text":"And who are they?"},{"speaker":"Host","text":"They are the blue team. We are all here now."},{"speaker":"Maya","text":"What is it?"},{"speaker":"Host","text":"It is your badge."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir los pronombres dentro de frases con ritmo comprensible y distinguir he, she, we, they e it.","models":[{"text":"I am here.","ipa":"/aɪ æm hɪr/"},{"text":"You are here.","ipa":"/juː ɑːr hɪr/"},{"text":"He is the organizer.","stress":["He","organizer"]},{"text":"She is a participant.","stress":["She","participant"]},{"text":"We are all here.","stress":["We","here"]},{"text":"They are the blue team.","stress":["They","blue team"]},{"text":"It is your badge.","stress":["It","badge"]}],"student_feedback":"La meta es que el interlocutor identifique el referente; no se penaliza un acento extranjero comprensible."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Host","text":"Hi! I''m Leo. You are Maya, right?"},{"speaker":"Maya","text":"Yes, I am. Nice to meet you."},{"speaker":"Host","text":"He is Omar, the organizer. She is Nina, a participant."},{"speaker":"Maya","text":"And who are they?"},{"speaker":"Host","text":"They are the blue team. We are all here now."},{"speaker":"Maya","text":"What is it?"},{"speaker":"Host","text":"It is your badge."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The community event","text":"Leo welcomes Maya at a community event. He introduces Omar, the organizer, and Nina, a participant. Maya asks about another group. They are the blue team. Leo gives Maya a badge. It has her name. Everyone is ready to begin.","interactive_vocabulary":["welcomes","community","organizer","another","ready","begin"],"questions":[{"prompt":"Who is the organizer?","options":["Omar","Leo","Maya"],"answer":"Omar"},{"prompt":"What does the badge have?","options":["Maya''s name","The blue team","A phone"],"answer":"Maya''s name"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Recibir a una persona nueva en un evento y explicar quién es cada participante.","communication_goal":"El estudiante puede presentar personas, grupos y objetos usando los siete pronombres personales en una interacción nueva.","activities":[{"id":"A1-M1-T02-L04-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA llega a un evento. Preséntate, presenta a dos personas, describe un objeto y habla de tu grupo.","role":"new event participant","student_goal":"Use all relevant personal pronouns to orient the visitor.","allowed_support":["picture map","sentence starter","Spanish hint","slow mode"],"success_criteria":["uses I and you","uses he or she","uses it","uses we and they when relevant"],"feedback_correct":"Orientaste a otra persona usando referencias claras.","feedback_incorrect":"Piensa en cada referente y usa: He is... / She is... / It is... / We are... / They are...","estimated_seconds":230,"prompt":"La IA llega a un evento. Preséntate, presenta a dos personas, describe un objeto y habla de tu grupo.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T02-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","mastery_assessment"],"topic_ready_when":"El estudiante selecciona y usa pronombres comprensibles en una escena nueva con al menos 80% de precisión.","retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Am es la forma de to be que usamos con I. Podemos decir I am o la forma corta I''m. Se usa para identidad, origen, profesión y estados: I''m a student, I''m from Peru, I''m tired.","communication_goal":"El estudiante puede decir quién es y expresar estados básicos usando I am y I''m.","language_focus":["I am Carlos.","I''m a student.","I''m from Peru.","I''m tired.","I''m happy.","Are you ready?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I''m a student.","meaning_es":"estudiante"},{"english":"I''m from Peru.","meaning_es":"de / procedente de"},{"english":"I''m ready.","meaning_es":"listo / lista"},{"english":"I''m tired.","meaning_es":"cansado / cansada"},{"english":"I''m happy.","meaning_es":"feliz"},{"english":"I''m nervous.","meaning_es":"nervioso / nerviosa"}],"dialogue":[{"speaker":"Teacher","text":"Hi! I''m Ms. Lee. What''s your name?"},{"speaker":"Student","text":"I''m Carlos. I''m from Peru."},{"speaker":"Teacher","text":"Welcome, Carlos. Are you ready?"},{"speaker":"Student","text":"Yes, I''m ready. I''m a little nervous."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir I am e I''m con claridad y usar la contracción en conversación.","models":[{"text":"I am","ipa":"/aɪ æm/"},{"text":"I''m","ipa":"/aɪm/"},{"text":"I''m from Peru.","stress":["from","Peru"]},{"text":"I''m ready.","stress":["ready"]}],"student_feedback":"La contracción I''m debe sonar como una unidad corta, pero la palabra I debe seguir siendo audible."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Teacher","text":"Hi! I''m Ms. Lee. What''s your name?"},{"speaker":"Student","text":"I''m Carlos. I''m from Peru."},{"speaker":"Teacher","text":"Welcome, Carlos. Are you ready?"},{"speaker":"Student","text":"Yes, I''m ready. I''m a little nervous."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A new student","text":"Carlos is a new student. He is from Peru. Today is his first English class. He is happy, but he is a little nervous. He says, ''I''m ready.''","interactive_vocabulary":["new","first","today","a little","nervous"],"questions":[{"prompt":"Where is Carlos from?","options":["Peru","Canada","Spain"],"answer":"Peru"},{"prompt":"How does Carlos feel?","options":["Happy and a little nervous","Angry and tired","Not ready"],"answer":"Happy and a little nervous"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Presentarse en una clase y decir cómo se siente al comenzar el día.","communication_goal":"El estudiante puede decir quién es y expresar estados básicos usando I am y I''m.","activities":[{"id":"A1-M1-T03-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu profesor. Preséntate y di de dónde eres y cómo te sientes.","role":"English teacher","student_goal":"Use I am/I''m for identity, origin and one current state.","allowed_support":["sentence starter","Spanish hint","slow mode"],"success_criteria":["says who they are","says where they are from","expresses a state"],"feedback_correct":"Completaste una presentación con información personal útil.","feedback_incorrect":"Usa: I''m a... / I''m from... / I''m feeling...","estimated_seconds":180,"prompt":"La IA es tu profesor. Preséntate y di de dónde eres y cómo te sientes.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T03-L01"},{"id":"A1-M1-T03-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Envía un audio breve a un nuevo compañero antes de tu primera clase.","prompt":"Hi! I''m ____. I''m from ____. I''m feeling ____. See you in class!","response_type":"open_speech_or_text","evaluation_criteria":["uses I''m three times appropriately","communicates personal information","is understandable"],"feedback_correct":"Usaste to be para comunicar información personal en una situación real.","feedback_incorrect":"Completa una frase de identidad, una de origen y una de estado.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T03-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Con he, she e it usamos is: He is, She is, It is. En conversación son comunes las formas cortas he''s, she''s e it''s. Is puede describir identidad, estados y ubicación.","communication_goal":"El estudiante puede describir una persona o un objeto con is y explicar dónde está.","language_focus":["He is my coworker.","She''s in the office.","It is on the table.","He is tired.","She is ready.","It''s near the door."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"He is my coworker.","meaning_es":"compañero / compañera de trabajo"},{"english":"She''s in the office.","meaning_es":"oficina"},{"english":"It is on the table.","meaning_es":"mesa"},{"english":"It''s near the door.","meaning_es":"cerca de"},{"english":"The bag is near the door.","meaning_es":"puerta"},{"english":"She is ready.","meaning_es":"listo / lista"}],"dialogue":[{"speaker":"New employee","text":"Who is he?"},{"speaker":"Maya","text":"He is my coworker, Daniel."},{"speaker":"New employee","text":"Where is she?"},{"speaker":"Maya","text":"She''s in the office. She is ready for the meeting."},{"speaker":"New employee","text":"What is that?"},{"speaker":"Maya","text":"It''s my bag. It is near the door."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir he is, she is e it is y producir las contracciones en conversación.","models":[{"text":"He''s my coworker.","stress":["coworker"]},{"text":"She''s in the office.","stress":["office"]},{"text":"It''s near the door.","stress":["near","door"]}],"student_feedback":"Mantén audible el pronombre y conecta la contracción con el resto de la frase."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"New employee","text":"Who is he?"},{"speaker":"Maya","text":"He is my coworker, Daniel."},{"speaker":"New employee","text":"Where is she?"},{"speaker":"Maya","text":"She''s in the office. She is ready for the meeting."},{"speaker":"New employee","text":"What is that?"},{"speaker":"Maya","text":"It''s my bag. It is near the door."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A new office","text":"Daniel is Maya''s coworker. He is friendly and he is near the window. Sofia is the manager. She is in the office. Maya has a new bag. It is on the table, near the door.","interactive_vocabulary":["friendly","window","manager","new bag"],"questions":[{"prompt":"Who is near the window?","options":["Daniel","Sofia","The bag"],"answer":"Daniel"},{"prompt":"Where is the bag?","options":["On the table near the door","In the window","In the office upstairs"],"answer":"On the table near the door"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Describir a una persona y localizar un objeto en una oficina.","communication_goal":"El estudiante puede describir una persona o un objeto con is y explicar dónde está.","activities":[{"id":"A1-M1-T03-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es un nuevo empleado. Explícale quién es una persona y dónde están dos objetos.","role":"new employee","student_goal":"Use he is, she is and it is to describe people and locations.","allowed_support":["office map","sentence starter","Spanish hint"],"success_criteria":["describes one man","describes one woman","locates two objects"],"feedback_correct":"Usaste is para identidad, estado y ubicación.","feedback_incorrect":"Prueba: He is... / She is... / It''s on... / It''s near...","estimated_seconds":180,"prompt":"La IA es un nuevo empleado. Explícale quién es una persona y dónde están dos objetos.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T03-L02"},{"id":"A1-M1-T03-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe tu espacio: una persona, otra persona y dos objetos.","prompt":"He/She is ____. He/She is ____. It is ____. It''s near ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses is with three referents","describes one state or identity","gives one location"],"feedback_correct":"Usaste to be para describir una escena de tu vida.","feedback_incorrect":"Elige un referente cada vez y usa he, she o it antes de is.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T03-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Con you, we y they usamos are: You are, We are y They are. You puede referirse a una o varias personas. We incluye al hablante; they se refiere a otro grupo.","communication_goal":"El estudiante puede describir a su interlocutor, a su propio grupo y a otros grupos usando are.","language_focus":["You are in the right room.","We are ready.","They are outside.","Are you ready?","We are from the same class.","They''re near the door."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"We are ready.","meaning_es":"listo / lista"},{"english":"They are outside.","meaning_es":"afuera"},{"english":"We are in the same class.","meaning_es":"mismo / misma"},{"english":"You are in the right room.","meaning_es":"sala / habitación"},{"english":"We are early.","meaning_es":"temprano"},{"english":"They are late.","meaning_es":"tarde"}],"dialogue":[{"speaker":"Leader","text":"Are you ready?"},{"speaker":"Student","text":"Yes, we are ready."},{"speaker":"Leader","text":"Great. You are in the right room."},{"speaker":"Student","text":"Where are the other students?"},{"speaker":"Leader","text":"They are outside. They''re near the door."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir are y sus contracciones en preguntas y respuestas con ritmo natural.","models":[{"text":"You are ready.","stress":["ready"]},{"text":"We''re in the same class.","stress":["same","class"]},{"text":"They''re outside.","stress":["outside"]},{"text":"Are you ready?","intonation":"rising"}],"student_feedback":"Conserva la diferencia entre la pregunta Are you...? y la respuesta We are...; no elimines el sujeto."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Leader","text":"Are you ready?"},{"speaker":"Student","text":"Yes, we are ready."},{"speaker":"Leader","text":"Great. You are in the right room."},{"speaker":"Student","text":"Where are the other students?"},{"speaker":"Leader","text":"They are outside. They''re near the door."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Before the workshop","text":"We are early for the workshop. The leader says, ''You are in the right room.'' Two students are outside. They are near the door. We are ready, but they are a little late.","interactive_vocabulary":["workshop","leader","right room","a little late"],"questions":[{"prompt":"Who is early?","options":["We","They","The leader only"],"answer":"We"},{"prompt":"Where are the two students?","options":["Outside near the door","In another country","At home"],"answer":"Outside near the door"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Organizar a participantes antes de comenzar una actividad grupal.","communication_goal":"El estudiante puede describir a su interlocutor, a su propio grupo y a otros grupos usando are.","activities":[{"id":"A1-M1-T03-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es el líder de un taller. Responde si estás listo, explica quién está contigo y dónde está otro grupo.","role":"workshop leader","student_goal":"Use you, we and they with are in a group situation.","allowed_support":["group map","sentence starter","Spanish hint"],"success_criteria":["answers Are you ready?","describes own group with we","locates another group with they"],"feedback_correct":"Usaste are para organizar una situación grupal.","feedback_incorrect":"Prueba: Yes, we are. / They are... / We are...","estimated_seconds":180,"prompt":"La IA es el líder de un taller. Responde si estás listo, explica quién está contigo y dónde está otro grupo.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T03-L03"},{"id":"A1-M1-T03-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Envía un mensaje a tu equipo antes de una reunión.","prompt":"Are you ready? We are ____. They are ____. See you soon!","response_type":"open_speech_or_text","evaluation_criteria":["uses are with you/we/they","describes two groups","communicates readiness or location"],"feedback_correct":"Usaste are para comunicar información práctica a un equipo.","feedback_incorrect":"Revisa qué grupo incluye al hablante y cuál es otro grupo.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T03-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Con I usamos am; con he, she e it usamos is; con you, we y they usamos are. Estas formas sirven para identidad, estados, ubicación y preguntas.","communication_goal":"El estudiante puede describir identidad, estados y ubicación usando am, is y are en una situación nueva.","language_focus":["I am...","He/She/It is...","You/We/They are...","Where are you?","Is he ready?","Are they here?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Everyone is present.","meaning_es":"presente"},{"english":"The teacher is available.","meaning_es":"disponible"},{"english":"She is busy.","meaning_es":"ocupado / ocupada"},{"english":"We are at the entrance.","meaning_es":"entrada"},{"english":"They are in the hall.","meaning_es":"pasillo"},{"english":"The meeting is ready.","meaning_es":"reunión"}],"dialogue":[{"speaker":"Student","text":"Hi, I''m new. Where are we?"},{"speaker":"Guide","text":"We are at the language school. You are in Room 2."},{"speaker":"Student","text":"Is the teacher here?"},{"speaker":"Guide","text":"Yes, she is in the hall. She is available."},{"speaker":"Student","text":"Are the other students here?"},{"speaker":"Guide","text":"Yes, they are in the classroom. It is ready for the lesson."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Usar am, is y are con ritmo comprensible en afirmaciones y preguntas.","models":[{"text":"I''m new.","stress":["new"]},{"text":"She is available.","stress":["available"]},{"text":"They are in the classroom.","stress":["classroom"]},{"text":"Are they here?","intonation":"rising"}],"student_feedback":"No necesitas sonar nativo; debes hacer reconocible el sujeto y la forma de to be."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Student","text":"Hi, I''m new. Where are we?"},{"speaker":"Guide","text":"We are at the language school. You are in Room 2."},{"speaker":"Student","text":"Is the teacher here?"},{"speaker":"Guide","text":"Yes, she is in the hall. She is available."},{"speaker":"Student","text":"Are the other students here?"},{"speaker":"Guide","text":"Yes, they are in the classroom. It is ready for the lesson."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"At the language school","text":"I am new at the language school. We are at the entrance. The guide is friendly and she is available. The teacher is in the hall. She is ready. The other students are in Room 2. They are present and the classroom is ready.","interactive_vocabulary":["entrance","guide","friendly","available","present"],"questions":[{"prompt":"Where are the speakers?","options":["At a language school","At a hotel","At an airport"],"answer":"At a language school"},{"prompt":"Where are the other students?","options":["In Room 2","At the entrance","In the hall only"],"answer":"In Room 2"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Orientar a una persona en una escuela y describir quién está presente, cómo está y dónde se encuentra.","communication_goal":"El estudiante puede describir identidad, estados y ubicación usando am, is y are en una situación nueva.","activities":[{"id":"A1-M1-T03-L04-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es un estudiante nuevo. Oriéntalo por la escuela y responde preguntas con am, is y are.","role":"new student","student_goal":"Describe yourself, a person, an object and groups using all relevant forms of to be.","allowed_support":["school map","sentence starter","Spanish hint","slow mode"],"success_criteria":["uses am for self","uses is for a person or object","uses are for a group","answers one question"],"feedback_correct":"Orientaste a la persona combinando identidad, estado y ubicación.","feedback_incorrect":"Organiza tu respuesta: I am... / He or she is... / They are...","estimated_seconds":230,"prompt":"La IA es un estudiante nuevo. Oriéntalo por la escuela y responde preguntas con am, is y are.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T03-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","mastery_assessment"],"topic_ready_when":"El estudiante elige y produce am, is y are en una situación nueva con al menos 80% de precisión y comprensión.","retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Usamos a antes de un sustantivo singular que comienza con sonido consonántico: a pen, a book. Usamos an antes de un sustantivo singular que comienza con sonido vocálico: an apple, an umbrella.","communication_goal":"El estudiante puede identificar y pedir un objeto singular usando a o an.","language_focus":["I need a pen.","I need an umbrella.","It''s a book.","It''s an apple.","Can I have a ticket?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I need a pen.","meaning_es":"bolígrafo"},{"english":"It''s a book.","meaning_es":"libro"},{"english":"I want an apple.","meaning_es":"manzana"},{"english":"I need an umbrella.","meaning_es":"paraguas"},{"english":"Can I have a ticket?","meaning_es":"boleto / billete"},{"english":"This is an item.","meaning_es":"artículo / objeto"}],"dialogue":[{"speaker":"Customer","text":"Hi. I need an umbrella and a pen, please."},{"speaker":"Shop assistant","text":"Sure. Anything else?"},{"speaker":"Customer","text":"Yes, an apple and a book, please."},{"speaker":"Shop assistant","text":"Here you are."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Conectar a/an con el sustantivo sin añadir pausas innecesarias.","models":[{"text":"a pen","stress":["pen"]},{"text":"a book","stress":["book"]},{"text":"an apple","stress":["apple"]},{"text":"an umbrella","stress":["umbrella"]}],"student_feedback":"A menudo suena débil y se une a la siguiente palabra; la palabra importante es el objeto."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Customer","text":"Hi. I need an umbrella and a pen, please."},{"speaker":"Shop assistant","text":"Sure. Anything else?"},{"speaker":"Customer","text":"Yes, an apple and a book, please."},{"speaker":"Shop assistant","text":"Here you are."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A quick shop visit","text":"It is raining. Sam goes to a small shop. Sam needs an umbrella, a pen and an apple. The shop also has a book. Sam buys the umbrella and the apple.","interactive_vocabulary":["raining","goes","needs","also","buys"],"questions":[{"prompt":"Why does Sam need an umbrella?","options":["It is raining","He is hungry","He wants a book"],"answer":"It is raining"},{"prompt":"What does Sam buy?","options":["An umbrella and an apple","A pen and a book","A ticket"],"answer":"An umbrella and an apple"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Describir lo que necesita en una tienda pequeña.","communication_goal":"El estudiante puede identificar y pedir un objeto singular usando a o an.","activities":[{"id":"A1-M1-T04-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es dependiente de una tienda. Pide tres objetos, usando a o an correctamente.","role":"shop assistant","student_goal":"Request singular objects with a/an and respond to one follow-up question.","allowed_support":["object pictures","sentence starter","Spanish hint"],"success_criteria":["requests three objects","uses a/an accurately","uses please"],"feedback_correct":"Hiciste pedidos comprensibles usando artículos en una situación real.","feedback_incorrect":"Escucha el primer sonido del objeto y usa a o an antes de pedirlo.","estimated_seconds":180,"prompt":"La IA es dependiente de una tienda. Pide tres objetos, usando a o an correctamente.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T04-L01"},{"id":"A1-M1-T04-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Prepara una lista oral para una emergencia de lluvia: tres cosas que necesitas.","prompt":"I need a ____, an ____, and a ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses three singular nouns","selects a/an by sound","communicates a real need"],"feedback_correct":"Transferiste los artículos a una necesidad personal.","feedback_incorrect":"Pronuncia cada objeto y decide si el sonido inicial es consonántico o vocálico.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T04-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Usamos a/an cuando presentamos una cosa no identificada o una de varias. Usamos the cuando hablamos de una cosa específica que ya se presentó o que ambos pueden identificar.","communication_goal":"El estudiante puede distinguir entre presentar un objeto y referirse a un objeto específico usando a/an o the.","language_focus":["I need a cup.","The cup is on the table.","I see a bag.","The bag is blue.","Where is the ticket?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I need a cup.","meaning_es":"taza / vaso"},{"english":"The cup is on the table.","meaning_es":"mesa"},{"english":"I see a bag.","meaning_es":"bolso / bolsa"},{"english":"Where is the ticket?","meaning_es":"boleto / billete"},{"english":"The bag is specific.","meaning_es":"específico"},{"english":"The bag is blue.","meaning_es":"azul"}],"dialogue":[{"speaker":"Customer","text":"Can I have a cup, please?"},{"speaker":"Assistant","text":"Sure. Here is the cup."},{"speaker":"Customer","text":"Thanks. Where is the ticket?"},{"speaker":"Assistant","text":"The ticket is next to the bag."},{"speaker":"Customer","text":"I see a bag. Is the bag blue?"},{"speaker":"Assistant","text":"Yes, the bag is blue."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir a/an de the y producir the antes de consonante y vocal sin convertirlo en una sílaba fuerte.","models":[{"text":"a bag","stress":["bag"]},{"text":"the bag","stress":["bag"]},{"text":"the ticket","stress":["ticket"]},{"text":"the apple","stress":["apple"]}],"student_feedback":"The suele ser débil; la información importante está en bag, ticket o apple."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Customer","text":"Can I have a cup, please?"},{"speaker":"Assistant","text":"Sure. Here is the cup."},{"speaker":"Customer","text":"Thanks. Where is the ticket?"},{"speaker":"Assistant","text":"The ticket is next to the bag."},{"speaker":"Customer","text":"I see a bag. Is the bag blue?"},{"speaker":"Assistant","text":"Yes, the bag is blue."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The blue bag","text":"Mia sees a bag in a café. She does not know the bag. Then she sees a ticket next to it. She asks the assistant about the bag. The assistant says, ''The bag is blue and the ticket is under the cup.''","interactive_vocabulary":["café","does not know","next to","under","assistant"],"questions":[{"prompt":"When does Mia use a bag?","options":["When she first sees one","After she identifies it","Never"],"answer":"When she first sees one"},{"prompt":"Where is the ticket?","options":["Under the cup","Inside the bag","On the chair"],"answer":"Under the cup"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Pedir un objeto en una cafetería y luego identificar el objeto concreto sobre la mesa.","communication_goal":"El estudiante puede distinguir entre presentar un objeto y referirse a un objeto específico usando a/an o the.","activities":[{"id":"A1-M1-T04-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA está en una cafetería. Presenta objetos nuevos y luego pregunta por objetos específicos.","role":"café assistant","student_goal":"Use a/an to introduce items and the to refer back to them.","allowed_support":["object cards","sentence starter","Spanish hint"],"success_criteria":["introduces two objects","refers to each with the","asks one specific-item question"],"feedback_correct":"Usaste los artículos según la información compartida.","feedback_incorrect":"Primero presenta con a/an; después usa the para el objeto ya conocido.","estimated_seconds":180,"prompt":"La IA está en una cafetería. Presenta objetos nuevos y luego pregunta por objetos específicos.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T04-L02"},{"id":"A1-M1-T04-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe tres objetos en tu mesa: preséntalos y después describe uno específicamente.","prompt":"I see a ____, an ____, and a ____. The ____ is ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses a/an for first mentions","uses the for a known item","communicates a detail"],"feedback_correct":"Aplicaste la diferencia entre información nueva y específica.","feedback_incorrect":"Presenta primero cada objeto y luego retoma uno con the.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T04-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"En una descripción, a/an presenta un objeto por primera vez y the identifica el mismo objeto después. El contexto puede hacer que un objeto sea específico aunque no se haya mencionado antes: The key is next to the door si ambos saben qué llave buscan.","communication_goal":"El estudiante puede describir objetos de un espacio compartido usando artículos según el contexto.","language_focus":["There is a chair.","The chair is near the window.","There is an orange on the table.","The orange is for you.","I need a key."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"There is a chair.","meaning_es":"silla"},{"english":"The chair is near the window.","meaning_es":"ventana"},{"english":"There is an orange.","meaning_es":"naranja"},{"english":"I need a key.","meaning_es":"llave"},{"english":"The room is small.","meaning_es":"habitación / sala"},{"english":"The orange is for you.","meaning_es":"para ti / usted"}],"dialogue":[{"speaker":"Alex","text":"There is a chair near the window."},{"speaker":"Sam","text":"The chair is comfortable."},{"speaker":"Alex","text":"There is an orange on the table."},{"speaker":"Sam","text":"Great. The orange is for the guest."},{"speaker":"Alex","text":"I also need a key."},{"speaker":"Sam","text":"The key is next to the door."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Mantener artículos débiles y destacar la información nueva o específica.","models":[{"text":"a chair","stress":["chair"]},{"text":"the chair","stress":["chair"]},{"text":"an orange","stress":["orange"]},{"text":"the key is next to the door","stress":["key","next","door"]}],"student_feedback":"El artículo acompaña al sustantivo; no lo conviertas en la palabra más fuerte de la frase."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Alex","text":"There is a chair near the window."},{"speaker":"Sam","text":"The chair is comfortable."},{"speaker":"Alex","text":"There is an orange on the table."},{"speaker":"Sam","text":"Great. The orange is for the guest."},{"speaker":"Alex","text":"I also need a key."},{"speaker":"Sam","text":"The key is next to the door."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Before the guest arrives","text":"There is a small room for a guest. There is a chair near a window. The chair is comfortable. There is an orange on a table. The orange is fresh. The key is next to the door.","interactive_vocabulary":["guest","small","comfortable","fresh","next to"],"questions":[{"prompt":"Where is the chair?","options":["Near a window","Next to the door","On the table"],"answer":"Near a window"},{"prompt":"Where is the key?","options":["Next to the door","Inside the orange","Near the window"],"answer":"Next to the door"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Explicar a un compañero qué hay en una habitación y señalar objetos concretos.","communication_goal":"El estudiante puede describir objetos de un espacio compartido usando artículos según el contexto.","activities":[{"id":"A1-M1-T04-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu compañero de habitación. Describe qué hay en el espacio y responde preguntas sobre objetos específicos.","role":"roommate","student_goal":"Introduce objects with a/an and identify them with the when asked.","allowed_support":["room picture","sentence starter","Spanish hint"],"success_criteria":["introduces three objects","locates two objects","answers one the question"],"feedback_correct":"Describiste un espacio y mantuviste claros los referentes.","feedback_incorrect":"Presenta con There is a/an... y responde sobre el objeto con The...","estimated_seconds":190,"prompt":"La IA es tu compañero de habitación. Describe qué hay en el espacio y responde preguntas sobre objetos específicos.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T04-L03"},{"id":"A1-M1-T04-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe tu escritorio para una persona que no lo puede ver.","prompt":"There is a ____. There is an ____. The ____ is ____. The ____ is near ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses a/an for new objects","uses the for known objects","gives two locations"],"feedback_correct":"Convertiste artículos y ubicación en una descripción útil.","feedback_incorrect":"Presenta los objetos primero y después usa the para describirlos.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T04-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"A/an presenta un objeto singular no identificado. The señala un objeto concreto, ya mencionado o claro para ambos. La elección de a/an depende del sonido inicial; the depende de si el referente es identificable.","communication_goal":"El estudiante puede pedir, identificar y describir objetos usando a, an y the en una situación nueva.","language_focus":["I need a...","I need an...","The ... is...","Can I have the...?","There is a...","Where is the...?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I have a shopping list.","meaning_es":"lista de compras"},{"english":"I need a bottle.","meaning_es":"botella"},{"english":"I need an egg.","meaning_es":"huevo"},{"english":"I need an orange.","meaning_es":"naranja"},{"english":"The basket is here.","meaning_es":"canasta / cesta"},{"english":"The bottle is on the shelf.","meaning_es":"estante"}],"dialogue":[{"speaker":"Shopper","text":"I need a bottle of water and an orange, please."},{"speaker":"Assistant","text":"The bottles are on the shelf. The oranges are over there."},{"speaker":"Shopper","text":"Thanks. I also need an egg."},{"speaker":"Assistant","text":"Here is an egg. Do you need the basket?"},{"speaker":"Shopper","text":"Yes, please. Where is the basket?"},{"speaker":"Assistant","text":"The basket is next to the door."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Usar artículos débiles y destacar el objeto importante dentro de pedidos y aclaraciones.","models":[{"text":"a bottle","stress":["bottle"]},{"text":"an orange","stress":["orange"]},{"text":"the basket","stress":["basket"]},{"text":"Where is the basket?","stress":["where","basket"],"intonation":"rising"}],"student_feedback":"Los artículos suelen ser débiles; mantén claras las palabras bottle, orange, egg y basket."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Shopper","text":"I need a bottle of water and an orange, please."},{"speaker":"Assistant","text":"The bottles are on the shelf. The oranges are over there."},{"speaker":"Shopper","text":"Thanks. I also need an egg."},{"speaker":"Assistant","text":"Here is an egg. Do you need the basket?"},{"speaker":"Shopper","text":"Yes, please. Where is the basket?"},{"speaker":"Assistant","text":"The basket is next to the door."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The market list","text":"Lina has a shopping list. She needs a bottle of water, an orange and an egg. She sees a basket near the door. Later, she asks for the basket because she knows which basket she needs. The assistant helps her find the items.","interactive_vocabulary":["market","list","bottle of water","items","find"],"questions":[{"prompt":"What does Lina need first?","options":["A bottle, an orange and an egg","The basket only","A book and a pen"],"answer":"A bottle, an orange and an egg"},{"prompt":"Why does she say the basket?","options":["It is identifiable in the situation","It is plural","It starts with a vowel"],"answer":"It is identifiable in the situation"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Comprar varios artículos y explicar cuál objeto específico necesita.","communication_goal":"El estudiante puede pedir, identificar y describir objetos usando a, an y the en una situación nueva.","activities":[{"id":"A1-M1-T04-L04-E07","type":"ai_roleplay","skill":"conversation","instruction":"La IA es dependiente de un mercado. Compra tres objetos y vuelve a referirte a uno específico.","role":"market assistant","student_goal":"Request new items with a/an, then ask about one known item with the.","allowed_support":["shopping list","object pictures","sentence starter","Spanish hint"],"success_criteria":["requests three items","uses a/an appropriately","uses the for a known item","asks a location question"],"feedback_correct":"Completaste una compra usando artículos con intención comunicativa.","feedback_incorrect":"Presenta con a/an y luego identifica con the cuando el objeto ya está claro.","estimated_seconds":230,"prompt":"La IA es dependiente de un mercado. Compra tres objetos y vuelve a referirte a uno específico.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T04-L04"},{"id":"A1-M1-T04-L04-E08","type":"transfer_mission","skill":"integrated","instruction":"Crea y expresa una lista de compras de cuatro artículos. Después pregunta por uno específico.","prompt":"I need a ____, an ____, a ____, and an ____. Where is the ____?","response_type":"open_speech_or_text","evaluation_criteria":["uses four singular nouns","chooses a/an by sound","uses the for a known item","communicates a real shopping need"],"feedback_correct":"Usaste los artículos para completar una tarea real y transferible.","feedback_incorrect":"Revisa cada sonido inicial y luego decide cuál objeto ya es identificable.","estimated_seconds":150,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T04-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","mastery_assessment"],"topic_ready_when":"El estudiante elige artículos por sonido y contexto, y completa una compra comprensible con al menos 80% de precisión.","retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Un sustantivo singular habla de una cosa: one book. Para muchos sustantivos regulares añadimos -s: two books, three pens. El plural también cambia la forma del verbo: There is one book; There are two books.","communication_goal":"El estudiante puede distinguir un objeto de varios y formar plurales regulares básicos.","language_focus":["one book","two books","a pen","three pens","There is a chair.","There are two chairs."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"There are two books.","meaning_es":"libro"},{"english":"There are three pens.","meaning_es":"bolígrafo"},{"english":"There is a chair.","meaning_es":"silla"},{"english":"The desks are clean.","meaning_es":"escritorio"},{"english":"I have two notebooks.","meaning_es":"cuaderno"},{"english":"three books","meaning_es":"uno / dos / tres"}],"dialogue":[{"speaker":"Teacher","text":"There is one book on the desk."},{"speaker":"Assistant","text":"There are two books in the box."},{"speaker":"Teacher","text":"Are there any pens?"},{"speaker":"Assistant","text":"Yes, there are three pens and two notebooks."},{"speaker":"Teacher","text":"Great. The students are ready."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Pronunciar plurales regulares y distinguir singular de plural al escuchar.","models":[{"text":"book / books","ipa":"/bʊk/ - /bʊks/"},{"text":"pen / pens","ipa":"/pen/ - /penz/"},{"text":"one chair / two chairs","stress":["one","two","chairs"]}],"student_feedback":"La terminación plural puede sonar /s/ o /z/; la meta A1 es que el número se entienda."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Teacher","text":"There is one book on the desk."},{"speaker":"Assistant","text":"There are two books in the box."},{"speaker":"Teacher","text":"Are there any pens?"},{"speaker":"Assistant","text":"Yes, there are three pens and two notebooks."},{"speaker":"Teacher","text":"Great. The students are ready."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The classroom materials","text":"There is one teacher''s desk and there are three student desks. There are two books on a table. There are four pens in a box. The notebooks are next to the books.","interactive_vocabulary":["classroom","materials","student desk","box","next to"],"questions":[{"prompt":"How many books are on the table?","options":["Two","Three","Four"],"answer":"Two"},{"prompt":"Where are the notebooks?","options":["Next to the books","In the desk","On the window"],"answer":"Next to the books"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Organizar materiales en una mesa y decir qué objetos hay.","communication_goal":"El estudiante puede distinguir un objeto de varios y formar plurales regulares básicos.","activities":[{"id":"A1-M1-T05-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es una profesora que revisa materiales. Dile cuántos objetos hay en tu mesa.","role":"teacher","student_goal":"Report singular and plural classroom objects with numbers.","allowed_support":["object picture","number cards","sentence starter","Spanish hint"],"success_criteria":["reports one singular item","reports two plural items","uses there is/are"],"feedback_correct":"Informaste cantidades y objetos de forma clara.","feedback_incorrect":"Usa There is para uno y There are para más de uno.","estimated_seconds":180,"prompt":"La IA es una profesora que revisa materiales. Dile cuántos objetos hay en tu mesa.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T05-L01"},{"id":"A1-M1-T05-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Haz un inventario hablado de cuatro objetos de tu habitación.","prompt":"There is one ____. There are two ____. There are three ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses singular and plural nouns","uses numbers","uses there is/are accurately"],"feedback_correct":"Convertiste números y plurales en información útil.","feedback_incorrect":"Comprueba el número y añade -s cuando hay más de un objeto.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T05-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Algunos plurales frecuentes no añaden simplemente -s: person → people, child → children, man → men, woman → women. Conviene aprenderlos dentro de frases y situaciones, no como una lista aislada.","communication_goal":"El estudiante puede reconocer y usar plurales frecuentes regulares e irregulares en situaciones cotidianas.","language_focus":["one person / two people","one child / two children","one man / two men","one woman / two women","There are people here."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"There are three people.","meaning_es":"persona / personas"},{"english":"The children are here.","meaning_es":"niño / niños"},{"english":"Two men are outside.","meaning_es":"hombre / hombres"},{"english":"Two women are here.","meaning_es":"mujer / mujeres"},{"english":"There are two boxes.","meaning_es":"caja"},{"english":"The classes start at nine.","meaning_es":"clase"}],"dialogue":[{"speaker":"Coordinator","text":"How many people are here?"},{"speaker":"Assistant","text":"There are two men, three women and two children."},{"speaker":"Coordinator","text":"Great. Are the boxes ready?"},{"speaker":"Assistant","text":"Yes, the boxes are ready. The classes can start."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Reconocer y producir los cambios de sonido de people, children, men y women.","models":[{"text":"person / people","ipa":"/ˈpɜːrsən/ - /ˈpiːpəl/"},{"text":"child / children","ipa":"/tʃaɪld/ - /ˈtʃɪldrən/"},{"text":"man / men","ipa":"/mæn/ - /men/"},{"text":"woman / women","ipa":"/ˈwʊmən/ - /ˈwɪmɪn/"}],"student_feedback":"La meta es reconocer la palabra y comunicar la cantidad; no memorices solo la terminación escrita."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Coordinator","text":"How many people are here?"},{"speaker":"Assistant","text":"There are two men, three women and two children."},{"speaker":"Coordinator","text":"Great. Are the boxes ready?"},{"speaker":"Assistant","text":"Yes, the boxes are ready. The classes can start."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"People at the activity","text":"There are many people at the community center. Two men are near the door. Three women are at a table. Two children are with their parents. The boxes are ready for the activity.","interactive_vocabulary":["many","community center","near","parents","activity"],"questions":[{"prompt":"How many women are at the table?","options":["Three","Two","Four"],"answer":"Three"},{"prompt":"Who is with their parents?","options":["The children","The men","The coordinator"],"answer":"The children"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Describir quién está en una sala y qué objetos hay en una tienda.","communication_goal":"El estudiante puede reconocer y usar plurales frecuentes regulares e irregulares en situaciones cotidianas.","activities":[{"id":"A1-M1-T05-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA organiza un evento. Cuenta cuántos hombres, mujeres, niños y personas hay.","role":"event coordinator","student_goal":"Report group counts with people, men, women and children.","allowed_support":["counting cards","picture","sentence starter","Spanish hint"],"success_criteria":["uses two irregular plurals","reports at least three counts","uses there are"],"feedback_correct":"Informaste cantidades reales usando plurales variados.","feedback_incorrect":"Usa There are + número + plural; recuerda people, women y children.","estimated_seconds":180,"prompt":"La IA organiza un evento. Cuenta cuántos hombres, mujeres, niños y personas hay.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T05-L02"},{"id":"A1-M1-T05-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe una foto familiar imaginaria con cuatro grupos o personas.","prompt":"There are ___ people. There are ___ men, ___ women and ___ children.","response_type":"open_speech_or_text","evaluation_criteria":["uses people correctly","uses at least two irregular plurals","communicates counts"],"feedback_correct":"Usaste plurales para describir una escena personal.","feedback_incorrect":"Recuerda que people ya es plural y que child cambia a children.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T05-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Muchos plurales añaden -s: cup → cups. Algunas palabras añaden -es para facilitar el sonido: box → boxes, class → classes, dish → dishes. En A1 aprendemos primero patrones frecuentes y los practicamos dentro de frases.","communication_goal":"El estudiante puede formar y reconocer plurales regulares frecuentes al describir objetos cotidianos.","language_focus":["one cup / two cups","one box / two boxes","one class / two classes","one dish / two dishes","The boxes are ready."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"There are six cups.","meaning_es":"taza / vaso"},{"english":"There are two boxes.","meaning_es":"caja"},{"english":"The classes start at nine.","meaning_es":"clase"},{"english":"There are clean dishes.","meaning_es":"plato"},{"english":"The plates are on the table.","meaning_es":"plato llano"},{"english":"Check the list.","meaning_es":"lista"}],"dialogue":[{"speaker":"Volunteer","text":"How many cups do we need?"},{"speaker":"Organizer","text":"We need six cups and six plates."},{"speaker":"Volunteer","text":"Are the boxes ready?"},{"speaker":"Organizer","text":"Yes, the boxes are ready. The dishes are clean."},{"speaker":"Volunteer","text":"Great. The classes can start."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir las terminaciones /s/, /z/ y /ɪz/ en plurales frecuentes.","models":[{"text":"cups","ipa":"/kʌps/"},{"text":"plates","ipa":"/pleɪts/"},{"text":"boxes","ipa":"/ˈbɒksɪz/"},{"text":"classes","ipa":"/ˈklæsɪz/"}],"student_feedback":"En boxes y classes se escucha una sílaba extra; no la elimines."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Volunteer","text":"How many cups do we need?"},{"speaker":"Organizer","text":"We need six cups and six plates."},{"speaker":"Volunteer","text":"Are the boxes ready?"},{"speaker":"Organizer","text":"Yes, the boxes are ready. The dishes are clean."},{"speaker":"Volunteer","text":"Great. The classes can start."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Preparing the meeting table","text":"The volunteers prepare a table. They put six cups, six plates and two boxes on it. The boxes contain clean dishes. They check the lists before the meeting starts.","interactive_vocabulary":["volunteer","prepare","contain","clean","before"],"questions":[{"prompt":"How many cups are on the table?","options":["Six","Two","Eight"],"answer":"Six"},{"prompt":"What do the boxes contain?","options":["Clean dishes","Books","Tickets"],"answer":"Clean dishes"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Preparar una mesa y comprobar una lista de objetos para una reunión.","communication_goal":"El estudiante puede formar y reconocer plurales regulares frecuentes al describir objetos cotidianos.","activities":[{"id":"A1-M1-T05-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es la organizadora. Informa qué materiales hay y cuáles faltan.","role":"event organizer","student_goal":"Report plural objects and quantities using natural classroom or event vocabulary.","allowed_support":["checklist","object pictures","sentence starter","Spanish hint"],"success_criteria":["reports three plural nouns","uses quantities","says one item is missing"],"feedback_correct":"Usaste plurales para resolver una tarea de organización.","feedback_incorrect":"Cuenta primero y luego forma el plural: two boxes, six cups, clean dishes.","estimated_seconds":180,"prompt":"La IA es la organizadora. Informa qué materiales hay y cuáles faltan.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T05-L03"},{"id":"A1-M1-T05-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Prepara una lista hablada para una reunión: cuatro objetos y sus cantidades.","prompt":"We need ___ cups, ___ boxes, ___ plates and ___ dishes.","response_type":"open_speech_or_text","evaluation_criteria":["uses plural spelling or speech","uses four quantities","communicates a useful list"],"feedback_correct":"Aplicaste plurales y cantidades a una tarea real.","feedback_incorrect":"Revisa si cada objeto necesita -s o -es y comprueba la terminación oral.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T05-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para un inventario, combina número + sustantivo singular o plural. Usa there is con uno y there are con más de uno. Recuerda plurales regulares como chairs y boxes e irregulares como people y children.","communication_goal":"El estudiante puede hacer un inventario oral y escrito usando cantidades, plurales regulares e irregulares y there is/there are.","language_focus":["There is one...","There are three...","There are two people.","The boxes are ready.","There is a problem.","We need more chairs."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Let''s check the inventory.","meaning_es":"inventario"},{"english":"We need more chairs.","meaning_es":"silla"},{"english":"There are two tables.","meaning_es":"mesa"},{"english":"There are five people.","meaning_es":"persona / personas"},{"english":"The children are ready.","meaning_es":"niño / niños"},{"english":"Two chairs are missing.","meaning_es":"que falta"}],"dialogue":[{"speaker":"Coordinator","text":"Let''s check the inventory. How many tables are there?"},{"speaker":"Volunteer","text":"There are two tables and twelve chairs."},{"speaker":"Coordinator","text":"How many people are here?"},{"speaker":"Volunteer","text":"There are eight people and two children."},{"speaker":"Coordinator","text":"Are the boxes ready?"},{"speaker":"Volunteer","text":"Yes, but two chairs are missing."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Comunicar cantidades y plurales con ritmo claro en una lista y un reporte de problema.","models":[{"text":"There are twelve chairs.","stress":["twelve","chairs"]},{"text":"There are eight people.","stress":["eight","people"]},{"text":"Two chairs are missing.","stress":["two","chairs","missing"]}],"student_feedback":"Haz audibles los números y las terminaciones plurales; no aceleres la lista."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Coordinator","text":"Let''s check the inventory. How many tables are there?"},{"speaker":"Volunteer","text":"There are two tables and twelve chairs."},{"speaker":"Coordinator","text":"How many people are here?"},{"speaker":"Volunteer","text":"There are eight people and two children."},{"speaker":"Coordinator","text":"Are the boxes ready?"},{"speaker":"Volunteer","text":"Yes, but two chairs are missing."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Before the workshop","text":"Before the workshop, a volunteer checks the room. There are two tables and twelve chairs. There are eight people and two children. The boxes are ready, but two chairs are missing. The volunteer tells the coordinator about the problem.","interactive_vocabulary":["before","workshop","checks","missing","problem"],"questions":[{"prompt":"How many chairs are there at first?","options":["Twelve","Two","Eight"],"answer":"Twelve"},{"prompt":"What is missing?","options":["Two chairs","Two tables","Two children"],"answer":"Two chairs"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Comprobar una sala antes de abrir un evento y reportar qué personas y objetos están presentes.","communication_goal":"El estudiante puede hacer un inventario oral y escrito usando cantidades, plurales regulares e irregulares y there is/there are.","activities":[{"id":"A1-M1-T05-L04-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es el coordinador. Haz un inventario de una sala y reporta un objeto que falta.","role":"event coordinator","student_goal":"Report quantities, use regular and irregular plurals, and identify a missing item.","allowed_support":["room image","inventory checklist","sentence starter","Spanish hint"],"success_criteria":["reports four quantities","uses people or children","uses there is/are","reports a problem"],"feedback_correct":"Completaste una tarea real de inventario y resolución de problemas.","feedback_incorrect":"Cuenta, forma el plural y usa there are para cantidades mayores que uno.","estimated_seconds":230,"prompt":"La IA es el coordinador. Haz un inventario de una sala y reporta un objeto que falta.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T05-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","mastery_assessment"],"topic_ready_when":"El estudiante entrega un inventario comprensible con al menos 80% de precisión y usa un plural irregular correctamente.","retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"En inglés, el adjetivo normalmente va antes del sustantivo: a big room, a friendly teacher. También puede ir después de to be: The room is big. Los adjetivos no cambian por género ni plural: a small table, small tables.","communication_goal":"El estudiante puede describir personas y objetos con adjetivos básicos en frases sencillas.","language_focus":["a big room","a small table","a friendly teacher","The room is quiet.","The bag is blue."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"a big room","meaning_es":"grande"},{"english":"a small table","meaning_es":"pequeño / pequeña"},{"english":"a new bag","meaning_es":"nuevo / nueva"},{"english":"an old book","meaning_es":"viejo / vieja"},{"english":"The room is quiet.","meaning_es":"tranquilo / tranquila"},{"english":"a friendly teacher","meaning_es":"amable"},{"english":"The bag is blue.","meaning_es":"azul"}],"dialogue":[{"speaker":"Friend","text":"How is your new classroom?"},{"speaker":"Student","text":"It''s a big, bright room."},{"speaker":"Friend","text":"Is the teacher friendly?"},{"speaker":"Student","text":"Yes, she is very friendly. The tables are small."},{"speaker":"Friend","text":"What color is your bag?"},{"speaker":"Student","text":"It''s blue and new."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir el adjetivo antes del sustantivo y después de be con ritmo claro.","models":[{"text":"a big room","stress":["big","room"]},{"text":"a friendly teacher","stress":["friendly","teacher"]},{"text":"The bag is blue.","stress":["bag","blue"]}],"student_feedback":"El adjetivo no debe desaparecer; enfatízalo cuando aporta la información principal."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Friend","text":"How is your new classroom?"},{"speaker":"Student","text":"It''s a big, bright room."},{"speaker":"Friend","text":"Is the teacher friendly?"},{"speaker":"Student","text":"Yes, she is very friendly. The tables are small."},{"speaker":"Friend","text":"What color is your bag?"},{"speaker":"Student","text":"It''s blue and new."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"My new classroom","text":"My new classroom is big and bright. The tables are small, but the room is comfortable. My teacher is friendly. I have a new blue bag and an old book.","interactive_vocabulary":["classroom","bright","comfortable","teacher","old book"],"questions":[{"prompt":"What is the classroom like?","options":["Big and bright","Small and dark","Old and noisy"],"answer":"Big and bright"},{"prompt":"What color is the bag?","options":["Blue","Green","Red"],"answer":"Blue"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Describir una habitación y a las personas que están en ella.","communication_goal":"El estudiante puede describir personas y objetos con adjetivos básicos en frases sencillas.","activities":[{"id":"A1-M1-T06-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA está buscando una sala. Descríbele dos personas y tres objetos.","role":"visitor","student_goal":"Describe people and objects with adjectives before and after nouns.","allowed_support":["picture cards","adjective bank","sentence starter","Spanish hint"],"success_criteria":["uses three adjectives","describes two objects","answers one follow-up question"],"feedback_correct":"Describiste una escena usando detalles útiles.","feedback_incorrect":"Usa artículo + adjetivo + sustantivo o sujeto + be + adjetivo.","estimated_seconds":180,"prompt":"La IA está buscando una sala. Descríbele dos personas y tres objetos.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T06-L01"},{"id":"A1-M1-T06-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe un objeto importante para ti con tres adjetivos.","prompt":"I have a ____. It is ____, ____ and ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses three relevant adjectives","uses adjective after be","communicates a clear description"],"feedback_correct":"Usaste adjetivos para comunicar información personal.","feedback_incorrect":"Elige adjetivos que describan tamaño, color, edad o estado.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T06-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Los adjetivos pueden combinarse para dar una descripción más precisa: a small red bag, a large black phone. Cuando describimos el estado o apariencia después de be, usamos sujeto + be + adjetivo: The bag is red.","communication_goal":"El estudiante puede identificar objetos y personas usando color, tamaño y apariencia básica.","language_focus":["a red bag","a large black phone","The bag is under the chair.","It is small and blue.","The woman is tall."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"a red bag","meaning_es":"rojo / roja"},{"english":"a black phone","meaning_es":"negro / negra"},{"english":"a white shirt","meaning_es":"blanco / blanca"},{"english":"a large phone","meaning_es":"grande"},{"english":"The woman is tall.","meaning_es":"alto / alta"},{"english":"The man is short.","meaning_es":"bajo / baja"},{"english":"My phone is lost.","meaning_es":"perdido / perdida"}],"dialogue":[{"speaker":"Staff member","text":"What does your bag look like?"},{"speaker":"Passenger","text":"It''s a small red bag."},{"speaker":"Staff member","text":"Is it under the chair?"},{"speaker":"Passenger","text":"No, it is a large black bag. It has a white label."},{"speaker":"Staff member","text":"I see it. The black bag is next to the door."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir grupos de adjetivos con pausas naturales y destacar la característica que diferencia el objeto.","models":[{"text":"a small red bag","stress":["small","red","bag"]},{"text":"a large black bag","stress":["large","black","bag"]},{"text":"The black bag is next to the door.","stress":["black","next","door"]}],"student_feedback":"No añadas terminaciones de plural a los adjetivos: red bags, no reds bags."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Staff member","text":"What does your bag look like?"},{"speaker":"Passenger","text":"It''s a small red bag."},{"speaker":"Staff member","text":"Is it under the chair?"},{"speaker":"Passenger","text":"No, it is a large black bag. It has a white label."},{"speaker":"Staff member","text":"I see it. The black bag is next to the door."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A lost bag","text":"A passenger loses a bag at the station. The bag is small and red. It has a white label. A staff member finds a large black bag near the door, but it is not the passenger''s bag. The passenger continues looking.","interactive_vocabulary":["passenger","loses","station","label","continues"],"questions":[{"prompt":"What color is the lost bag?","options":["Red","Black","White"],"answer":"Red"},{"prompt":"Is the large black bag the correct bag?","options":["No","Yes","The text does not say"],"answer":"No"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Encontrar un objeto perdido mediante una descripción.","communication_goal":"El estudiante puede identificar objetos y personas usando color, tamaño y apariencia básica.","activities":[{"id":"A1-M1-T06-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA trabaja en objetos perdidos. Describe tu objeto y responde preguntas de color, tamaño y ubicación.","role":"lost-and-found staff member","student_goal":"Give enough adjectives and location information to identify an object.","allowed_support":["adjective bank","object images","sentence starter","Spanish hint"],"success_criteria":["uses color","uses size","gives location","confirms or rejects an object"],"feedback_correct":"Tu descripción contiene información suficiente para encontrar el objeto.","feedback_incorrect":"Añade tamaño, color y una ubicación: It''s a small red bag near the door.","estimated_seconds":190,"prompt":"La IA trabaja en objetos perdidos. Describe tu objeto y responde preguntas de color, tamaño y ubicación.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T06-L02"},{"id":"A1-M1-T06-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe un objeto de tu entorno para que otra persona lo encuentre.","prompt":"It''s a ____ ____ ____. It is ____ the ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses two adjectives","keeps natural word order","gives a location","is understandable"],"feedback_correct":"Usaste una descripción concreta para resolver una necesidad.","feedback_incorrect":"Incluye dos adjetivos antes del objeto y una ubicación después de be.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T06-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para hablar de estados y cualidades usamos be + adjetivo: I''m tired, She is happy, They are nervous. En inglés el adjetivo no cambia por género ni número: tired puede acompañar a una persona o a varias.","communication_goal":"El estudiante puede describir estados emocionales y cualidades básicas de personas con cuidado y claridad.","language_focus":["Are you okay?","I''m tired.","She is happy.","He is busy.","We are excited.","They are nervous."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Are you okay?","meaning_es":"bien"},{"english":"I''m tired.","meaning_es":"cansado / cansada"},{"english":"He is busy.","meaning_es":"ocupado / ocupada"},{"english":"She is happy.","meaning_es":"feliz"},{"english":"We are excited.","meaning_es":"emocionado / emocionada"},{"english":"They are nervous.","meaning_es":"nervioso / nerviosa"},{"english":"She is calm.","meaning_es":"tranquilo / tranquila"}],"dialogue":[{"speaker":"Maya","text":"Are you okay, Luis?"},{"speaker":"Luis","text":"I''m a little nervous."},{"speaker":"Maya","text":"That''s normal. We are ready."},{"speaker":"Luis","text":"Thanks. Are the others ready?"},{"speaker":"Maya","text":"Yes, they are calm and prepared."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir preguntas y respuestas emocionales con entonación amable y comprensible.","models":[{"text":"Are you okay?","stress":["okay"],"intonation":"rising"},{"text":"I''m a little nervous.","stress":["little","nervous"]},{"text":"We are ready.","stress":["ready"]}],"student_feedback":"La entonación debe sonar interesada en la pregunta y tranquila en la respuesta."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Maya","text":"Are you okay, Luis?"},{"speaker":"Luis","text":"I''m a little nervous."},{"speaker":"Maya","text":"That''s normal. We are ready."},{"speaker":"Luis","text":"Thanks. Are the others ready?"},{"speaker":"Maya","text":"Yes, they are calm and prepared."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Before the presentation","text":"Luis is nervous before a presentation. Maya asks if he is okay. Luis says he is a little nervous. Maya is calm and supportive. The other coworkers are ready. Soon, everyone is prepared to begin.","interactive_vocabulary":["presentation","before","supportive","coworkers","prepared"],"questions":[{"prompt":"How does Luis feel?","options":["A little nervous","Angry","Very tired"],"answer":"A little nervous"},{"prompt":"How is Maya?","options":["Calm and supportive","Nervous and busy","Not ready"],"answer":"Calm and supportive"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Preguntar cómo está un compañero y responder sobre el propio estado.","communication_goal":"El estudiante puede describir estados emocionales y cualidades básicas de personas con cuidado y claridad.","activities":[{"id":"A1-M1-T06-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu compañero antes de un examen. Pregunta cómo está y comparte tu estado.","role":"classmate","student_goal":"Ask about a feeling, describe your state and respond supportively.","allowed_support":["emotion cards","sentence starter","Spanish hint"],"success_criteria":["asks Are you okay?","uses be plus adjective","responds politely"],"feedback_correct":"Usaste adjetivos para tener una interacción humana y natural.","feedback_incorrect":"Prueba: Are you okay? / I''m... / That''s normal. / We are ready.","estimated_seconds":190,"prompt":"La IA es tu compañero antes de un examen. Pregunta cómo está y comparte tu estado.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T06-L03"},{"id":"A1-M1-T06-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Envía un mensaje de apoyo a alguien antes de una actividad.","prompt":"Are you okay? I''m ____. You are ____. We are ready.","response_type":"open_speech_or_text","evaluation_criteria":["asks a caring question","uses two be + adjective sentences","communicates support"],"feedback_correct":"Usaste el inglés para expresar un estado y apoyar a otra persona.","feedback_incorrect":"Incluye una pregunta, un estado propio y una frase positiva.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T06-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para identificar algo o alguien, combina adjetivos de apariencia, color, tamaño y estado. Puedes usar be + adjetivo, be + wearing + prenda y adjetivo antes del sustantivo: a small black bag.","communication_goal":"El estudiante puede describir personas, objetos y estados para ayudar a otra persona a identificar una escena.","language_focus":["He is tall and friendly.","She is wearing a red jacket.","It is a small black bag.","We are near the entrance.","They are ready."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"He is tall.","meaning_es":"alto / alta"},{"english":"She is friendly.","meaning_es":"amable"},{"english":"She is wearing a red jacket.","meaning_es":"chaqueta"},{"english":"We are near the entrance.","meaning_es":"entrada"},{"english":"He is wearing a blue shirt.","meaning_es":"llevando puesto"},{"english":"The bags are different.","meaning_es":"diferente"}],"dialogue":[{"speaker":"Friend","text":"What does your friend look like?"},{"speaker":"Student","text":"He is tall and friendly. He is wearing a blue shirt."},{"speaker":"Friend","text":"What about his bag?"},{"speaker":"Student","text":"It is a small black bag. We are near the entrance."},{"speaker":"Friend","text":"I see him. They are ready to leave."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir descripciones con dos adjetivos, ropa y ubicación con ritmo claro.","models":[{"text":"He is tall and friendly.","stress":["tall","friendly"]},{"text":"a small black bag","stress":["small","black","bag"]},{"text":"We are near the entrance.","stress":["near","entrance"]}],"student_feedback":"Agrupa la descripción en bloques: persona, objeto y ubicación."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Friend","text":"What does your friend look like?"},{"speaker":"Student","text":"He is tall and friendly. He is wearing a blue shirt."},{"speaker":"Friend","text":"What about his bag?"},{"speaker":"Student","text":"It is a small black bag. We are near the entrance."},{"speaker":"Friend","text":"I see him. They are ready to leave."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Find the person at the event","text":"Nora is looking for her friend at a busy event. Her friend is tall and friendly. He is wearing a blue shirt and has a small black bag. Nora sees a tall man near the entrance, but his bag is red. She continues looking for the person with the blue shirt and black bag.","interactive_vocabulary":["looking for","busy event","wearing","continues","person"],"questions":[{"prompt":"What color is the correct shirt?","options":["Blue","Red","Black"],"answer":"Blue"},{"prompt":"Why is the tall man near the entrance not the correct person?","options":["His bag is red","He is not tall","He is not at the event"],"answer":"His bag is red"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Describir una persona y sus objetos en un punto de encuentro.","communication_goal":"El estudiante puede describir personas, objetos y estados para ayudar a otra persona a identificar una escena.","activities":[{"id":"A1-M1-T06-L04-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu amigo perdido en un evento. Descríbele a la persona que buscas y responde sus preguntas.","role":"friend at an event","student_goal":"Give a multi-detail description and confirm whether a candidate matches.","allowed_support":["adjective bank","candidate cards","sentence starter","Spanish hint"],"success_criteria":["describes appearance","describes clothing or object","gives location","rejects or confirms a candidate"],"feedback_correct":"Usaste descripciones para resolver un problema comunicativo.","feedback_incorrect":"Incluye altura o cualidad, ropa, objeto y ubicación.","estimated_seconds":220,"prompt":"La IA es tu amigo perdido en un evento. Descríbele a la persona que buscas y responde sus preguntas.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T06-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","mastery_assessment"],"topic_ready_when":"El estudiante describe una persona y un objeto con detalles suficientes y al menos 80% de precisión.","retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"My indica que algo pertenece a la persona que habla; your indica que pertenece a la persona a la que hablas. Van antes del sustantivo: my book, your phone. No cambian por singular o plural: my book, my books.","communication_goal":"El estudiante puede decir qué pertenece a sí mismo o a su interlocutor usando my y your.","language_focus":["This is my book.","Is this your pen?","Yes, it''s my pen.","No, it''s not my bag.","Your phone is here."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"This is my book.","meaning_es":"mi / mis"},{"english":"Is this your pen?","meaning_es":"tu / su / sus"},{"english":"My book is blue.","meaning_es":"libro"},{"english":"Your pen is here.","meaning_es":"bolígrafo"},{"english":"Is this your phone?","meaning_es":"teléfono"},{"english":"Does this belong to you?","meaning_es":"pertenecer"}],"dialogue":[{"speaker":"Ana","text":"Is this your book?"},{"speaker":"Luis","text":"No, it isn''t my book. My book is red."},{"speaker":"Ana","text":"Is this your phone?"},{"speaker":"Luis","text":"Yes, it''s my phone. Your pen is next to it."},{"speaker":"Ana","text":"Thanks. Let''s return the other things."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir my y your dentro de preguntas y respuestas sobre pertenencias.","models":[{"text":"my","ipa":"/maɪ/"},{"text":"your","ipa":"/jʊr/"},{"text":"Is this your phone?","stress":["your","phone"],"intonation":"rising"},{"text":"It''s my phone.","stress":["my","phone"]}],"student_feedback":"El posesivo debe escucharse porque cambia de quién es el objeto."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Ana","text":"Is this your book?"},{"speaker":"Luis","text":"No, it isn''t my book. My book is red."},{"speaker":"Ana","text":"Is this your phone?"},{"speaker":"Luis","text":"Yes, it''s my phone. Your pen is next to it."},{"speaker":"Ana","text":"Thanks. Let''s return the other things."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"After class","text":"After class, Ana and Luis find a book, a phone and two pens. Ana asks Luis about the book. It is not his book. Then Luis finds his phone. Ana finds her pens next to the chair. They return the objects to their owners.","interactive_vocabulary":["after class","find","owners","return","next to"],"questions":[{"prompt":"What does Luis find?","options":["His phone","Her pens","A new chair"],"answer":"His phone"},{"prompt":"Where are the pens?","options":["Next to the chair","On the desk at home","In Luis''s phone"],"answer":"Next to the chair"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Identificar pertenencias en un aula compartida.","communication_goal":"El estudiante puede decir qué pertenece a sí mismo o a su interlocutor usando my y your.","activities":[{"id":"A1-M1-T07-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu compañero de clase. Encuentren a quién pertenecen tres objetos.","role":"classmate","student_goal":"Ask Is this your...? and answer with my or not my.","allowed_support":["object cards","sentence starter","Spanish hint"],"success_criteria":["asks about two objects","answers with my","rejects one object politely"],"feedback_correct":"Resolviste una tarea real de pertenencias.","feedback_incorrect":"Usa Is this your...? y responde Yes, it''s my... o No, it isn''t my...","estimated_seconds":180,"prompt":"La IA es tu compañero de clase. Encuentren a quién pertenecen tres objetos.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T07-L01"},{"id":"A1-M1-T07-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe dos objetos tuyos y pregunta por uno de otra persona.","prompt":"This is my ____. This is my ____. Is this your ____?","response_type":"open_speech_or_text","evaluation_criteria":["uses my twice","uses your in a question","communicates ownership clearly"],"feedback_correct":"Usaste posesivos para resolver una situación cotidiana.","feedback_incorrect":"My habla de tus objetos; your aparece al preguntar por el objeto de otra persona.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T07-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"His significa de él y her significa de ella. El posesivo depende del dueño, no del género del objeto: his jacket si el dueño es un hombre; her jacket si la dueña es una mujer.","communication_goal":"El estudiante puede decir a quién pertenece un objeto cuando el dueño es otra persona.","language_focus":["This is his wallet.","That is her jacket.","His phone is black.","Her bag is red.","Is this his?","Is this hers?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"This is his wallet.","meaning_es":"su / de él"},{"english":"That is her jacket.","meaning_es":"su / de ella"},{"english":"His wallet is black.","meaning_es":"billetera"},{"english":"Her jacket is red.","meaning_es":"chaqueta"},{"english":"Her keys are here.","meaning_es":"llaves"},{"english":"Find the owner.","meaning_es":"dueño / dueña"}],"dialogue":[{"speaker":"Receptionist","text":"Is this Daniel''s wallet?"},{"speaker":"Maya","text":"Yes, it''s his wallet. His phone is inside, too."},{"speaker":"Receptionist","text":"And whose jacket is this?"},{"speaker":"Maya","text":"It''s Sofia''s. It''s her jacket."},{"speaker":"Receptionist","text":"Great. Let''s return his and her things."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir his y her dentro de frases sobre pertenencias.","models":[{"text":"his","ipa":"/hɪz/"},{"text":"her","ipa":"/hɜːr/"},{"text":"His phone is black.","stress":["His","phone","black"]},{"text":"Her jacket is red.","stress":["Her","jacket","red"]}],"student_feedback":"Marca el dueño con his o her; la descripción del objeto no cambia el posesivo."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Receptionist","text":"Is this Daniel''s wallet?"},{"speaker":"Maya","text":"Yes, it''s his wallet. His phone is inside, too."},{"speaker":"Receptionist","text":"And whose jacket is this?"},{"speaker":"Maya","text":"It''s Sofia''s. It''s her jacket."},{"speaker":"Receptionist","text":"Great. Let''s return his and her things."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Lost belongings","text":"Daniel and Sofia leave a meeting room. Daniel cannot find his wallet. Sofia cannot find her keys. A receptionist finds a black wallet and a set of keys on a chair. The wallet is his and the keys are hers.","interactive_vocabulary":["belongings","leave","cannot find","set of keys","hers"],"questions":[{"prompt":"What cannot Daniel find?","options":["His wallet","Her keys","His jacket"],"answer":"His wallet"},{"prompt":"Whose keys are on the chair?","options":["Sofia''s","Daniel''s","The receptionist''s"],"answer":"Sofia''s"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Entregar objetos encontrados a dos compañeros.","communication_goal":"El estudiante puede decir a quién pertenece un objeto cuando el dueño es otra persona.","activities":[{"id":"A1-M1-T07-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es recepcionista. Identifica los objetos de Daniel y Sofia y entrégaselos.","role":"receptionist","student_goal":"Use his and her to return two belongings to their owners.","allowed_support":["owner cards","object cards","sentence starter","Spanish hint"],"success_criteria":["uses his for one man","uses her for one woman","returns two correct objects"],"feedback_correct":"Identificaste correctamente a los dueños y sus pertenencias.","feedback_incorrect":"Mira primero quién es el dueño y luego usa his o her.","estimated_seconds":180,"prompt":"La IA es recepcionista. Identifica los objetos de Daniel y Sofia y entrégaselos.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T07-L02"},{"id":"A1-M1-T07-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe dos objetos de dos personas que conoces.","prompt":"This is ____''s ____. It is his/her ____. This is ____''s ____. It is his/her ____.","response_type":"open_speech_or_text","evaluation_criteria":["identifies two owners","uses his and her appropriately","communicates two belongings"],"feedback_correct":"Usaste posesivos para hablar de personas reales.","feedback_incorrect":"Elige his o her según el dueño, no según el objeto.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T07-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Our indica que algo pertenece al grupo que incluye al hablante. Their indica que pertenece a otro grupo. Van antes del sustantivo y no cambian por singular o plural: our room, our rooms; their bag, their bags.","communication_goal":"El estudiante puede identificar pertenencias de su grupo y de otros grupos usando our y their.","language_focus":["This is our table.","These are our materials.","That is their room.","Their bags are here.","Where are our keys?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"This is our table.","meaning_es":"nuestro / nuestra / nuestros / nuestras"},{"english":"Their bags are here.","meaning_es":"su / de ellos / de ellas"},{"english":"Our materials are ready.","meaning_es":"materiales"},{"english":"Their room is upstairs.","meaning_es":"sala / habitación"},{"english":"Our team is ready.","meaning_es":"equipo"},{"english":"Where are our keys?","meaning_es":"llaves"}],"dialogue":[{"speaker":"Leader","text":"Are these our materials?"},{"speaker":"Maya","text":"Yes, these are our materials. Our team is ready."},{"speaker":"Leader","text":"Where are the other team''s bags?"},{"speaker":"Maya","text":"Their bags are in their room."},{"speaker":"Leader","text":"Great. Our room is ready, too."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir our y their, especialmente their frente a they''re.","models":[{"text":"our","ipa":"/aʊər/"},{"text":"their","ipa":"/ðer/"},{"text":"Our team is ready.","stress":["our","team","ready"]},{"text":"Their bags are here.","stress":["their","bags","here"]}],"student_feedback":"Enfatiza our o their cuando necesitas aclarar qué grupo es el dueño."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Leader","text":"Are these our materials?"},{"speaker":"Maya","text":"Yes, these are our materials. Our team is ready."},{"speaker":"Leader","text":"Where are the other team''s bags?"},{"speaker":"Maya","text":"Their bags are in their room."},{"speaker":"Leader","text":"Great. Our room is ready, too."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Two workshop rooms","text":"Our team is in Room A. Our materials are on the table. The other team is in Room B. Their materials are in boxes. Our room is small, but their room is large. Both teams are ready.","interactive_vocabulary":["workshop","other team","boxes","both","large"],"questions":[{"prompt":"Where are our materials?","options":["On the table in Room A","In Room B","Outside"],"answer":"On the table in Room A"},{"prompt":"Which room is large?","options":["Their room","Our room","Both rooms"],"answer":"Their room"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Organizar materiales de dos equipos antes de una actividad.","communication_goal":"El estudiante puede identificar pertenencias de su grupo y de otros grupos usando our y their.","activities":[{"id":"A1-M1-T07-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es la líder de otro equipo. Comparen sus materiales y habitaciones.","role":"other team leader","student_goal":"Use our and their to compare group belongings and locations.","allowed_support":["team cards","room map","sentence starter","Spanish hint"],"success_criteria":["describes own team''s items with our","describes other team''s items with their","answers one ownership question"],"feedback_correct":"Comparaste pertenencias de dos grupos con claridad.","feedback_incorrect":"Tu grupo = our; el otro grupo = their.","estimated_seconds":180,"prompt":"La IA es la líder de otro equipo. Comparen sus materiales y habitaciones.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T07-L03"},{"id":"A1-M1-T07-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe tu equipo y otro equipo antes de una actividad.","prompt":"Our ____ is ____. Their ____ is ____. Our materials are ____. Their materials are ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses our for own group","uses their for another group","describes two belongings or locations"],"feedback_correct":"Usaste posesivos para coordinar grupos reales.","feedback_incorrect":"Comprueba si el hablante pertenece al grupo antes de escoger our o their.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T07-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Los posesivos indican quién tiene o posee algo: my/your para hablante e interlocutor, his/her para una persona, our para el grupo del hablante y their para otro grupo. El posesivo se elige por el dueño, no por el objeto.","communication_goal":"El estudiante puede identificar pertenencias propias, de otras personas y de grupos usando my, your, his, her, our y their.","language_focus":["This is my...","Is this your...?","It''s his/her...","These are our...","Those are their...","Whose is this?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"The lost-and-found desk is here.","meaning_es":"objetos perdidos"},{"english":"Find the owner.","meaning_es":"dueño / dueña"},{"english":"Her scarf is blue.","meaning_es":"bufanda"},{"english":"His backpack is black.","meaning_es":"mochila"},{"english":"Our equipment is ready.","meaning_es":"equipo / material"},{"english":"Whose bag is this?","meaning_es":"de quién"}],"dialogue":[{"speaker":"Maya","text":"Whose backpack is this?"},{"speaker":"Leo","text":"It''s his backpack. It belongs to Daniel."},{"speaker":"Maya","text":"And is this Sofia''s scarf?"},{"speaker":"Leo","text":"Yes, it''s her scarf."},{"speaker":"Maya","text":"These are our boxes, but those are their boxes."},{"speaker":"Leo","text":"Great. Let''s return everything."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir preguntas y respuestas de pertenencia con énfasis claro en el posesivo.","models":[{"text":"Whose backpack is this?","stress":["Whose","backpack"],"intonation":"rising"},{"text":"It''s his backpack.","stress":["his","backpack"]},{"text":"These are our boxes.","stress":["our","boxes"]},{"text":"Those are their boxes.","stress":["their","boxes"]}],"student_feedback":"Haz audible la palabra que identifica al dueño; esa es la información que resuelve la búsqueda."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Maya","text":"Whose backpack is this?"},{"speaker":"Leo","text":"It''s his backpack. It belongs to Daniel."},{"speaker":"Maya","text":"And is this Sofia''s scarf?"},{"speaker":"Leo","text":"Yes, it''s her scarf."},{"speaker":"Maya","text":"These are our boxes, but those are their boxes."},{"speaker":"Leo","text":"Great. Let''s return everything."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Sorting the lost things","text":"After the event, Maya and Leo work at the lost-and-found desk. They find Daniel''s black backpack and Sofia''s blue scarf. They put their belongings in separate boxes. The volunteers keep their own equipment in another box.","interactive_vocabulary":["sorting","lost-and-found desk","separate","belongings","own equipment"],"questions":[{"prompt":"Whose backpack do they find?","options":["Daniel''s","Sofia''s","The volunteers''"],"answer":"Daniel''s"},{"prompt":"Where do the volunteers keep their equipment?","options":["In another box","In Daniel''s backpack","On the desk"],"answer":"In another box"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Organizar objetos perdidos después de un evento y devolverlos a sus dueños.","communication_goal":"El estudiante puede identificar pertenencias propias, de otras personas y de grupos usando my, your, his, her, our y their.","activities":[{"id":"A1-M1-T07-L04-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu compañero en objetos perdidos. Pregunta y responde sobre pertenencias de varias personas y equipos.","role":"lost-and-found partner","student_goal":"Ask Whose...? and identify belongings with all relevant possessives.","allowed_support":["owner cards","object cards","sentence starter","Spanish hint"],"success_criteria":["asks Whose","uses his/her","uses our/their","returns three objects"],"feedback_correct":"Resolviste una situación compleja de pertenencias.","feedback_incorrect":"Pregunta Whose...? y responde según el dueño: his, her, our o their.","estimated_seconds":230,"prompt":"La IA es tu compañero en objetos perdidos. Pregunta y responde sobre pertenencias de varias personas y equipos.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T07-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","mastery_assessment"],"topic_ready_when":"El estudiante identifica pertenencias de distintos dueños y usa al menos cuatro posesivos con 80% de precisión.","retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"This señala un objeto singular cerca del hablante. That señala un objeto singular más lejos. Ambos pueden ir antes del sustantivo o funcionar solos: this phone, What is that?.","communication_goal":"El estudiante puede señalar y describir un objeto cercano o lejano usando this y that.","language_focus":["What is this?","This is a phone.","What is that?","That is a lamp.","This book is new.","That bag is blue."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"What is this?","meaning_es":"este / esta / esto"},{"english":"What is that?","meaning_es":"ese / esa / eso"},{"english":"This is a phone.","meaning_es":"teléfono"},{"english":"That is a lamp.","meaning_es":"lámpara"},{"english":"This bag is near me.","meaning_es":"cerca"},{"english":"That lamp is far away.","meaning_es":"lejos"}],"dialogue":[{"speaker":"Customer","text":"What is this?"},{"speaker":"Assistant","text":"This is a small phone case."},{"speaker":"Customer","text":"And what is that over there?"},{"speaker":"Assistant","text":"That is a lamp. It is near the window."},{"speaker":"Customer","text":"I like this case, but I need that lamp."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir this y that y producir el sonido /ð/ de forma comprensible.","models":[{"text":"this","ipa":"/ðɪs/"},{"text":"that","ipa":"/ðæt/"},{"text":"What is this?","stress":["what","this"],"intonation":"rising"},{"text":"That is a lamp.","stress":["that","lamp"]}],"student_feedback":"Coloca suavemente la lengua entre los dientes para el sonido inicial de this y that."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Customer","text":"What is this?"},{"speaker":"Assistant","text":"This is a small phone case."},{"speaker":"Customer","text":"And what is that over there?"},{"speaker":"Assistant","text":"That is a lamp. It is near the window."},{"speaker":"Customer","text":"I like this case, but I need that lamp."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"In the store","text":"This is a small store. A phone case is near the customer. That lamp is at the back of the store. This case is new, but that lamp is old. The customer likes this case and looks at that lamp.","interactive_vocabulary":["store","phone case","at the back","customer","looks at"],"questions":[{"prompt":"Which object is near the customer?","options":["The phone case","The lamp","The store"],"answer":"The phone case"},{"prompt":"Where is the lamp?","options":["At the back of the store","In the customer''s hand","Near the door"],"answer":"At the back of the store"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Preguntar por objetos en una tienda y distinguir los que están cerca de los que están al fondo.","communication_goal":"El estudiante puede señalar y describir un objeto cercano o lejano usando this y that.","activities":[{"id":"A1-M1-T08-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es dependiente de una tienda. Señala objetos cerca y lejos y pregunta qué son.","role":"store assistant","student_goal":"Use this and that to identify two nearby or distant objects.","allowed_support":["store picture","pointing mode","sentence starter","Spanish hint"],"success_criteria":["asks What is this?","asks What is that?","identifies two objects"],"feedback_correct":"Usaste demostrativos para orientar la atención del interlocutor.","feedback_incorrect":"Objeto cercano = this; objeto lejano = that.","estimated_seconds":180,"prompt":"La IA es dependiente de una tienda. Señala objetos cerca y lejos y pregunta qué son.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T08-L01"},{"id":"A1-M1-T08-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Graba un recorrido breve por tu habitación señalando un objeto cerca y otro lejos.","prompt":"This is my ____. That is my ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses this for a nearby item","uses that for a distant item","identifies both objects"],"feedback_correct":"Usaste demostrativos para guiar la atención en un espacio real.","feedback_incorrect":"Mira la distancia: en tu mano o cerca = this; al fondo = that.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T08-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"These señala varios objetos cercanos; those señala varios objetos más lejos. Son plurales: these books, those boxes. Por eso usamos are, no is.","communication_goal":"El estudiante puede señalar varios objetos cercanos o lejanos usando these y those.","language_focus":["These are my books.","Those are your bags.","What are these?","What are those?","These chairs are new.","Those boxes are old."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"These are my books.","meaning_es":"estos / estas"},{"english":"Those are your bags.","meaning_es":"esos / esas"},{"english":"These books are new.","meaning_es":"libros"},{"english":"Those bags are old.","meaning_es":"bolsos / bolsas"},{"english":"These chairs are clean.","meaning_es":"sillas"},{"english":"Those boxes are heavy.","meaning_es":"cajas"}],"dialogue":[{"speaker":"Teacher","text":"What are these?"},{"speaker":"Student","text":"These are new books."},{"speaker":"Teacher","text":"And what are those near the door?"},{"speaker":"Student","text":"Those are old boxes."},{"speaker":"Teacher","text":"Please put these books on the table."},{"speaker":"Student","text":"Okay. Those boxes can stay near the door."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir this/these y that/those en frases plurales.","models":[{"text":"these","ipa":"/ðiːz/"},{"text":"those","ipa":"/ðoʊz/"},{"text":"These are new books.","stress":["these","new books"]},{"text":"Those are old boxes.","stress":["those","old boxes"]}],"student_feedback":"Haz audible el plural del demostrativo y del sustantivo cuando corresponda."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Teacher","text":"What are these?"},{"speaker":"Student","text":"These are new books."},{"speaker":"Teacher","text":"And what are those near the door?"},{"speaker":"Student","text":"Those are old boxes."},{"speaker":"Teacher","text":"Please put these books on the table."},{"speaker":"Student","text":"Okay. Those boxes can stay near the door."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Two sides of the classroom","text":"These books are on the teacher''s table. They are new. Those boxes are near the door. They are old and heavy. These chairs are for the students, but those chairs are for visitors.","interactive_vocabulary":["teacher''s table","heavy","visitors","for","students"],"questions":[{"prompt":"Where are the new books?","options":["On the teacher''s table","Near the door","Outside"],"answer":"On the teacher''s table"},{"prompt":"Who are the distant chairs for?","options":["Visitors","Students","The teacher"],"answer":"Visitors"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Organizar materiales cercanos y reconocer objetos al otro lado de una sala.","communication_goal":"El estudiante puede señalar varios objetos cercanos o lejanos usando these y those.","activities":[{"id":"A1-M1-T08-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es una profesora. Clasifica materiales cercanos y lejanos usando these y those.","role":"teacher","student_goal":"Identify groups of nearby and distant objects using these/those.","allowed_support":["classroom map","pointing mode","sentence starter","Spanish hint"],"success_criteria":["uses these for nearby plural","uses those for distant plural","answers one What are...? question"],"feedback_correct":"Organizaste grupos de materiales con demostrativos correctos.","feedback_incorrect":"Varios cerca = these; varios lejos = those.","estimated_seconds":180,"prompt":"La IA es una profesora. Clasifica materiales cercanos y lejanos usando these y those.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T08-L02"},{"id":"A1-M1-T08-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Haz un recorrido por tu espacio y señala un grupo cercano y otro lejano.","prompt":"These are my ____. Those are my ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses these for nearby plural","uses those for distant plural","identifies two groups"],"feedback_correct":"Usaste demostrativos plurales para orientar a otra persona.","feedback_incorrect":"Comprueba que hay varios objetos y mira su distancia.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T08-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Los demostrativos combinan cantidad y distancia: this = uno cerca, that = uno lejos, these = varios cerca, those = varios lejos. Con this/that puedes usar one para no repetir el sustantivo.","communication_goal":"El estudiante puede elegir y comparar objetos según su distancia y cantidad.","language_focus":["I like this one.","I want that one.","These are cheaper.","Those are expensive.","What are these?","How much are those?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I like this one.","meaning_es":"uno / una"},{"english":"These are cheaper.","meaning_es":"más barato / barata"},{"english":"Those are expensive.","meaning_es":"caro / cara"},{"english":"What''s the price?","meaning_es":"precio"},{"english":"These are a pair of shoes.","meaning_es":"par"},{"english":"Those are over there.","meaning_es":"allí / por allí"}],"dialogue":[{"speaker":"Customer","text":"What are these?"},{"speaker":"Assistant","text":"These are new notebooks."},{"speaker":"Customer","text":"I like this one. How much is it?"},{"speaker":"Assistant","text":"It''s five dollars."},{"speaker":"Customer","text":"And what are those over there?"},{"speaker":"Assistant","text":"Those are older notebooks. They are cheaper."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir los cuatro demostrativos en preguntas y decisiones de compra.","models":[{"text":"this one","stress":["this","one"]},{"text":"that one","stress":["that","one"]},{"text":"these are cheaper","stress":["these","cheaper"]},{"text":"those are expensive","stress":["those","expensive"]}],"student_feedback":"La forma del demostrativo ayuda al interlocutor a localizar exactamente el producto."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Customer","text":"What are these?"},{"speaker":"Assistant","text":"These are new notebooks."},{"speaker":"Customer","text":"I like this one. How much is it?"},{"speaker":"Assistant","text":"It''s five dollars."},{"speaker":"Customer","text":"And what are those over there?"},{"speaker":"Assistant","text":"Those are older notebooks. They are cheaper."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"At the notebook store","text":"A customer looks at notebooks. These notebooks are new and bright. That notebook near the register is special. Those notebooks on the high shelf are older, but they are cheaper. The customer chooses this one.","interactive_vocabulary":["bright","register","special","high shelf","chooses"],"questions":[{"prompt":"Where are the older notebooks?","options":["On the high shelf","Near the register","In the customer''s bag"],"answer":"On the high shelf"},{"prompt":"Which notebook does the customer choose?","options":["This one","That one near the register","Those on the high shelf"],"answer":"This one"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Elegir productos en una tienda y pedir información sobre objetos cercanos y lejanos.","communication_goal":"El estudiante puede elegir y comparar objetos según su distancia y cantidad.","activities":[{"id":"A1-M1-T08-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es dependiente de una tienda. Pregunta por cuatro productos y elige uno.","role":"store assistant","student_goal":"Ask about nearby and distant singular/plural products and make a choice.","allowed_support":["store image","price tags","sentence starter","Spanish hint"],"success_criteria":["asks two What is/are questions","uses this/that/these/those","chooses one item"],"feedback_correct":"Usaste demostrativos para comprar y tomar una decisión.","feedback_incorrect":"Uno cerca = this; uno lejos = that; varios cerca = these; varios lejos = those.","estimated_seconds":200,"prompt":"La IA es dependiente de una tienda. Pregunta por cuatro productos y elige uno.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T08-L03"},{"id":"A1-M1-T08-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Elige tres objetos de una imagen: uno cercano, uno lejano y un grupo cercano o lejano.","prompt":"I want this ____. I don''t want that ____. These/Those are ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses singular near","uses singular far","uses plural demonstrative","communicates a preference"],"feedback_correct":"Usaste demostrativos para expresar una elección real.","feedback_incorrect":"Separa las decisiones por cantidad y distancia antes de hablar.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T08-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para elegir correctamente, identifica dos cosas: uno o varios objetos, y cerca o lejos. Luego selecciona this, that, these o those y usa is para singular o are para plural.","communication_goal":"El estudiante puede señalar objetos singulares y plurales, cercanos y lejanos, para orientar a otra persona.","language_focus":["This is...","That is...","These are...","Those are...","What is this?","What are those?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"The visitor is here.","meaning_es":"visitante"},{"english":"That is the entrance.","meaning_es":"entrada"},{"english":"This is a sign.","meaning_es":"letrero / señal"},{"english":"These are the materials.","meaning_es":"materiales"},{"english":"Those are the shelves.","meaning_es":"estantes"},{"english":"The chairs are nearby.","meaning_es":"cercano"}],"dialogue":[{"speaker":"Visitor","text":"What is this?"},{"speaker":"Guide","text":"This is the information desk."},{"speaker":"Visitor","text":"What is that at the entrance?"},{"speaker":"Guide","text":"That is the sign for Room 2."},{"speaker":"Visitor","text":"What are these?"},{"speaker":"Guide","text":"These are the workshop materials."},{"speaker":"Visitor","text":"And what are those near the window?"},{"speaker":"Guide","text":"Those are the shelves."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Usar los cuatro demostrativos en una orientación continua y comprensible.","models":[{"text":"This is the desk.","stress":["this","desk"]},{"text":"That is the entrance.","stress":["that","entrance"]},{"text":"These are the materials.","stress":["these","materials"]},{"text":"Those are the shelves.","stress":["those","shelves"]}],"student_feedback":"La prioridad es que el visitante sepa qué objeto señalas y a qué distancia está."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Visitor","text":"What is this?"},{"speaker":"Guide","text":"This is the information desk."},{"speaker":"Visitor","text":"What is that at the entrance?"},{"speaker":"Guide","text":"That is the sign for Room 2."},{"speaker":"Visitor","text":"What are these?"},{"speaker":"Guide","text":"These are the workshop materials."},{"speaker":"Visitor","text":"And what are those near the window?"},{"speaker":"Guide","text":"Those are the shelves."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A guide to the center","text":"This is the entrance desk. That is the sign for Room 2. These are the materials for the workshop. Those are the shelves near the window. The visitor thanks the guide because the directions are clear.","interactive_vocabulary":["entrance desk","directions","clear","workshop","shelves"],"questions":[{"prompt":"What is the sign for?","options":["Room 2","The window","The desk"],"answer":"Room 2"},{"prompt":"Where are the shelves?","options":["Near the window","At the entrance desk","Outside"],"answer":"Near the window"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Ayudar a un visitante a encontrar materiales dentro de una sala grande.","communication_goal":"El estudiante puede señalar objetos singulares y plurales, cercanos y lejanos, para orientar a otra persona.","activities":[{"id":"A1-M1-T08-L04-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es un visitante. Oriéntala por una sala usando los cuatro demostrativos.","role":"visitor","student_goal":"Give clear directions using this, that, these and those.","allowed_support":["room map","pointing mode","sentence starter","Spanish hint"],"success_criteria":["uses all four when relevant","matches is/are","answers two questions"],"feedback_correct":"Orientaste a otra persona con precisión espacial y gramatical.","feedback_incorrect":"Recuerda: this/that + is; these/those + are.","estimated_seconds":230,"prompt":"La IA es un visitante. Oriéntala por una sala usando los cuatro demostrativos.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T08-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","mastery_assessment"],"topic_ready_when":"El estudiante orienta a otra persona usando los cuatro demostrativos con al menos 80% de precisión.","retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"There is presenta una cosa: There is a table. There are presenta varias: There are two chairs. La expresión describe qué existe o se encuentra en un lugar; no es igual que usar there como ubicación.","communication_goal":"El estudiante puede decir qué hay en un espacio usando there is y there are.","language_focus":["There is a table.","There is an armchair.","There are two chairs.","There are books on the shelf.","There is a window."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"There is a table.","meaning_es":"hay / existe uno"},{"english":"There are two chairs.","meaning_es":"hay / existen varios"},{"english":"There is an armchair.","meaning_es":"sillón"},{"english":"There are books on the shelf.","meaning_es":"estante"},{"english":"There is a window.","meaning_es":"ventana"},{"english":"The room is small.","meaning_es":"habitación / sala"}],"dialogue":[{"speaker":"Guest","text":"What''s in the room?"},{"speaker":"Host","text":"There is a table and an armchair."},{"speaker":"Guest","text":"Are there any chairs?"},{"speaker":"Host","text":"Yes, there are two chairs near the window."},{"speaker":"Guest","text":"Great. Is there a shelf?"},{"speaker":"Host","text":"Yes, there is. There are some books on it."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir there is y there are y producir la estructura con ritmo natural.","models":[{"text":"There is a table.","stress":["table"]},{"text":"There are two chairs.","stress":["two","chairs"]},{"text":"Is there a shelf?","intonation":"rising"},{"text":"Are there any chairs?","intonation":"rising"}],"student_feedback":"Haz audible la diferencia entre is y are, especialmente antes de la palabra importante."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Guest","text":"What''s in the room?"},{"speaker":"Host","text":"There is a table and an armchair."},{"speaker":"Guest","text":"Are there any chairs?"},{"speaker":"Host","text":"Yes, there are two chairs near the window."},{"speaker":"Guest","text":"Great. Is there a shelf?"},{"speaker":"Host","text":"Yes, there is. There are some books on it."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The guest room","text":"There is a small table in the guest room. There is an armchair next to the window. There are two chairs near the door. There are books on a shelf. The room is simple and comfortable.","interactive_vocabulary":["guest room","next to","near","door","simple","comfortable"],"questions":[{"prompt":"What is next to the window?","options":["An armchair","Two chairs","A shelf"],"answer":"An armchair"},{"prompt":"How many chairs are near the door?","options":["Two","One","Three"],"answer":"Two"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Describir una habitación a una persona que llega por primera vez.","communication_goal":"El estudiante puede decir qué hay en un espacio usando there is y there are.","activities":[{"id":"A1-M1-T09-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA llega a tu habitación. Descríbele qué hay y dónde está.","role":"guest","student_goal":"Use there is and there are to describe a room with locations.","allowed_support":["room picture","object bank","sentence starter","Spanish hint"],"success_criteria":["uses there is once","uses there are twice","gives two locations"],"feedback_correct":"Describiste un espacio de forma útil para un visitante.","feedback_incorrect":"Cuenta primero: singular = there is; plural = there are.","estimated_seconds":180,"prompt":"La IA llega a tu habitación. Descríbele qué hay y dónde está.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T09-L01"},{"id":"A1-M1-T09-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Haz un tour de audio de tu espacio para una persona que llegará mañana.","prompt":"There is a ____. There are ____. The ____ is near ____. ","response_type":"open_speech_or_text","evaluation_criteria":["uses singular and plural existence","describes two locations","communicates clearly"],"feedback_correct":"Usaste there is/are para orientar a otra persona.","feedback_incorrect":"Incluye una cosa singular, varias cosas y dos ubicaciones.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T09-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para preguntar por una cosa singular usamos Is there...?; para varias usamos Are there...? Las respuestas cortas repiten is o are: Yes, there is; No, there aren''t.","communication_goal":"El estudiante puede preguntar si existe un objeto y responder afirmativa o negativamente.","language_focus":["Is there a bathroom?","Are there any towels?","Yes, there is.","No, there isn''t.","Yes, there are.","No, there aren''t."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Is there a bathroom?","meaning_es":"baño"},{"english":"Are there any towels?","meaning_es":"toalla"},{"english":"There is a shower.","meaning_es":"ducha"},{"english":"Is there wifi?","meaning_es":"wifi"},{"english":"There are two blankets.","meaning_es":"manta"},{"english":"There isn''t one available.","meaning_es":"disponible"}],"dialogue":[{"speaker":"Guest","text":"Is there a bathroom in the room?"},{"speaker":"Host","text":"Yes, there is. It is next to the door."},{"speaker":"Guest","text":"Are there any towels?"},{"speaker":"Host","text":"Yes, there are two towels."},{"speaker":"Guest","text":"Is there wifi?"},{"speaker":"Host","text":"No, there isn''t wifi today."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir preguntas rising y respuestas cortas con there is/are.","models":[{"text":"Is there a bathroom?","stress":["bathroom"],"intonation":"rising"},{"text":"Are there any towels?","stress":["towels"],"intonation":"rising"},{"text":"Yes, there is.","intonation":"falling"},{"text":"No, there aren''t.","intonation":"falling"}],"student_feedback":"Haz clara la diferencia entre singular is y plural are en la pregunta y la respuesta."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Guest","text":"Is there a bathroom in the room?"},{"speaker":"Host","text":"Yes, there is. It is next to the door."},{"speaker":"Guest","text":"Are there any towels?"},{"speaker":"Host","text":"Yes, there are two towels."},{"speaker":"Guest","text":"Is there wifi?"},{"speaker":"Host","text":"No, there isn''t wifi today."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Checking the room","text":"Before the guest arrives, the host checks the room. There is a bathroom and there is a shower. There are two towels and one blanket. There isn''t wifi today, but there is a comfortable chair.","interactive_vocabulary":["arrives","checks","blanket","comfortable","today"],"questions":[{"prompt":"How many towels are there?","options":["Two","One","Three"],"answer":"Two"},{"prompt":"What is not available today?","options":["Wifi","A bathroom","A chair"],"answer":"Wifi"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Comprobar si una habitación tiene los servicios y objetos necesarios.","communication_goal":"El estudiante puede preguntar si existe un objeto y responder afirmativa o negativamente.","activities":[{"id":"A1-M1-T09-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es el anfitrión. Comprueba cinco cosas antes de aceptar una habitación.","role":"host","student_goal":"Ask singular and plural existence questions and understand short answers.","allowed_support":["room checklist","sentence starter","Spanish hint"],"success_criteria":["asks two Is there questions","asks two Are there questions","responds to one negative answer"],"feedback_correct":"Comprobaste servicios y objetos con preguntas naturales.","feedback_incorrect":"Singular: Is there...? Plural: Are there any...?.","estimated_seconds":200,"prompt":"La IA es el anfitrión. Comprueba cinco cosas antes de aceptar una habitación.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T09-L02"},{"id":"A1-M1-T09-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Haz cinco preguntas antes de visitar un lugar nuevo y registra las respuestas.","prompt":"Is there a ____? Are there any ____? Yes, there is/are. No, there isn''t/aren''t.","response_type":"open_speech_or_text","evaluation_criteria":["uses singular and plural questions","uses short answers","communicates practical needs"],"feedback_correct":"Aplicaste la estructura para comprobar un lugar real.","feedback_incorrect":"Clasifica tus necesidades como una cosa o varias antes de preguntar.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T09-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"There isn''t se usa con singular: There isn''t a printer. There aren''t se usa con plural: There aren''t enough chairs. También puedes usar There is no + singular o There are no + plural para decir que no hay.","communication_goal":"El estudiante puede decir qué no hay y explicar qué falta en un espacio.","language_focus":["There isn''t a printer.","There aren''t enough chairs.","There is no coffee.","There are no clean cups.","We need more tables."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Two chairs are missing.","meaning_es":"que falta"},{"english":"There aren''t enough chairs.","meaning_es":"suficiente"},{"english":"There isn''t a printer.","meaning_es":"impresora"},{"english":"There is no coffee.","meaning_es":"café"},{"english":"There are no clean cups.","meaning_es":"limpio / limpia"},{"english":"We need more tables.","meaning_es":"necesitar"}],"dialogue":[{"speaker":"Organizer","text":"Is the room ready?"},{"speaker":"Assistant","text":"Almost. There isn''t a printer."},{"speaker":"Organizer","text":"Are there enough chairs?"},{"speaker":"Assistant","text":"No, there aren''t enough chairs. There are no clean cups, either."},{"speaker":"Organizer","text":"Okay. We need two more chairs and some cups."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir negativas con there isn''t y there aren''t y destacar el objeto que falta.","models":[{"text":"There isn''t a printer.","stress":["isn''t","printer"]},{"text":"There aren''t enough chairs.","stress":["aren''t","enough","chairs"]},{"text":"There are no clean cups.","stress":["no","clean cups"]}],"student_feedback":"La negación debe ser audible porque cambia el significado del reporte."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Organizer","text":"Is the room ready?"},{"speaker":"Assistant","text":"Almost. There isn''t a printer."},{"speaker":"Organizer","text":"Are there enough chairs?"},{"speaker":"Assistant","text":"No, there aren''t enough chairs. There are no clean cups, either."},{"speaker":"Organizer","text":"Okay. We need two more chairs and some cups."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The room is almost ready","text":"The meeting room has tables and a projector. There isn''t a printer. There aren''t enough chairs for everyone. There are no clean cups. The team writes a list of missing items and asks for help.","interactive_vocabulary":["almost","projector","for everyone","writes","asks for help"],"questions":[{"prompt":"What is missing?","options":["A printer and enough chairs","Tables and a projector","The room"],"answer":"A printer and enough chairs"},{"prompt":"What does the team do?","options":["Writes a list and asks for help","Leaves immediately","Buys a room"],"answer":"Writes a list and asks for help"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Preparar una sala y avisar que faltan objetos necesarios.","communication_goal":"El estudiante puede decir qué no hay y explicar qué falta en un espacio.","activities":[{"id":"A1-M1-T09-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es la persona responsable. Reporta qué falta en una sala y propone qué necesitan.","role":"responsible manager","student_goal":"Use negative there is/are and state two needs.","allowed_support":["room checklist","problem cards","sentence starter","Spanish hint"],"success_criteria":["reports one singular absence","reports one plural shortage","proposes two needs"],"feedback_correct":"Describiste un problema y ayudaste a resolverlo.","feedback_incorrect":"Singular: There isn''t...; plural: There aren''t...; solución: We need...","estimated_seconds":200,"prompt":"La IA es la persona responsable. Reporta qué falta en una sala y propone qué necesitan.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T09-L03"},{"id":"A1-M1-T09-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Envía un reporte de tres cosas que faltan en una casa, sala o trabajo.","prompt":"There isn''t ____. There aren''t ____. We need ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses singular negative","uses plural negative","proposes a need or solution"],"feedback_correct":"Usaste la estructura para resolver una necesidad concreta.","feedback_incorrect":"Separa un problema singular, uno plural y la solución.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T09-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una revisión completa combina afirmaciones, preguntas y negaciones. Usa there is/are para describir, Is/Are there para comprobar y We need para convertir un problema en una acción.","communication_goal":"El estudiante puede comprobar una habitación, describir qué hay, qué falta y qué se necesita.","language_focus":["There is...","There are...","Is there...?","Are there...?","There isn''t...","There aren''t...","We need..."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Let''s do a readiness check.","meaning_es":"revisión de preparación"},{"english":"There is a projector.","meaning_es":"proyector"},{"english":"There isn''t an extension cord.","meaning_es":"cable de extensión"},{"english":"There are enough seats.","meaning_es":"asientos"},{"english":"There aren''t any markers.","meaning_es":"marcadores"},{"english":"The room is ready.","meaning_es":"listo / lista"}],"dialogue":[{"speaker":"Manager","text":"Is the room ready?"},{"speaker":"Assistant","text":"Almost. There is a projector and there are twelve seats."},{"speaker":"Manager","text":"Are there any markers?"},{"speaker":"Assistant","text":"No, there aren''t any markers. There is an extension cord, though."},{"speaker":"Manager","text":"Okay. We need markers. Are there enough seats?"},{"speaker":"Assistant","text":"Yes, there are. The room is ready after we get the markers."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Mantener claridad en un reporte con afirmaciones, preguntas y problemas.","models":[{"text":"There is a projector.","stress":["projector"]},{"text":"Are there any markers?","stress":["markers"],"intonation":"rising"},{"text":"There aren''t any markers.","stress":["aren''t","markers"]},{"text":"We need markers.","stress":["need","markers"]}],"student_feedback":"Organiza el reporte en bloques: qué hay, qué falta y qué acción se necesita."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Manager","text":"Is the room ready?"},{"speaker":"Assistant","text":"Almost. There is a projector and there are twelve seats."},{"speaker":"Manager","text":"Are there any markers?"},{"speaker":"Assistant","text":"No, there aren''t any markers. There is an extension cord, though."},{"speaker":"Manager","text":"Okay. We need markers. Are there enough seats?"},{"speaker":"Assistant","text":"Yes, there are. The room is ready after we get the markers."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Fifteen minutes before the meeting","text":"Fifteen minutes before the meeting, the team checks the room. There is a projector and there are twelve seats. There are no markers, and there isn''t an extension cord. The team needs markers and an extension cord. After that, the room is ready.","interactive_vocabulary":["fifteen minutes","checks","extension cord","after that","meeting"],"questions":[{"prompt":"What is in the room?","options":["A projector and twelve seats","Markers and an extension cord","Only tables"],"answer":"A projector and twelve seats"},{"prompt":"What does the team need?","options":["Markers and an extension cord","More seats","A new room"],"answer":"Markers and an extension cord"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Revisar una sala antes de una reunión y comunicar el resultado a un responsable.","communication_goal":"El estudiante puede comprobar una habitación, describir qué hay, qué falta y qué se necesita.","activities":[{"id":"A1-M1-T09-L04-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es el gerente. Revisa una sala, responde preguntas y propone soluciones.","role":"manager","student_goal":"Complete a readiness check with statements, questions, negatives and needs.","allowed_support":["room checklist","problem cards","sentence starter","Spanish hint"],"success_criteria":["describes two existing items","asks singular and plural questions","reports one absence","proposes a need"],"feedback_correct":"Completaste una revisión operativa completa.","feedback_incorrect":"Usa la secuencia: There is/are; Is/Are there?; There isn''t/aren''t; We need.","estimated_seconds":230,"prompt":"La IA es el gerente. Revisa una sala, responde preguntas y propone soluciones.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T09-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","mastery_assessment"],"topic_ready_when":"El estudiante entrega un reporte completo y comprensible de una sala con al menos 80% de precisión.","retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"In indica que algo está dentro de un espacio; on que está sobre una superficie; under que está debajo de algo. La preposición conecta el objeto con el lugar.","communication_goal":"El estudiante puede localizar objetos usando in, on y under.","language_focus":["The keys are in the bag.","The phone is on the table.","The shoes are under the bed.","Where is my book?","It''s in the box."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"The keys are in the bag.","meaning_es":"dentro de / en"},{"english":"The phone is on the table.","meaning_es":"encima de / sobre"},{"english":"The shoes are under the bed.","meaning_es":"debajo de"},{"english":"My keys are in the bag.","meaning_es":"llaves"},{"english":"The book is in the box.","meaning_es":"caja"},{"english":"The shoes are under the bed.","meaning_es":"cama"}],"dialogue":[{"speaker":"Alex","text":"Where is my phone?"},{"speaker":"Sam","text":"It''s on the table."},{"speaker":"Alex","text":"And where are my keys?"},{"speaker":"Sam","text":"They are in your bag."},{"speaker":"Alex","text":"I can''t find my shoes."},{"speaker":"Sam","text":"They are under the bed."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir preposiciones cortas dentro de frases de ubicación.","models":[{"text":"in the bag","stress":["bag"]},{"text":"on the table","stress":["table"]},{"text":"under the bed","stress":["under","bed"]}],"student_feedback":"Las preposiciones suelen ser débiles; destaca el objeto y el lugar importante."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Alex","text":"Where is my phone?"},{"speaker":"Sam","text":"It''s on the table."},{"speaker":"Alex","text":"And where are my keys?"},{"speaker":"Sam","text":"They are in your bag."},{"speaker":"Alex","text":"I can''t find my shoes."},{"speaker":"Sam","text":"They are under the bed."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Before leaving home","text":"Alex is ready to leave home. The phone is on the table. The keys are in a small bag. The shoes are under the bed. Alex finds everything and leaves on time.","interactive_vocabulary":["ready","leave home","small bag","finds","on time"],"questions":[{"prompt":"Where is the phone?","options":["On the table","In the bag","Under the bed"],"answer":"On the table"},{"prompt":"Where are the shoes?","options":["Under the bed","On the table","In the room''s box"],"answer":"Under the bed"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Encontrar objetos en una habitación y explicar dónde están.","communication_goal":"El estudiante puede localizar objetos usando in, on y under.","activities":[{"id":"A1-M1-T10-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA perdió tres objetos. Pregunta dónde están y ayuda a encontrarlos.","role":"person looking for belongings","student_goal":"Ask and answer Where is/are...? using in, on and under.","allowed_support":["room map","object cards","sentence starter","Spanish hint"],"success_criteria":["uses in","uses on","uses under","answers one Where are question"],"feedback_correct":"Resolviste una búsqueda usando relaciones espaciales.","feedback_incorrect":"Dentro = in; superficie = on; debajo = under.","estimated_seconds":180,"prompt":"La IA perdió tres objetos. Pregunta dónde están y ayuda a encontrarlos.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T10-L01"},{"id":"A1-M1-T10-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Graba instrucciones para encontrar tres objetos en tu espacio.","prompt":"The ____ is in ____. The ____ is on ____. The ____ is under ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses all three prepositions","identifies three objects","communicates locations clearly"],"feedback_correct":"Usaste preposiciones para orientar a alguien en un espacio real.","feedback_incorrect":"Piensa si cada objeto está dentro, sobre o debajo de algo.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T10-L01"}]}'::jsonb,6);
