insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Next to indica al lado de; near indica cerca de; behind indica detrás de; in front of indica delante de. Estas expresiones describen la relación entre dos lugares u objetos.","communication_goal":"El estudiante puede describir la posición de objetos usando relaciones espaciales frecuentes.","language_focus":["The bank is next to the station.","The bag is near the chair.","The keys are behind the book.","The desk is in front of the window.","Where is the elevator?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"The desk is next to the window.","meaning_es":"al lado de"},{"english":"The elevator is near the stairs.","meaning_es":"cerca de"},{"english":"The bag is behind the chair.","meaning_es":"detrás de"},{"english":"The desk is in front of the window.","meaning_es":"delante de"},{"english":"The elevator is near the stairs.","meaning_es":"ascensor"},{"english":"The stairs are behind the hall.","meaning_es":"escaleras"}],"dialogue":[{"speaker":"Visitor","text":"Excuse me. Where is the elevator?"},{"speaker":"Worker","text":"It''s next to the stairs."},{"speaker":"Visitor","text":"And where is the meeting room?"},{"speaker":"Worker","text":"It''s behind the reception desk, near the window."},{"speaker":"Visitor","text":"Is the printer in front of the desk?"},{"speaker":"Worker","text":"No, it''s behind the desk."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir expresiones espaciales de varias palabras sin perder claridad.","models":[{"text":"next to the stairs","stress":["next","stairs"]},{"text":"near the window","stress":["near","window"]},{"text":"behind the desk","stress":["behind","desk"]},{"text":"in front of the building","stress":["front","building"]}],"student_feedback":"Mantén clara la palabra principal de la relación y no elimines of en in front of."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Visitor","text":"Excuse me. Where is the elevator?"},{"speaker":"Worker","text":"It''s next to the stairs."},{"speaker":"Visitor","text":"And where is the meeting room?"},{"speaker":"Worker","text":"It''s behind the reception desk, near the window."},{"speaker":"Visitor","text":"Is the printer in front of the desk?"},{"speaker":"Worker","text":"No, it''s behind the desk."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Inside the office building","text":"The elevator is next to the stairs. The reception desk is in front of a large window. The meeting room is behind the desk. The printer is near the door, and the waiting area is next to the meeting room.","interactive_vocabulary":["office building","reception desk","waiting area","meeting room","large window"],"questions":[{"prompt":"What is next to the stairs?","options":["The elevator","The printer","The meeting room"],"answer":"The elevator"},{"prompt":"Where is the printer?","options":["Near the door","Behind the window","In front of the stairs"],"answer":"Near the door"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Dar indicaciones dentro de una oficina o edificio.","communication_goal":"El estudiante puede describir la posición de objetos usando relaciones espaciales frecuentes.","activities":[{"id":"A1-M1-T10-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es visitante. Dale tres indicaciones para llegar a una sala.","role":"visitor","student_goal":"Use next to, near, behind and in front of to give directions.","allowed_support":["building map","direction cards","sentence starter","Spanish hint"],"success_criteria":["uses three target prepositions","gives a reference point","answers one Where is question"],"feedback_correct":"Orientaste a la persona usando referencias claras.","feedback_incorrect":"Cada expresión necesita un punto de referencia: near the door, behind the desk.","estimated_seconds":190,"prompt":"La IA es visitante. Dale tres indicaciones para llegar a una sala.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T10-L02"},{"id":"A1-M1-T10-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe cuatro lugares de tu casa, escuela o trabajo para una persona nueva.","prompt":"The ____ is next to ____. The ____ is behind ____. The ____ is near ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses three target prepositions","gives reference points","communicates a usable route"],"feedback_correct":"Convertiste relaciones espaciales en indicaciones reales.","feedback_incorrect":"Nombra primero el lugar y luego explica su relación con otro lugar.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T10-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Between coloca algo entre dos referencias. Across from y opposite indican que dos lugares están enfrentados. At the corner ubica algo en una esquina.","communication_goal":"El estudiante puede dar y entender indicaciones sencillas usando puntos de referencia.","language_focus":["The bank is between the café and the pharmacy.","The station is across from the hotel.","The bus stop is at the corner.","The pharmacy is opposite the bank."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"The bank is between the café and the pharmacy.","meaning_es":"entre"},{"english":"The station is across from the hotel.","meaning_es":"enfrente de"},{"english":"The pharmacy is opposite the bank.","meaning_es":"enfrente de"},{"english":"The bus stop is at the corner.","meaning_es":"esquina"},{"english":"The station is nearby.","meaning_es":"estación"},{"english":"The pharmacy is opposite the bank.","meaning_es":"farmacia"}],"dialogue":[{"speaker":"Tourist","text":"Excuse me. Where is the pharmacy?"},{"speaker":"Local","text":"It is opposite the bank."},{"speaker":"Tourist","text":"Where is the bank?"},{"speaker":"Local","text":"It is between the café and the pharmacy."},{"speaker":"Tourist","text":"And the station?"},{"speaker":"Local","text":"The station is across from the hotel, near the corner."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir relaciones espaciales con dos referencias y frases de dirección.","models":[{"text":"between the café and the pharmacy","stress":["between","café","pharmacy"]},{"text":"across from the hotel","stress":["across","hotel"]},{"text":"at the corner","stress":["corner"]}],"student_feedback":"Mantén claras las dos referencias de between y la expresión completa across from."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Tourist","text":"Excuse me. Where is the pharmacy?"},{"speaker":"Local","text":"It is opposite the bank."},{"speaker":"Tourist","text":"Where is the bank?"},{"speaker":"Local","text":"It is between the café and the pharmacy."},{"speaker":"Tourist","text":"And the station?"},{"speaker":"Local","text":"The station is across from the hotel, near the corner."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A short city walk","text":"The visitor starts at the hotel. The station is across from the hotel. The bank is between a café and a pharmacy. The bus stop is at the corner, opposite the station. The visitor finds the pharmacy first.","interactive_vocabulary":["visitor","starts","city walk","bus stop","finds"],"questions":[{"prompt":"What is across from the hotel?","options":["The station","The bank","The café"],"answer":"The station"},{"prompt":"Where is the bank?","options":["Between a café and a pharmacy","At the hotel","Under the station"],"answer":"Between a café and a pharmacy"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Ayudar a un visitante a encontrar una farmacia, un banco y una estación.","communication_goal":"El estudiante puede dar y entender indicaciones sencillas usando puntos de referencia.","activities":[{"id":"A1-M1-T10-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es turista. Dale una ruta desde un hotel hasta una farmacia y estación.","role":"tourist","student_goal":"Give directions using between, across from, opposite and at the corner.","allowed_support":["city map","direction cards","sentence starter","Spanish hint"],"success_criteria":["uses between with two references","uses across from/opposite","uses at the corner","answers one follow-up"],"feedback_correct":"Diste una ruta comprensible con puntos de referencia.","feedback_incorrect":"Usa una expresión por relación y nombra siempre el punto de referencia.","estimated_seconds":200,"prompt":"La IA es turista. Dale una ruta desde un hotel hasta una farmacia y estación.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T10-L03"},{"id":"A1-M1-T10-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Describe el camino entre dos lugares conocidos de tu barrio.","prompt":"The ____ is between ____ and ____. The ____ is across from ____. The ____ is at the corner.","response_type":"open_speech_or_text","evaluation_criteria":["uses three target relations","uses two references with between","communicates a usable route"],"feedback_correct":"Aplicaste preposiciones a tu entorno real.","feedback_incorrect":"Dibuja primero el mapa y después convierte cada relación en una frase.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T10-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una indicación clara combina punto de partida, referencias espaciales y destino. No necesitas usar todas las preposiciones en una sola frase; elige las que hagan la ruta comprensible.","communication_goal":"El estudiante puede describir ubicaciones y dar indicaciones comprensibles en un espacio real o mapa.","language_focus":["in","on","under","next to","near","behind","in front of","between","across from","at the corner"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Can you give me directions?","meaning_es":"indicaciones"},{"english":"Start at the entrance.","meaning_es":"entrada"},{"english":"The room is in the hallway.","meaning_es":"pasillo"},{"english":"The desk is in front of the entrance.","meaning_es":"mostrador de información"},{"english":"Turn at the corner.","meaning_es":"esquina"},{"english":"The room is your destination.","meaning_es":"destino"}],"dialogue":[{"speaker":"Visitor","text":"How do I get to Room 4?"},{"speaker":"Guide","text":"Start at the entrance. The information desk is in front of you."},{"speaker":"Visitor","text":"Where is the elevator?"},{"speaker":"Guide","text":"It is next to the stairs, near the corner."},{"speaker":"Visitor","text":"And Room 4?"},{"speaker":"Guide","text":"It is behind the desk, between the library and the kitchen."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Dar una ruta en bloques cortos, con énfasis en lugares y giros.","models":[{"text":"Start at the entrance.","stress":["start","entrance"]},{"text":"The elevator is next to the stairs.","stress":["elevator","next","stairs"]},{"text":"Room 4 is behind the desk.","stress":["Room 4","behind","desk"]}],"student_feedback":"Haz una pausa entre indicaciones; el oyente debe construir el mapa mentalmente."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Visitor","text":"How do I get to Room 4?"},{"speaker":"Guide","text":"Start at the entrance. The information desk is in front of you."},{"speaker":"Visitor","text":"Where is the elevator?"},{"speaker":"Guide","text":"It is next to the stairs, near the corner."},{"speaker":"Visitor","text":"And Room 4?"},{"speaker":"Guide","text":"It is behind the desk, between the library and the kitchen."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A route through the center","text":"Start at the entrance. The information desk is in front of the entrance. The elevator is next to the stairs and near the corner. Room 4 is behind the desk, between the library and the kitchen. The restrooms are across from Room 4.","interactive_vocabulary":["route","restrooms","library","kitchen","rest of"],"questions":[{"prompt":"Where is the elevator?","options":["Next to the stairs and near the corner","Behind the kitchen","In the library"],"answer":"Next to the stairs and near the corner"},{"prompt":"What is across from Room 4?","options":["The restrooms","The entrance","The elevator"],"answer":"The restrooms"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Guiar a una persona desde la entrada de un edificio hasta una sala y varios servicios.","communication_goal":"El estudiante puede describir ubicaciones y dar indicaciones comprensibles en un espacio real o mapa.","activities":[{"id":"A1-M1-T10-L04-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es visitante. Guíala desde la entrada hasta un destino y responde una pregunta de seguimiento.","role":"visitor","student_goal":"Give a complete route using at least four basic prepositions.","allowed_support":["building map","route cards","sentence starter","Spanish hint"],"success_criteria":["gives a starting point","uses four relations","names a destination","repairs one misunderstanding"],"feedback_correct":"Diste una ruta funcional y reparaste una posible confusión.","feedback_incorrect":"Divide la ruta en pasos y usa un punto de referencia en cada uno.","estimated_seconds":240,"prompt":"La IA es visitante. Guíala desde la entrada hasta un destino y responde una pregunta de seguimiento.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M1-T10-L04"}]}'::jsonb,6);
