insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"En una frase afirmativa básica, el orden habitual es sujeto + verbo + complemento: I study English. En inglés el sujeto normalmente debe aparecer, aunque en español pueda omitirse.","communication_goal":"El estudiante puede construir frases afirmativas básicas con sujeto, verbo y complemento.","language_focus":["I study English.","She drinks coffee.","We live in a city.","They play music.","I read a book."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I study English.","meaning_es":"estudiar"},{"english":"She drinks coffee.","meaning_es":"beber"},{"english":"We live in a city.","meaning_es":"vivir"},{"english":"They play music.","meaning_es":"jugar / tocar"},{"english":"I read a book.","meaning_es":"leer"},{"english":"Build a sentence.","meaning_es":"oración / frase"}],"dialogue":[{"speaker":"Teacher","text":"Tell me about your day."},{"speaker":"Student","text":"I study English. I drink coffee. I read a book."},{"speaker":"Teacher","text":"Good. Can you write one sentence about your friend?"},{"speaker":"Student","text":"She plays music."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir frases cortas con ritmo sujeto-verbo-complemento.","models":[{"text":"I study English.","stress":["study","English"]},{"text":"She drinks coffee.","stress":["drinks","coffee"]},{"text":"We live in a city.","stress":["live","city"]}],"student_feedback":"Marca el verbo y la información importante; no pronuncies cada palabra con el mismo peso."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Teacher","text":"Tell me about your day."},{"speaker":"Student","text":"I study English. I drink coffee. I read a book."},{"speaker":"Teacher","text":"Good. Can you write one sentence about your friend?"},{"speaker":"Student","text":"She plays music."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A simple daily routine","text":"I study English in the morning. I drink coffee and read a short book. My friend lives nearby. She plays music in the afternoon. We talk about our day.","interactive_vocabulary":["morning","short","nearby","afternoon","talk"],"questions":[{"prompt":"What does the speaker study?","options":["English","Music","Coffee"],"answer":"English"},{"prompt":"What does the friend play?","options":["Music","A book","A city"],"answer":"Music"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Escribir mensajes sencillos sobre actividades diarias.","communication_goal":"El estudiante puede construir frases afirmativas básicas con sujeto, verbo y complemento.","activities":[{"id":"A1-M2-T01-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu profesor. Dile tres cosas que haces durante el día.","role":"English teacher","student_goal":"Produce three affirmative sentences with subject, verb and complement.","allowed_support":["verb cards","sentence frame","Spanish hint"],"success_criteria":["produces three sentences","includes a subject each time","uses understandable word order"],"feedback_correct":"Construiste mensajes claros sobre tu vida.","feedback_incorrect":"Usa el marco: I + verb + information.","estimated_seconds":180,"prompt":"La IA es tu profesor. Dile tres cosas que haces durante el día.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T01-L01"},{"id":"A1-M2-T01-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Escribe o graba tres frases para presentarte a un compañero nuevo.","prompt":"I ____ ____. I ____ ____. I ____ ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses three subjects","uses three verbs","maintains subject-verb-complement order"],"feedback_correct":"Usaste el orden básico para comunicar información personal.","feedback_incorrect":"Comprueba que cada frase empieza con un sujeto y continúa con un verbo.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T01-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una frase puede crecer con lugar y tiempo. El orden básico sigue siendo sujeto + verbo + complemento; después añadimos información como at home, in the morning o at night.","communication_goal":"El estudiante puede ampliar una frase básica con información de tiempo y lugar.","language_focus":["I study English at home.","I drink coffee in the morning.","We work in an office.","She reads at night.","They play soccer in the park."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I study at home.","meaning_es":"en casa"},{"english":"I drink coffee in the morning.","meaning_es":"en la mañana"},{"english":"She reads at night.","meaning_es":"por la noche"},{"english":"We work in an office.","meaning_es":"oficina"},{"english":"They play in the park.","meaning_es":"parque"},{"english":"I usually study at home.","meaning_es":"normalmente"}],"dialogue":[{"speaker":"Maya","text":"Where do you study?"},{"speaker":"Luis","text":"I study English at home in the morning."},{"speaker":"Maya","text":"Where do you work?"},{"speaker":"Luis","text":"I work in an office. I read at night."},{"speaker":"Maya","text":"I usually study in the park on Saturdays."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Mantener ritmo claro al añadir lugar y tiempo.","models":[{"text":"I study English at home.","stress":["study","English","home"]},{"text":"I drink coffee in the morning.","stress":["drink","coffee","morning"]}],"student_feedback":"Agrupa la frase en acción + lugar + tiempo."}'::jsonb,3);
