insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Two routines","text":"Maya studies English at home in the morning. Luis works in an office and reads at night. On Saturdays, Maya studies in the park. They talk about their routines.","interactive_vocabulary":["weekday","routine","Saturday","talk","usually"],"questions":[{"prompt":"Where does Luis work?","options":["In an office","At home","In a park"],"answer":"In an office"},{"prompt":"When does Luis read?","options":["At night","In the morning","On Saturdays"],"answer":"At night"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Contar dónde y cuándo realiza actividades cotidianas.","communication_goal":"El estudiante puede ampliar una frase básica con información de tiempo y lugar.","activities":[{"id":"A1-M2-T01-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu compañero. Pregunta y responde dónde y cuándo estudias o trabajas.","role":"classmate","student_goal":"Exchange two routine sentences with place and time.","allowed_support":["routine cards","sentence starter","Spanish hint"],"success_criteria":["answers where","answers when","produces two expanded sentences"],"feedback_correct":"Compartiste información concreta de tu rutina.","feedback_incorrect":"Usa I + verb + place + time.","estimated_seconds":180,"prompt":"La IA es tu compañero. Pregunta y responde dónde y cuándo estudias o trabajas.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T01-L02"},{"id":"A1-M2-T01-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Graba un mensaje con dos actividades, sus lugares y momentos.","prompt":"I ____ ____ at ____. I ____ ____ in the ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses two verbs","gives two places","gives two times","maintains word order"],"feedback_correct":"Convertiste la estructura en información personal útil.","feedback_incorrect":"Construye cada frase por bloques: sujeto, verbo, complemento, lugar y tiempo.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T01-L02"}]}'::jsonb,6);
