insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Cuando una frase contiene acción, persona, lugar y tiempo, organiza primero sujeto + verbo + complemento y después añade lugar o tiempo. Corregir el orden ayuda a que el interlocutor entienda el mensaje rápidamente.","communication_goal":"El estudiante puede reorganizar y corregir frases para transmitir un mensaje claro.","language_focus":["I meet my friend at six.","We eat dinner at home.","She studies English on Monday.","They play tennis in the park."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I meet my friend at six.","meaning_es":"encontrarse con"},{"english":"We eat dinner at home.","meaning_es":"cenar"},{"english":"She studies on Monday.","meaning_es":"el lunes"},{"english":"Read the message.","meaning_es":"mensaje"},{"english":"Correct the message.","meaning_es":"corregir / correcto"},{"english":"What is the plan?","meaning_es":"plan"}],"dialogue":[{"speaker":"Ana","text":"What is the plan?"},{"speaker":"Luis","text":"At six my friend I meet."},{"speaker":"Ana","text":"Do you mean ''I meet my friend at six''?"},{"speaker":"Luis","text":"Yes. We eat dinner at home."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Leer mensajes corregidos con ritmo natural y énfasis en la información nueva.","models":[{"text":"I meet my friend at six.","stress":["meet","friend","six"]},{"text":"We eat dinner at home.","stress":["eat","dinner","home"]}],"student_feedback":"La claridad del orden debe escucharse, no solo verse."}'::jsonb,3);
