insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A corrected plan","text":"Ana and Luis make a plan. They meet at six and eat dinner at home. On Monday, Ana studies English. On Tuesday, Luis plays tennis in the park. Their messages are short but clear.","interactive_vocabulary":["make a plan","meet","dinner","Tuesday","clear"],"questions":[{"prompt":"When do they meet?","options":["At six","On Monday","At home"],"answer":"At six"},{"prompt":"Where does Luis play tennis?","options":["In the park","At school","At home"],"answer":"In the park"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Revisar mensajes de chat sobre planes y actividades.","communication_goal":"El estudiante puede reorganizar y corregir frases para transmitir un mensaje claro.","activities":[{"id":"A1-M2-T01-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu amigo. Corrijan juntos tres mensajes desordenados sobre sus planes.","role":"friend","student_goal":"Repair word order and confirm the intended meaning.","allowed_support":["message blocks","sentence frame","Spanish hint"],"success_criteria":["corrects three messages","explains one correction","confirms a plan"],"feedback_correct":"Usaste el orden para evitar malentendidos.","feedback_incorrect":"Reconstruye sujeto + verbo + complemento y añade lugar/tiempo.","estimated_seconds":200,"prompt":"La IA es tu amigo. Corrijan juntos tres mensajes desordenados sobre sus planes.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T01-L03"},{"id":"A1-M2-T01-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Escribe un mensaje claro con un plan para mañana.","prompt":"Tomorrow, I ____ ____ at ____. We ____ ____ at ____.","response_type":"open_speech_or_text","evaluation_criteria":["produces two complete sentences","uses natural word order","includes time or place"],"feedback_correct":"Creaste un mensaje que otra persona puede entender.","feedback_incorrect":"Escribe primero quién, después qué hace y al final dónde/cuándo.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T01-L03"}]}'::jsonb,6);
