insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una frase básica debe tener un sujeto claro, un verbo, información necesaria y un orden que el interlocutor pueda procesar. La evaluación final combina construcción, corrección y uso comunicativo.","communication_goal":"El estudiante puede construir y corregir mensajes afirmativos básicos en una situación nueva.","language_focus":["I work at home on Friday.","She calls me in the morning.","We meet at the station.","They study English after work."]}'::jsonb,1);
