insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A clear plan","text":"On Friday, Carla works at home in the morning. After work, she calls her friend. They meet at the station at six. Their plan is short and clear.","interactive_vocabulary":["Friday","works","calls","meet","plan"],"questions":[{"prompt":"When do they meet?","options":["At six on Friday","In the morning at home","After Saturday"],"answer":"At six on Friday"},{"prompt":"Who calls the friend?","options":["Carla","The station","The teacher"],"answer":"Carla"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Enviar instrucciones y planes claros a un compañero.","communication_goal":"El estudiante puede construir y corregir mensajes afirmativos básicos en una situación nueva.","activities":[{"id":"A1-M2-T01-L04-E07","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu compañero. Coordina un encuentro y corrige un malentendido de horario.","role":"friend","student_goal":"Send a clear plan, answer a follow-up and repair one confusing sentence.","allowed_support":["calendar","sentence frame","Spanish hint"],"success_criteria":["states activity","states place","states time","repairs one message"],"feedback_correct":"Lograste coordinar una actividad con mensajes claros.","feedback_incorrect":"Usa sujeto + verbo + lugar + tiempo y divide el mensaje si es largo.","estimated_seconds":220,"prompt":"La IA es tu compañero. Coordina un encuentro y corrige un malentendido de horario.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T01-L04"},{"id":"A1-M2-T01-L04-E08","type":"transfer_mission","skill":"integrated","instruction":"Envía una invitación clara para una actividad real.","prompt":"We ____ at ____. We ____ at ____. See you ____.","response_type":"open_speech_or_text","evaluation_criteria":["has two complete sentences","includes place and time","is understandable without translation"],"feedback_correct":"Creaste un mensaje que otra persona puede usar.","feedback_incorrect":"Escribe dos frases cortas y coloca lugar y tiempo después del mensaje principal.","estimated_seconds":140,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T01-L04"}]}'::jsonb,6);
