insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"El presente simple describe hábitos y rutinas. Con I, you, we y they usamos la forma base: I work, they study. En preguntas usamos do: Do you work?","communication_goal":"El estudiante puede hablar de hábitos y rutinas usando el presente simple con I, you, we y they.","language_focus":["I get up at seven.","I have breakfast.","We work every day.","They study at night.","Do you work on Saturdays?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I get up at seven.","meaning_es":"levantarse"},{"english":"I have breakfast at home.","meaning_es":"desayunar"},{"english":"We go to work by bus.","meaning_es":"ir al trabajo"},{"english":"I work every day.","meaning_es":"todos los días"},{"english":"They study on Saturdays.","meaning_es":"los sábados"},{"english":"Tell me about your routine.","meaning_es":"rutina"}],"dialogue":[{"speaker":"Maya","text":"What time do you get up?"},{"speaker":"Luis","text":"I get up at seven. I have breakfast at home."},{"speaker":"Maya","text":"Do you go to work by bus?"},{"speaker":"Luis","text":"Yes, I do. I work every day except Sunday."},{"speaker":"Maya","text":"We have a similar routine."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir rutinas con ritmo claro y reconocer do you en preguntas.","models":[{"text":"I get up at seven.","stress":["get up","seven"]},{"text":"I have breakfast at home.","stress":["breakfast","home"]},{"text":"Do you work every day?","stress":["work","every day"],"intonation":"rising"}],"student_feedback":"El verbo principal y el momento del día deben ser fáciles de identificar."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Maya","text":"What time do you get up?"},{"speaker":"Luis","text":"I get up at seven. I have breakfast at home."},{"speaker":"Maya","text":"Do you go to work by bus?"},{"speaker":"Luis","text":"Yes, I do. I work every day except Sunday."},{"speaker":"Maya","text":"We have a similar routine."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A weekday routine","text":"Luis gets up at seven on weekdays. He has breakfast at home and goes to work by bus. He works every day except Sunday. On Saturdays, he studies English in the afternoon.","interactive_vocabulary":["weekday","by bus","except","afternoon","studies"],"questions":[{"prompt":"How does Luis go to work?","options":["By bus","By train","On foot"],"answer":"By bus"},{"prompt":"When does he study English?","options":["On Saturdays","Every morning","Only Sunday"],"answer":"On Saturdays"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Contar una rutina diaria y preguntar por los hábitos de otra persona.","communication_goal":"El estudiante puede hablar de hábitos y rutinas usando el presente simple con I, you, we y they.","activities":[{"id":"A1-M2-T02-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es un compañero. Pregunta por su rutina y responde sobre la tuya.","role":"coworker","student_goal":"Ask and answer two routine questions using present simple.","allowed_support":["routine cards","sentence starter","Spanish hint"],"success_criteria":["asks Do you...?","answers with a routine verb","gives time or frequency"],"feedback_correct":"Conversaste sobre hábitos usando el presente simple.","feedback_incorrect":"Usa Do you + verbo base? y responde I + verbo.","estimated_seconds":180,"prompt":"La IA es un compañero. Pregunta por su rutina y responde sobre la tuya.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T02-L01"},{"id":"A1-M2-T02-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Graba un audio de tu rutina de mañana y haz una pregunta al oyente.","prompt":"I get up ____. I have breakfast ____. I go to ____. Do you ____?","response_type":"open_speech_or_text","evaluation_criteria":["uses three routine verbs","includes time/place","asks one Do question"],"feedback_correct":"Usaste el presente simple para hablar de tu vida.","feedback_incorrect":"Construye tres afirmaciones y termina con Do you + verbo base?.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T02-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_complete":["pronunciation_recording","ai_roleplay","transfer_mission"],"retry_policy":"Los errores se programan para recuperación a 1, 3, 7 y 14 días."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Con he, she e it, el presente simple suele añadir -s o -es al verbo: work → works, watch → watches, study → studies. En preguntas usamos does y el verbo vuelve a la forma base: Does she work?, no Does she works?.","communication_goal":"El estudiante puede describir la rutina de otra persona y reconocer la terminación de tercera persona.","language_focus":["He works in an office.","She studies English.","He gets up early.","She watches TV at night.","Does she work on Sundays?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"He works in an office.","meaning_es":"trabaja"},{"english":"She studies English.","meaning_es":"estudia"},{"english":"He gets up early.","meaning_es":"se levanta"},{"english":"She watches TV at night.","meaning_es":"mira televisión"},{"english":"He gets up early.","meaning_es":"temprano"},{"english":"She works on Sundays.","meaning_es":"los domingos"}],"dialogue":[{"speaker":"Teacher","text":"What does your brother do?"},{"speaker":"Student","text":"He works in an office. He gets up early."},{"speaker":"Teacher","text":"Does he study English?"},{"speaker":"Student","text":"No, he doesn''t. My sister studies English at night."},{"speaker":"Teacher","text":"Does she work on Sundays?"},{"speaker":"Student","text":"Yes, she does."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Reconocer y producir terminaciones de tercera persona y preguntas con does.","models":[{"text":"He works in an office.","stress":["works","office"]},{"text":"She studies English.","stress":["studies","English"]},{"text":"Does she work on Sundays?","stress":["work","Sundays"],"intonation":"rising"}],"student_feedback":"La s final importa, pero después de does desaparece del verbo principal."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Teacher","text":"What does your brother do?"},{"speaker":"Student","text":"He works in an office. He gets up early."},{"speaker":"Teacher","text":"Does he study English?"},{"speaker":"Student","text":"No, he doesn''t. My sister studies English at night."},{"speaker":"Teacher","text":"Does she work on Sundays?"},{"speaker":"Student","text":"Yes, she does."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"My family''s routines","text":"My brother works in an office. He gets up early and takes the bus. My sister studies English at night. She watches TV after class. She works on Sundays, but my brother does not work on Sundays.","interactive_vocabulary":["brother","sister","takes the bus","after class","does not"],"questions":[{"prompt":"Who studies English at night?","options":["The sister","The brother","The teacher"],"answer":"The sister"},{"prompt":"Who does not work on Sundays?","options":["The brother","The sister","Both"],"answer":"The brother"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Hablar de la rutina de un familiar o compañero.","communication_goal":"El estudiante puede describir la rutina de otra persona y reconocer la terminación de tercera persona.","activities":[{"id":"A1-M2-T02-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu profesor. Habla sobre la rutina de un familiar y responde preguntas con does.","role":"teacher","student_goal":"Describe another person''s routine and answer two Does questions.","allowed_support":["family cards","verb bank","sentence starter","Spanish hint"],"success_criteria":["uses three third-person verbs","answers Does questions","uses base verb after does"],"feedback_correct":"Describiste a otra persona con precisión gramatical.","feedback_incorrect":"Afirmativa: she works. Pregunta: Does she work?.","estimated_seconds":190,"prompt":"La IA es tu profesor. Habla sobre la rutina de un familiar y responde preguntas con does.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T02-L02"},{"id":"A1-M2-T02-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Graba una mini descripción de la rutina de un familiar o amigo.","prompt":"He/She ____ at ____. He/She ____ ____. Does he/she ____?","response_type":"open_speech_or_text","evaluation_criteria":["uses three third-person forms","includes time/place","forms one Does question"],"feedback_correct":"Usaste el presente simple para describir a otra persona.","feedback_incorrect":"Añade s en afirmaciones, pero usa verbo base después de Does.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T02-L02"}]}'::jsonb,6);
