insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para negar hábitos usamos don''t con I, you, we y they; usamos doesn''t con he, she e it. Después de don''t/doesn''t el verbo vuelve a la forma base: She doesn''t drink, no She doesn''t drinks.","communication_goal":"El estudiante puede expresar hábitos que no realiza usando don''t y doesn''t.","language_focus":["I don''t work on Sundays.","We don''t eat meat.","He doesn''t drink coffee.","She doesn''t study at night.","I do not usually watch TV."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I don''t work on Sundays.","meaning_es":"no hago / no hacen"},{"english":"She doesn''t drink coffee.","meaning_es":"no hace"},{"english":"We don''t eat meat.","meaning_es":"comer carne"},{"english":"He doesn''t drink coffee.","meaning_es":"beber café"},{"english":"I don''t watch TV at night.","meaning_es":"ver televisión"},{"english":"I don''t usually eat late.","meaning_es":"normalmente"}],"dialogue":[{"speaker":"Maya","text":"Do you work on Sundays?"},{"speaker":"Luis","text":"No, I don''t. I don''t work on Sundays."},{"speaker":"Maya","text":"Does your brother drink coffee?"},{"speaker":"Luis","text":"No, he doesn''t. He drinks tea."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Distinguir don''t y doesn''t en respuestas negativas.","models":[{"text":"I don''t work on Sundays.","stress":["don''t","work","Sundays"]},{"text":"He doesn''t drink coffee.","stress":["doesn''t","drink","coffee"]}],"student_feedback":"Haz audible la negación y mantén el verbo principal en forma base."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Maya","text":"Do you work on Sundays?"},{"speaker":"Luis","text":"No, I don''t. I don''t work on Sundays."},{"speaker":"Maya","text":"Does your brother drink coffee?"},{"speaker":"Luis","text":"No, he doesn''t. He drinks tea."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Different habits","text":"Maya works on Saturdays, but she doesn''t work on Sundays. Luis doesn''t drink coffee. He drinks tea. They don''t eat dinner late because they get up early.","interactive_vocabulary":["different","Saturdays","Sundays","tea","late"],"questions":[{"prompt":"When does Maya not work?","options":["On Sundays","On Saturdays","Every day"],"answer":"On Sundays"},{"prompt":"What does Luis drink?","options":["Tea","Coffee","Water only"],"answer":"Tea"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Comparar hábitos y explicar diferencias de rutina.","communication_goal":"El estudiante puede expresar hábitos que no realiza usando don''t y doesn''t.","activities":[{"id":"A1-M2-T02-L03-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu compañero. Comparen tres hábitos y expliquen una diferencia negativa.","role":"friend","student_goal":"Use don''t and doesn''t to compare habits.","allowed_support":["habit cards","sentence starter","Spanish hint"],"success_criteria":["uses don''t","uses doesn''t","answers one Do/Does question"],"feedback_correct":"Comparaste rutinas y expresaste diferencias.","feedback_incorrect":"I/you/we/they = don''t; he/she/it = doesn''t.","estimated_seconds":190,"prompt":"La IA es tu compañero. Comparen tres hábitos y expliquen una diferencia negativa.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T02-L03"},{"id":"A1-M2-T02-L03-E09","type":"transfer_mission","skill":"integrated","instruction":"Graba tres frases: dos hábitos que no haces y uno que otra persona no hace.","prompt":"I don''t ____. I don''t ____. He/She doesn''t ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses don''t twice","uses doesn''t once","uses base verbs"],"feedback_correct":"Expresaste diferencias reales de rutina.","feedback_incorrect":"Usa don''t con I y doesn''t con he/she; no añadas s al verbo.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T02-L03"}]}'::jsonb,6);
