insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una conversación de rutinas combina preguntas con do/does, respuestas afirmativas y negativas, y adverbios de frecuencia. El objetivo es obtener información, no completar una regla aislada.","communication_goal":"El estudiante puede preguntar, responder, afirmar y negar hábitos en una conversación breve.","language_focus":["What time do you...?","Do you...?","Does he/she...?","I usually...","I don''t...","He/She doesn''t..."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Complete the routine interview.","meaning_es":"entrevista"},{"english":"I usually walk to work.","meaning_es":"normalmente"},{"english":"I sometimes cook.","meaning_es":"a veces"},{"english":"She never works late.","meaning_es":"nunca"},{"english":"I walk to work.","meaning_es":"caminar"},{"english":"We cook at home.","meaning_es":"cocinar"}],"dialogue":[{"speaker":"Learner","text":"What time do you get up?"},{"speaker":"Roommate","text":"I get up at six. I usually walk to work."},{"speaker":"Learner","text":"Do you cook at home?"},{"speaker":"Roommate","text":"Yes, I do. I don''t eat out often."},{"speaker":"Learner","text":"Does your sister live here?"},{"speaker":"Roommate","text":"No, she doesn''t. She lives in another city."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Mantener ritmo conversacional en preguntas, respuestas cortas y detalles de frecuencia.","models":[{"text":"What time do you get up?","stress":["time","get up"]},{"text":"I usually walk to work.","stress":["usually","walk","work"]},{"text":"No, she doesn''t.","stress":["no","doesn''t"]}],"student_feedback":"La pregunta debe sonar abierta y la respuesta debe destacar el hábito importante."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Learner","text":"What time do you get up?"},{"speaker":"Roommate","text":"I get up at six. I usually walk to work."},{"speaker":"Learner","text":"Do you cook at home?"},{"speaker":"Roommate","text":"Yes, I do. I don''t eat out often."},{"speaker":"Learner","text":"Does your sister live here?"},{"speaker":"Roommate","text":"No, she doesn''t. She lives in another city."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A routine interview","text":"Tom gets up at six and usually walks to work. He cooks at home, but he sometimes eats out. His sister does not live with him. She lives in another city and never works on Sundays.","interactive_vocabulary":["roommate","often","eats out","another city","never"],"questions":[{"prompt":"How does Tom usually go to work?","options":["He walks","He drives","He takes a train"],"answer":"He walks"},{"prompt":"Where does his sister live?","options":["In another city","With Tom","At the office"],"answer":"In another city"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Completar una entrevista sobre rutinas y comparar respuestas.","communication_goal":"El estudiante puede preguntar, responder, afirmar y negar hábitos en una conversación breve.","activities":[{"id":"A1-M2-T02-L04-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es tu nuevo compañero de vivienda. Haz una entrevista de seis preguntas y reacciona a sus respuestas.","role":"new roommate","student_goal":"Conduct a routine interview using Do/Does and follow-up questions.","allowed_support":["question cards","routine calendar","sentence starter","Spanish hint"],"success_criteria":["asks four questions","uses Do and Does","understands one negative answer","shares two habits"],"feedback_correct":"Mantuviste una entrevista real y obtuviste información útil.","feedback_incorrect":"Alterna preguntas Do/Does y responde con frases completas o respuestas cortas.","estimated_seconds":240,"prompt":"La IA es tu nuevo compañero de vivienda. Haz una entrevista de seis preguntas y reacciona a sus respuestas.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T02-L04"}]}'::jsonb,6);
