insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Do ayuda a formar preguntas con I, you, we y they. Does se usa con he, she e it. El verbo principal permanece en forma base: Does he play?, no Does he plays?.","communication_goal":"El estudiante puede formular preguntas sobre hábitos usando do y does.","language_focus":["Do you like music?","Do they work here?","Does he play tennis?","Does she live nearby?","What do you do?"]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Do you like music?","meaning_es":"gustar"},{"english":"Does he play tennis?","meaning_es":"jugar al tenis"},{"english":"Does she live nearby?","meaning_es":"vivir cerca"},{"english":"Do they work here?","meaning_es":"trabajar aquí"},{"english":"Ask a question.","meaning_es":"pregunta"},{"english":"Give an answer.","meaning_es":"respuesta"}],"dialogue":[{"speaker":"Student","text":"Do you like music?"},{"speaker":"Classmate","text":"Yes, I do."},{"speaker":"Student","text":"Does your brother play tennis?"},{"speaker":"Classmate","text":"No, he doesn''t. He plays soccer."},{"speaker":"Student","text":"Do your friends work here?"},{"speaker":"Classmate","text":"Yes, they do."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir do/does en preguntas con entonación natural.","models":[{"text":"Do you like music?","stress":["like","music"],"intonation":"rising"},{"text":"Does he play tennis?","stress":["play","tennis"],"intonation":"rising"}],"student_feedback":"Do/does suele ser corto; la información principal está en el verbo y el complemento."}'::jsonb,3);
