insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Welcome questions","text":"At the welcome activity, students ask questions. Ana asks Luis if he likes music. Luis asks about her brother. Her brother does not play tennis; he plays soccer. Their friends work at the school.","interactive_vocabulary":["welcome activity","asks","brother","soccer","school"],"questions":[{"prompt":"What does Luis play?","options":["Soccer","Tennis","Music"],"answer":"Soccer"},{"prompt":"Where do their friends work?","options":["At the school","At home","At a park"],"answer":"At the school"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Hacer preguntas para conocer las preferencias y rutinas de otra persona.","communication_goal":"El estudiante puede formular preguntas sobre hábitos usando do y does.","activities":[{"id":"A1-M2-T03-L01-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA es un compañero nuevo. Haz cinco preguntas sobre sus hábitos y familia.","role":"classmate","student_goal":"Use Do and Does questions with base verbs.","allowed_support":["question cards","subject cards","Spanish hint"],"success_criteria":["asks three Do questions","asks two Does questions","uses base verbs"],"feedback_correct":"Hiciste preguntas variadas y gramaticalmente claras.","feedback_incorrect":"Elige do/does por sujeto y deja el verbo en forma base.","estimated_seconds":190,"prompt":"La IA es un compañero nuevo. Haz cinco preguntas sobre sus hábitos y familia.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T03-L01"},{"id":"A1-M2-T03-L01-E09","type":"transfer_mission","skill":"integrated","instruction":"Crea una mini encuesta para una persona conocida.","prompt":"Do you ____? Do you ____? Does your ____ ____?","response_type":"open_speech_or_text","evaluation_criteria":["uses two Do questions","uses one Does question","uses base verbs","has clear meaning"],"feedback_correct":"Usaste auxiliares para obtener información real.","feedback_incorrect":"Revisa el sujeto de cada pregunta.","estimated_seconds":120,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T03-L01"}]}'::jsonb,6);
