insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Las respuestas cortas repiten el auxiliar: Do you...? Yes, I do. Does she...? No, she doesn''t. No repetimos el verbo principal en la respuesta corta.","communication_goal":"El estudiante puede responder preguntas con do/does usando respuestas cortas afirmativas y negativas.","language_focus":["Do you work here? Yes, I do.","Do they live nearby? No, they don''t.","Does he cook? Yes, he does.","Does she drive? No, she doesn''t."]}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Does she drive?","meaning_es":"conducir"},{"english":"Does he cook?","meaning_es":"cocinar"},{"english":"Do they live nearby?","meaning_es":"vivir cerca"},{"english":"Give a short answer.","meaning_es":"respuesta corta"},{"english":"Do you really like it?","meaning_es":"realmente"},{"english":"Ask a follow-up question.","meaning_es":"seguimiento"}],"dialogue":[{"speaker":"Host","text":"Do you work here?"},{"speaker":"Guest","text":"Yes, I do."},{"speaker":"Host","text":"Does your friend work here?"},{"speaker":"Guest","text":"No, she doesn''t. She visits on Saturdays."},{"speaker":"Host","text":"Do they live nearby?"},{"speaker":"Guest","text":"Yes, they do."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"target":"Producir respuestas cortas rápidas sin perder do/does.","models":[{"text":"Yes, I do.","stress":["yes","do"]},{"text":"No, she doesn''t.","stress":["no","doesn''t"]},{"text":"Yes, they do.","stress":["yes","do"]}],"student_feedback":"La palabra final do/doesn''t completa la respuesta; no la elimines."}'::jsonb,3);
