insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Participar en una conversación rápida sobre gustos y hábitos.","communication_goal":"El estudiante puede responder preguntas con do/does usando respuestas cortas afirmativas y negativas.","activities":[{"id":"A1-M2-T03-L02-E08","type":"ai_roleplay","skill":"conversation","instruction":"La IA te hace preguntas rápidas. Responde con short answers y añade detalles cuando sea útil.","role":"event host","student_goal":"Respond naturally with Yes/No short answers and one follow-up detail.","allowed_support":["answer cards","pause mode","Spanish hint"],"success_criteria":["answers four questions","uses do and does","gives one expanded answer"],"feedback_correct":"Respondíste rápidamente y mantuviste la conversación.","feedback_incorrect":"Repite el auxiliar: Yes, I do / No, she doesn''t / Yes, they do.","estimated_seconds":190,"prompt":"La IA te hace preguntas rápidas. Responde con short answers y añade detalles cuando sea útil.","difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T03-L02"},{"id":"A1-M2-T03-L02-E09","type":"transfer_mission","skill":"integrated","instruction":"Crea una encuesta de tres preguntas y escribe las respuestas cortas de un compañero.","prompt":"Do you ____? Yes, I ____. Does he/she ____? No, he/she ____.","response_type":"open_speech_or_text","evaluation_criteria":["uses two short-answer patterns","matches subject and auxiliary","records meaningful answers"],"feedback_correct":"Usaste respuestas cortas en una interacción auténtica.","feedback_incorrect":"Haz coincidir I do, they do, he does o she doesn''t con el sujeto.","estimated_seconds":130,"difficulty":null,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"hint":null,"source_lesson_id":"A1-M2-T03-L02"}]}'::jsonb,6);
