insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"En una respuesta corta repetimos el auxiliar de la pregunta. Con I, you, we y they usamos do o don''t. Con he, she e it usamos does o doesn''t. No repitas el verbo principal: Do you read? Yes, I do.","communication_goal":"Responder preguntas sencillas sobre hábitos y preferencias con respuestas cortas correctas.","language_focus":{"grammar":["Yes, I do.","No, I don''t.","Yes, she does.","No, she doesn''t."],"function":"short answers with do and does"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I read every night.","word":"read","meaning_es":"leer"},{"english":"Does he watch TV?","word":"watch TV","meaning_es":"ver televisión"},{"english":"We don''t go out on Mondays.","word":"go out","meaning_es":"salir"},{"english":"Do you exercise?","word":"exercise","meaning_es":"hacer ejercicio"},{"english":"I usually read.","word":"usually","meaning_es":"normalmente"},{"english":"Yes, I do.","word":"short answer","meaning_es":"respuesta corta"}],"dialogue":[{"speaker":"Mia","english":"Do you read in English?","spanish":"¿Lees en inglés?"},{"speaker":"Leo","english":"Yes, I do. I read short stories.","spanish":"Sí. Leo historias cortas."},{"speaker":"Mia","english":"Does your sister read too?","spanish":"¿Tu hermana también lee?"},{"speaker":"Leo","english":"No, she doesn''t. She watches TV.","spanish":"No. Ella ve televisión."}]}'::jsonb,2);
