insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Two reading habits","text":"Leo reads before bed. Do you read before bed? Yes, I do. Leo''s sister doesn''t read. She watches TV, but she usually exercises in the morning.","glossary":[{"term":"before bed","meaning_es":"antes de dormir"},{"term":"in the morning","meaning_es":"por la mañana"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Conoces a un compañero nuevo y conversan sobre sus actividades cotidianas.","communication_goal":"Responder preguntas sencillas sobre hábitos y preferencias con respuestas cortas correctas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA te pregunta cinco cosas sobre tus hábitos. Responde con Yes, I do o No, I don''t y añade una idea cuando puedas.","scenario":"Un compañero quiere conocer tus hábitos de lectura, ejercicio y tiempo libre.","ai_language":"English with brief Spanish support","prompt":"La IA te pregunta cinco cosas sobre tus hábitos. Responde con Yes, I do o No, I don''t y añade una idea cuando puedas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T03-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba cuatro preguntas y respuestas sobre ti: dos afirmativas y dos negativas.","success_criteria":["usa do o does correctamente","usa don''t o doesn''t correctamente","la respuesta comunica una idea real"],"prompt":"Graba cuatro preguntas y respuestas sobre ti: dos afirmativas y dos negativas.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T03-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["responder cuatro preguntas con do/does","distinguir don''t y doesn''t","producir respuestas comprensibles en voz alta"],"retry":"Si confundes do y does, repasa la tabla de sujetos y vuelve a practicar con ejemplos personales."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para una entrevista básica combina tres movimientos: pregunta, respuesta corta y seguimiento. Do se usa con I/you/we/they; does con he/she/it. Después de does el verbo principal no lleva s: Does he study? Yes, he does.","communication_goal":"Mantener una mini entrevista sobre rutinas usando preguntas con do/does y respuestas breves con seguimiento.","language_focus":{"grammar":["Do you...?","Does he/she...?","Yes, I do.","No, I don''t.","Yes, he/she does.","No, he/she doesn''t."],"function":"asking, answering and following up"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Do you wake up early?","word":"wake up","meaning_es":"despertarse"},{"english":"Does she work here?","word":"work","meaning_es":"trabajar"},{"english":"Do you study English?","word":"study","meaning_es":"estudiar"},{"english":"Does he like music?","word":"like","meaning_es":"gustar"},{"english":"I study every day.","word":"every day","meaning_es":"todos los días"},{"english":"I like coffee. How about you?","word":"how about you?","meaning_es":"¿y tú?"}],"dialogue":[{"speaker":"Nora","english":"Do you study English every day?","spanish":"¿Estudias inglés todos los días?"},{"speaker":"Sam","english":"Yes, I do. How about you?","spanish":"Sí. ¿Y tú?"},{"speaker":"Nora","english":"No, I don''t. I study three times a week.","spanish":"No. Estudio tres veces por semana."},{"speaker":"Sam","english":"Does your brother study English too?","spanish":"¿Tu hermano también estudia inglés?"},{"speaker":"Nora","english":"Yes, he does.","spanish":"Sí."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Do you study English every day?","focus":"reducir do you de forma natural"},{"text":"Does your brother study English too?","focus":"distinguir does y study"}],"tip_es":"Primero busca claridad; después practica unir do you y does your sin perder el sonido final."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Nora","english":"Do you study English every day?","spanish":"¿Estudias inglés todos los días?"},{"speaker":"Sam","english":"Yes, I do. How about you?","spanish":"Sí. ¿Y tú?"},{"speaker":"Nora","english":"No, I don''t. I study three times a week.","spanish":"No. Estudio tres veces por semana."},{"speaker":"Sam","english":"Does your brother study English too?","spanish":"¿Tu hermano también estudia inglés?"},{"speaker":"Nora","english":"Yes, he does.","spanish":"Sí."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A study survey","text":"Nora and Sam are new classmates. Nora doesn''t study English every day. She studies three times a week. Sam studies every day. His brother studies English too, and Sam likes music after class.","glossary":[{"term":"new classmates","meaning_es":"compañeros nuevos de clase"},{"term":"three times a week","meaning_es":"tres veces por semana"},{"term":"after class","meaning_es":"después de clase"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Participas en una actividad de bienvenida y entrevistas a otra persona.","communication_goal":"Mantener una mini entrevista sobre rutinas usando preguntas con do/does y respuestas breves con seguimiento.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero nuevo. Hazle seis preguntas sobre estudio, trabajo, música y rutinas. Responde también a sus preguntas.","scenario":"Welcome survey at the first English class.","ai_language":"Start in English; give Spanish help only after a clear difficulty","prompt":"La IA será un compañero nuevo. Hazle seis preguntas sobre estudio, trabajo, música y rutinas. Responde también a sus preguntas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T03-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Completa una encuesta real con una persona: escribe cuatro preguntas con do/does y registra sus respuestas.","success_criteria":["incluye al menos una pregunta con does","usa dos respuestas negativas o afirmativas correctas","añade un seguimiento con how about you?"],"prompt":"Completa una encuesta real con una persona: escribe cuatro preguntas con do/does y registra sus respuestas.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T03-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["formular preguntas con do y does","responder sin confundir el verbo principal","sostener una mini entrevista de al menos cuatro turnos"],"retry":"Si el resultado es menor de 80%, repasa T03-L01 a L03 y repite la entrevista con preguntas sobre tu vida."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Las palabras interrogativas piden información específica: what = qué/cuál, where = dónde y who = quién. En preguntas con presente simple usamos do/does: Where do you live? Who does she work with? Para preguntar por el verbo to be usamos su orden propio: What is your name?","communication_goal":"Formular y comprender preguntas básicas con what, where y who.","language_focus":{"grammar":["What do you...?","Where do you...?","Who does he/she...?"],"function":"asking for information"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"What is your name?","word":"name","meaning_es":"nombre"},{"english":"Where do you live?","word":"live","meaning_es":"vivir"},{"english":"Where do you work?","word":"work","meaning_es":"trabajar"},{"english":"Who is your friend?","word":"friend","meaning_es":"amigo"},{"english":"What city do you live in?","word":"city","meaning_es":"ciudad"},{"english":"What is your address?","word":"address","meaning_es":"dirección"}],"dialogue":[{"speaker":"Ana","english":"What is your name?","spanish":"¿Cómo te llamas?"},{"speaker":"Ben","english":"I''m Ben. What is your name?","spanish":"Soy Ben. ¿Cómo te llamas?"},{"speaker":"Ana","english":"I''m Ana. Where do you live?","spanish":"Soy Ana. ¿Dónde vives?"},{"speaker":"Ben","english":"I live in Miami. Who is your friend?","spanish":"Vivo en Miami. ¿Quién es tu amigo?"},{"speaker":"Ana","english":"That is Carlos. He lives next door.","spanish":"Ese es Carlos. Vive al lado."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"What is your name?","focus":"entonación ascendente y unión what is"},{"text":"Where do you live?","focus":"reducir do you sin perder claridad"},{"text":"Who is your friend?","focus":"mantener claro el sonido /h/"}],"tip_es":"Escucha la pregunta completa antes de responder; la palabra interrogativa indica qué información debes dar."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Ana","english":"What is your name?","spanish":"¿Cómo te llamas?"},{"speaker":"Ben","english":"I''m Ben. What is your name?","spanish":"Soy Ben. ¿Cómo te llamas?"},{"speaker":"Ana","english":"I''m Ana. Where do you live?","spanish":"Soy Ana. ¿Dónde vives?"},{"speaker":"Ben","english":"I live in Miami. Who is your friend?","spanish":"Vivo en Miami. ¿Quién es tu amigo?"},{"speaker":"Ana","english":"That is Carlos. He lives next door.","spanish":"Ese es Carlos. Vive al lado."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A new neighbor","text":"Ben is Ana''s new neighbor. What is his name? His name is Ben. Where does he live? He lives in Miami. Who is Ana''s friend? Her friend is Carlos. Carlos lives next door.","glossary":[{"term":"neighbor","meaning_es":"vecino"},{"term":"next door","meaning_es":"al lado"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Necesitas conocer datos sencillos de una persona y de un lugar.","communication_goal":"Formular y comprender preguntas básicas con what, where y who.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será tu nuevo vecino. Pregunta su nombre, ciudad y trabajo; responde también a sus preguntas.","scenario":"First conversation with a neighbor.","ai_language":"English with Spanish support after an unsuccessful attempt","prompt":"La IA será tu nuevo vecino. Pregunta su nombre, ciudad y trabajo; responde también a sus preguntas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T04-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Escribe y graba tres preguntas para conocer a un compañero nuevo: una con what, una con where y una con who.","success_criteria":["cada pregunta busca información diferente","usa do cuando corresponde","la pronunciación es comprensible"],"prompt":"Escribe y graba tres preguntas para conocer a un compañero nuevo: una con what, una con where y una con who.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T04-L01"}]}'::jsonb,6);
