insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"When pregunta por tiempo, why por razón y how por manera o proceso. La respuesta a why suele comenzar con because. How often pregunta frecuencia: How often do you practice? También puedes responder con every day, once a week o three times a week.","communication_goal":"Preguntar por tiempo, razones y maneras de hacer algo usando when, why y how.","language_focus":{"grammar":["When do you...?","Why do you...?","How do you...?","How often...?"],"function":"asking about time, reason and manner"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"When does the class start?","word":"start","meaning_es":"empezar"},{"english":"When do you finish work?","word":"finish","meaning_es":"terminar"},{"english":"I study because I need English.","word":"because","meaning_es":"porque"},{"english":"Why do you wake up early?","word":"early","meaning_es":"temprano"},{"english":"How do you get to work?","word":"get to","meaning_es":"llegar a"},{"english":"How often do you practice?","word":"often","meaning_es":"a menudo"}],"dialogue":[{"speaker":"Maya","english":"When does the class start?","spanish":"¿Cuándo empieza la clase?"},{"speaker":"Omar","english":"It starts at six. Why do you ask?","spanish":"Empieza a las seis. ¿Por qué preguntas?"},{"speaker":"Maya","english":"Because I work until five. How do you get here?","spanish":"Porque trabajo hasta las cinco. ¿Cómo llegas aquí?"},{"speaker":"Omar","english":"I take the bus. How often do you study English?","spanish":"Tomo el autobús. ¿Con qué frecuencia estudias inglés?"},{"speaker":"Maya","english":"I study three times a week.","spanish":"Estudio tres veces por semana."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"When does the class start?","focus":"does the como grupo de palabras"},{"text":"Why do you ask?","focus":"sonido /w/ inicial de why"},{"text":"How often do you practice?","focus":"ritmo de la pregunta completa"}],"tip_es":"Practica las preguntas como unidades de sentido, con una pausa breve antes de la respuesta."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Maya","english":"When does the class start?","spanish":"¿Cuándo empieza la clase?"},{"speaker":"Omar","english":"It starts at six. Why do you ask?","spanish":"Empieza a las seis. ¿Por qué preguntas?"},{"speaker":"Maya","english":"Because I work until five. How do you get here?","spanish":"Porque trabajo hasta las cinco. ¿Cómo llegas aquí?"},{"speaker":"Omar","english":"I take the bus. How often do you study English?","spanish":"Tomo el autobús. ¿Con qué frecuencia estudias inglés?"},{"speaker":"Maya","english":"I study three times a week.","spanish":"Estudio tres veces por semana."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A busy schedule","text":"Maya works until five, so she studies English in the evening. When does her class start? It starts at six. Why does she study? She studies because she needs English for work. She takes the bus and practices three times a week.","glossary":[{"term":"until five","meaning_es":"hasta las cinco"},{"term":"in the evening","meaning_es":"por la tarde/noche"},{"term":"needs English for work","meaning_es":"necesita inglés para el trabajo"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Organizas una actividad y necesitas aclarar horarios, razones y procedimientos.","communication_goal":"Preguntar por tiempo, razones y maneras de hacer algo usando when, why y how.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un organizador de clases. Pregunta cuándo empieza, por qué estudias, cómo llegas y con qué frecuencia practicas.","scenario":"Planning your weekly English class.","ai_language":"English first; Spanish explanation only when requested","prompt":"La IA será un organizador de clases. Pregunta cuándo empieza, por qué estudias, cómo llegas y con qué frecuencia practicas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T04-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Haz una encuesta a un compañero con cuatro preguntas: when, why, how y how often. Resume sus respuestas en cuatro frases.","success_criteria":["cada palabra interrogativa tiene un propósito correcto","incluye because para una razón","incluye una expresión de frecuencia"],"prompt":"Haz una encuesta a un compañero con cuatro preguntas: when, why, how y how often. Resume sus respuestas en cuatro frases.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T04-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["usar when, why y how sin traducir literalmente","dar razones con because","preguntar y responder sobre frecuencia"],"retry":"Si confundes when y why, responde primero si buscas un momento o una razón y vuelve a construir la pregunta."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Antes de preguntar, identifica el tipo de información: persona = who, lugar = where, momento = when, razón = why, manera = how y cosa o dato = what. La estructura cambia según el verbo: Where is it? usa to be; Where do you work? usa do; When does it open? usa does.","communication_goal":"Seleccionar y formular la pregunta adecuada para obtener información concreta en una conversación.","language_focus":{"grammar":["What do you need?","Where is it?","Who is she?","When does it open?","Why are you here?","How much is it?"],"function":"clarifying information"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"What do you need?","word":"need","meaning_es":"necesitar"},{"english":"When does the store open?","word":"open","meaning_es":"abrir/estar abierto"},{"english":"How much does it cost?","word":"cost","meaning_es":"costar"},{"english":"Who is the manager?","word":"manager","meaning_es":"gerente"},{"english":"Is this seat available?","word":"available","meaning_es":"disponible"},{"english":"What is the problem?","word":"problem","meaning_es":"problema"}],"dialogue":[{"speaker":"Visitor","english":"Excuse me. Where is room five?","spanish":"Disculpe. ¿Dónde está la sala cinco?"},{"speaker":"Assistant","english":"It is upstairs. What do you need?","spanish":"Está arriba. ¿Qué necesita?"},{"speaker":"Visitor","english":"I need the English class. When does it start?","spanish":"Necesito la clase de inglés. ¿Cuándo empieza?"},{"speaker":"Assistant","english":"It starts at ten. Who is your teacher?","spanish":"Empieza a las diez. ¿Quién es su profesor?"},{"speaker":"Visitor","english":"I don''t know. How do I get to room five?","spanish":"No lo sé. ¿Cómo llego a la sala cinco?"}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Excuse me. Where is room five?","focus":"entonación amable y enlace where is"},{"text":"When does it start?","focus":"does it como unidad"},{"text":"How do I get there?","focus":"sonido inicial /h/ y ritmo"}],"tip_es":"La entonación y Excuse me ayudan a que una pregunta directa suene natural y educada."}'::jsonb,3);
