insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Finding a room","text":"A visitor is at an information desk. She needs the English class, but she doesn''t know the room. She asks where room five is and when the class starts. The assistant explains how to get there.","glossary":[{"term":"information desk","meaning_es":"mostrador de información"},{"term":"upstairs","meaning_es":"arriba"},{"term":"get there","meaning_es":"llegar allí"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"En una cafetería, una clase y una oficina necesitas aclarar información rápidamente.","communication_goal":"Seleccionar y formular la pregunta adecuada para obtener información concreta en una conversación.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un asistente de información. Pregunta por una sala, horario, precio y dirección; reacciona a sus respuestas.","scenario":"You are looking for a class in a new building.","ai_language":"English with a Spanish hint only if you choose the wrong question type","prompt":"La IA será un asistente de información. Pregunta por una sala, horario, precio y dirección; reacciona a sus respuestas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T04-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Crea seis preguntas para una situación real: una con cada palabra interrogativa estudiada.","success_criteria":["what, where, when, why, who y how aparecen una vez","cada pregunta busca información coherente","incluye al menos una fórmula cortés"],"prompt":"Crea seis preguntas para una situación real: una con cada palabra interrogativa estudiada.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T04-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["elegir la palabra interrogativa correcta","distinguir to be de do/does","formular preguntas corteses y comprensibles"],"retry":"Si eliges una palabra incorrecta, identifica primero qué tipo de respuesta esperas: persona, lugar, tiempo, razón, manera o cosa."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una conversación real combina preguntas con to be y con do/does. Usa What is your name? y Where are you from? con to be. Usa Where do you live? y Why do you study? con do. Escucha la respuesta y formula una pregunta de seguimiento relacionada, en lugar de cambiar de tema sin conexión.","communication_goal":"Mantener una conversación breve haciendo y respondiendo preguntas básicas de forma natural.","language_focus":{"grammar":["what, where, when, why, who, how","do/does questions","to be questions","short answers"],"function":"integrated information exchange"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Where is your hometown?","word":"hometown","meaning_es":"ciudad natal"},{"english":"What is your favorite food?","word":"favorite","meaning_es":"favorito"},{"english":"What do you usually do?","word":"usually","meaning_es":"normalmente"},{"english":"What do you do on weekends?","word":"weekend","meaning_es":"fin de semana"},{"english":"Why is it interesting?","word":"interesting","meaning_es":"interesante"},{"english":"Tell me about your family.","word":"tell me","meaning_es":"cuéntame"}],"dialogue":[{"speaker":"Ella","english":"Hi! What is your name?","spanish":"¡Hola! ¿Cómo te llamas?"},{"speaker":"Diego","english":"I''m Diego. Where are you from?","spanish":"Soy Diego. ¿De dónde eres?"},{"speaker":"Ella","english":"I''m from Canada. What do you usually do on weekends?","spanish":"Soy de Canadá. ¿Qué haces normalmente los fines de semana?"},{"speaker":"Diego","english":"I visit my family. Who do you live with?","spanish":"Visito a mi familia. ¿Con quién vives?"},{"speaker":"Ella","english":"I live with my sister. Why do you study English?","spanish":"Vivo con mi hermana. ¿Por qué estudias inglés?"},{"speaker":"Diego","english":"Because I want to travel.","spanish":"Porque quiero viajar."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Where are you from?","focus":"unir where are you"},{"text":"What do you usually do on weekends?","focus":"ritmo y palabra usually"},{"text":"Why do you study English?","focus":"entonación y because en la respuesta"}],"tip_es":"Practica la entrevista en bloques: saludo, información personal, rutina, razón y despedida."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Ella","english":"Hi! What is your name?","spanish":"¡Hola! ¿Cómo te llamas?"},{"speaker":"Diego","english":"I''m Diego. Where are you from?","spanish":"Soy Diego. ¿De dónde eres?"},{"speaker":"Ella","english":"I''m from Canada. What do you usually do on weekends?","spanish":"Soy de Canadá. ¿Qué haces normalmente los fines de semana?"},{"speaker":"Diego","english":"I visit my family. Who do you live with?","spanish":"Visito a mi familia. ¿Con quién vives?"},{"speaker":"Ella","english":"I live with my sister. Why do you study English?","spanish":"Vivo con mi hermana. ¿Por qué estudias inglés?"},{"speaker":"Diego","english":"Because I want to travel.","spanish":"Porque quiero viajar."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Getting to know Diego","text":"Diego is a new student. He is from Canada, but he wants to travel and study English. On weekends, he visits his family. He lives with his sister. His classmate asks questions because she wants to know him better.","glossary":[{"term":"new student","meaning_es":"estudiante nuevo"},{"term":"wants to travel","meaning_es":"quiere viajar"},{"term":"know him better","meaning_es":"conocerlo mejor"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Conoces a una persona nueva y quieres aprender sobre su vida, rutina y preferencias.","communication_goal":"Mantener una conversación breve haciendo y respondiendo preguntas básicas de forma natural.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Realiza una entrevista de bienvenida con la IA. Debes hacer al menos seis preguntas y una pregunta de seguimiento después de una respuesta.","scenario":"First day in an international English class.","ai_language":"English conversation; provide a brief Spanish explanation after a repeated error","prompt":"Realiza una entrevista de bienvenida con la IA. Debes hacer al menos seis preguntas y una pregunta de seguimiento después de una respuesta.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T04-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una entrevista contigo mismo: formula seis preguntas y responde con información real. Incluye una pregunta con cada palabra interrogativa.","success_criteria":["usa las seis palabras interrogativas","combina to be y do/does","responde con frases completas","incluye una razón con because"],"prompt":"Graba una entrevista contigo mismo: formula seis preguntas y responde con información real. Incluye una pregunta con cada palabra interrogativa.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T04-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["usar correctamente las seis palabras interrogativas","combinar preguntas con to be y do/does","mantener al menos seis turnos de conversación"],"retry":"Si el resultado es menor de 80%, repasa la pregunta que causó el error y vuelve a usarla en una situación personal."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para negar acciones en presente simple usa sujeto + don''t + verbo base. Don''t es la contracción de do not. No agregues s al verbo después de don''t: I don''t drive, no I don''t drives. La negación va antes del verbo principal.","communication_goal":"Expresar hábitos y acciones que no realizas usando don''t con I, you, we y they.","language_focus":{"grammar":["I don''t...","You don''t...","We don''t...","They don''t..."],"function":"negative statements in the present simple"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I don''t drive to work.","word":"drive","meaning_es":"conducir"},{"english":"I don''t drink coffee.","word":"drink coffee","meaning_es":"tomar café"},{"english":"We don''t watch the news.","word":"watch the news","meaning_es":"ver las noticias"},{"english":"They don''t work on Sundays.","word":"work on Sundays","meaning_es":"trabajar los domingos"},{"english":"I exercise every morning.","word":"every morning","meaning_es":"cada mañana"},{"english":"We don''t often eat out.","word":"often","meaning_es":"a menudo"}],"dialogue":[{"speaker":"Julia","english":"Do you drive to work?","spanish":"¿Conduces al trabajo?"},{"speaker":"Marco","english":"No, I don''t. I take the bus.","spanish":"No. Tomo el autobús."},{"speaker":"Julia","english":"Do you drink coffee in the morning?","spanish":"¿Tomas café por la mañana?"},{"speaker":"Marco","english":"No, I don''t. We drink tea at home.","spanish":"No. En casa tomamos té."},{"speaker":"Julia","english":"My parents don''t work on Sundays either.","spanish":"Mis padres tampoco trabajan los domingos."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I don''t drive.","focus":"contracción don''t clara"},{"text":"We don''t work on Sundays.","focus":"ritmo de la negación"},{"text":"They don''t drink coffee either.","focus":"either al final"}],"tip_es":"La palabra don''t debe escucharse, pero no la acentúes más que toda la frase."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Julia","english":"Do you drive to work?","spanish":"¿Conduces al trabajo?"},{"speaker":"Marco","english":"No, I don''t. I take the bus.","spanish":"No. Tomo el autobús."},{"speaker":"Julia","english":"Do you drink coffee in the morning?","spanish":"¿Tomas café por la mañana?"},{"speaker":"Marco","english":"No, I don''t. We drink tea at home.","spanish":"No. En casa tomamos té."},{"speaker":"Julia","english":"My parents don''t work on Sundays either.","spanish":"Mis padres tampoco trabajan los domingos."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A different morning","text":"Marco doesn''t drive to work. He takes the bus. He doesn''t drink coffee, either. He drinks tea at home. On Sundays, he and his friends don''t work. They play soccer instead.","glossary":[{"term":"either","meaning_es":"tampoco"},{"term":"instead","meaning_es":"en cambio"},{"term":"play soccer","meaning_es":"jugar al fútbol"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Hablas sobre tu rutina y aclaras qué actividades no forman parte de tu día.","communication_goal":"Expresar hábitos y acciones que no realizas usando don''t con I, you, we y they.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero comparando rutinas. Responde con frases afirmativas o negativas y explica una diferencia.","scenario":"You and a classmate compare morning routines.","ai_language":"English with a Spanish hint after two failed attempts","prompt":"La IA será un compañero comparando rutinas. Responde con frases afirmativas o negativas y explica una diferencia.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T05-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Escribe y graba cinco cosas que no haces en tu rutina. Añade una alternativa para dos de ellas.","success_criteria":["usa don''t correctamente","mantiene el verbo en forma base","las frases describen tu vida real"],"prompt":"Escribe y graba cinco cosas que no haces en tu rutina. Añade una alternativa para dos de ellas.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T05-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["formar negaciones con don''t","usar el verbo base después de don''t","explicar al menos tres hábitos que no realiza"],"retry":"Si agregas s después de don''t, repite la regla: don''t + verbo base."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Con he, she e it usamos doesn''t = does not para negar. La estructura es sujeto + doesn''t + verbo base: She doesn''t drive. Aunque el sujeto sea tercera persona, la s desaparece del verbo porque ya está representada en does: He doesn''t eat, no He doesn''t eats.","communication_goal":"Describir hábitos negativos de otras personas usando doesn''t con he, she e it.","language_focus":{"grammar":["He doesn''t...","She doesn''t...","It doesn''t..."],"function":"third-person negative statements"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"She doesn''t eat meat.","word":"eat meat","meaning_es":"comer carne"},{"english":"He doesn''t like spicy food.","word":"like spicy food","meaning_es":"gustarle la comida picante"},{"english":"She doesn''t use a car.","word":"use a car","meaning_es":"usar un automóvil"},{"english":"He doesn''t sleep late.","word":"sleep late","meaning_es":"dormir hasta tarde"},{"english":"It doesn''t need batteries.","word":"need","meaning_es":"necesitar"},{"english":"She usually walks.","word":"usually","meaning_es":"normalmente"}],"dialogue":[{"speaker":"Nina","english":"Does your brother eat meat?","spanish":"¿Tu hermano come carne?"},{"speaker":"Luis","english":"No, he doesn''t. He eats vegetables.","spanish":"No. Come verduras."},{"speaker":"Nina","english":"Does your sister drive?","spanish":"¿Tu hermana conduce?"},{"speaker":"Luis","english":"No, she doesn''t. She walks to work.","spanish":"No. Camina al trabajo."},{"speaker":"Nina","english":"That sounds healthy.","spanish":"Eso suena saludable."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"She doesn''t drive.","focus":"contracción doesn''t"},{"text":"He doesn''t eat meat.","focus":"enlace doesn''t eat"},{"text":"It doesn''t need batteries.","focus":"it y doesn''t claramente separados"}],"tip_es":"Graba primero lentamente y luego a velocidad conversacional; comprueba que doesn''t no desaparezca."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Nina","english":"Does your brother eat meat?","spanish":"¿Tu hermano come carne?"},{"speaker":"Luis","english":"No, he doesn''t. He eats vegetables.","spanish":"No. Come verduras."},{"speaker":"Nina","english":"Does your sister drive?","spanish":"¿Tu hermana conduce?"},{"speaker":"Luis","english":"No, she doesn''t. She walks to work.","spanish":"No. Camina al trabajo."},{"speaker":"Nina","english":"That sounds healthy.","spanish":"Eso suena saludable."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Lucía''s healthy routine","text":"Lucía doesn''t eat meat and she doesn''t drink soda. She walks to work because she doesn''t use a car. Her brother likes fast food, but he doesn''t cook at home. Their dog doesn''t need a car; it walks with Lucía.","glossary":[{"term":"soda","meaning_es":"refresco/gaseosa"},{"term":"fast food","meaning_es":"comida rápida"},{"term":"walks with","meaning_es":"camina con"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Explicas la rutina de familiares y compañeros sin confundir la tercera persona.","communication_goal":"Describir hábitos negativos de otras personas usando doesn''t con he, she e it.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Describe a un familiar o amigo. La IA hace preguntas sobre lo que esa persona hace y no hace.","scenario":"You are describing a family member''s routine to a curious classmate.","ai_language":"English; correct only the target error and keep the conversation moving","prompt":"Describe a un familiar o amigo. La IA hace preguntas sobre lo que esa persona hace y no hace.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T05-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Escribe seis frases sobre dos personas: tres con doesn''t para cada una. Incluye una diferencia entre sus rutinas.","success_criteria":["usa he/she correctamente","usa doesn''t + verbo base","las frases son comprensibles y conectadas"],"prompt":"Escribe seis frases sobre dos personas: tres con doesn''t para cada una. Incluye una diferencia entre sus rutinas.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T05-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["usar doesn''t con he, she e it","mantener el verbo base","describir hábitos negativos de dos personas"],"retry":"Si escribes doesn''t + verbo con s, elimina la s y recuerda que does ya marca la tercera persona."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una pregunta negativa confirma una idea o expresa sorpresa: Don''t you bring lunch? y Doesn''t he work here? Para responder, piensa en el hecho real, no solo en la forma negativa. Si traes almuerzo, responde Yes, I do; si no, No, I don''t.","communication_goal":"Formular preguntas negativas y responderlas para confirmar información sobre hábitos.","language_focus":{"grammar":["Don''t you...?","Doesn''t he/she...?","No, I don''t.","Yes, she does."],"function":"negative questions and confirmation"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Don''t you remember?","word":"remember","meaning_es":"recordar"},{"english":"I don''t forget my keys.","word":"forget","meaning_es":"olvidar"},{"english":"Doesn''t he bring lunch?","word":"bring","meaning_es":"traer"},{"english":"I don''t understand.","word":"understand","meaning_es":"entender"},{"english":"She usually brings lunch.","word":"usually","meaning_es":"normalmente"},{"english":"Don''t you already know?","word":"already","meaning_es":"ya"}],"dialogue":[{"speaker":"Eva","english":"Doesn''t Tom bring lunch?","spanish":"¿Tom no trae el almuerzo?"},{"speaker":"Nora","english":"No, he doesn''t. He buys lunch here.","spanish":"No. Compra el almuerzo aquí."},{"speaker":"Eva","english":"Don''t you bring lunch?","spanish":"¿Tú no traes el almuerzo?"},{"speaker":"Nora","english":"Yes, I do. I bring lunch every day.","spanish":"Sí. Traigo el almuerzo todos los días."},{"speaker":"Eva","english":"Oh, I understand now.","spanish":"Ah, ahora entiendo."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Don''t you bring lunch?","focus":"unir don''t you y entonación"},{"text":"Doesn''t he work here?","focus":"contracción doesn''t"},{"text":"Yes, I do.","focus":"respuesta breve clara"}],"tip_es":"Practica cada pregunta con dos respuestas posibles para evitar responder por la forma y no por el significado."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Eva","english":"Doesn''t Tom bring lunch?","spanish":"¿Tom no trae el almuerzo?"},{"speaker":"Nora","english":"No, he doesn''t. He buys lunch here.","spanish":"No. Compra el almuerzo aquí."},{"speaker":"Eva","english":"Don''t you bring lunch?","spanish":"¿Tú no traes el almuerzo?"},{"speaker":"Nora","english":"Yes, I do. I bring lunch every day.","spanish":"Sí. Traigo el almuerzo todos los días."},{"speaker":"Eva","english":"Oh, I understand now.","spanish":"Ah, ahora entiendo."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The lunch plan","text":"Nora brings lunch every day. Eva thinks Tom brings lunch too, but he doesn''t. He buys lunch at the cafe. Eva asks Nora, ''Don''t you bring lunch?''. Nora says yes, she does, and explains her routine.","glossary":[{"term":"lunch plan","meaning_es":"plan del almuerzo"},{"term":"buys lunch","meaning_es":"compra el almuerzo"},{"term":"cafe","meaning_es":"cafetería"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Compruebas si una persona realiza una actividad o aclaras una suposición.","communication_goal":"Formular preguntas negativas y responderlas para confirmar información sobre hábitos.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA hace suposiciones sobre tu rutina. Confírmalas o corrígelas con Yes/No y una frase adicional.","scenario":"A classmate is checking the details of your daily routine.","ai_language":"English; keep questions short and natural","prompt":"La IA hace suposiciones sobre tu rutina. Confírmalas o corrígelas con Yes/No y una frase adicional.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T05-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Escribe cuatro preguntas negativas sobre hábitos de una persona conocida y responde cada una según la realidad.","success_criteria":["usa don''t con I/you/we/they","usa doesn''t con he/she/it","responde según el hecho real"],"prompt":"Escribe cuatro preguntas negativas sobre hábitos de una persona conocida y responde cada una según la realidad.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T05-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["interpretar preguntas negativas","responder según el significado real","evitar la s después de does/doesn''t"],"retry":"Si inviertes Yes y No, vuelve a contestar con hechos concretos: ¿la acción ocurre o no ocurre?"},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para hablar con naturalidad combina afirmaciones y negaciones: I work, but I don''t work on Sundays. Usa and para añadir, but para contrastar y because para explicar una razón. En tercera persona: She prepares breakfast, but she doesn''t work on Sundays.","communication_goal":"Describir hábitos afirmativos y negativos de forma conectada, comprensible y personal.","language_focus":{"grammar":["present simple affirmative and negative","don''t/doesn''t","do/does questions","because, but, and"],"function":"connected routine description"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I don''t relax in the morning.","word":"relax","meaning_es":"relajarse"},{"english":"She prepares breakfast.","word":"prepare","meaning_es":"preparar"},{"english":"We take a break at noon.","word":"take a break","meaning_es":"tomarse un descanso"},{"english":"My mornings are busy.","word":"busy","meaning_es":"ocupado"},{"english":"I don''t have much free time.","word":"free time","meaning_es":"tiempo libre"},{"english":"He works on weekdays.","word":"on weekdays","meaning_es":"entre semana"}],"dialogue":[{"speaker":"Sara","english":"I work on weekdays, but I don''t work on Sundays.","spanish":"Trabajo entre semana, pero no trabajo los domingos."},{"speaker":"David","english":"I don''t work on Sundays either. I prepare breakfast for my family.","spanish":"Yo tampoco trabajo los domingos. Preparo el desayuno para mi familia."},{"speaker":"Sara","english":"Does your family eat together?","spanish":"¿Tu familia come junta?"},{"speaker":"David","english":"Yes, they do. We usually eat at eight.","spanish":"Sí. Normalmente comemos a las ocho."},{"speaker":"Sara","english":"My family doesn''t eat together because our schedules are different.","spanish":"Mi familia no come junta porque nuestros horarios son diferentes."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I work on weekdays, but I don''t work on Sundays.","focus":"contraste work/don''t work"},{"text":"She prepares breakfast, but she doesn''t work on Sundays.","focus":"s de prepares y verbo base después de doesn''t"},{"text":"We usually eat together.","focus":"ritmo y usually"}],"tip_es":"Marca el contraste con la voz, no con pausas excesivas: afirmación, but, negación."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Sara","english":"I work on weekdays, but I don''t work on Sundays.","spanish":"Trabajo entre semana, pero no trabajo los domingos."},{"speaker":"David","english":"I don''t work on Sundays either. I prepare breakfast for my family.","spanish":"Yo tampoco trabajo los domingos. Preparo el desayuno para mi familia."},{"speaker":"Sara","english":"Does your family eat together?","spanish":"¿Tu familia come junta?"},{"speaker":"David","english":"Yes, they do. We usually eat at eight.","spanish":"Sí. Normalmente comemos a las ocho."},{"speaker":"Sara","english":"My family doesn''t eat together because our schedules are different.","spanish":"Mi familia no come junta porque nuestros horarios son diferentes."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A balanced week","text":"David works on weekdays, but he doesn''t work on Sundays. He prepares breakfast and eats with his family. Sara works too, but her family doesn''t eat together because their schedules are different. On weekends, Sara relaxes and David visits his parents.","glossary":[{"term":"balanced week","meaning_es":"semana equilibrada"},{"term":"schedules are different","meaning_es":"los horarios son diferentes"},{"term":"visits his parents","meaning_es":"visita a sus padres"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Presentas tu rutina y comparas tus hábitos con los de otra persona.","communication_goal":"Describir hábitos afirmativos y negativos de forma conectada, comprensible y personal.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero que compara su semana contigo. Describe cuatro hábitos, dos positivos y dos negativos, y pregunta por los suyos.","scenario":"Comparing weekday and weekend routines.","ai_language":"English conversation with encouraging corrective feedback","prompt":"La IA será un compañero que compara su semana contigo. Describe cuatro hábitos, dos positivos y dos negativos, y pregunta por los suyos.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T05-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una descripción de 45 segundos de tu rutina. Incluye cinco afirmaciones, tres negaciones y una comparación con otra persona.","success_criteria":["usa don''t/doesn''t correctamente","conecta ideas con and, but o because","comunica una rutina real y comprensible"],"prompt":"Graba una descripción de 45 segundos de tu rutina. Incluye cinco afirmaciones, tres negaciones y una comparación con otra persona.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T05-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["combinar afirmativas y negativas","usar don''t y doesn''t según el sujeto","describir una rutina conectando ideas"],"retry":"Si el resultado es menor de 80%, vuelve a describir un día real con frases cortas antes de intentar una presentación más larga."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Los adverbios de frecuencia indican cuántas veces ocurre algo: always, usually, often, sometimes y never. Forman una escala: always es 100% y never es 0%. La pregunta más común es How often do you...? y la respuesta puede ser un adverbio o una expresión como every day.","communication_goal":"Describir con qué frecuencia realizas actividades cotidianas usando adverbios básicos.","language_focus":{"grammar":["always","usually","often","sometimes","never"],"function":"expressing frequency"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I always eat breakfast.","word":"always","meaning_es":"siempre"},{"english":"I usually walk to work.","word":"usually","meaning_es":"normalmente"},{"english":"We often study together.","word":"often","meaning_es":"a menudo"},{"english":"She sometimes cooks.","word":"sometimes","meaning_es":"a veces"},{"english":"They never smoke.","word":"never","meaning_es":"nunca"},{"english":"I practice often.","word":"practice","meaning_es":"practicar"}],"dialogue":[{"speaker":"Mia","english":"How often do you practice English?","spanish":"¿Con qué frecuencia practicas inglés?"},{"speaker":"Leo","english":"I always practice in the morning.","spanish":"Siempre practico por la mañana."},{"speaker":"Mia","english":"Do you study with friends?","spanish":"¿Estudias con amigos?"},{"speaker":"Leo","english":"I sometimes study with Ana, but I usually study alone.","spanish":"A veces estudio con Ana, pero normalmente estudio solo."},{"speaker":"Mia","english":"I never study alone. I often practice with my brother.","spanish":"Nunca estudio sola. A menudo practico con mi hermano."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I always practice in the morning.","focus":"always claramente reconocible"},{"text":"I sometimes study with Ana.","focus":"sílabas de sometimes"},{"text":"I never study alone.","focus":"never y ritmo de la frase"}],"tip_es":"Practica la escala con los dedos: always, usually, often, sometimes, never."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Mia","english":"How often do you practice English?","spanish":"¿Con qué frecuencia practicas inglés?"},{"speaker":"Leo","english":"I always practice in the morning.","spanish":"Siempre practico por la mañana."},{"speaker":"Mia","english":"Do you study with friends?","spanish":"¿Estudias con amigos?"},{"speaker":"Leo","english":"I sometimes study with Ana, but I usually study alone.","spanish":"A veces estudio con Ana, pero normalmente estudio solo."},{"speaker":"Mia","english":"I never study alone. I often practice with my brother.","spanish":"Nunca estudio sola. A menudo practico con mi hermano."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Mia''s study habits","text":"Mia always studies English after work. She usually studies at home, but she sometimes goes to a library. She often listens to English on the bus. She never skips her weekly review.","glossary":[{"term":"after work","meaning_es":"después del trabajo"},{"term":"library","meaning_es":"biblioteca"},{"term":"skip","meaning_es":"saltarse/omitir"},{"term":"weekly review","meaning_es":"repaso semanal"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Comparas hábitos y descubres qué actividades haces mucho, poco o nunca.","communication_goal":"Describir con qué frecuencia realizas actividades cotidianas usando adverbios básicos.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA realiza una encuesta sobre tus hábitos. Responde con always, usually, often, sometimes o never y explica una respuesta.","scenario":"A classmate is learning about your study habits.","ai_language":"English with brief Spanish support when needed","prompt":"La IA realiza una encuesta sobre tus hábitos. Responde con always, usually, often, sometimes o never y explica una respuesta.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T06-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Escribe cinco frases sobre tus hábitos de estudio usando cada adverbio una vez. Haz que sean verdaderas para ti.","success_criteria":["usa los cinco adverbios","las frases tienen sentido personal","never no lleva otra negación"],"prompt":"Escribe cinco frases sobre tus hábitos de estudio usando cada adverbio una vez. Haz que sean verdaderas para ti.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T06-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["ordenar la escala de frecuencia","usar cinco adverbios en contexto","evitar la doble negación con never"],"retry":"Si confundes dos adverbios, relaciónalos con un porcentaje y escribe un ejemplo de tu propia rutina."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Con un verbo principal, el adverbio suele ir antes del verbo: She often checks email. Con to be, va después de am/is/are: She is often tired; We are always on time. Sometimes también puede ir al inicio: Sometimes I feel tired.","communication_goal":"Colocar correctamente los adverbios de frecuencia con verbos principales y con el verbo to be.","language_focus":{"grammar":["subject + adverb + main verb","be + adverb","adverb at the beginning/end"],"function":"frequency adverb position"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I am never late.","word":"be late","meaning_es":"llegar tarde/estar tarde"},{"english":"She is often tired.","word":"be tired","meaning_es":"estar cansado"},{"english":"He usually arrives at eight.","word":"arrive","meaning_es":"llegar"},{"english":"I always check my email.","word":"check email","meaning_es":"revisar el correo"},{"english":"They sometimes feel tired.","word":"feel","meaning_es":"sentirse"},{"english":"We are always on time.","word":"on time","meaning_es":"a tiempo"}],"dialogue":[{"speaker":"Manager","english":"Is Ana usually on time?","spanish":"¿Ana suele llegar a tiempo?"},{"speaker":"Ben","english":"Yes, she is. She is always on time.","spanish":"Sí. Siempre llega a tiempo."},{"speaker":"Manager","english":"Does Carlos arrive early?","spanish":"¿Carlos llega temprano?"},{"speaker":"Ben","english":"He usually arrives at eight, but he is sometimes late.","spanish":"Normalmente llega a las ocho, pero a veces llega tarde."},{"speaker":"Manager","english":"I am never late.","spanish":"Yo nunca llego tarde."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"She is always on time.","focus":"unir is always"},{"text":"He usually arrives at eight.","focus":"usually y la s de arrives"},{"text":"I am never late.","focus":"am never con ritmo natural"}],"tip_es":"Haz una pausa visual entre sujeto, adverbio y verbo al practicar, pero luego une la frase al hablar."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Manager","english":"Is Ana usually on time?","spanish":"¿Ana suele llegar a tiempo?"},{"speaker":"Ben","english":"Yes, she is. She is always on time.","spanish":"Sí. Siempre llega a tiempo."},{"speaker":"Manager","english":"Does Carlos arrive early?","spanish":"¿Carlos llega temprano?"},{"speaker":"Ben","english":"He usually arrives at eight, but he is sometimes late.","spanish":"Normalmente llega a las ocho, pero a veces llega tarde."},{"speaker":"Manager","english":"I am never late.","spanish":"Yo nunca llego tarde."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A reliable team","text":"Ana is always on time. She usually checks her email before work. Carlos usually arrives at eight, but he is sometimes late. The manager is never angry because Carlos always calls when he is late.","glossary":[{"term":"reliable","meaning_es":"confiable"},{"term":"before work","meaning_es":"antes del trabajo"},{"term":"angry","meaning_es":"enojado"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Describes rutinas de personas, horarios y estados habituales con frases naturales.","communication_goal":"Colocar correctamente los adverbios de frecuencia con verbos principales y con el verbo to be.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será tu supervisor y preguntará por hábitos de trabajo o estudio. Responde usando adverbios con verbos normales y con to be.","scenario":"Talking about reliable work and study habits.","ai_language":"English; correct adverb position with a short explanation","prompt":"La IA será tu supervisor y preguntará por hábitos de trabajo o estudio. Responde usando adverbios con verbos normales y con to be.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T06-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Describe a una persona en seis frases: tres con verbos principales y tres con am/is/are. Usa seis adverbios de frecuencia.","success_criteria":["coloca el adverbio antes del verbo principal","coloca el adverbio después de be","la descripción es coherente"],"prompt":"Describe a una persona en seis frases: tres con verbos principales y tres con am/is/are. Usa seis adverbios de frecuencia.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T06-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["colocar adverbios con verbos principales","colocarlos correctamente con to be","explicar rutinas de forma natural"],"retry":"Si mezclas las posiciones, separa primero las frases en dos grupos: verbo principal o am/is/are."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Las expresiones de frecuencia dan un número concreto: once a week = una vez por semana, twice a month = dos veces al mes y three times a week = tres veces por semana. Every day no lleva a: every day. Puedes combinar una expresión con un adverbio: I usually practice twice a week.","communication_goal":"Combinar adverbios y expresiones de tiempo para describir con precisión la frecuencia de una actividad.","language_focus":{"grammar":["every day","once a week","twice a month","three times a week","on Mondays"],"function":"specific frequency expressions"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I go once a week.","word":"once","meaning_es":"una vez"},{"english":"She practices twice a week.","word":"twice","meaning_es":"dos veces"},{"english":"We meet three times a month.","word":"three times","meaning_es":"tres veces"},{"english":"I study on weekdays.","word":"weekday","meaning_es":"día entre semana"},{"english":"We have a monthly meeting.","word":"monthly","meaning_es":"mensual"},{"english":"My schedule is busy.","word":"schedule","meaning_es":"horario/plan"}],"dialogue":[{"speaker":"Lina","english":"How often do you go to the gym?","spanish":"¿Con qué frecuencia vas al gimnasio?"},{"speaker":"Owen","english":"I go three times a week, usually on Mondays, Wednesdays and Fridays.","spanish":"Voy tres veces por semana, normalmente los lunes, miércoles y viernes."},{"speaker":"Lina","english":"I exercise every day, but I take a class only once a week.","spanish":"Hago ejercicio todos los días, pero tomo una clase solo una vez por semana."},{"speaker":"Owen","english":"How often do you practice English?","spanish":"¿Con qué frecuencia practicas inglés?"},{"speaker":"Lina","english":"I practice twice a week with my study group.","spanish":"Practico dos veces por semana con mi grupo de estudio."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"three times a week","focus":"th de three y unión times a"},{"text":"once a week","focus":"once claramente, sin añadir sílabas"},{"text":"twice a month","focus":"twice y month"}],"tip_es":"Repite las expresiones como bloques completos, no palabra por palabra."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Lina","english":"How often do you go to the gym?","spanish":"¿Con qué frecuencia vas al gimnasio?"},{"speaker":"Owen","english":"I go three times a week, usually on Mondays, Wednesdays and Fridays.","spanish":"Voy tres veces por semana, normalmente los lunes, miércoles y viernes."},{"speaker":"Lina","english":"I exercise every day, but I take a class only once a week.","spanish":"Hago ejercicio todos los días, pero tomo una clase solo una vez por semana."},{"speaker":"Owen","english":"How often do you practice English?","spanish":"¿Con qué frecuencia practicas inglés?"},{"speaker":"Lina","english":"I practice twice a week with my study group.","spanish":"Practico dos veces por semana con mi grupo de estudio."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A practical schedule","text":"Owen goes to the gym three times a week. He practices English twice a week with Lina. Lina exercises every day, but she takes an English class once a week. They meet on Fridays to review their schedule.","glossary":[{"term":"practical schedule","meaning_es":"horario práctico"},{"term":"study group","meaning_es":"grupo de estudio"},{"term":"review","meaning_es":"repasar"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Organizas un plan semanal y explicas cuántas veces haces cada actividad.","communication_goal":"Combinar adverbios y expresiones de tiempo para describir con precisión la frecuencia de una actividad.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será tu compañero de planificación. Pregunta y responde sobre actividades semanales usando números y días.","scenario":"Planning a study and exercise schedule.","ai_language":"English; request a concrete frequency when the answer is vague","prompt":"La IA será tu compañero de planificación. Pregunta y responde sobre actividades semanales usando números y días.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T06-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Crea un horario semanal de estudio: cinco actividades con su frecuencia y al menos dos días específicos.","success_criteria":["usa every day, once o twice correctamente","usa on con días","el horario es realista"],"prompt":"Crea un horario semanal de estudio: cinco actividades con su frecuencia y al menos dos días específicos.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T06-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["expresar cantidades de frecuencia","usar on con días","describir un plan semanal concreto"],"retry":"Si confundes once y twice, asócialos con los números 1 y 2 y crea un ejemplo personal para cada uno."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para expresar hábitos con precisión puedes combinar un adverbio y una cantidad: I usually read twice a week. La pregunta How often...? permite pedir la frecuencia. Para mantener la conversación, devuelve la pregunta con How about you? y escucha si la otra persona usa always, sometimes o una expresión concreta.","communication_goal":"Hablar de hábitos con adverbios y expresiones de frecuencia, hacer preguntas y comparar respuestas.","language_focus":{"grammar":["frequency adverbs","frequency expressions","How often...?","present simple questions and answers"],"function":"integrated habit profile"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Reading is a good habit.","word":"habit","meaning_es":"hábito"},{"english":"What do you do in your free time?","word":"free time","meaning_es":"tiempo libre"},{"english":"I often go for a walk.","word":"go for a walk","meaning_es":"salir a caminar"},{"english":"She listens to music every day.","word":"listen to music","meaning_es":"escuchar música"},{"english":"I read for pleasure once a week.","word":"read for pleasure","meaning_es":"leer por placer"},{"english":"We share our habits.","word":"share","meaning_es":"compartir"}],"dialogue":[{"speaker":"Coach","english":"How often do you read for pleasure?","spanish":"¿Con qué frecuencia lees por placer?"},{"speaker":"Rosa","english":"I usually read twice a week. How about you?","spanish":"Normalmente leo dos veces por semana. ¿Y tú?"},{"speaker":"Coach","english":"I always read before bed, but I don''t watch TV every day.","spanish":"Siempre leo antes de dormir, pero no veo televisión todos los días."},{"speaker":"Rosa","english":"Do you go for a walk?","spanish":"¿Sales a caminar?"},{"speaker":"Coach","english":"Yes, I do. I go for a walk three times a week.","spanish":"Sí. Salgo a caminar tres veces por semana."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"How often do you read for pleasure?","focus":"ritmo de how often do you"},{"text":"I usually read twice a week.","focus":"usually y twice a week"},{"text":"How about you?","focus":"entonación de devolución"}],"tip_es":"Practica la pregunta y la respuesta como un par; la conversación debe sonar como intercambio, no como lista."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Coach","english":"How often do you read for pleasure?","spanish":"¿Con qué frecuencia lees por placer?"},{"speaker":"Rosa","english":"I usually read twice a week. How about you?","spanish":"Normalmente leo dos veces por semana. ¿Y tú?"},{"speaker":"Coach","english":"I always read before bed, but I don''t watch TV every day.","spanish":"Siempre leo antes de dormir, pero no veo televisión todos los días."},{"speaker":"Rosa","english":"Do you go for a walk?","spanish":"¿Sales a caminar?"},{"speaker":"Coach","english":"Yes, I do. I go for a walk three times a week.","spanish":"Sí. Salgo a caminar tres veces por semana."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Three different profiles","text":"Rosa usually reads twice a week and often goes for a walk. Leo always listens to music after work, but he never reads for pleasure. Maya reads every day and goes for a walk three times a week. Their habits are different, but they all practice English.","glossary":[{"term":"habit profile","meaning_es":"perfil de hábitos"},{"term":"after work","meaning_es":"después del trabajo"},{"term":"all","meaning_es":"todos"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Completa un perfil de hábitos y conversa sobre las actividades que forman parte de tu vida.","communication_goal":"Hablar de hábitos con adverbios y expresiones de frecuencia, hacer preguntas y comparar respuestas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Completa un perfil de hábitos con la IA. Responde ocho preguntas, devuelve al menos dos con How about you? y compara una actividad.","scenario":"A friendly habit-profile interview.","ai_language":"English conversation with supportive feedback on frequency","prompt":"Completa un perfil de hábitos con la IA. Responde ocho preguntas, devuelve al menos dos con How about you? y compara una actividad.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T06-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un audio de 60 segundos sobre cinco hábitos reales. Usa tres adverbios, dos expresiones de frecuencia, una negación y una pregunta para el oyente.","success_criteria":["varía los adverbios","usa expresiones concretas","mantiene la gramática básica","el mensaje se entiende sin leerlo"],"prompt":"Graba un audio de 60 segundos sobre cinco hábitos reales. Usa tres adverbios, dos expresiones de frecuencia, una negación y una pregunta para el oyente.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T06-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["usar adverbios y expresiones de frecuencia","responder How often con precisión","mantener una conversación breve sobre hábitos"],"retry":"Si el resultado es menor de 80%, vuelve a practicar con tu propio horario y graba respuestas más cortas antes de repetir la evaluación."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una buena conversación usa preguntas relacionadas. Empieza con información básica (what is your name?, where are you from?), continúa con hábitos (when do you study?, how do you spend your free time?) y añade una razón con why. La respuesta de una pregunta puede darte la siguiente pregunta.","communication_goal":"Usar preguntas interrogativas para obtener información personal y mantener una conversación conectada.","language_focus":{"grammar":["What do you like?","Where are you from?","Who do you live with?","When do you study?","Why do you like it?","How do you spend your free time?"],"function":"personal information questions"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"What are your interests?","word":"interest","meaning_es":"interés"},{"english":"What is your hobby?","word":"hobby","meaning_es":"pasatiempo"},{"english":"What is your favorite movie?","word":"favorite","meaning_es":"favorito"},{"english":"How do you spend your free time?","word":"spend time","meaning_es":"pasar tiempo"},{"english":"Who do you study with?","word":"together","meaning_es":"juntos"},{"english":"I like it because it is fun.","word":"because","meaning_es":"porque"}],"dialogue":[{"speaker":"Nadia","english":"Where are you from?","spanish":"¿De dónde eres?"},{"speaker":"Eric","english":"I''m from Peru. What do you do in your free time?","spanish":"Soy de Perú. ¿Qué haces en tu tiempo libre?"},{"speaker":"Nadia","english":"I read and listen to music. Who do you live with?","spanish":"Leo y escucho música. ¿Con quién vives?"},{"speaker":"Eric","english":"I live with my cousin. When do you usually read?","spanish":"Vivo con mi primo. ¿Cuándo sueles leer?"},{"speaker":"Nadia","english":"I read at night because it is quiet.","spanish":"Leo por la noche porque es tranquilo."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"What do you do in your free time?","focus":"reducir do you y ritmo"},{"text":"Who do you live with?","focus":"who y enlace live with"},{"text":"When do you usually read?","focus":"when y usually"}],"tip_es":"Sube la entonación al final de preguntas de información cuando realmente buscas una respuesta nueva."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Nadia","english":"Where are you from?","spanish":"¿De dónde eres?"},{"speaker":"Eric","english":"I''m from Peru. What do you do in your free time?","spanish":"Soy de Perú. ¿Qué haces en tu tiempo libre?"},{"speaker":"Nadia","english":"I read and listen to music. Who do you live with?","spanish":"Leo y escucho música. ¿Con quién vives?"},{"speaker":"Eric","english":"I live with my cousin. When do you usually read?","spanish":"Vivo con mi primo. ¿Cuándo sueles leer?"},{"speaker":"Nadia","english":"I read at night because it is quiet.","spanish":"Leo por la noche porque es tranquilo."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Getting to know Eric","text":"Nadia meets Eric in an English class. He is from Peru and lives with his cousin. In his free time, he reads and listens to music. He usually reads at night because it is quiet.","glossary":[{"term":"conversation starter","meaning_es":"iniciador de conversación"},{"term":"cousin","meaning_es":"primo/prima"},{"term":"quiet","meaning_es":"tranquilo/silencioso"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Conoces a una persona nueva y haces preguntas que avanzan de datos básicos a intereses.","communication_goal":"Usar preguntas interrogativas para obtener información personal y mantener una conversación conectada.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será una persona nueva en tu clase. Haz preguntas conectadas sobre origen, familia, hábitos e intereses.","scenario":"Getting to know a new classmate.","ai_language":"English; suggest a follow-up question only after a long pause","prompt":"La IA será una persona nueva en tu clase. Haz preguntas conectadas sobre origen, familia, hábitos e intereses.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T07-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Escribe una cadena de seis preguntas: cada respuesta imaginaria debe inspirar la siguiente pregunta.","success_criteria":["usa al menos cinco palabras interrogativas","las preguntas están relacionadas","combina to be y do/does"],"prompt":"Escribe una cadena de seis preguntas: cada respuesta imaginaria debe inspirar la siguiente pregunta.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T07-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["elegir la pregunta adecuada","formular preguntas relacionadas","hacer al menos una pregunta de seguimiento"],"retry":"Si las preguntas no se conectan, subraya la información nueva de cada respuesta y úsala para crear la siguiente."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para resolver una necesidad, identifica el dato que falta: lugar = where, precio = how much, hora = what time/when, manera o dirección = how. Where is the office? usa to be; Where do I turn? usa do; What time does the train leave? usa does.","communication_goal":"Usar preguntas interrogativas para orientarse, confirmar horarios y resolver necesidades cotidianas.","language_focus":{"grammar":["Where is...?","Where do I...?","When does...?","What time does...?","How do I...?","How much...?"],"function":"practical information questions"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Where is the entrance?","word":"entrance","meaning_es":"entrada"},{"english":"Where is the exit?","word":"exit","meaning_es":"salida"},{"english":"How much is a ticket?","word":"ticket","meaning_es":"boleto/entrada"},{"english":"What time does it open?","word":"schedule","meaning_es":"horario"},{"english":"What floor is the office on?","word":"floor","meaning_es":"piso"},{"english":"Where do I turn?","word":"turn","meaning_es":"girar"}],"dialogue":[{"speaker":"Traveler","english":"Excuse me. Where is the ticket office?","spanish":"Disculpe. ¿Dónde está la taquilla?"},{"speaker":"Agent","english":"It is on the first floor. What do you need?","spanish":"Está en el primer piso. ¿Qué necesita?"},{"speaker":"Traveler","english":"I need a ticket to Boston. How much is it?","spanish":"Necesito un boleto a Boston. ¿Cuánto cuesta?"},{"speaker":"Agent","english":"It is twenty dollars. What time do you want to leave?","spanish":"Cuesta veinte dólares. ¿A qué hora quiere salir?"},{"speaker":"Traveler","english":"At nine. When does the train arrive?","spanish":"A las nueve. ¿Cuándo llega el tren?"}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Where is the ticket office?","focus":"enlace where is"},{"text":"How much is it?","focus":"how much y entonación"},{"text":"What time does the train leave?","focus":"what time does y leave"}],"tip_es":"En una situación real habla despacio al principio y deja una pausa después de Excuse me."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Traveler","english":"Excuse me. Where is the ticket office?","spanish":"Disculpe. ¿Dónde está la taquilla?"},{"speaker":"Agent","english":"It is on the first floor. What do you need?","spanish":"Está en el primer piso. ¿Qué necesita?"},{"speaker":"Traveler","english":"I need a ticket to Boston. How much is it?","spanish":"Necesito un boleto a Boston. ¿Cuánto cuesta?"},{"speaker":"Agent","english":"It is twenty dollars. What time do you want to leave?","spanish":"Cuesta veinte dólares. ¿A qué hora quiere salir?"},{"speaker":"Traveler","english":"At nine. When does the train arrive?","spanish":"A las nueve. ¿Cuándo llega el tren?"}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A train trip","text":"A traveler is at a station. She needs a ticket to Boston. First, she asks where the ticket office is. Then she asks how much the ticket costs and what time the train leaves. The train leaves at nine.","glossary":[{"term":"ticket office","meaning_es":"taquilla"},{"term":"first floor","meaning_es":"primer piso"},{"term":"train leaves","meaning_es":"el tren sale"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Estás en un lugar nuevo y necesitas preguntar por servicios, horarios y direcciones.","communication_goal":"Usar preguntas interrogativas para orientarse, confirmar horarios y resolver necesidades cotidianas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un empleado de una estación. Pregunta por boleto, precio, horario y dirección. Reacciona a cada respuesta.","scenario":"Buying a ticket and finding the correct platform.","ai_language":"English with Spanish support after a failed attempt","prompt":"La IA será un empleado de una estación. Pregunta por boleto, precio, horario y dirección. Reacciona a cada respuesta.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T07-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Imagina que llegas a un lugar nuevo. Graba cinco preguntas para resolver dónde, cuándo, cómo y cuánto.","success_criteria":["cada pregunta pide un dato diferente","usa where, when/what time, how y how much","incluye una fórmula cortés"],"prompt":"Imagina que llegas a un lugar nuevo. Graba cinco preguntas para resolver dónde, cuándo, cómo y cuánto.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T07-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["elegir la palabra interrogativa según la necesidad","usar estructuras con is, do y does","resolver una situación práctica con preguntas"],"retry":"Si eliges how many para precio o where para hora, identifica primero qué tipo de respuesta necesitas."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Cuando no entiendes, no tienes que abandonar la conversación. Puedes preguntar What does ___ mean? para significado, How do you spell ___? para deletrear y Could you repeat, please? para repetir. También puedes decir I don''t understand y pedir que hablen lentamente.","communication_goal":"Pedir repetición, aclaración o ejemplos usando preguntas sencillas y expresiones de apoyo.","language_focus":{"grammar":["What does ... mean?","How do you spell ...?","Could you repeat, please?","Where do I go?","What do you mean?"],"function":"clarifying and repairing communication"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"What does this word mean?","word":"mean","meaning_es":"significar"},{"english":"How do you spell it?","word":"spell","meaning_es":"deletrear"},{"english":"Could you repeat, please?","word":"repeat","meaning_es":"repetir"},{"english":"Could you speak slowly?","word":"slowly","meaning_es":"despacio"},{"english":"Can you give an example?","word":"example","meaning_es":"ejemplo"},{"english":"I don''t understand.","word":"understand","meaning_es":"entender"}],"dialogue":[{"speaker":"Teacher","english":"Please open your book to page ten.","spanish":"Por favor, abre tu libro en la página diez."},{"speaker":"Student","english":"Sorry, what does page mean?","spanish":"Disculpa, ¿qué significa page?"},{"speaker":"Teacher","english":"It means a page in a book. It is number ten.","spanish":"Significa una página de un libro. Es el número diez."},{"speaker":"Student","english":"Thank you. How do you spell page?","spanish":"Gracias. ¿Cómo se deletrea page?"},{"speaker":"Teacher","english":"P-A-G-E. Does that help?","spanish":"P-A-G-E. ¿Eso ayuda?"}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"What does this word mean?","focus":"does this y mean claramente"},{"text":"How do you spell it?","focus":"spell y entonación"},{"text":"Could you repeat, please?","focus":"could you como unidad"}],"tip_es":"La claridad es más importante que la velocidad; usa una pausa después de Sorry o Excuse me."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Teacher","english":"Please open your book to page ten.","spanish":"Por favor, abre tu libro en la página diez."},{"speaker":"Student","english":"Sorry, what does page mean?","spanish":"Disculpa, ¿qué significa page?"},{"speaker":"Teacher","english":"It means a page in a book. It is number ten.","spanish":"Significa una página de un libro. Es el número diez."},{"speaker":"Student","english":"Thank you. How do you spell page?","spanish":"Gracias. ¿Cómo se deletrea page?"},{"speaker":"Teacher","english":"P-A-G-E. Does that help?","spanish":"P-A-G-E. ¿Eso ayuda?"}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A useful question","text":"In class, Diego hears a new word: page. He doesn''t understand it, so he asks what it means. Then he asks how to spell it. The teacher gives an example and repeats the word slowly.","glossary":[{"term":"page","meaning_es":"página"},{"term":"useful question","meaning_es":"pregunta útil"},{"term":"slowly","meaning_es":"despacio"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"En una conversación o clase no entiendes una palabra, una dirección o una instrucción.","communication_goal":"Pedir repetición, aclaración o ejemplos usando preguntas sencillas y expresiones de apoyo.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un profesor que usa palabras nuevas. Practica pedir significado, deletreo, repetición y un ejemplo sin cambiar al español inmediatamente.","scenario":"Keeping an English conversation alive when you do not understand.","ai_language":"English first; respond naturally to clarification requests","prompt":"La IA será un profesor que usa palabras nuevas. Practica pedir significado, deletreo, repetición y un ejemplo sin cambiar al español inmediatamente.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T07-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un diálogo de seis turnos en el que no entiendes dos palabras y pides aclaración de forma cortés.","success_criteria":["usa dos estrategias distintas","mantiene I don''t understand o una petición similar","pronuncia las preguntas con claridad"],"prompt":"Graba un diálogo de seis turnos en el que no entiendes dos palabras y pides aclaración de forma cortés.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T07-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["pedir aclaración sin abandonar la conversación","usar does + verbo base","pronunciar dos expresiones de reparación"],"retry":"Si formulas What does it means?, elimina la s después de does y repite la pregunta en voz alta."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una conversación completa tiene tres habilidades: preguntar lo que quieres saber, hacer seguimiento a una respuesta y pedir aclaración cuando aparece algo nuevo. Combina what, where, when, why, who y how con do/does o to be. La meta no es hacer preguntas perfectas aisladas, sino sostener el intercambio.","communication_goal":"Realizar una conversación completa con preguntas de información, seguimiento y aclaración.","language_focus":{"grammar":["what, where, when, why, who, how","do/does and to be questions","clarification questions","short answers"],"function":"integrated question strategies"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"We have a short conversation.","word":"conversation","meaning_es":"conversación"},{"english":"I complete a questionnaire.","word":"questionnaire","meaning_es":"cuestionario"},{"english":"Ask a follow-up question.","word":"follow-up","meaning_es":"seguimiento"},{"english":"Can you clarify that?","word":"clarify","meaning_es":"aclarar"},{"english":"That is interesting.","word":"interesting","meaning_es":"interesante"},{"english":"Tell me more about your hobby.","word":"tell me more","meaning_es":"cuéntame más"}],"dialogue":[{"speaker":"Interviewer","english":"What is your name and where are you from?","spanish":"¿Cómo te llamas y de dónde eres?"},{"speaker":"Student","english":"I''m Valeria. I''m from Colombia.","spanish":"Soy Valeria. Soy de Colombia."},{"speaker":"Interviewer","english":"What do you usually do after work?","spanish":"¿Qué haces normalmente después del trabajo?"},{"speaker":"Student","english":"I read and go for a walk. What does hobby mean?","spanish":"Leo y salgo a caminar. ¿Qué significa hobby?"},{"speaker":"Interviewer","english":"It means an activity you enjoy. What is your favorite hobby?","spanish":"Significa una actividad que disfrutas. ¿Cuál es tu pasatiempo favorito?"},{"speaker":"Student","english":"Reading. I read twice a week.","spanish":"Leer. Leo dos veces por semana."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"What do you usually do after work?","focus":"ritmo de la pregunta"},{"text":"What does hobby mean?","focus":"does hobby mean"},{"text":"Tell me more about your hobby.","focus":"entonación invitante"}],"tip_es":"Usa cambios de entonación: preguntas abiertas, confirmación y petición de aclaración no suenan igual."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Interviewer","english":"What is your name and where are you from?","spanish":"¿Cómo te llamas y de dónde eres?"},{"speaker":"Student","english":"I''m Valeria. I''m from Colombia.","spanish":"Soy Valeria. Soy de Colombia."},{"speaker":"Interviewer","english":"What do you usually do after work?","spanish":"¿Qué haces normalmente después del trabajo?"},{"speaker":"Student","english":"I read and go for a walk. What does hobby mean?","spanish":"Leo y salgo a caminar. ¿Qué significa hobby?"},{"speaker":"Interviewer","english":"It means an activity you enjoy. What is your favorite hobby?","spanish":"Significa una actividad que disfrutas. ¿Cuál es tu pasatiempo favorito?"},{"speaker":"Student","english":"Reading. I read twice a week.","spanish":"Leer. Leo dos veces por semana."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A meaningful interview","text":"Valeria has a short interview in English class. She answers questions about her country, work and hobbies. When she hears a new word, she asks what it means. Then she answers a follow-up question about reading.","glossary":[{"term":"meaningful interview","meaning_es":"entrevista significativa"},{"term":"country","meaning_es":"país"},{"term":"follow-up question","meaning_es":"pregunta de seguimiento"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Entrevistas a una persona nueva y resuelves cualquier malentendido durante la conversación.","communication_goal":"Realizar una conversación completa con preguntas de información, seguimiento y aclaración.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Realiza con la IA una entrevista completa de ocho turnos. Haz preguntas de información, una pregunta de seguimiento y una aclaración.","scenario":"Meeting an international classmate for the first time.","ai_language":"English; support Spanish only after a genuine communication attempt","prompt":"Realiza con la IA una entrevista completa de ocho turnos. Haz preguntas de información, una pregunta de seguimiento y una aclaración.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T07-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una entrevista de 60 segundos sobre ti: saludo, seis preguntas, dos seguimientos y una aclaración.","success_criteria":["usa cinco palabras interrogativas","combina estructuras con to be y do/does","incluye una pregunta de reparación","mantiene el intercambio conectado"],"prompt":"Graba una entrevista de 60 segundos sobre ti: saludo, seis preguntas, dos seguimientos y una aclaración.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T07-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["formular preguntas de información correctas","hacer seguimiento relacionado","pedir aclaración y continuar la conversación"],"retry":"Si el resultado es menor de 80%, practica primero una entrevista escrita y luego repítela oralmente con preguntas más cortas."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Los pronombres de objeto reciben la acción o aparecen después de una preposición: I call her, Help me, I talk to him. La tabla es: I → me, you → you, he → him, she → her, it → it, we → us, they → them. No uses el pronombre de sujeto después del verbo: Call me, no Call I.","communication_goal":"Usar pronombres de objeto para indicar quién recibe una acción.","language_focus":{"grammar":["me","you","him","her","it","us","them"],"function":"object pronouns after verbs and prepositions"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Call me tonight.","word":"call","meaning_es":"llamar"},{"english":"Can you help me?","word":"help","meaning_es":"ayudar"},{"english":"I see her at work.","word":"see","meaning_es":"ver"},{"english":"Do you know him?","word":"know","meaning_es":"conocer/saber"},{"english":"We invite them.","word":"invite","meaning_es":"invitar"},{"english":"I meet you at six.","word":"meet","meaning_es":"encontrarse con"}],"dialogue":[{"speaker":"Maya","english":"Can you call me tonight?","spanish":"¿Puedes llamarme esta noche?"},{"speaker":"Leo","english":"Yes, I can call you after work.","spanish":"Sí, puedo llamarte después del trabajo."},{"speaker":"Maya","english":"Do you know Ana and Carlos?","spanish":"¿Conoces a Ana y Carlos?"},{"speaker":"Leo","english":"Yes, I know them. I see her at work and I meet him on Fridays.","spanish":"Sí, los conozco. La veo en el trabajo y me encuentro con él los viernes."},{"speaker":"Maya","english":"Please invite us next time.","spanish":"Por favor, invítanos la próxima vez."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Can you help me?","focus":"help me unido sin perder me"},{"text":"I know them.","focus":"them y sonido /ð/"},{"text":"Please call her.","focus":"her sin eliminar la h"}],"tip_es":"Practica cada pronombre dentro de una frase; aislado es más difícil saber cuándo usarlo."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Maya","english":"Can you call me tonight?","spanish":"¿Puedes llamarme esta noche?"},{"speaker":"Leo","english":"Yes, I can call you after work.","spanish":"Sí, puedo llamarte después del trabajo."},{"speaker":"Maya","english":"Do you know Ana and Carlos?","spanish":"¿Conoces a Ana y Carlos?"},{"speaker":"Leo","english":"Yes, I know them. I see her at work and I meet him on Fridays.","spanish":"Sí, los conozco. La veo en el trabajo y me encuentro con él los viernes."},{"speaker":"Maya","english":"Please invite us next time.","spanish":"Por favor, invítanos la próxima vez."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The weekend invitation","text":"Maya calls Leo and invites him to a small dinner. Leo knows her friend Ana and sees her at work. He also knows Carlos and meets him on Fridays. Maya asks Leo to invite them next time.","glossary":[{"term":"invitation","meaning_es":"invitación"},{"term":"small dinner","meaning_es":"cena pequeña"},{"term":"next time","meaning_es":"la próxima vez"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Hablas de personas que conoces, ayudas o llamas durante el día.","communication_goal":"Usar pronombres de objeto para indicar quién recibe una acción.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será tu amigo organizando una reunión. Habla de a quién llamas, invitas, ves y ayudas.","scenario":"Planning a small gathering with friends.","ai_language":"English with Spanish support after a repeated pronoun error","prompt":"La IA será tu amigo organizando una reunión. Habla de a quién llamas, invitas, ves y ayudas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T08-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Escribe seis frases sobre personas reales usando me, you, him, her, us y them al menos una vez.","success_criteria":["cada pronombre recibe una acción","no usa pronombres de sujeto después del verbo","las frases tienen sentido personal"],"prompt":"Escribe seis frases sobre personas reales usando me, you, him, her, us y them al menos una vez.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T08-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["distinguir sujeto y objeto","usar cinco pronombres de objeto","colocarlos después de verbos o preposiciones"],"retry":"Si usas I, he o she después del verbo, pregunta quién recibe la acción y cambia al pronombre de objeto."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Usa him y her para personas, it para una cosa o animal singular y them/us para grupos. Después de to también usamos objeto: send it to me, give it to her. En frases con dos pronombres, identifica qué recibes y quién lo recibe: send it to you = envía la cosa a ti.","communication_goal":"Elegir pronombres de objeto para hablar de personas, animales, objetos y grupos.","language_focus":{"grammar":["him/her for people","it for a thing or animal","us/them for groups","to + object pronoun"],"function":"referencing people and things"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Text me later.","word":"text","meaning_es":"enviar mensaje"},{"english":"Can you show it to me?","word":"show","meaning_es":"mostrar"},{"english":"Give it to her.","word":"give","meaning_es":"dar"},{"english":"Send them a message.","word":"send","meaning_es":"enviar"},{"english":"I use it every day.","word":"website","meaning_es":"sitio web"},{"english":"I walk him every morning.","word":"dog","meaning_es":"perro"}],"dialogue":[{"speaker":"Sara","english":"Can you send me the website?","spanish":"¿Puedes enviarme el sitio web?"},{"speaker":"Tom","english":"Sure. I can send it to you now.","spanish":"Claro. Puedo enviártelo ahora."},{"speaker":"Sara","english":"Please show it to Ana too.","spanish":"Por favor, muéstraselo a Ana también."},{"speaker":"Tom","english":"I can show it to her after lunch.","spanish":"Puedo mostrárselo después del almuerzo."},{"speaker":"Sara","english":"Thanks. Send us a message when you finish.","spanish":"Gracias. Envíanos un mensaje cuando termines."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Send it to me.","focus":"enlace send it to"},{"text":"Show it to her.","focus":"her con h audible"},{"text":"Send us a message.","focus":"us y ritmo"}],"tip_es":"Repite la secuencia verbo + cosa + to + persona como un bloque."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Sara","english":"Can you send me the website?","spanish":"¿Puedes enviarme el sitio web?"},{"speaker":"Tom","english":"Sure. I can send it to you now.","spanish":"Claro. Puedo enviártelo ahora."},{"speaker":"Sara","english":"Please show it to Ana too.","spanish":"Por favor, muéstraselo a Ana también."},{"speaker":"Tom","english":"I can show it to her after lunch.","spanish":"Puedo mostrárselo después del almuerzo."},{"speaker":"Sara","english":"Thanks. Send us a message when you finish.","spanish":"Gracias. Envíanos un mensaje cuando termines."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The useful website","text":"Tom sends Sara a useful website. He sends it to her by message. Sara asks him to show it to Ana too. Tom sends them the website and asks them to share it with us.","glossary":[{"term":"useful website","meaning_es":"sitio web útil"},{"term":"by message","meaning_es":"por mensaje"},{"term":"share","meaning_es":"compartir"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Describes mensajes, objetos y relaciones en situaciones cotidianas.","communication_goal":"Elegir pronombres de objeto para hablar de personas, animales, objetos y grupos.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA te pide compartir objetos o enlaces con otras personas. Responde usando it, me, him, her, us o them.","scenario":"Helping classmates share a useful online resource.","ai_language":"English with visual referents and brief corrections","prompt":"La IA te pide compartir objetos o enlaces con otras personas. Responde usando it, me, him, her, us o them.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T08-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Describe cómo compartes un enlace, objeto o información con dos personas. Usa al menos cuatro pronombres de objeto.","success_criteria":["it se refiere claramente a una cosa","him/her se refiere a personas","usa to cuando corresponde"],"prompt":"Describe cómo compartes un enlace, objeto o información con dos personas. Usa al menos cuatro pronombres de objeto.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T08-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["usar it para cosas y animales","distinguir him/her/them","formar frases con to + pronombre"],"retry":"Si dudas, señala mentalmente la cosa y la persona: cosa = it; receptor = me, him, her, us o them."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Después de una preposición usamos pronombres de objeto: with me, for him, to her, about them. No uses pronombres de sujeto después de estas palabras: Come with us, no Come with we. Algunas combinaciones comunes deben aprenderse como bloques: listen to me, wait for us, talk to him.","communication_goal":"Usar pronombres de objeto después de to, for, with y about en intercambios cotidianos.","language_focus":{"grammar":["with me/you/him/her/us/them","for me/you/him/her/us/them","to me/you/him/her/us/them","about me/you/him/her/us/them"],"function":"object pronouns after prepositions"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I talk to her every day.","word":"talk to","meaning_es":"hablar con"},{"english":"Please wait for me.","word":"wait for","meaning_es":"esperar a"},{"english":"Come with us.","word":"come with","meaning_es":"venir con"},{"english":"I think about them.","word":"think about","meaning_es":"pensar en"},{"english":"I buy it for him.","word":"buy for","meaning_es":"comprar para"},{"english":"Listen to me.","word":"listen to","meaning_es":"escuchar a"}],"dialogue":[{"speaker":"Jade","english":"Are you waiting for me?","spanish":"¿Me estás esperando?"},{"speaker":"Omar","english":"Yes, I am. I want to talk to you about the trip.","spanish":"Sí. Quiero hablar contigo sobre el viaje."},{"speaker":"Jade","english":"Can I come with you?","spanish":"¿Puedo ir contigo?"},{"speaker":"Omar","english":"Of course. Come with us. We are waiting for Ana too.","spanish":"Claro. Ven con nosotros. También estamos esperando a Ana."},{"speaker":"Jade","english":"I will buy a ticket for her.","spanish":"Compraré un boleto para ella."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Wait for me.","focus":"for reducido y me claro"},{"text":"Come with us.","focus":"with y us"},{"text":"Talk to him about it.","focus":"bloques to him y about it"}],"tip_es":"Repite la preposición y el pronombre juntos como una unidad de ritmo."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Jade","english":"Are you waiting for me?","spanish":"¿Me estás esperando?"},{"speaker":"Omar","english":"Yes, I am. I want to talk to you about the trip.","spanish":"Sí. Quiero hablar contigo sobre el viaje."},{"speaker":"Jade","english":"Can I come with you?","spanish":"¿Puedo ir contigo?"},{"speaker":"Omar","english":"Of course. Come with us. We are waiting for Ana too.","spanish":"Claro. Ven con nosotros. También estamos esperando a Ana."},{"speaker":"Jade","english":"I will buy a ticket for her.","spanish":"Compraré un boleto para ella."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The group plan","text":"Omar is waiting for Jade. He wants to talk to her about a trip. Jade comes with him and the group. Omar buys a ticket for her and asks her to listen to him about the plan.","glossary":[{"term":"group plan","meaning_es":"plan del grupo"},{"term":"trip","meaning_es":"viaje"},{"term":"plan","meaning_es":"plan"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Hablas de personas con las que haces cosas, para quienes compras algo o sobre quienes conversas.","communication_goal":"Usar pronombres de objeto después de to, for, with y about en intercambios cotidianos.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA organiza un plan contigo. Usa with, for, to y about para hablar de personas que participan o reciben algo.","scenario":"Planning a trip with friends.","ai_language":"English; recast incorrect object pronouns naturally","prompt":"La IA organiza un plan contigo. Usa with, for, to y about para hablar de personas que participan o reciben algo.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T08-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba cinco frases sobre un plan con amigos: con quién vas, a quién esperas, para quién compras algo y de quién hablas.","success_criteria":["usa with, for, to y about","usa pronombres de objeto","las frases forman una situación coherente"],"prompt":"Graba cinco frases sobre un plan con amigos: con quién vas, a quién esperas, para quién compras algo y de quién hablas.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T08-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["usar pronombres después de preposiciones","recordar combinaciones wait for, talk to y listen to","hablar de personas y relaciones con claridad"],"retry":"Si usas we o they después de una preposición, cambia a us o them y repite la frase completa."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"En una conversación, el pronombre evita repetir nombres: I explain the activity to them → I explain it to them. Pregunta siempre qué recibe la acción (it/them) y quién la recibe (me/you/him/her/us/them). Después de una preposición sigue usando objeto: with them, to us, about me.","communication_goal":"Usar pronombres de objeto con naturalidad para hablar de personas, cosas y relaciones en una conversación.","language_focus":{"grammar":["me, you, him, her, it, us, them","pronouns after verbs","pronouns after prepositions","send/show/give + object"],"function":"integrated object pronoun use"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Remind me tomorrow.","word":"remind","meaning_es":"recordar a alguien"},{"english":"I introduce her to my friend.","word":"introduce","meaning_es":"presentar"},{"english":"Bring it to us.","word":"bring","meaning_es":"traer"},{"english":"Explain it to me.","word":"explain","meaning_es":"explicar"},{"english":"Share it with them.","word":"share","meaning_es":"compartir"},{"english":"Tell everyone about us.","word":"everyone","meaning_es":"todos/todas las personas"}],"dialogue":[{"speaker":"Nora","english":"Can you remind me about the meeting?","spanish":"¿Puedes recordarme la reunión?"},{"speaker":"Luis","english":"Sure. I can remind you tomorrow.","spanish":"Claro. Puedo recordártelo mañana."},{"speaker":"Nora","english":"Please explain the activity to them.","spanish":"Por favor, explícales la actividad."},{"speaker":"Luis","english":"I can explain it to them and share it with everyone.","spanish":"Puedo explicársela y compartirla con todos."},{"speaker":"Nora","english":"Great. Bring the notes to us, please.","spanish":"Perfecto. Tráenos las notas, por favor."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Explain it to them.","focus":"it to them como bloque"},{"text":"Share it with everyone.","focus":"with y everyone"},{"text":"Bring the notes to us, please.","focus":"to us y cortesía"}],"tip_es":"Lee primero con pausas entre grupos y después vuelve a grabar con ritmo conversacional."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Nora","english":"Can you remind me about the meeting?","spanish":"¿Puedes recordarme la reunión?"},{"speaker":"Luis","english":"Sure. I can remind you tomorrow.","spanish":"Claro. Puedo recordártelo mañana."},{"speaker":"Nora","english":"Please explain the activity to them.","spanish":"Por favor, explícales la actividad."},{"speaker":"Luis","english":"I can explain it to them and share it with everyone.","spanish":"Puedo explicársela y compartirla con todos."},{"speaker":"Nora","english":"Great. Bring the notes to us, please.","spanish":"Perfecto. Tráenos las notas, por favor."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The study meeting","text":"Nora organizes a study meeting for her classmates. She sends them the time and asks Luis to explain the activity to everyone. He explains it to them and shares the notes with us. Nora reminds him to bring them to the meeting.","glossary":[{"term":"classmates","meaning_es":"compañeros de clase"},{"term":"notes","meaning_es":"apuntes"},{"term":"remind","meaning_es":"recordar a alguien"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Organizas una reunión, compartes información y explicas quién recibe o hace cada acción.","communication_goal":"Usar pronombres de objeto con naturalidad para hablar de personas, cosas y relaciones en una conversación.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Organiza con la IA una reunión de estudio. Comparte información, explica una actividad y pide que la envíen a otras personas.","scenario":"Coordinating a study group through messages.","ai_language":"English; use context to resolve each pronoun","prompt":"Organiza con la IA una reunión de estudio. Comparte información, explica una actividad y pide que la envíen a otras personas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T08-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un mensaje de 45 segundos organizando una reunión. Presenta tres referentes y luego reemplázalos con it, him/her y them/us.","success_criteria":["cada pronombre tiene un referente claro","usa al menos una preposición","la conversación se entiende sin repetir nombres constantemente"],"prompt":"Graba un mensaje de 45 segundos organizando una reunión. Presenta tres referentes y luego reemplázalos con it, him/her y them/us.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T08-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["elegir pronombres según el referente","usarlos después de verbos y preposiciones","mantener una conversación sin repetir nombres innecesariamente"],"retry":"Si el resultado es menor de 80%, subraya primero la cosa y la persona receptora en cada frase y vuelve a sustituirlas."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Los sustantivos contables pueden tener un número: one apple, two apples. Tienen singular y plural y pueden usar a/an en singular. Los no contables se consideran una cantidad o sustancia: rice, water, bread, milk. No decimos a rice o two waters cuando hablamos de la sustancia; usamos some rice o a bottle of water.","communication_goal":"Distinguir sustantivos contables y no contables en situaciones cotidianas.","language_focus":{"grammar":["a/an + singular countable","plural countable nouns","uncountable nouns without a/an"],"function":"classifying nouns"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I need an apple.","word":"apple","meaning_es":"manzana"},{"english":"We need three eggs.","word":"egg","meaning_es":"huevo"},{"english":"We need some rice.","word":"rice","meaning_es":"arroz"},{"english":"There is some water.","word":"water","meaning_es":"agua"},{"english":"I buy bread.","word":"bread","meaning_es":"pan"},{"english":"I need two bottles.","word":"bottle","meaning_es":"botella"}],"dialogue":[{"speaker":"Mia","english":"What do we need for dinner?","spanish":"¿Qué necesitamos para la cena?"},{"speaker":"Leo","english":"We need three apples, two eggs and some rice.","spanish":"Necesitamos tres manzanas, dos huevos y arroz."},{"speaker":"Mia","english":"Do we have water?","spanish":"¿Tenemos agua?"},{"speaker":"Leo","english":"Yes, we have some water, but we need a bottle of milk.","spanish":"Sí, tenemos agua, pero necesitamos una botella de leche."},{"speaker":"Mia","english":"Great. I can buy the bread.","spanish":"Perfecto. Puedo comprar el pan."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"three apples","focus":"plural /z/ o /s/ en apples"},{"text":"some rice","focus":"rice sin plural"},{"text":"a bottle of water","focus":"enlace bottle of water"}],"tip_es":"Escucha si el número cambia el sustantivo o si necesitas una unidad como bottle."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Mia","english":"What do we need for dinner?","spanish":"¿Qué necesitamos para la cena?"},{"speaker":"Leo","english":"We need three apples, two eggs and some rice.","spanish":"Necesitamos tres manzanas, dos huevos y arroz."},{"speaker":"Mia","english":"Do we have water?","spanish":"¿Tenemos agua?"},{"speaker":"Leo","english":"Yes, we have some water, but we need a bottle of milk.","spanish":"Sí, tenemos agua, pero necesitamos una botella de leche."},{"speaker":"Mia","english":"Great. I can buy the bread.","spanish":"Perfecto. Puedo comprar el pan."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A simple shopping list","text":"Mia and Leo prepare dinner. They need three apples, two eggs, some rice and a bottle of water. They already have bread at home. They do not need more bread today.","glossary":[{"term":"shopping list","meaning_es":"lista de compras"},{"term":"prepare dinner","meaning_es":"preparar la cena"},{"term":"already","meaning_es":"ya"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Preparas una lista de compras y decides qué puedes contar directamente.","communication_goal":"Distinguir sustantivos contables y no contables en situaciones cotidianas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero preparando una lista de compras. Decide qué objetos se cuentan y qué productos necesitan una unidad.","scenario":"Planning dinner and shopping for ingredients.","ai_language":"English with short Spanish explanation of countable choices","prompt":"La IA será un compañero preparando una lista de compras. Decide qué objetos se cuentan y qué productos necesitan una unidad.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T09-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Crea una lista de diez productos: cinco contables y cinco no contables. Escribe una frase de compra para cada uno.","success_criteria":["clasifica correctamente","usa a/an o números con contables","usa some o una unidad con no contables"],"prompt":"Crea una lista de diez productos: cinco contables y cinco no contables. Escribe una frase de compra para cada uno.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T09-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["distinguir contables y no contables","formar plurales contables","usar unidades con sustancias"],"retry":"Si dudas, pregunta: ¿puedo poner un número directamente? Si no, añade some o una unidad como bottle."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para expresar una cantidad concreta de un sustantivo no contable usa una unidad: a cup of rice, two glasses of water, a slice of bread. La unidad sí puede ir en plural, pero el sustantivo después de of permanece sin plural: two cups of rice, no two cups of rices. Some expresa una cantidad no específica.","communication_goal":"Hablar de cantidades básicas de ingredientes usando unidades y expresiones cotidianas.","language_focus":{"grammar":["a piece of","a cup of","a glass of","a bottle of","a slice of","some + uncountable"],"function":"measuring uncountable nouns"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"a piece of cake","word":"piece","meaning_es":"pedazo/pieza"},{"english":"a cup of rice","word":"cup","meaning_es":"taza"},{"english":"a glass of water","word":"glass","meaning_es":"vaso"},{"english":"two slices of bread","word":"slice","meaning_es":"rebanada"},{"english":"some flour","word":"flour","meaning_es":"harina"},{"english":"a cup of sugar","word":"sugar","meaning_es":"azúcar"}],"dialogue":[{"speaker":"Chef","english":"How much rice do we need?","spanish":"¿Cuánto arroz necesitamos?"},{"speaker":"Student","english":"We need two cups of rice.","spanish":"Necesitamos dos tazas de arroz."},{"speaker":"Chef","english":"And how much water?","spanish":"¿Y cuánta agua?"},{"speaker":"Student","english":"Three glasses of water. We also need two slices of bread.","spanish":"Tres vasos de agua. También necesitamos dos rebanadas de pan."},{"speaker":"Chef","english":"Good. Add some salt, please.","spanish":"Bien. Añade un poco de sal, por favor."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"two cups of rice","focus":"cups of como bloque"},{"text":"three glasses of water","focus":"plural glasses"},{"text":"two slices of bread","focus":"slices of y bread"}],"tip_es":"Acentúa la unidad y mantén el ingrediente claro al final."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Chef","english":"How much rice do we need?","spanish":"¿Cuánto arroz necesitamos?"},{"speaker":"Student","english":"We need two cups of rice.","spanish":"Necesitamos dos tazas de arroz."},{"speaker":"Chef","english":"And how much water?","spanish":"¿Y cuánta agua?"},{"speaker":"Student","english":"Three glasses of water. We also need two slices of bread.","spanish":"Tres vasos de agua. También necesitamos dos rebanadas de pan."},{"speaker":"Chef","english":"Good. Add some salt, please.","spanish":"Bien. Añade un poco de sal, por favor."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A breakfast recipe","text":"For breakfast, we need two slices of bread, a glass of water and a cup of fruit. We also need some sugar. We do not need flour or rice for this recipe.","glossary":[{"term":"breakfast recipe","meaning_es":"receta de desayuno"},{"term":"fruit","meaning_es":"fruta"},{"term":"salt","meaning_es":"sal"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Sigues una receta sencilla y preguntas qué ingredientes hay y en qué cantidad.","communication_goal":"Hablar de cantidades básicas de ingredientes usando unidades y expresiones cotidianas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un chef. Pregunta How much o How many y responde con cantidades para una receta sencilla.","scenario":"Cooking breakfast together.","ai_language":"English; correct the unit, not every minor error","prompt":"La IA será un chef. Pregunta How much o How many y responde con cantidades para una receta sencilla.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T09-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Escribe una receta de cinco pasos con al menos seis cantidades: dos contables y cuatro unidades de no contables.","success_criteria":["usa how much/how many correctamente","usa unidades adecuadas","mantiene sustancias sin plural"],"prompt":"Escribe una receta de cinco pasos con al menos seis cantidades: dos contables y cuatro unidades de no contables.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T09-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["usar unidades para no contables","distinguir how much y how many","expresar cantidades en una receta"],"retry":"Si agregas plural al ingrediente, revisa que el plural debe estar en la unidad: cups, glasses o slices."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"En una tienda, How many pregunta por productos contables: How many apples? How much pregunta por una sustancia o cantidad: How much rice? Puedes convertir un no contable en una cantidad con packet, bottle, can, box o kilo. Una forma natural de cerrar la compra es Anything else? y That''s enough.","communication_goal":"Pedir productos y cantidades en una tienda usando preguntas contables y no contables.","language_focus":{"grammar":["How many...?","How much...?","a/an + countable singular","some + uncountable/plural","a bottle/packet/box of"],"function":"shopping for quantities"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"a packet of rice","word":"packet","meaning_es":"paquete"},{"english":"a box of cereal","word":"box","meaning_es":"caja"},{"english":"two cans of beans","word":"can","meaning_es":"lata"},{"english":"a kilo of apples","word":"kilo","meaning_es":"kilo"},{"english":"Is that enough?","word":"enough","meaning_es":"suficiente"},{"english":"Do you need anything else?","word":"anything else","meaning_es":"algo más"}],"dialogue":[{"speaker":"Customer","english":"How much rice do you need?","spanish":"¿Cuánto arroz necesitas?"},{"speaker":"Shopkeeper","english":"I need a packet of rice and a bottle of oil.","spanish":"Necesito un paquete de arroz y una botella de aceite."},{"speaker":"Customer","english":"How many apples do you want?","spanish":"¿Cuántas manzanas quieres?"},{"speaker":"Shopkeeper","english":"A kilo of apples, please. And two cans of beans.","spanish":"Un kilo de manzanas, por favor. Y dos latas de frijoles."},{"speaker":"Customer","english":"Anything else?","spanish":"¿Algo más?"},{"speaker":"Shopkeeper","english":"No, that''s enough. Thank you.","spanish":"No, es suficiente. Gracias."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"How much rice do you need?","focus":"how much y rice"},{"text":"A packet of rice, please.","focus":"packet of como bloque"},{"text":"Anything else? That''s enough.","focus":"entonación de cierre"}],"tip_es":"En una tienda, habla con frases cortas y agrega please para sonar amable."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Customer","english":"How much rice do you need?","spanish":"¿Cuánto arroz necesitas?"},{"speaker":"Shopkeeper","english":"I need a packet of rice and a bottle of oil.","spanish":"Necesito un paquete de arroz y una botella de aceite."},{"speaker":"Customer","english":"How many apples do you want?","spanish":"¿Cuántas manzanas quieres?"},{"speaker":"Shopkeeper","english":"A kilo of apples, please. And two cans of beans.","spanish":"Un kilo de manzanas, por favor. Y dos latas de frijoles."},{"speaker":"Customer","english":"Anything else?","spanish":"¿Algo más?"},{"speaker":"Shopkeeper","english":"No, that''s enough. Thank you.","spanish":"No, es suficiente. Gracias."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The grocery order","text":"The shopkeeper needs a packet of rice, a bottle of oil, a kilo of apples and two cans of beans. The customer asks if he needs anything else. He says no, that is enough.","glossary":[{"term":"grocery store","meaning_es":"tienda de alimentos"},{"term":"oil","meaning_es":"aceite"},{"term":"beans","meaning_es":"frijoles"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Compras alimentos y aclaras cuánto necesitas y qué presentación prefieres.","communication_goal":"Pedir productos y cantidades en una tienda usando preguntas contables y no contables.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un vendedor. Compra cinco productos, pide cantidades y responde Anything else? con naturalidad.","scenario":"Shopping for a dinner at a grocery store.","ai_language":"English; use realistic quantities and gentle corrections","prompt":"La IA será un vendedor. Compra cinco productos, pide cantidades y responde Anything else? con naturalidad.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T09-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Haz una lista de compras para una comida. Graba el diálogo entre cliente y vendedor usando How much, How many, una unidad y Anything else?.","success_criteria":["distingue contables y no contables","usa dos unidades adecuadas","incluye una petición cortés"],"prompt":"Haz una lista de compras para una comida. Graba el diálogo entre cliente y vendedor usando How much, How many, una unidad y Anything else?.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T09-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["preguntar por cantidades","elegir How much o How many","usar presentaciones de productos"],"retry":"Si confundes las preguntas, mira el sustantivo: plural contable = how many; sustancia o unidad = how much."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para planificar, combina preguntas de cantidad con some/any y there is/are. Usa any normalmente en preguntas: Are there any eggs? Usa some en afirmaciones: There are some vegetables. Para una cantidad exacta añade una unidad: one cup of rice, two cups more.","communication_goal":"Usar cantidades, unidades y preguntas para planificar una comida con otra persona.","language_focus":{"grammar":["countable and uncountable nouns","How much/How many","some/any","units of measurement","there is/are review"],"function":"meal planning and shopping"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"What ingredients do we need?","word":"ingredient","meaning_es":"ingrediente"},{"english":"Let''s plan the menu.","word":"menu","meaning_es":"menú"},{"english":"We have enough rice.","word":"enough","meaning_es":"suficiente"},{"english":"We need more water.","word":"need more","meaning_es":"necesitar más"},{"english":"Are there any eggs available?","word":"available","meaning_es":"disponible"},{"english":"Let''s check the list.","word":"check","meaning_es":"revisar"}],"dialogue":[{"speaker":"Ana","english":"Let''s plan dinner for four people. How many eggs do we have?","spanish":"Planeemos la cena para cuatro personas. ¿Cuántos huevos tenemos?"},{"speaker":"Luis","english":"We have four eggs, but we need two more.","spanish":"Tenemos cuatro huevos, pero necesitamos dos más."},{"speaker":"Ana","english":"How much rice is available?","spanish":"¿Cuánto arroz hay disponible?"},{"speaker":"Luis","english":"There is one cup of rice. We need two cups more.","spanish":"Hay una taza de arroz. Necesitamos dos tazas más."},{"speaker":"Ana","english":"Are there any vegetables?","spanish":"¿Hay verduras?"},{"speaker":"Luis","english":"Yes, there are some vegetables in the fridge.","spanish":"Sí, hay algunas verduras en el refrigerador."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"How many eggs do we have?","focus":"how many eggs y do we"},{"text":"How much rice is available?","focus":"how much rice"},{"text":"There are some vegetables in the fridge.","focus":"there are y vegetables"}],"tip_es":"En una conversación de planificación, confirma las cantidades repitiéndolas: Two cups of rice? Yes, two cups."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Ana","english":"Let''s plan dinner for four people. How many eggs do we have?","spanish":"Planeemos la cena para cuatro personas. ¿Cuántos huevos tenemos?"},{"speaker":"Luis","english":"We have four eggs, but we need two more.","spanish":"Tenemos cuatro huevos, pero necesitamos dos más."},{"speaker":"Ana","english":"How much rice is available?","spanish":"¿Cuánto arroz hay disponible?"},{"speaker":"Luis","english":"There is one cup of rice. We need two cups more.","spanish":"Hay una taza de arroz. Necesitamos dos tazas más."},{"speaker":"Ana","english":"Are there any vegetables?","spanish":"¿Hay verduras?"},{"speaker":"Luis","english":"Yes, there are some vegetables in the fridge.","spanish":"Sí, hay algunas verduras en el refrigerador."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The dinner checklist","text":"Ana and Luis plan dinner for four people. They have four eggs, some vegetables and one cup of rice. They need two more eggs and two more cups of rice. They check the menu before going to the store.","glossary":[{"term":"dinner checklist","meaning_es":"lista de comprobación de la cena"},{"term":"fridge","meaning_es":"refrigerador/nevera"},{"term":"store","meaning_es":"tienda"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Decides un menú, revisas qué tienes y compras lo que falta.","communication_goal":"Usar cantidades, unidades y preguntas para planificar una comida con otra persona.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Planifica una cena con la IA. Revisa ingredientes disponibles, pregunta por cantidades y decide qué comprar.","scenario":"Planning dinner for four people with a limited budget.","ai_language":"English; ask for clarification when quantities are unclear","prompt":"Planifica una cena con la IA. Revisa ingredientes disponibles, pregunta por cantidades y decide qué comprar.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T09-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Crea y graba un diálogo de planificación de comida de ocho turnos. Incluye contables, no contables, some/any, there is/are y dos unidades.","success_criteria":["pregunta how much y how many","usa some/any en contextos adecuados","mantiene cantidades coherentes","el diálogo resuelve qué comprar"],"prompt":"Crea y graba un diálogo de planificación de comida de ocho turnos. Incluye contables, no contables, some/any, there is/are y dos unidades.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T09-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["distinguir contables y no contables","usar cantidades y unidades","resolver una planificación con preguntas y respuestas"],"retry":"Si el resultado es menor de 80%, vuelve a clasificar los ingredientes y reconstruye la lista con unidades antes de repetir el diálogo."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Usa some en afirmaciones con plurales contables o no contables: some tomatoes, some cheese. Usa any normalmente en preguntas: Is there any juice? y en negaciones: There aren''t any onions. No significa ''cualquier'' en estos ejemplos; indica una cantidad no específica.","communication_goal":"Usar some y any para hablar de cantidades no específicas en afirmaciones, preguntas y negaciones.","language_focus":{"grammar":["some + plural countable/uncountable","any in questions","any in negatives","not any"],"function":"non-specific quantities"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"There is some cheese.","word":"cheese","meaning_es":"queso"},{"english":"There are some tomatoes.","word":"tomatoes","meaning_es":"tomates"},{"english":"Is there any juice?","word":"juice","meaning_es":"jugo/zumo"},{"english":"There aren''t any onions.","word":"onions","meaning_es":"cebollas"},{"english":"Is there any food left?","word":"left","meaning_es":"que queda"},{"english":"Check the fridge.","word":"fridge","meaning_es":"refrigerador"}],"dialogue":[{"speaker":"Nina","english":"Is there any cheese in the fridge?","spanish":"¿Hay queso en el refrigerador?"},{"speaker":"Omar","english":"Yes, there is some cheese and some juice.","spanish":"Sí, hay queso y jugo."},{"speaker":"Nina","english":"Are there any tomatoes?","spanish":"¿Hay tomates?"},{"speaker":"Omar","english":"There are some tomatoes, but there aren''t any onions.","spanish":"Hay tomates, pero no hay cebollas."},{"speaker":"Nina","english":"Okay. Let''s buy some onions.","spanish":"Bien. Compremos cebollas."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Is there any cheese?","focus":"any cheese unido"},{"text":"There is some juice.","focus":"some juice"},{"text":"There aren''t any onions.","focus":"aren''t any"}],"tip_es":"Contrasta afirmación y negación: some en lo que existe, any después de not en lo que no existe."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Nina","english":"Is there any cheese in the fridge?","spanish":"¿Hay queso en el refrigerador?"},{"speaker":"Omar","english":"Yes, there is some cheese and some juice.","spanish":"Sí, hay queso y jugo."},{"speaker":"Nina","english":"Are there any tomatoes?","spanish":"¿Hay tomates?"},{"speaker":"Omar","english":"There are some tomatoes, but there aren''t any onions.","spanish":"Hay tomates, pero no hay cebollas."},{"speaker":"Nina","english":"Okay. Let''s buy some onions.","spanish":"Bien. Compremos cebollas."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"What is left?","text":"There is some cheese and some juice in the fridge. There are some tomatoes too. There aren''t any onions, and there isn''t any milk. Nina writes onions and milk on the shopping list.","glossary":[{"term":"what is left","meaning_es":"qué queda"},{"term":"shopping list","meaning_es":"lista de compras"},{"term":"milk","meaning_es":"leche"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Revisas qué alimentos tienes en casa y preguntas qué falta.","communication_goal":"Usar some y any para hablar de cantidades no específicas en afirmaciones, preguntas y negaciones.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será tu compañero revisando el refrigerador. Pregunta y responde usando some y any para decidir qué comprar.","scenario":"Checking food before cooking dinner.","ai_language":"English with visual food items and short corrections","prompt":"La IA será tu compañero revisando el refrigerador. Pregunta y responde usando some y any para decidir qué comprar.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T10-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Describe el contenido de tu cocina con seis frases: tres afirmativas con some y tres preguntas o negaciones con any.","success_criteria":["some en afirmaciones","any en preguntas o negaciones","distingue plural y no contable"],"prompt":"Describe el contenido de tu cocina con seis frases: tres afirmativas con some y tres preguntas o negaciones con any.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T10-L01"}]}'::jsonb,6);
