insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Much acompaña sustantivos no contables: much time, much money, much homework. Many acompaña sustantivos contables plurales: many questions, many people. En conversación afirmativa suele sonar más natural a lot of para ambos: a lot of time, a lot of questions.","communication_goal":"Preguntar y responder sobre cantidades usando much con no contables y many con contables plurales.","language_focus":{"grammar":["How much + uncountable noun","How many + plural countable noun","not much","not many","a lot of"],"function":"quantity questions and answers"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"How much time do we have?","word":"time","meaning_es":"tiempo"},{"english":"I have a lot of homework.","word":"homework","meaning_es":"tarea"},{"english":"How many questions are there?","word":"questions","meaning_es":"preguntas"},{"english":"I don''t have much money.","word":"money","meaning_es":"dinero"},{"english":"How many people are here?","word":"people","meaning_es":"personas"},{"english":"We have a lot of time.","word":"a lot of","meaning_es":"mucho/a, muchos/as"}],"dialogue":[{"speaker":"Ella","english":"How much time do we have?","spanish":"¿Cuánto tiempo tenemos?"},{"speaker":"Ben","english":"We have a lot of time. The test starts at two.","spanish":"Tenemos mucho tiempo. El examen empieza a las dos."},{"speaker":"Ella","english":"How many questions are there?","spanish":"¿Cuántas preguntas hay?"},{"speaker":"Ben","english":"There are many questions, but they are easy.","spanish":"Hay muchas preguntas, pero son fáciles."},{"speaker":"Ella","english":"I don''t have much money for a new book.","spanish":"No tengo mucho dinero para un libro nuevo."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"How much time do we have?","focus":"much time y do we"},{"text":"How many questions are there?","focus":"many questions"},{"text":"There are a lot of questions.","focus":"a lot of como bloque"}],"tip_es":"No acentúes much o many de forma exagerada; la palabra clave suele ser el sustantivo."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Ella","english":"How much time do we have?","spanish":"¿Cuánto tiempo tenemos?"},{"speaker":"Ben","english":"We have a lot of time. The test starts at two.","spanish":"Tenemos mucho tiempo. El examen empieza a las dos."},{"speaker":"Ella","english":"How many questions are there?","spanish":"¿Cuántas preguntas hay?"},{"speaker":"Ben","english":"There are many questions, but they are easy.","spanish":"Hay muchas preguntas, pero son fáciles."},{"speaker":"Ella","english":"I don''t have much money for a new book.","spanish":"No tengo mucho dinero para un libro nuevo."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A busy study day","text":"Ben has a lot of homework and many questions to review. He has much less time than Ella, but he has a lot of energy. They have many exercises and enough time to finish them before the test.","glossary":[{"term":"study day","meaning_es":"día de estudio"},{"term":"less time","meaning_es":"menos tiempo"},{"term":"finish","meaning_es":"terminar"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Hablas de cuánto trabajo, comida o tiempo hay en una actividad cotidiana.","communication_goal":"Preguntar y responder sobre cantidades usando much con no contables y many con contables plurales.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será tu compañero preparando un examen. Hablen de tiempo, preguntas, tareas, dinero y ejercicios.","scenario":"Preparing for a test together.","ai_language":"English; contrast much, many and a lot of naturally","prompt":"La IA será tu compañero preparando un examen. Hablen de tiempo, preguntas, tareas, dinero y ejercicios.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T10-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Describe tu próxima sesión de estudio con seis frases: dos con much, dos con many y dos con a lot of.","success_criteria":["much con no contables","many con plurales contables","a lot of con sustantivos adecuados"],"prompt":"Describe tu próxima sesión de estudio con seis frases: dos con much, dos con many y dos con a lot of.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T10-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["distinguir much y many","usar a lot of en afirmaciones","preguntar por cantidades con claridad"],"retry":"Si dudas, mira el sustantivo: ¿es una sustancia/concepto o un plural que puedes contar?"},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Few y little indican una cantidad pequeña, pero se usan con tipos distintos. Few va con contables plurales: few chairs. Little va con no contables: little water. La expresión a few significa algunos y suele sonar positiva; a little significa un poco y también indica que hay una cantidad útil. Sin a, few/little sugieren que casi no hay suficiente.","communication_goal":"Describir cantidades pequeñas usando few con contables y little con no contables.","language_focus":{"grammar":["a few + plural countable","few + plural countable","a little + uncountable","little + uncountable","enough"],"function":"small quantities and sufficiency"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I have a few questions.","word":"a few","meaning_es":"unos pocos/algunos"},{"english":"There are few chairs.","word":"few","meaning_es":"pocos, casi ninguno"},{"english":"We have a little time.","word":"a little","meaning_es":"un poco"},{"english":"There is little water.","word":"little","meaning_es":"poco, casi nada"},{"english":"We have enough chairs.","word":"enough","meaning_es":"suficiente"},{"english":"There are a few chairs.","word":"chair","meaning_es":"silla"}],"dialogue":[{"speaker":"Mia","english":"How many chairs do we have?","spanish":"¿Cuántas sillas tenemos?"},{"speaker":"Leo","english":"We have a few chairs, but there are few tables.","spanish":"Tenemos algunas sillas, pero hay pocas mesas."},{"speaker":"Mia","english":"Do we have enough water?","spanish":"¿Tenemos suficiente agua?"},{"speaker":"Leo","english":"We have a little water, but not enough for everyone.","spanish":"Tenemos un poco de agua, pero no suficiente para todos."},{"speaker":"Mia","english":"Okay. Let''s buy more tables and water.","spanish":"Bien. Compremos más mesas y agua."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"a few chairs","focus":"few chairs como bloque"},{"text":"a little water","focus":"little water"},{"text":"not enough for everyone","focus":"enough y for"}],"tip_es":"La diferencia de significado depende mucho de a: compara few y a few con ejemplos reales."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Mia","english":"How many chairs do we have?","spanish":"¿Cuántas sillas tenemos?"},{"speaker":"Leo","english":"We have a few chairs, but there are few tables.","spanish":"Tenemos algunas sillas, pero hay pocas mesas."},{"speaker":"Mia","english":"Do we have enough water?","spanish":"¿Tenemos suficiente agua?"},{"speaker":"Leo","english":"We have a little water, but not enough for everyone.","spanish":"Tenemos un poco de agua, pero no suficiente para todos."},{"speaker":"Mia","english":"Okay. Let''s buy more tables and water.","spanish":"Bien. Compremos más mesas y agua."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A small workshop","text":"Mia and Leo prepare a small workshop. They have a few chairs, but few tables. They have a little water, but little coffee. There is enough food for the guests, so they only buy tables and drinks.","glossary":[{"term":"small workshop","meaning_es":"taller pequeño"},{"term":"guests","meaning_es":"invitados"},{"term":"drinks","meaning_es":"bebidas"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Explicas qué recursos tienes disponibles y si son suficientes para terminar una tarea.","communication_goal":"Describir cantidades pequeñas usando few con contables y little con no contables.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un organizador. Decidan si hay suficientes sillas, tiempo, agua y comida usando few, a few, little y a little.","scenario":"Preparing supplies for a small event.","ai_language":"English; ask whether the quantity is enough","prompt":"La IA será un organizador. Decidan si hay suficientes sillas, tiempo, agua y comida usando few, a few, little y a little.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T10-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Describe cuatro recursos de tu día: dos contables y dos no contables. Explica cuáles son suficientes y cuáles necesitan más.","success_criteria":["few/a few con plurales","little/a little con no contables","usa enough o not enough con sentido"],"prompt":"Describe cuatro recursos de tu día: dos contables y dos no contables. Explica cuáles son suficientes y cuáles necesitan más.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T10-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["distinguir few/little","usar a few/a little como cantidades disponibles","explicar si una cantidad es suficiente"],"retry":"Si confundes few y little, revisa primero si el sustantivo se puede contar directamente."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para resolver una situación, combina varias herramientas: some/any para existencia no específica, much/many para preguntar cantidad, few/little para cantidades pequeñas y enough para decidir si basta. Revisa el sustantivo antes de elegir: guests y cups son contables; bread, juice y water son no contables.","communication_goal":"Combinar some, any, much, many, few, little y unidades para resolver una necesidad cotidiana.","language_focus":{"grammar":["some/any","much/many","few/little","a lot of","enough","units of measure"],"function":"integrated quantity language"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"We need more supplies.","word":"supplies","meaning_es":"materiales/suministros"},{"english":"How many guests are there?","word":"guest","meaning_es":"invitado"},{"english":"How much food is available?","word":"available","meaning_es":"disponible"},{"english":"We need two extra chairs.","word":"extra","meaning_es":"adicional/extra"},{"english":"We might run out of water.","word":"run out of","meaning_es":"quedarse sin"},{"english":"Let''s plan ahead.","word":"plan ahead","meaning_es":"planificar con anticipación"}],"dialogue":[{"speaker":"Organizer","english":"How many guests are coming?","spanish":"¿Cuántos invitados vienen?"},{"speaker":"Volunteer","english":"There are thirty guests. We have a lot of bread and a few eggs.","spanish":"Hay treinta invitados. Tenemos mucho pan y algunos huevos."},{"speaker":"Organizer","english":"How much juice is available?","spanish":"¿Cuánto jugo hay disponible?"},{"speaker":"Volunteer","english":"There is little juice and not enough water. We need two more bottles of water.","spanish":"Hay poco jugo y no suficiente agua. Necesitamos dos botellas más de agua."},{"speaker":"Organizer","english":"Are there any cups?","spanish":"¿Hay vasos?"},{"speaker":"Volunteer","english":"Yes, there are some cups, but few plates.","spanish":"Sí, hay algunos vasos, pero pocos platos."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"There are thirty guests.","focus":"thirty y guests"},{"text":"There is not enough water.","focus":"not enough water"},{"text":"There are some cups, but few plates.","focus":"contraste some/few"}],"tip_es":"En una situación real, repite la cantidad y confirma: Two more bottles? Yes, two more bottles."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Organizer","english":"How many guests are coming?","spanish":"¿Cuántos invitados vienen?"},{"speaker":"Volunteer","english":"There are thirty guests. We have a lot of bread and a few eggs.","spanish":"Hay treinta invitados. Tenemos mucho pan y algunos huevos."},{"speaker":"Organizer","english":"How much juice is available?","spanish":"¿Cuánto jugo hay disponible?"},{"speaker":"Volunteer","english":"There is little juice and not enough water. We need two more bottles of water.","spanish":"Hay poco jugo y no suficiente agua. Necesitamos dos botellas más de agua."},{"speaker":"Organizer","english":"Are there any cups?","spanish":"¿Hay vasos?"},{"speaker":"Volunteer","english":"Yes, there are some cups, but few plates.","spanish":"Sí, hay algunos vasos, pero pocos platos."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The breakfast plan","text":"Thirty guests are coming to a community breakfast. The organizers have a lot of bread, a few eggs and some cups. They have little juice, not enough water and few plates, so they buy two bottles of water and extra plates.","glossary":[{"term":"community breakfast","meaning_es":"desayuno comunitario"},{"term":"organizer","meaning_es":"organizador"},{"term":"extra plates","meaning_es":"platos adicionales"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Organizas una reunión y decides qué recursos tienes, qué falta y cuánto comprar.","communication_goal":"Combinar some, any, much, many, few, little y unidades para resolver una necesidad cotidiana.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Resuelve con la IA el inventario de un evento. Pregunta cantidades, identifica faltantes y acuerda una lista de compras.","scenario":"Planning supplies for a community breakfast.","ai_language":"English; require a reason for each purchase","prompt":"Resuelve con la IA el inventario de un evento. Pregunta cantidades, identifica faltantes y acuerda una lista de compras.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T10-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un diálogo de diez turnos en el que planificas una reunión. Incluye some, any, much, many, few, little, enough, a lot of y dos unidades.","success_criteria":["cada cuantificador tiene un sustantivo adecuado","las preguntas y respuestas son coherentes","la conversación termina con una decisión de compra"],"prompt":"Graba un diálogo de diez turnos en el que planificas una reunión. Incluye some, any, much, many, few, little, enough, a lot of y dos unidades.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M2-T10-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["seleccionar cuantificadores según el sustantivo y el contexto","expresar suficiencia o falta","resolver oralmente una situación de cantidades"],"retry":"Si el resultado es menor de 80%, clasifica cada sustantivo y reconstruye el inventario con frases cortas antes de repetir el diálogo."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para presentarte puedes decir Hi, I''m + nombre o My name is + nombre. Para preguntar usas What''s your name? La expresión Nice to meet you equivale a ''mucho gusto'' y se responde Nice to meet you too. En una situación informal Hi es común; Hello funciona en situaciones informales y formales.","communication_goal":"Saludar, decir tu nombre y preguntar el nombre de otra persona.","language_focus":{"grammar":["Hi, I''m...","My name is...","What''s your name?","Nice to meet you.","How are you?"],"function":"greetings and introductions"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Hello, I''m Sofia.","word":"hello","meaning_es":"hola"},{"english":"Hi, my name is Ben.","word":"hi","meaning_es":"hola informal"},{"english":"What''s your name?","word":"name","meaning_es":"nombre"},{"english":"Nice to meet you.","word":"meet","meaning_es":"conocer/encontrarse"},{"english":"Nice to meet you.","word":"nice","meaning_es":"agradable"},{"english":"I''m fine, thanks.","word":"fine","meaning_es":"bien"}],"dialogue":[{"speaker":"Sofia","english":"Hi, I''m Sofia. What''s your name?","spanish":"Hola, soy Sofia. ¿Cómo te llamas?"},{"speaker":"Ben","english":"Hello, my name is Ben.","spanish":"Hola, mi nombre es Ben."},{"speaker":"Sofia","english":"Nice to meet you, Ben.","spanish":"Mucho gusto, Ben."},{"speaker":"Ben","english":"Nice to meet you too. How are you?","spanish":"Mucho gusto también. ¿Cómo estás?"},{"speaker":"Sofia","english":"I''m fine, thanks. How are you?","spanish":"Estoy bien, gracias. ¿Y tú?"}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Hi, I''m Sofia.","focus":"unir Hi I''m"},{"text":"What''s your name?","focus":"what''s y your"},{"text":"Nice to meet you too.","focus":"ritmo de la expresión fija"}],"tip_es":"Memoriza el saludo como un bloque conversacional y practica la respuesta inmediatamente después."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Sofia","english":"Hi, I''m Sofia. What''s your name?","spanish":"Hola, soy Sofia. ¿Cómo te llamas?"},{"speaker":"Ben","english":"Hello, my name is Ben.","spanish":"Hola, mi nombre es Ben."},{"speaker":"Sofia","english":"Nice to meet you, Ben.","spanish":"Mucho gusto, Ben."},{"speaker":"Ben","english":"Nice to meet you too. How are you?","spanish":"Mucho gusto también. ¿Cómo estás?"},{"speaker":"Sofia","english":"I''m fine, thanks. How are you?","spanish":"Estoy bien, gracias. ¿Y tú?"}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A new classmate","text":"Sofia is in a new English class. She says hello to Ben and introduces herself. They say their names and ask how each person is. They are both fine and happy to start the class.","glossary":[{"term":"classmate","meaning_es":"compañero de clase"},{"term":"introduce herself","meaning_es":"presentarse"},{"term":"both","meaning_es":"ambos"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Conoces a alguien por primera vez en una clase, trabajo o actividad social.","communication_goal":"Saludar, decir tu nombre y preguntar el nombre de otra persona.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero nuevo. Saluda, di tu nombre, pregunta el suyo y responde How are you?.","scenario":"First meeting in an English class.","ai_language":"English with friendly Spanish support only after difficulty","prompt":"La IA será un compañero nuevo. Saluda, di tu nombre, pregunta el suyo y responde How are you?.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T01-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una presentación de 20 segundos para una persona nueva: saludo, nombre, pregunta y despedida amable.","success_criteria":["usa I''m o My name is","pregunta el nombre","usa Nice to meet you","voz comprensible"],"prompt":"Graba una presentación de 20 segundos para una persona nueva: saludo, nombre, pregunta y despedida amable.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T01-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["saludar y decir el nombre","preguntar el nombre","responder a How are you? y Nice to meet you"],"retry":"Si traduces literalmente la pregunta del nombre, repite el bloque What''s your name? hasta decirlo sin pausas."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Usa Where are you from? para preguntar origen y Where do you live? para residencia. Para trabajo puedes decir What do you do? o What is your job? Responde I work as a + profesión o I am a + profesión. Para datos como teléfono y correo, usa What''s your phone number/email address?. Comparte datos personales solo en contextos seguros.","communication_goal":"Dar y preguntar información básica como país, ciudad, trabajo y número de teléfono.","language_focus":{"grammar":["Where are you from?","I''m from...","Where do you live?","I live in...","What do you do?","I work as..."],"function":"basic personal information"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I''m from Colombia.","word":"country","meaning_es":"país"},{"english":"I live in Miami.","word":"city","meaning_es":"ciudad"},{"english":"Where do you live?","word":"live","meaning_es":"vivir"},{"english":"What is your job?","word":"job","meaning_es":"trabajo"},{"english":"What''s your phone number?","word":"phone number","meaning_es":"número de teléfono"},{"english":"What''s your email address?","word":"email address","meaning_es":"dirección de correo"}],"dialogue":[{"speaker":"Staff","english":"What''s your name?","spanish":"¿Cómo te llamas?"},{"speaker":"Visitor","english":"My name is Daniela Cruz.","spanish":"Me llamo Daniela Cruz."},{"speaker":"Staff","english":"Where are you from?","spanish":"¿De dónde eres?"},{"speaker":"Visitor","english":"I''m from Mexico, but I live in Chicago.","spanish":"Soy de México, pero vivo en Chicago."},{"speaker":"Staff","english":"What do you do?","spanish":"¿A qué te dedicas?"},{"speaker":"Visitor","english":"I work as a designer. My phone number is 555-0182.","spanish":"Trabajo como diseñadora. Mi número es 555-0182."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Where are you from?","focus":"where are you unido"},{"text":"I live in Chicago.","focus":"live in"},{"text":"What do you do?","focus":"repetición natural do you do"}],"tip_es":"Al decir un correo o teléfono, habla más despacio y confirma la información."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Staff","english":"What''s your name?","spanish":"¿Cómo te llamas?"},{"speaker":"Visitor","english":"My name is Daniela Cruz.","spanish":"Me llamo Daniela Cruz."},{"speaker":"Staff","english":"Where are you from?","spanish":"¿De dónde eres?"},{"speaker":"Visitor","english":"I''m from Mexico, but I live in Chicago.","spanish":"Soy de México, pero vivo en Chicago."},{"speaker":"Staff","english":"What do you do?","spanish":"¿A qué te dedicas?"},{"speaker":"Visitor","english":"I work as a designer. My phone number is 555-0182.","spanish":"Trabajo como diseñadora. Mi número es 555-0182."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Daniela''s profile","text":"Daniela Cruz is from Mexico, but she lives in Chicago. She works as a designer. Her phone number is 555-0182, and her email address is daniela@example.com. She is completing a registration form for an English class.","glossary":[{"term":"profile","meaning_es":"perfil"},{"term":"registration form","meaning_es":"formulario de registro"},{"term":"designer","meaning_es":"diseñador/a"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Completar un registro o conversar con alguien nuevo sobre datos personales básicos.","communication_goal":"Dar y preguntar información básica como país, ciudad, trabajo y número de teléfono.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será personal de recepción. Completa un registro oral con nombre, origen, residencia y trabajo.","scenario":"Registering for an English class.","ai_language":"English; avoid requesting real private information","prompt":"La IA será personal de recepción. Completa un registro oral con nombre, origen, residencia y trabajo.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T01-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un perfil ficticio seguro de 30 segundos con nombre, país, ciudad, trabajo y un dato de contacto inventado.","success_criteria":["distingue from e in","usa What do you do?","pronuncia datos comprensiblemente","no usa información privada real"],"prompt":"Graba un perfil ficticio seguro de 30 segundos con nombre, país, ciudad, trabajo y un dato de contacto inventado.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T01-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["dar origen y residencia","hablar de trabajo","comprender preguntas de información personal"],"retry":"Si confundes from e in, recuerda: from indica de dónde vienes; in indica dónde vives."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Después de los datos básicos puedes añadir edad, intereses y actividades. En inglés se dice I am twenty-eight years old, no I have twenty-eight years. Para gustos usa I like + sustantivo o verbo en -ing: I like music, I like cooking. What about you? devuelve la conversación a la otra persona.","communication_goal":"Añadir edad, intereses y actividades a una presentación personal breve.","language_focus":{"grammar":["I am ... years old","I like...","I enjoy...","My favorite ... is...","What about you?"],"function":"extending a personal introduction"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I am thirty years old.","word":"years old","meaning_es":"años de edad"},{"english":"My hobby is cooking.","word":"hobby","meaning_es":"pasatiempo"},{"english":"I like music.","word":"music","meaning_es":"música"},{"english":"My favorite movie is ...","word":"movie","meaning_es":"película"},{"english":"I enjoy cooking.","word":"cook","meaning_es":"cocinar"},{"english":"What do you do in your free time?","word":"free time","meaning_es":"tiempo libre"}],"dialogue":[{"speaker":"Teacher","english":"Tell us about yourself, Ana.","spanish":"Cuéntanos sobre ti, Ana."},{"speaker":"Ana","english":"I''m Ana. I''m from Ecuador, but I live in New York. I''m twenty-eight years old.","spanish":"Soy Ana. Soy de Ecuador, pero vivo en Nueva York. Tengo veintiocho años."},{"speaker":"Teacher","english":"What do you do in your free time?","spanish":"¿Qué haces en tu tiempo libre?"},{"speaker":"Ana","english":"I like music and I enjoy cooking. My favorite movie is a comedy.","spanish":"Me gusta la música y disfruto cocinar. Mi película favorita es una comedia."},{"speaker":"Teacher","english":"What about you?","spanish":"¿Y tú?"}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I am twenty-eight years old.","focus":"years old y número compuesto"},{"text":"I enjoy cooking.","focus":"enjoy y cooking"},{"text":"What about you?","focus":"entonación de devolución"}],"tip_es":"Agrupa la presentación en bloques: identidad, origen, edad, trabajo e intereses."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Teacher","english":"Tell us about yourself, Ana.","spanish":"Cuéntanos sobre ti, Ana."},{"speaker":"Ana","english":"I''m Ana. I''m from Ecuador, but I live in New York. I''m twenty-eight years old.","spanish":"Soy Ana. Soy de Ecuador, pero vivo en Nueva York. Tengo veintiocho años."},{"speaker":"Teacher","english":"What do you do in your free time?","spanish":"¿Qué haces en tu tiempo libre?"},{"speaker":"Ana","english":"I like music and I enjoy cooking. My favorite movie is a comedy.","spanish":"Me gusta la música y disfruto cocinar. Mi película favorita es una comedia."},{"speaker":"Teacher","english":"What about you?","spanish":"¿Y tú?"}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Ana''s introduction","text":"Ana is twenty-eight years old. She is from Ecuador, but she lives in New York. She works in an office and enjoys cooking in her free time. She likes music, and her favorite movies are comedies.","glossary":[{"term":"tell us about yourself","meaning_es":"cuéntanos sobre ti"},{"term":"office","meaning_es":"oficina"},{"term":"comedy","meaning_es":"comedia"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Conversas con un compañero después de presentarte y compartes información apropiada.","communication_goal":"Añadir edad, intereses y actividades a una presentación personal breve.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero curioso. Amplía tu presentación con edad ficticia, intereses y tiempo libre; pregunta What about you?.","scenario":"Continuing a friendly introduction after basic information.","ai_language":"English; keep personal details fictional","prompt":"La IA será un compañero curioso. Amplía tu presentación con edad ficticia, intereses y tiempo libre; pregunta What about you?.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T01-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una presentación de 40 segundos con nombre, origen, ciudad, edad ficticia, trabajo e intereses.","success_criteria":["usa be para edad y origen","usa like/enjoy correctamente","incluye What about you?","mensaje comprensible"],"prompt":"Graba una presentación de 40 segundos con nombre, origen, ciudad, edad ficticia, trabajo e intereses.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T01-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["añadir edad e intereses","usar like y enjoy","devolver la conversación con What about you?"],"retry":"Si traduces la edad con have, repite cinco frases con I am ... years old."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una presentación completa combina identidad, origen, residencia, trabajo e intereses. Usa to be para identidad, origen y edad; do para rutinas; like/enjoy para gustos. Conecta ideas con and, but y because y haz una pregunta de seguimiento. En un contexto formal puedes usar Pleased to meet you; en uno informal Nice to meet you.","communication_goal":"Presentarte con naturalidad, responder preguntas personales básicas y mantener varios turnos de conversación.","language_focus":{"grammar":["to be for identity/origin/age","do questions for routines","like/enjoy","and/but/because","follow-up questions"],"function":"complete personal introduction"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Let me introduce myself.","word":"introduce","meaning_es":"presentar"},{"english":"Tell me about your background.","word":"background","meaning_es":"origen/experiencia"},{"english":"I currently live in Boston.","word":"currently","meaning_es":"actualmente"},{"english":"Pleased to meet you.","word":"pleased","meaning_es":"encantado/a"},{"english":"We have a short conversation.","word":"conversation","meaning_es":"conversación"},{"english":"Here is my contact information.","word":"contact","meaning_es":"contacto"}],"dialogue":[{"speaker":"Rafael","english":"Hi, I''m Rafael. Let me introduce myself.","spanish":"Hola, soy Rafael. Permíteme presentarme."},{"speaker":"Mina","english":"Pleased to meet you. Where are you from?","spanish":"Encantada de conocerte. ¿De dónde eres?"},{"speaker":"Rafael","english":"I''m from Spain, but I currently live in Boston. I work as a nurse.","spanish":"Soy de España, pero actualmente vivo en Boston. Trabajo como enfermero."},{"speaker":"Mina","english":"What do you do in your free time?","spanish":"¿Qué haces en tu tiempo libre?"},{"speaker":"Rafael","english":"I enjoy cooking and I often play soccer. What about you?","spanish":"Disfruto cocinar y a menudo juego fútbol. ¿Y tú?"},{"speaker":"Mina","english":"I like reading. Nice to meet you, Rafael.","spanish":"Me gusta leer. Mucho gusto, Rafael."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Let me introduce myself.","focus":"introduce myself"},{"text":"I currently live in Boston.","focus":"currently live in"},{"text":"I enjoy cooking and often play soccer.","focus":"conexión and often"}],"tip_es":"Practica la presentación en dos velocidades: clara para un formulario y natural para una conversación."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Rafael","english":"Hi, I''m Rafael. Let me introduce myself.","spanish":"Hola, soy Rafael. Permíteme presentarme."},{"speaker":"Mina","english":"Pleased to meet you. Where are you from?","spanish":"Encantada de conocerte. ¿De dónde eres?"},{"speaker":"Rafael","english":"I''m from Spain, but I currently live in Boston. I work as a nurse.","spanish":"Soy de España, pero actualmente vivo en Boston. Trabajo como enfermero."},{"speaker":"Mina","english":"What do you do in your free time?","spanish":"¿Qué haces en tu tiempo libre?"},{"speaker":"Rafael","english":"I enjoy cooking and I often play soccer. What about you?","spanish":"Disfruto cocinar y a menudo juego fútbol. ¿Y tú?"},{"speaker":"Mina","english":"I like reading. Nice to meet you, Rafael.","spanish":"Me gusta leer. Mucho gusto, Rafael."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Rafael''s profile","text":"Rafael is from Spain, but he currently lives in Boston. He works as a nurse and enjoys cooking. In his free time, he often plays soccer. At a welcome event, he introduces himself and asks other people about their lives.","glossary":[{"term":"welcome event","meaning_es":"evento de bienvenida"},{"term":"currently","meaning_es":"actualmente"},{"term":"nurse","meaning_es":"enfermero/a"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Participas en una actividad de networking o bienvenida y conversas con varias personas.","communication_goal":"Presentarte con naturalidad, responder preguntas personales básicas y mantener varios turnos de conversación.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será una persona en un evento de bienvenida. Realiza seis turnos: saludo, presentación, preguntas, respuesta y seguimiento.","scenario":"A friendly professional welcome event with fictional details.","ai_language":"English; adapt questions to the learner''s answers","prompt":"La IA será una persona en un evento de bienvenida. Realiza seis turnos: saludo, presentación, preguntas, respuesta y seguimiento.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T01-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Realiza dos presentaciones: una informal para un compañero y otra formal para una actividad profesional, usando datos ficticios.","success_criteria":["diferencia Hi y Pleased to meet you","incluye origen, ciudad, trabajo e intereses","hace una pregunta de seguimiento","habla con claridad"],"prompt":"Realiza dos presentaciones: una informal para un compañero y otra formal para una actividad profesional, usando datos ficticios.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T01-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["presentarse con información conectada","responder preguntas personales","mantener una conversación de al menos seis turnos"],"retry":"Si el resultado es menor de 80%, usa una plantilla de cinco bloques y repite la presentación con datos ficticios."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para presentar una persona usa This is my + familiar: This is my mother. Para varias personas usa These are my parents. Pregunta Who is this? para una persona y Who are they? para varias. My indica posesión: my mother, my brother, my family.","communication_goal":"Nombrar familiares y decir quiénes forman parte de tu familia.","language_focus":{"grammar":["This is my...","These are my...","I have...","He/She is my...","Who is...?"],"function":"introducing family members"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"This is my mother.","word":"mother","meaning_es":"madre"},{"english":"He is my father.","word":"father","meaning_es":"padre"},{"english":"I have one sister.","word":"sister","meaning_es":"hermana"},{"english":"These are my brothers.","word":"brother","meaning_es":"hermano"},{"english":"My parents live nearby.","word":"parents","meaning_es":"padres"},{"english":"My family is small.","word":"family","meaning_es":"familia"}],"dialogue":[{"speaker":"Lia","english":"Who is this?","spanish":"¿Quién es esta persona?"},{"speaker":"Marco","english":"This is my mother. Her name is Rosa.","spanish":"Esta es mi madre. Se llama Rosa."},{"speaker":"Lia","english":"And who are they?","spanish":"¿Y quiénes son ellos?"},{"speaker":"Marco","english":"They are my brother and sister.","spanish":"Son mi hermano y mi hermana."},{"speaker":"Lia","english":"Do you have a big family?","spanish":"¿Tienes una familia grande?"},{"speaker":"Marco","english":"No, I don''t. My family is small.","spanish":"No. Mi familia es pequeña."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"This is my mother.","focus":"this is my unido"},{"text":"These are my parents.","focus":"these y parents"},{"text":"Who are they?","focus":"who are y plural"}],"tip_es":"Practica señalando una foto: una persona = this is; varias = these are."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Lia","english":"Who is this?","spanish":"¿Quién es esta persona?"},{"speaker":"Marco","english":"This is my mother. Her name is Rosa.","spanish":"Esta es mi madre. Se llama Rosa."},{"speaker":"Lia","english":"And who are they?","spanish":"¿Y quiénes son ellos?"},{"speaker":"Marco","english":"They are my brother and sister.","spanish":"Son mi hermano y mi hermana."},{"speaker":"Lia","english":"Do you have a big family?","spanish":"¿Tienes una familia grande?"},{"speaker":"Marco","english":"No, I don''t. My family is small.","spanish":"No. Mi familia es pequeña."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Marco''s family","text":"Marco has a small family. He has one brother and one sister. His mother is Rosa and his father is Luis. His parents live nearby. Marco loves his family.","glossary":[{"term":"nearby","meaning_es":"cerca"},{"term":"small family","meaning_es":"familia pequeña"},{"term":"loves","meaning_es":"ama/quiére"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Muestras una foto o describes tu familia a un compañero nuevo.","communication_goal":"Nombrar familiares y decir quiénes forman parte de tu familia.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero viendo una foto familiar ficticia. Presenta cinco personas y pregunta Who is this?/Who are they?.","scenario":"Talking about a fictional family photo.","ai_language":"English; avoid asking for real private family details","prompt":"La IA será un compañero viendo una foto familiar ficticia. Presenta cinco personas y pregunta Who is this?/Who are they?.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T02-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Crea un árbol familiar ficticio y graba seis frases para presentarlo.","success_criteria":["usa al menos seis familiares","distingue this/these","usa my correctamente","la descripción se entiende"],"prompt":"Crea un árbol familiar ficticio y graba seis frases para presentarlo.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T02-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["nombrar familiares","distinguir this/these","presentar personas con my"],"retry":"Si confundes singular y plural, señala una persona o varias y elige this is o these are."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para describir a un familiar usa he o she según la persona: He is quiet; She is kind. Para hablar de algo que le pertenece usa his o her: his job, her name. En presente simple, he/she lleva s en afirmativa: She works, He likes. Para preguntar por una actividad usa What does she do? y el verbo principal queda en base.","communication_goal":"Describir familiares con edad, profesión, personalidad y acciones cotidianas básicas.","language_focus":{"grammar":["He/She is...","He/She works...","He/She likes...","His/Her...","Who does he/she...?"],"function":"describing family members"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"My sister is kind.","word":"kind","meaning_es":"amable"},{"english":"My brother is funny.","word":"funny","meaning_es":"divertido/a"},{"english":"My father is quiet.","word":"quiet","meaning_es":"tranquilo/a"},{"english":"She works as a teacher.","word":"teacher","meaning_es":"profesor/a"},{"english":"My cousin is young.","word":"young","meaning_es":"joven"},{"english":"My grandfather is old.","word":"old","meaning_es":"mayor/viejo"}],"dialogue":[{"speaker":"Ana","english":"Tell me about your sister.","spanish":"Háblame de tu hermana."},{"speaker":"Luis","english":"Her name is Elena. She is kind and funny.","spanish":"Se llama Elena. Es amable y divertida."},{"speaker":"Ana","english":"What does she do?","spanish":"¿A qué se dedica?"},{"speaker":"Luis","english":"She works as a teacher. She likes reading.","spanish":"Trabaja como profesora. Le gusta leer."},{"speaker":"Ana","english":"And your brother?","spanish":"¿Y tu hermano?"},{"speaker":"Luis","english":"He is quiet, but he likes music.","spanish":"Es tranquilo, pero le gusta la música."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Her name is Elena.","focus":"her name is"},{"text":"She works as a teacher.","focus":"s de works"},{"text":"What does she do?","focus":"does she do como bloque"}],"tip_es":"Practica cada descripción con el pronombre, el verbo y la información en tres grupos de ritmo."}'::jsonb,3);
