insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Elena and David","text":"Elena is Luis''s sister. She is kind and funny, and she works as a teacher. She likes reading. Luis''s brother David is quiet. He likes music and works in a store.","glossary":[{"term":"different siblings","meaning_es":"hermanos diferentes"},{"term":"store","meaning_es":"tienda"},{"term":"kind","meaning_es":"amable"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Respondes preguntas sobre tu familia y comparas a dos personas.","communication_goal":"Describir familiares con edad, profesión, personalidad y acciones cotidianas básicas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Describe a dos familiares ficticios. La IA pregunta por su personalidad, trabajo, gustos y rutinas.","scenario":"Talking about two fictional family members.","ai_language":"English; prompt he/she and his/her naturally","prompt":"Describe a dos familiares ficticios. La IA pregunta por su personalidad, trabajo, gustos y rutinas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T02-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una comparación de 40 segundos entre dos familiares ficticios usando but y sus nombres/pronombres.","success_criteria":["usa he/she correctamente","usa his/her correctamente","incluye personalidad, trabajo y gusto","conecta con but"],"prompt":"Graba una comparación de 40 segundos entre dos familiares ficticios usando but y sus nombres/pronombres.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T02-L02"}]}'::jsonb,6);
