insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para hablar de convivencia usa live with: I live with my wife. Para actividades compartidas, We + verbo: We visit my parents; We eat together. Para preguntar por la persona que acompaña una acción usa Who do you live with? o Who do you visit? Con he/she recuerda la s: He lives nearby.","communication_goal":"Hablar de relaciones familiares y actividades que haces con otras personas.","language_focus":{"grammar":["I live with...","I visit...","We usually...","He/She lives...","Who do you...?"],"function":"family relationships and shared routines"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"She lives with her husband.","word":"husband","meaning_es":"esposo"},{"english":"He visits his wife.","word":"wife","meaning_es":"esposa"},{"english":"Their son is young.","word":"son","meaning_es":"hijo"},{"english":"Their daughter likes music.","word":"daughter","meaning_es":"hija"},{"english":"We visit our grandparents.","word":"visit","meaning_es":"visitar"},{"english":"We eat together.","word":"together","meaning_es":"juntos"}],"dialogue":[{"speaker":"Clara","english":"Who do you live with?","spanish":"¿Con quién vives?"},{"speaker":"Jorge","english":"I live with my wife and our daughter.","spanish":"Vivo con mi esposa y nuestra hija."},{"speaker":"Clara","english":"What do you do on Sundays?","spanish":"¿Qué hacen los domingos?"},{"speaker":"Jorge","english":"We usually visit my parents. We eat together.","spanish":"Normalmente visitamos a mis padres. Comemos juntos."},{"speaker":"Clara","english":"Does your son live with you too?","spanish":"¿Tu hijo también vive contigo?"},{"speaker":"Jorge","english":"No, he doesn''t. He lives nearby.","spanish":"No. Vive cerca."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I live with my wife and our daughter.","focus":"live with y our"},{"text":"We usually visit my parents.","focus":"usually visit"},{"text":"Who do you live with?","focus":"who do you y with"}],"tip_es":"En frases largas, agrupa a las personas primero y la actividad después."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Clara","english":"Who do you live with?","spanish":"¿Con quién vives?"},{"speaker":"Jorge","english":"I live with my wife and our daughter.","spanish":"Vivo con mi esposa y nuestra hija."},{"speaker":"Clara","english":"What do you do on Sundays?","spanish":"¿Qué hacen los domingos?"},{"speaker":"Jorge","english":"We usually visit my parents. We eat together.","spanish":"Normalmente visitamos a mis padres. Comemos juntos."},{"speaker":"Clara","english":"Does your son live with you too?","spanish":"¿Tu hijo también vive contigo?"},{"speaker":"Jorge","english":"No, he doesn''t. He lives nearby.","spanish":"No. Vive cerca."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Jorge''s Sunday","text":"Jorge lives with his wife and their daughter. On Sundays, they usually visit Jorge''s parents and eat together. Their son does not live with them, but he lives nearby and visits often.","glossary":[{"term":"shared routines","meaning_es":"rutinas compartidas"},{"term":"nearby","meaning_es":"cerca"},{"term":"visits often","meaning_es":"visita a menudo"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Explicas con quién vives, a quién visitas y qué haces con tu familia.","communication_goal":"Hablar de relaciones familiares y actividades que haces con otras personas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un amigo que pregunta por tus rutinas familiares. Habla usando live with, visit, eat together y who questions.","scenario":"Talking about a typical family Sunday.","ai_language":"English; use fictional details if preferred","prompt":"La IA será un amigo que pregunta por tus rutinas familiares. Habla usando live with, visit, eat together y who questions.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T02-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba seis frases sobre una rutina familiar ficticia: convivencia, visitas y dos actividades compartidas.","success_criteria":["usa live with correctamente","usa al menos dos familiares","incluye una frase con we","tercera persona correcta"],"prompt":"Graba seis frases sobre una rutina familiar ficticia: convivencia, visitas y dos actividades compartidas.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T02-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["hablar de convivencia","describir actividades compartidas","usar live/visits en tercera persona"],"retry":"Si confundes live y visit, recuerda: live = vivir; visit = ir a ver a alguien."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una presentación familiar conecta información: This is a photo of my family. These are my parents... Usa my, his, her, our y their para relaciones y posesión. Añade older/younger para comparar edades y and, but o because para unir ideas. La meta es describir quiénes son, dónde viven y qué hacen juntos.","communication_goal":"Presentar a una familia de forma conectada, responder preguntas y comparar relaciones.","language_focus":{"grammar":["family vocabulary","possessives","he/she + verb-s","do/does questions","and/but/because"],"function":"complete family description"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"She is my relative.","word":"relative","meaning_es":"familiar/pariente"},{"english":"We are close.","word":"close","meaning_es":"cercano"},{"english":"My older brother lives nearby.","word":"older","meaning_es":"mayor"},{"english":"My younger sister studies.","word":"younger","meaning_es":"menor"},{"english":"My family supports me.","word":"support","meaning_es":"apoyar"},{"english":"This is a photo of my family.","word":"photo","meaning_es":"foto"}],"dialogue":[{"speaker":"Teacher","english":"Tell us about this photo.","spanish":"Háblanos de esta foto."},{"speaker":"Student","english":"This is a photo of my family. These are my parents and my younger sister.","spanish":"Esta es una foto de mi familia. Estos son mis padres y mi hermana menor."},{"speaker":"Teacher","english":"Who do you live with?","spanish":"¿Con quién vives?"},{"speaker":"Student","english":"I live with my parents. My older brother lives nearby, and we visit him on Sundays.","spanish":"Vivo con mis padres. Mi hermano mayor vive cerca y lo visitamos los domingos."},{"speaker":"Teacher","english":"Are you close?","spanish":"¿Son cercanos?"},{"speaker":"Student","english":"Yes, we are. My family supports me.","spanish":"Sí. Mi familia me apoya."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"This is a photo of my family.","focus":"photo of my"},{"text":"My older brother lives nearby.","focus":"older brother y lives"},{"text":"My family supports me.","focus":"supports me"}],"tip_es":"Usa la foto como apoyo visual, pero intenta mirar a la persona mientras presentas."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Teacher","english":"Tell us about this photo.","spanish":"Háblanos de esta foto."},{"speaker":"Student","english":"This is a photo of my family. These are my parents and my younger sister.","spanish":"Esta es una foto de mi familia. Estos son mis padres y mi hermana menor."},{"speaker":"Teacher","english":"Who do you live with?","spanish":"¿Con quién vives?"},{"speaker":"Student","english":"I live with my parents. My older brother lives nearby, and we visit him on Sundays.","spanish":"Vivo con mis padres. Mi hermano mayor vive cerca y lo visitamos los domingos."},{"speaker":"Teacher","english":"Are you close?","spanish":"¿Son cercanos?"},{"speaker":"Student","english":"Yes, we are. My family supports me.","spanish":"Sí. Mi familia me apoya."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A close family","text":"This is a photo of Emma''s family. She lives with her parents and younger sister. Her older brother lives nearby. They visit him on Sundays because they are close. Emma''s family supports her.","glossary":[{"term":"family presentation","meaning_es":"presentación familiar"},{"term":"older brother","meaning_es":"hermano mayor"},{"term":"supports","meaning_es":"apoya"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Hablas de tu familia en una conversación, clase o actividad de presentación.","communication_goal":"Presentar a una familia de forma conectada, responder preguntas y comparar relaciones.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Presenta a la IA una familia ficticia con una foto imaginaria. La IA hará preguntas de seguimiento sobre convivencia y rutinas.","scenario":"Presenting a family photo in an English class.","ai_language":"English; respect fictional privacy-safe details","prompt":"Presenta a la IA una familia ficticia con una foto imaginaria. La IA hará preguntas de seguimiento sobre convivencia y rutinas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T02-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una presentación de 60 segundos sobre una familia ficticia y responde tres preguntas de seguimiento.","success_criteria":["presenta al menos cinco familiares","usa posesivos y pronombres de objeto","incluye una rutina familiar","responde preguntas comprensiblemente"],"prompt":"Graba una presentación de 60 segundos sobre una familia ficticia y responde tres preguntas de seguimiento.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T02-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["presentar una familia conectada","usar posesivos y pronombres correctamente","responder preguntas de seguimiento"],"retry":"Si el resultado es menor de 80%, usa primero una plantilla de cinco frases y después añade detalles y conectores."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para presentar una habitación usa This is the + habitación o There is a + habitación. Para decir dónde haces algo usa in: sleep in the bedroom, cook in the kitchen. Where is...? pregunta la ubicación. Las expresiones next to y across the hallway ayudan a conectar habitaciones.","communication_goal":"Nombrar habitaciones y decir dónde ocurren actividades cotidianas.","language_focus":{"grammar":["There is/are","This is the...","I sleep/cook/work in...","Where is...?"],"function":"rooms and locations"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I sleep in the bedroom.","word":"bedroom","meaning_es":"dormitorio"},{"english":"We cook in the kitchen.","word":"kitchen","meaning_es":"cocina"},{"english":"The bathroom is upstairs.","word":"bathroom","meaning_es":"baño"},{"english":"We watch TV in the living room.","word":"living room","meaning_es":"sala"},{"english":"We eat in the dining room.","word":"dining room","meaning_es":"comedor"},{"english":"The hallway is narrow.","word":"hallway","meaning_es":"pasillo"}],"dialogue":[{"speaker":"Host","english":"Welcome to my home. This is the living room.","spanish":"Bienvenido a mi casa. Esta es la sala."},{"speaker":"Guest","english":"Where is the kitchen?","spanish":"¿Dónde está la cocina?"},{"speaker":"Host","english":"The kitchen is next to the dining room.","spanish":"La cocina está al lado del comedor."},{"speaker":"Guest","english":"Where do you sleep?","spanish":"¿Dónde duermes?"},{"speaker":"Host","english":"I sleep in the bedroom. The bathroom is across the hallway.","spanish":"Duermo en el dormitorio. El baño está al otro lado del pasillo."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"This is the living room.","focus":"living room como bloque"},{"text":"Where is the kitchen?","focus":"where is the kitchen"},{"text":"I sleep in the bedroom.","focus":"sleep in y bedroom"}],"tip_es":"Camina mentalmente por la casa mientras pronuncias cada habitación; la memoria espacial ayuda."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Host","english":"Welcome to my home. This is the living room.","spanish":"Bienvenido a mi casa. Esta es la sala."},{"speaker":"Guest","english":"Where is the kitchen?","spanish":"¿Dónde está la cocina?"},{"speaker":"Host","english":"The kitchen is next to the dining room.","spanish":"La cocina está al lado del comedor."},{"speaker":"Guest","english":"Where do you sleep?","spanish":"¿Dónde duermes?"},{"speaker":"Host","english":"I sleep in the bedroom. The bathroom is across the hallway.","spanish":"Duermo en el dormitorio. El baño está al otro lado del pasillo."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A small apartment","text":"Lina lives in a small apartment. There is a living room, a kitchen, a bathroom and one bedroom. She cooks in the kitchen, works in the living room and sleeps in the bedroom.","glossary":[{"term":"home tour","meaning_es":"recorrido por la casa"},{"term":"apartment","meaning_es":"apartamento"},{"term":"small","meaning_es":"pequeño"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Describes tu casa o preguntas dónde está una habitación.","communication_goal":"Nombrar habitaciones y decir dónde ocurren actividades cotidianas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un visitante. Haz un recorrido por una casa ficticia y responde dónde ocurre cada actividad.","scenario":"Giving a home tour to a visitor.","ai_language":"English; use a simple floor plan as context","prompt":"La IA será un visitante. Haz un recorrido por una casa ficticia y responde dónde ocurre cada actividad.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T03-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Dibuja o imagina un plano sencillo y graba ocho frases sobre habitaciones y actividades.","success_criteria":["usa al menos cinco habitaciones","combina habitación y actividad","usa in correctamente","descripción comprensible"],"prompt":"Dibuja o imagina un plano sencillo y graba ocho frases sobre habitaciones y actividades.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T03-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["nombrar habitaciones","asociar actividades con habitaciones","usar in y where is"],"retry":"Si confundes las habitaciones, relaciona cada una con una acción concreta y vuelve a describir tu casa."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para decir que un objeto está en un lugar usa the + objeto + is/are + preposición: The book is on the table. Usa there is para un objeto singular y there are para varios. Las preguntas Where is my...? y Where are my...? cambian según el número. I can''t find... expresa que no encuentras algo.","communication_goal":"Nombrar muebles y objetos cotidianos y decir dónde están.","language_focus":{"grammar":["There is a...","There are...","The ... is on/in/under...","Where is my...?","I can''t find..."],"function":"household objects and locations"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"The book is on the table.","word":"table","meaning_es":"mesa"},{"english":"There are four chairs.","word":"chair","meaning_es":"silla"},{"english":"The keys are on the sofa.","word":"sofa","meaning_es":"sofá"},{"english":"The lamp is next to the bed.","word":"lamp","meaning_es":"lámpara"},{"english":"The mirror is in the bathroom.","word":"mirror","meaning_es":"espejo"},{"english":"I can''t find my keys.","word":"keys","meaning_es":"llaves"}],"dialogue":[{"speaker":"Nora","english":"Where are my keys? I can''t find them.","spanish":"¿Dónde están mis llaves? No las encuentro."},{"speaker":"Luis","english":"Are they on the table?","spanish":"¿Están sobre la mesa?"},{"speaker":"Nora","english":"No, they aren''t. There is a book on the table.","spanish":"No. Hay un libro sobre la mesa."},{"speaker":"Luis","english":"Are they under the sofa?","spanish":"¿Están debajo del sofá?"},{"speaker":"Nora","english":"Yes, they are! Thank you.","spanish":"¡Sí! Gracias."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Where are my keys?","focus":"where are y keys"},{"text":"I can''t find them.","focus":"can''t y them"},{"text":"They are under the sofa.","focus":"under the sofa"}],"tip_es":"Practica primero la pregunta y después responde con una ubicación completa."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Nora","english":"Where are my keys? I can''t find them.","spanish":"¿Dónde están mis llaves? No las encuentro."},{"speaker":"Luis","english":"Are they on the table?","spanish":"¿Están sobre la mesa?"},{"speaker":"Nora","english":"No, they aren''t. There is a book on the table.","spanish":"No. Hay un libro sobre la mesa."},{"speaker":"Luis","english":"Are they under the sofa?","spanish":"¿Están debajo del sofá?"},{"speaker":"Nora","english":"Yes, they are! Thank you.","spanish":"¡Sí! Gracias."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Looking for a phone","text":"Nora cannot find her phone. She looks in the living room. There is a phone on the sofa, but it is not her phone. Then she finds her phone under a book on the table.","glossary":[{"term":"look for","meaning_es":"buscar"},{"term":"phone","meaning_es":"teléfono"},{"term":"under a book","meaning_es":"debajo de un libro"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Buscas un objeto en una habitación o describes lo que hay en ella.","communication_goal":"Nombrar muebles y objetos cotidianos y decir dónde están.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será alguien que busca objetos. Da pistas usando on, in, under y next to hasta que encuentre el objeto.","scenario":"Helping someone find keys, a phone and a book.","ai_language":"English; ask for one location at a time","prompt":"La IA será alguien que busca objetos. Da pistas usando on, in, under y next to hasta que encuentre el objeto.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T03-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Describe cinco objetos de una habitación y sus ubicaciones. Después haz que otra persona adivine dónde está uno.","success_criteria":["usa there is/are","usa cuatro preposiciones","distingue singular y plural","las pistas son claras"],"prompt":"Describe cinco objetos de una habitación y sus ubicaciones. Después haz que otra persona adivine dónde está uno.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T03-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["nombrar objetos cotidianos","describir ubicaciones","distinguir is/are en there y preguntas"],"retry":"Si confundes is y are, cuenta el objeto antes de construir la frase."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para describir posición usa el objeto + is/are + preposición: The passport is behind the books. Behind = detrás, in front of = delante, between = entre dos o más elementos. Para varias cosas: The books are on the shelf. La preposición debe expresar la relación espacial real.","communication_goal":"Describir la posición de muebles y objetos usando preposiciones básicas.","language_focus":{"grammar":["on","in","under","next to","behind","in front of","between"],"function":"describing position"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"The bag is behind the chair.","word":"behind","meaning_es":"detrás de"},{"english":"The car is in front of the house.","word":"in front of","meaning_es":"delante de"},{"english":"The lamp is between the beds.","word":"between","meaning_es":"entre"},{"english":"The sofa is in the corner.","word":"corner","meaning_es":"esquina"},{"english":"The books are on the shelf.","word":"shelf","meaning_es":"estante"},{"english":"The keys are in the drawer.","word":"drawer","meaning_es":"cajón"}],"dialogue":[{"speaker":"Maya","english":"Where is my passport?","spanish":"¿Dónde está mi pasaporte?"},{"speaker":"Leo","english":"Is it in the drawer?","spanish":"¿Está en el cajón?"},{"speaker":"Maya","english":"No, it isn''t. The drawer is empty.","spanish":"No. El cajón está vacío."},{"speaker":"Leo","english":"Is it behind the books on the shelf?","spanish":"¿Está detrás de los libros del estante?"},{"speaker":"Maya","english":"Yes, it is! It is between two books.","spanish":"¡Sí! Está entre dos libros."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"The passport is behind the books.","focus":"behind the books"},{"text":"It is between two books.","focus":"between two"},{"text":"The books are on the shelf.","focus":"books are y shelf"}],"tip_es":"Usa objetos reales o una imagen para que la preposición tenga significado físico."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Maya","english":"Where is my passport?","spanish":"¿Dónde está mi pasaporte?"},{"speaker":"Leo","english":"Is it in the drawer?","spanish":"¿Está en el cajón?"},{"speaker":"Maya","english":"No, it isn''t. The drawer is empty.","spanish":"No. El cajón está vacío."},{"speaker":"Leo","english":"Is it behind the books on the shelf?","spanish":"¿Está detrás de los libros del estante?"},{"speaker":"Maya","english":"Yes, it is! It is between two books.","spanish":"¡Sí! Está entre dos libros."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"The bedroom map","text":"The bedroom has a bed, a shelf and a desk. The lamp is between the bed and the desk. The books are on the shelf. A bag is behind the chair, and the keys are in the top drawer.","glossary":[{"term":"bedroom map","meaning_es":"mapa del dormitorio"},{"term":"desk","meaning_es":"escritorio"},{"term":"top drawer","meaning_es":"cajón superior"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Explicas la distribución de una habitación o das pistas para encontrar un objeto.","communication_goal":"Describir la posición de muebles y objetos usando preposiciones básicas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será una persona que busca un objeto en una habitación. Da pistas espaciales hasta que lo encuentre.","scenario":"Describing a room to locate a lost item.","ai_language":"English; confirm each preposition with the learner","prompt":"La IA será una persona que busca un objeto en una habitación. Da pistas espaciales hasta que lo encuentre.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T03-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Dibuja una habitación con ocho objetos y descríbela oralmente usando al menos seis preposiciones.","success_criteria":["usa on, in, under, behind, between y next to","distingue singular/plural","las posiciones pueden verificarse visualmente"],"prompt":"Dibuja una habitación con ocho objetos y descríbela oralmente usando al menos seis preposiciones.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T03-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["usar seis preposiciones","describir posiciones verificables","distinguir is y are"],"retry":"Si confundes dos preposiciones, coloca físicamente dos objetos y verbaliza la relación."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una visita guiada combina existencia, identificación y ubicación. Usa This is para señalar una parte concreta, There is/are para presentar lo que hay y The ... is/are + preposición para ubicarlo. Responde preguntas del visitante y usa downstairs/upstairs para orientar por pisos.","communication_goal":"Describir una casa y responder preguntas sobre habitaciones, muebles y ubicaciones.","language_focus":{"grammar":["there is/are","this/these","prepositions of place","where is/are...?","in/on/under/behind/between"],"function":"complete home tour"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"The entrance is here.","word":"entrance","meaning_es":"entrada"},{"english":"The bedrooms are upstairs.","word":"upstairs","meaning_es":"arriba"},{"english":"The kitchen is downstairs.","word":"downstairs","meaning_es":"abajo"},{"english":"There is a balcony upstairs.","word":"balcony","meaning_es":"balcón"},{"english":"The living room is comfortable.","word":"comfortable","meaning_es":"cómodo/a"},{"english":"The guest room is small.","word":"guest","meaning_es":"invitado/visitante"}],"dialogue":[{"speaker":"Host","english":"Welcome! This is the entrance. The living room is downstairs.","spanish":"¡Bienvenido! Esta es la entrada. La sala está abajo."},{"speaker":"Guest","english":"Is there a kitchen downstairs too?","spanish":"¿También hay una cocina abajo?"},{"speaker":"Host","english":"Yes, there is. The table is next to the window.","spanish":"Sí. La mesa está al lado de la ventana."},{"speaker":"Guest","english":"Where are the bedrooms?","spanish":"¿Dónde están los dormitorios?"},{"speaker":"Host","english":"They are upstairs. The guest room is between the bathroom and the balcony.","spanish":"Están arriba. La habitación de invitados está entre el baño y el balcón."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Welcome to my home.","focus":"welcome to my home"},{"text":"The table is next to the window.","focus":"next to the window"},{"text":"The guest room is between the bathroom and the balcony.","focus":"between y palabras largas"}],"tip_es":"Una visita guiada debe sonar acogedora: usa Welcome y please cuando indiques algo al visitante."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Host","english":"Welcome! This is the entrance. The living room is downstairs.","spanish":"¡Bienvenido! Esta es la entrada. La sala está abajo."},{"speaker":"Guest","english":"Is there a kitchen downstairs too?","spanish":"¿También hay una cocina abajo?"},{"speaker":"Host","english":"Yes, there is. The table is next to the window.","spanish":"Sí. La mesa está al lado de la ventana."},{"speaker":"Guest","english":"Where are the bedrooms?","spanish":"¿Dónde están los dormitorios?"},{"speaker":"Host","english":"They are upstairs. The guest room is between the bathroom and the balcony.","spanish":"Están arriba. La habitación de invitados está entre el baño y el balcón."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A comfortable home","text":"The home has two floors. The kitchen and living room are downstairs. The bedrooms and a small balcony are upstairs. The guest room is between the bathroom and the balcony. The living room is comfortable and bright.","glossary":[{"term":"two floors","meaning_es":"dos pisos"},{"term":"bright","meaning_es":"luminoso/a"},{"term":"guest room","meaning_es":"habitación de invitados"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Recibes a un visitante y explicas cómo es tu casa y dónde encontrar objetos.","communication_goal":"Describir una casa y responder preguntas sobre habitaciones, muebles y ubicaciones.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un visitante curioso. Hazle una visita guiada, responde sus preguntas y ayuda a encontrar un objeto.","scenario":"Giving a complete home tour to a guest.","ai_language":"English; ask follow-up questions about location","prompt":"La IA será un visitante curioso. Hazle una visita guiada, responde sus preguntas y ayuda a encontrar un objeto.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T03-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una visita guiada de 75 segundos a una casa ficticia y responde tres preguntas sobre ella.","success_criteria":["incluye cinco habitaciones/objetos","usa there is/are y this/these","usa seis preposiciones o ubicaciones","responde con claridad"],"prompt":"Graba una visita guiada de 75 segundos a una casa ficticia y responde tres preguntas sobre ella.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T03-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["describir una casa completa","usar there is/are y preposiciones","responder preguntas de ubicación"],"retry":"Si el resultado es menor de 80%, usa un plano con cinco objetos y practica frases cortas antes de ampliar la visita."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para narrar una rutina usa el presente simple y conectores de orden: first, then, after that y finally. Wake up es despertarse y get up es levantarse; no son exactamente lo mismo. Have breakfast es la expresión natural para desayunar. Puedes preguntar What do you do next? para continuar la secuencia.","communication_goal":"Describir las actividades principales de un día en orden.","language_focus":{"grammar":["I wake up","I get up","I have breakfast","I go to work/school","then/after that/finally"],"function":"daily routine sequence"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I wake up at seven.","word":"wake up","meaning_es":"despertarse"},{"english":"I get up after my alarm.","word":"get up","meaning_es":"levantarse"},{"english":"I take a shower in the morning.","word":"take a shower","meaning_es":"ducharse"},{"english":"I get dressed quickly.","word":"get dressed","meaning_es":"vestirse"},{"english":"I have breakfast at home.","word":"have breakfast","meaning_es":"desayunar"},{"english":"I leave home at eight.","word":"leave home","meaning_es":"salir de casa"}],"dialogue":[{"speaker":"Maya","english":"What time do you wake up?","spanish":"¿A qué hora te despiertas?"},{"speaker":"Leo","english":"I wake up at six thirty and get up at six forty-five.","spanish":"Me despierto a las seis y media y me levanto a las seis cuarenta y cinco."},{"speaker":"Maya","english":"What do you do next?","spanish":"¿Qué haces después?"},{"speaker":"Leo","english":"I take a shower, get dressed and have breakfast.","spanish":"Me ducho, me visto y desayuno."},{"speaker":"Maya","english":"When do you leave home?","spanish":"¿Cuándo sales de casa?"},{"speaker":"Leo","english":"I leave home at eight.","spanish":"Salgo de casa a las ocho."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I wake up at six thirty.","focus":"wake up y hora"},{"text":"I take a shower and get dressed.","focus":"take a shower/get dressed"},{"text":"I leave home at eight.","focus":"leave home"}],"tip_es":"Practica la rutina con movimientos reales para unir cada verbo con su significado."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Maya","english":"What time do you wake up?","spanish":"¿A qué hora te despiertas?"},{"speaker":"Leo","english":"I wake up at six thirty and get up at six forty-five.","spanish":"Me despierto a las seis y media y me levanto a las seis cuarenta y cinco."},{"speaker":"Maya","english":"What do you do next?","spanish":"¿Qué haces después?"},{"speaker":"Leo","english":"I take a shower, get dressed and have breakfast.","spanish":"Me ducho, me visto y desayuno."},{"speaker":"Maya","english":"When do you leave home?","spanish":"¿Cuándo sales de casa?"},{"speaker":"Leo","english":"I leave home at eight.","spanish":"Salgo de casa a las ocho."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Leo''s morning","text":"Leo wakes up at six thirty. First, he gets up and takes a shower. Then he gets dressed and has breakfast. After that, he leaves home at eight and goes to work.","glossary":[{"term":"busy morning","meaning_es":"mañana ocupada"},{"term":"first","meaning_es":"primero"},{"term":"after that","meaning_es":"después de eso"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Cuentas a otra persona cómo es una mañana o un día normal.","communication_goal":"Describir las actividades principales de un día en orden.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero que pregunta por tu mañana. Describe tus pasos y responde What do you do next?.","scenario":"Comparing morning routines before work or school.","ai_language":"English; ask one sequence question at a time","prompt":"La IA será un compañero que pregunta por tu mañana. Describe tus pasos y responde What do you do next?.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T04-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una rutina de mañana de 30 segundos con seis actividades en orden.","success_criteria":["usa seis verbos de rutina","ordena las acciones","usa al menos dos conectores","pronunciación comprensible"],"prompt":"Graba una rutina de mañana de 30 segundos con seis actividades en orden.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T04-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["nombrar seis acciones","ordenar una rutina","usar presente simple y conectores"],"retry":"Si mezclas wake up y get up, practica la diferencia con una secuencia de dos acciones."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para horarios usa What time...? o When...? y responde con at + hora: I start at nine. Para un periodo usa from...to...: I work from nine to five. Las partes del día suelen usar in: in the afternoon, in the evening; pero noon y night tienen expresiones fijas: at noon, at night.","communication_goal":"Hablar de horarios y actividades habituales durante todo el día.","language_focus":{"grammar":["I start/finish at...","I work/study from... to...","at noon","in the afternoon/evening","What time...?"],"function":"daily schedules"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I start work at nine.","word":"start work","meaning_es":"empezar a trabajar"},{"english":"I finish work at five.","word":"finish work","meaning_es":"terminar de trabajar"},{"english":"We have lunch at noon.","word":"have lunch","meaning_es":"almorzar"},{"english":"I go home at six.","word":"go home","meaning_es":"ir a casa"},{"english":"She makes dinner.","word":"make dinner","meaning_es":"preparar la cena"},{"english":"I go to bed at ten.","word":"go to bed","meaning_es":"acostarse"}],"dialogue":[{"speaker":"Nora","english":"What time do you start work?","spanish":"¿A qué hora empiezas a trabajar?"},{"speaker":"Omar","english":"I start work at nine and finish at five.","spanish":"Empiezo a trabajar a las nueve y termino a las cinco."},{"speaker":"Nora","english":"When do you have lunch?","spanish":"¿Cuándo almuerzas?"},{"speaker":"Omar","english":"I have lunch at noon. Then I go home at six.","spanish":"Almuerzo al mediodía. Después voy a casa a las seis."},{"speaker":"Nora","english":"What time do you go to bed?","spanish":"¿A qué hora te acuestas?"},{"speaker":"Omar","english":"I go to bed at ten.","spanish":"Me acuesto a las diez."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I start work at nine and finish at five.","focus":"start/finish y horas"},{"text":"I have lunch at noon.","focus":"lunch at noon"},{"text":"I go to bed at ten.","focus":"go to bed"}],"tip_es":"Marca las horas con claridad; en conversaciones de horarios una cifra mal entendida cambia el plan."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Nora","english":"What time do you start work?","spanish":"¿A qué hora empiezas a trabajar?"},{"speaker":"Omar","english":"I start work at nine and finish at five.","spanish":"Empiezo a trabajar a las nueve y termino a las cinco."},{"speaker":"Nora","english":"When do you have lunch?","spanish":"¿Cuándo almuerzas?"},{"speaker":"Omar","english":"I have lunch at noon. Then I go home at six.","spanish":"Almuerzo al mediodía. Después voy a casa a las seis."},{"speaker":"Nora","english":"What time do you go to bed?","spanish":"¿A qué hora te acuestas?"},{"speaker":"Omar","english":"I go to bed at ten.","spanish":"Me acuesto a las diez."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Omar''s workday","text":"Omar starts work at nine and finishes at five. He has lunch at noon. In the afternoon, he goes home and makes dinner. He usually goes to bed at ten.","glossary":[{"term":"workday","meaning_es":"día laboral"},{"term":"noon","meaning_es":"mediodía"},{"term":"in the afternoon","meaning_es":"por la tarde"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Comparas tu horario de trabajo o estudio con el de otra persona.","communication_goal":"Hablar de horarios y actividades habituales durante todo el día.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero de trabajo. Comparen horarios y encuentren un momento libre en común.","scenario":"Comparing schedules to plan a meeting.","ai_language":"English; confirm times explicitly","prompt":"La IA será un compañero de trabajo. Comparen horarios y encuentren un momento libre en común.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T04-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Crea un horario de día laboral o de estudio con ocho actividades y horas. Grábalo como mensaje para un compañero.","success_criteria":["usa al menos seis actividades","usa at correctamente","incluye start/finish o from/to","mensaje claro"],"prompt":"Crea un horario de día laboral o de estudio con ocho actividades y horas. Grábalo como mensaje para un compañero.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T04-L02"}]}'::jsonb,6);
