insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Usa on weekdays y on weekends para hablar de periodos. Los adverbios expresan frecuencia: I usually wake up early; I sometimes go shopping. Conecta diferencias con but: I work on weekdays, but I don''t work on weekends. La pregunta What about weekends? invita a comparar.","communication_goal":"Comparar rutinas de días laborales y fines de semana usando frecuencia y conectores.","language_focus":{"grammar":["on weekdays","on weekends","usually/sometimes/never","but","because","Do you...?"],"function":"comparing routines"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I work on weekdays.","word":"weekday","meaning_es":"día entre semana"},{"english":"I relax on weekends.","word":"weekend","meaning_es":"fin de semana"},{"english":"I sleep late on Sundays.","word":"sleep late","meaning_es":"dormir hasta tarde"},{"english":"We go shopping on Saturdays.","word":"go shopping","meaning_es":"ir de compras"},{"english":"I visit friends on weekends.","word":"visit friends","meaning_es":"visitar amigos"},{"english":"She relaxes at home.","word":"relax","meaning_es":"relajarse"}],"dialogue":[{"speaker":"Mia","english":"What do you do on weekdays?","spanish":"¿Qué haces entre semana?"},{"speaker":"Leo","english":"I work and study English. I usually wake up early.","spanish":"Trabajo y estudio inglés. Normalmente me despierto temprano."},{"speaker":"Mia","english":"What about weekends?","spanish":"¿Y los fines de semana?"},{"speaker":"Leo","english":"I don''t work. I sleep late and visit friends.","spanish":"No trabajo. Duermo hasta tarde y visito amigos."},{"speaker":"Mia","english":"I usually go shopping on Saturdays, but I relax on Sundays.","spanish":"Normalmente voy de compras los sábados, pero descanso los domingos."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"What do you do on weekdays?","focus":"on weekdays"},{"text":"I usually wake up early.","focus":"usually wake up"},{"text":"I don''t work on weekends.","focus":"don''t work on weekends"}],"tip_es":"Marca el contraste con la entonación: weekdays, but weekends."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Mia","english":"What do you do on weekdays?","spanish":"¿Qué haces entre semana?"},{"speaker":"Leo","english":"I work and study English. I usually wake up early.","spanish":"Trabajo y estudio inglés. Normalmente me despierto temprano."},{"speaker":"Mia","english":"What about weekends?","spanish":"¿Y los fines de semana?"},{"speaker":"Leo","english":"I don''t work. I sleep late and visit friends.","spanish":"No trabajo. Duermo hasta tarde y visito amigos."},{"speaker":"Mia","english":"I usually go shopping on Saturdays, but I relax on Sundays.","spanish":"Normalmente voy de compras los sábados, pero descanso los domingos."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A balanced weekend","text":"Mia works on weekdays and usually wakes up early. On Saturdays, she goes shopping and visits friends. On Sundays, she never works and relaxes at home. Her weekend is different from her weekday routine.","glossary":[{"term":"balanced weekend","meaning_es":"fin de semana equilibrado"},{"term":"different from","meaning_es":"diferente de"},{"term":"wakes up early","meaning_es":"se despierta temprano"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Cuentas qué haces entre semana y cómo cambia tu rutina el sábado o domingo.","communication_goal":"Comparar rutinas de días laborales y fines de semana usando frecuencia y conectores.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un amigo comparando fines de semana. Responde preguntas y haz una pregunta sobre su rutina.","scenario":"Comparing weekday and weekend routines.","ai_language":"English; encourage a but contrast","prompt":"La IA será un amigo comparando fines de semana. Responde preguntas y haz una pregunta sobre su rutina.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T04-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una comparación de 45 segundos entre tu rutina de lunes a viernes y tu fin de semana usando cinco actividades y tres frecuencias.","success_criteria":["usa on weekdays/on weekends","incluye but","usa adverbios de frecuencia","mensaje comprensible"],"prompt":"Graba una comparación de 45 segundos entre tu rutina de lunes a viernes y tu fin de semana usando cinco actividades y tres frecuencias.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T04-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["comparar dos periodos","usar on weekdays/on weekends","conectar rutinas con but"],"retry":"Si mezclas los periodos, escribe dos columnas: weekdays y weekends, y coloca cada actividad antes de hablar."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una rutina completa organiza el día con horas, conectores y frecuencia. Empieza con una actividad, añade then/after that y termina con before bed. Responde How do you get to work? para hablar del desplazamiento y What do you do before bed? para cerrar el día. La meta es comunicar una secuencia comprensible, no recitar palabras aisladas.","communication_goal":"Describir una jornada completa, responder preguntas de rutina y conversar sobre horarios y frecuencia.","language_focus":{"grammar":["present simple routines","time expressions","frequency adverbs","do/does questions","sequence connectors"],"function":"complete daily routine conversation"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"My routine is simple.","word":"routine","meaning_es":"rutina"},{"english":"This is my typical day.","word":"typical","meaning_es":"típico/a"},{"english":"I commute by bus.","word":"commute","meaning_es":"desplazarse al trabajo"},{"english":"I take a break at noon.","word":"break","meaning_es":"descanso"},{"english":"I usually go home at six.","word":"usually","meaning_es":"normalmente"},{"english":"I read before bed.","word":"before bed","meaning_es":"antes de dormir"}],"dialogue":[{"speaker":"Coach","english":"Tell me about your typical day.","spanish":"Háblame de tu día típico."},{"speaker":"Student","english":"I wake up at seven. Then I have breakfast and go to work.","spanish":"Me despierto a las siete. Después desayuno y voy a trabajar."},{"speaker":"Coach","english":"How do you get to work?","spanish":"¿Cómo llegas al trabajo?"},{"speaker":"Student","english":"I commute by bus. I finish work at five and usually go home at six.","spanish":"Voy al trabajo en autobús. Termino a las cinco y normalmente llego a casa a las seis."},{"speaker":"Coach","english":"What do you do before bed?","spanish":"¿Qué haces antes de dormir?"},{"speaker":"Student","english":"I read for a few minutes. I never use my phone in bed.","spanish":"Leo unos minutos. Nunca uso mi teléfono en la cama."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I wake up at seven, then I have breakfast.","focus":"then y ritmo"},{"text":"I usually go home at six.","focus":"usually go home"},{"text":"I read before bed.","focus":"before bed"}],"tip_es":"Graba primero tu rutina con pausas y luego repítela intentando unir los conectores."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Coach","english":"Tell me about your typical day.","spanish":"Háblame de tu día típico."},{"speaker":"Student","english":"I wake up at seven. Then I have breakfast and go to work.","spanish":"Me despierto a las siete. Después desayuno y voy a trabajar."},{"speaker":"Coach","english":"How do you get to work?","spanish":"¿Cómo llegas al trabajo?"},{"speaker":"Student","english":"I commute by bus. I finish work at five and usually go home at six.","spanish":"Voy al trabajo en autobús. Termino a las cinco y normalmente llego a casa a las seis."},{"speaker":"Coach","english":"What do you do before bed?","spanish":"¿Qué haces antes de dormir?"},{"speaker":"Student","english":"I read for a few minutes. I never use my phone in bed.","spanish":"Leo unos minutos. Nunca uso mi teléfono en la cama."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A typical day","text":"Nora wakes up at seven and has breakfast. She goes to work by bus and takes a break at noon. She finishes work at five and usually gets home at six. Before bed, she reads for a few minutes and never checks work email.","glossary":[{"term":"typical day","meaning_es":"día típico"},{"term":"by bus","meaning_es":"en autobús"},{"term":"checks work email","meaning_es":"revisa el correo del trabajo"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Explicas tu rutina a un compañero o completas una entrevista sobre tu día.","communication_goal":"Describir una jornada completa, responder preguntas de rutina y conversar sobre horarios y frecuencia.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Completa una entrevista con la IA sobre tu rutina. Responde siete preguntas y haz dos preguntas de seguimiento.","scenario":"A friendly daily-routine interview.","ai_language":"English; adapt to work, school or home life","prompt":"Completa una entrevista con la IA sobre tu rutina. Responde siete preguntas y haz dos preguntas de seguimiento.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T04-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una presentación de 75 segundos titulada My Typical Day con horas, frecuencia, desplazamiento, comidas y actividad antes de dormir.","success_criteria":["usa ocho acciones","incluye tres horas","usa dos adverbios de frecuencia","conecta la rutina","mensaje comprensible"],"prompt":"Graba una presentación de 75 segundos titulada My Typical Day con horas, frecuencia, desplazamiento, comidas y actividad antes de dormir.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T04-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["describir una jornada completa","usar horarios y frecuencia","responder y formular preguntas de rutina"],"retry":"Si el resultado es menor de 80%, divide tu día en mañana, tarde y noche y practica cada bloque antes de unirlo."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para preferencias usa like o don''t like + sustantivo: I like fruit; I don''t like fish. Pregunta Do you like...? y responde Yes, I do o No, I don''t. Food puede hablar de comida en general; para una preferencia concreta usa My favorite food is.... No necesitas traducir literalmente los artículos del español.","communication_goal":"Nombrar alimentos y bebidas y decir qué te gusta o no te gusta.","language_focus":{"grammar":["I like...","I don''t like...","My favorite food is...","Do you like...?","Yes, I do/No, I don''t"],"function":"food preferences"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I eat fruit for breakfast.","word":"breakfast","meaning_es":"desayuno"},{"english":"I have lunch at noon.","word":"lunch","meaning_es":"almuerzo"},{"english":"We cook dinner at home.","word":"dinner","meaning_es":"cena"},{"english":"I like fruit.","word":"fruit","meaning_es":"fruta"},{"english":"She eats vegetables.","word":"vegetables","meaning_es":"verduras"},{"english":"Do you like coffee?","word":"coffee","meaning_es":"café"}],"dialogue":[{"speaker":"Ana","english":"What do you like for dinner?","spanish":"¿Qué te gusta para la cena?"},{"speaker":"Luis","english":"I like rice and vegetables. I don''t like fish.","spanish":"Me gustan el arroz y las verduras. No me gusta el pescado."},{"speaker":"Ana","english":"Do you like spicy food?","spanish":"¿Te gusta la comida picante?"},{"speaker":"Luis","english":"Yes, I do. My favorite food is Mexican food.","spanish":"Sí. Mi comida favorita es la mexicana."},{"speaker":"Ana","english":"I like it too, but I don''t eat meat.","spanish":"A mí también me gusta, pero no como carne."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I like rice and vegetables.","focus":"like rice and"},{"text":"I don''t like fish.","focus":"don''t like"},{"text":"Do you like spicy food?","focus":"do you like"}],"tip_es":"Pronuncia la preferencia completa y no solo la palabra del alimento; el contexto ayuda a recordar."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Ana","english":"What do you like for dinner?","spanish":"¿Qué te gusta para la cena?"},{"speaker":"Luis","english":"I like rice and vegetables. I don''t like fish.","spanish":"Me gustan el arroz y las verduras. No me gusta el pescado."},{"speaker":"Ana","english":"Do you like spicy food?","spanish":"¿Te gusta la comida picante?"},{"speaker":"Luis","english":"Yes, I do. My favorite food is Mexican food.","spanish":"Sí. Mi comida favorita es la mexicana."},{"speaker":"Ana","english":"I like it too, but I don''t eat meat.","spanish":"A mí también me gusta, pero no como carne."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A simple food survey","text":"Luis likes rice, vegetables and spicy food. He does not like fish, and he does not eat meat. Ana likes Mexican food too. She eats fruit for breakfast and drinks coffee in the morning.","glossary":[{"term":"food survey","meaning_es":"encuesta de comida"},{"term":"spicy","meaning_es":"picante"},{"term":"meat","meaning_es":"carne"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Hablas de tus preferencias antes de una comida o haces una lista sencilla.","communication_goal":"Nombrar alimentos y bebidas y decir qué te gusta o no te gusta.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será tu compañero planeando una comida. Pregunta y responde sobre alimentos, bebidas y preferencias.","scenario":"Finding food preferences before cooking dinner.","ai_language":"English; use fictional preferences if desired","prompt":"La IA será tu compañero planeando una comida. Pregunta y responde sobre alimentos, bebidas y preferencias.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T05-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una encuesta de preferencias con cinco alimentos y tres bebidas. Responde Yes, I do o No, I don''t y añade una preferencia favorita.","success_criteria":["usa Do you like...?","responde con do/don''t","nombra al menos ocho alimentos/bebidas","mensaje claro"],"prompt":"Graba una encuesta de preferencias con cinco alimentos y tres bebidas. Responde Yes, I do o No, I don''t y añade una preferencia favorita.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T05-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["nombrar alimentos básicos","expresar gustos y disgustos","preguntar por preferencias"],"retry":"Si confundes don''t y doesn''t, identifica el sujeto de la frase antes de responder."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para comprar con cortesía usa I''d like + producto y Can I have + producto?. Para precio, How much is...? con singular o How much are...? con plural. Para cantidades contables usa How many...? y para unidades o sustancias, How much...? Añade please y thank you para una interacción natural.","communication_goal":"Pedir alimentos, cantidades y precios en una tienda.","language_focus":{"grammar":["I''d like...","Can I have...?","How much is/are...?","How many...?","Here you are/Thank you"],"function":"buying food politely"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I''d like a kilo of apples.","word":"I''d like","meaning_es":"quisiera"},{"english":"Are these vegetables fresh?","word":"fresh","meaning_es":"fresco/a"},{"english":"What''s the price?","word":"price","meaning_es":"precio"},{"english":"A kilo, please.","word":"kilo","meaning_es":"kilo"},{"english":"Can I have a receipt?","word":"receipt","meaning_es":"recibo"},{"english":"Here is your change.","word":"change","meaning_es":"cambio"}],"dialogue":[{"speaker":"Customer","english":"Hello. I''d like a kilo of apples, please.","spanish":"Hola. Quisiera un kilo de manzanas, por favor."},{"speaker":"Seller","english":"Sure. Anything else?","spanish":"Claro. ¿Algo más?"},{"speaker":"Customer","english":"Yes. Can I have two bottles of water?","spanish":"Sí. ¿Puedo tener dos botellas de agua?"},{"speaker":"Seller","english":"Of course. How many oranges do you want?","spanish":"Claro. ¿Cuántas naranjas quieres?"},{"speaker":"Customer","english":"Six oranges. How much are the apples?","spanish":"Seis naranjas. ¿Cuánto cuestan las manzanas?"},{"speaker":"Seller","english":"They are four dollars.","spanish":"Cuestan cuatro dólares."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I''d like a kilo of apples, please.","focus":"I''d like y kilo of"},{"text":"Can I have two bottles of water?","focus":"can I have"},{"text":"How much are the apples?","focus":"much are"}],"tip_es":"En una tienda, practica la petición completa con una voz amable y una pausa antes de la cantidad."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Customer","english":"Hello. I''d like a kilo of apples, please.","spanish":"Hola. Quisiera un kilo de manzanas, por favor."},{"speaker":"Seller","english":"Sure. Anything else?","spanish":"Claro. ¿Algo más?"},{"speaker":"Customer","english":"Yes. Can I have two bottles of water?","spanish":"Sí. ¿Puedo tener dos botellas de agua?"},{"speaker":"Seller","english":"Of course. How many oranges do you want?","spanish":"Claro. ¿Cuántas naranjas quieres?"},{"speaker":"Customer","english":"Six oranges. How much are the apples?","spanish":"Seis naranjas. ¿Cuánto cuestan las manzanas?"},{"speaker":"Seller","english":"They are four dollars.","spanish":"Cuestan cuatro dólares."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A market order","text":"At the market, Rosa buys a kilo of apples, six oranges and two bottles of water. She asks the seller how much the apples are. She pays four dollars and asks for a receipt.","glossary":[{"term":"market order","meaning_es":"pedido del mercado"},{"term":"pays","meaning_es":"paga"},{"term":"receipt","meaning_es":"recibo"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Haces compras para una comida y conversas con el vendedor.","communication_goal":"Pedir alimentos, cantidades y precios en una tienda.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un vendedor de mercado. Compra cinco productos con cantidades, pregunta precios y pide un recibo.","scenario":"Shopping at a friendly local market.","ai_language":"English; include realistic seller follow-up questions","prompt":"La IA será un vendedor de mercado. Compra cinco productos con cantidades, pregunta precios y pide un recibo.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T05-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un diálogo de ocho turnos en una tienda comprando una comida completa.","success_criteria":["usa I''d like y Can I have","incluye cantidad y precio","usa please/thank you","interacción comprensible"],"prompt":"Graba un diálogo de ocho turnos en una tienda comprando una comida completa.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T05-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["hacer pedidos corteses","preguntar precios","usar cantidades en una compra"],"retry":"Si usas I want en todas las frases, practica cinco pedidos con I''d like y please."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"En un restaurante puedes decir I''d like the chicken, please o Can I have some water, please?. El camarero puede preguntar Would you like...? para ofrecer algo. Para terminar el pedido usa That''s all, thank you. Para pedir la cuenta, Can we have the bill, please?.","communication_goal":"Leer un menú, pedir comida y bebida y responder preguntas sencillas del camarero.","language_focus":{"grammar":["I''d like...","Can I have...?","For me...","Anything else?","That''s all, thank you","Would you like...?"],"function":"ordering at a restaurant"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Can I see the menu?","word":"menu","meaning_es":"menú"},{"english":"Are you ready to order?","word":"order","meaning_es":"pedido/pedir"},{"english":"The chicken is the main course.","word":"main course","meaning_es":"plato principal"},{"english":"I''d like rice as a side.","word":"side","meaning_es":"acompañamiento"},{"english":"Would you like dessert?","word":"dessert","meaning_es":"postre"},{"english":"Can we have the bill?","word":"bill","meaning_es":"cuenta"}],"dialogue":[{"speaker":"Server","english":"Are you ready to order?","spanish":"¿Están listos para pedir?"},{"speaker":"Customer","english":"Yes. I''d like the chicken with rice, please.","spanish":"Sí. Quisiera el pollo con arroz, por favor."},{"speaker":"Server","english":"Would you like a drink?","spanish":"¿Quieres una bebida?"},{"speaker":"Customer","english":"Can I have some water, please?","spanish":"¿Puedo tomar agua, por favor?"},{"speaker":"Server","english":"Anything else?","spanish":"¿Algo más?"},{"speaker":"Customer","english":"That''s all, thank you. Can we have the bill later?","spanish":"Eso es todo, gracias. ¿Podemos pedir la cuenta después?"}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I''d like the chicken with rice, please.","focus":"I''d like y chicken with rice"},{"text":"Can I have some water, please?","focus":"can I have y please"},{"text":"That''s all, thank you.","focus":"that''s all"}],"tip_es":"Usa una entonación amable y una pausa breve al terminar cada pedido."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Server","english":"Are you ready to order?","spanish":"¿Están listos para pedir?"},{"speaker":"Customer","english":"Yes. I''d like the chicken with rice, please.","spanish":"Sí. Quisiera el pollo con arroz, por favor."},{"speaker":"Server","english":"Would you like a drink?","spanish":"¿Quieres una bebida?"},{"speaker":"Customer","english":"Can I have some water, please?","spanish":"¿Puedo tomar agua, por favor?"},{"speaker":"Server","english":"Anything else?","spanish":"¿Algo más?"},{"speaker":"Customer","english":"That''s all, thank you. Can we have the bill later?","spanish":"Eso es todo, gracias. ¿Podemos pedir la cuenta después?"}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A cafe menu","text":"The cafe menu has chicken with rice, vegetable soup and a cheese sandwich. Customers can order water, juice or coffee. After dinner, they can have fruit or cake. The bill is five dollars for each person.","glossary":[{"term":"vegetable soup","meaning_es":"sopa de verduras"},{"term":"cheese sandwich","meaning_es":"sándwich de queso"},{"term":"each person","meaning_es":"cada persona"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Comes en un restaurante y haces un pedido con cortesía.","communication_goal":"Leer un menú, pedir comida y bebida y responder preguntas sencillas del camarero.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será camarero. Lee un menú ficticio, pide un plato, bebida y postre, y responde Would you like...?.","scenario":"Ordering a complete meal at a cafe.","ai_language":"English; make the menu accessible and realistic","prompt":"La IA será camarero. Lee un menú ficticio, pide un plato, bebida y postre, y responde Would you like...?.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T05-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un diálogo de ocho turnos en un restaurante: pedir menú, plato, bebida, postre y cuenta.","success_criteria":["usa I''d like y Can I have","usa please/thank you","responde Anything else?","pedido comprensible"],"prompt":"Graba un diálogo de ocho turnos en un restaurante: pedir menú, plato, bebida, postre y cuenta.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T05-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["pedir una comida","responder ofertas","terminar y solicitar la cuenta"],"retry":"Si traduces literalmente el pedido, practica tres veces el bloque I''d like..., please."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una situación de comida combina preferencias, cantidades y peticiones. Explica una preferencia con but o because: I like vegetables, but I don''t eat meat. Pregunta How many con ingredientes contables y How much con sustancias. En un restaurante usa I''d like y Can I have; si hay una alergia, comunícala claramente antes de pedir.","communication_goal":"Hablar de preferencias, comprar ingredientes y pedir una comida en una conversación integrada.","language_focus":{"grammar":["like/don''t like","I''d like/Can I have","How much/How many","some/any","because/but"],"function":"integrated food communication"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I am vegetarian.","word":"vegetarian","meaning_es":"vegetariano/a"},{"english":"I have a food allergy.","word":"allergy","meaning_es":"alergia"},{"english":"We want a healthy meal.","word":"healthy","meaning_es":"saludable"},{"english":"What ingredients do we need?","word":"ingredient","meaning_es":"ingrediente"},{"english":"This recipe is easy.","word":"recipe","meaning_es":"receta"},{"english":"Can we share a dessert?","word":"share","meaning_es":"compartir"}],"dialogue":[{"speaker":"Marta","english":"What should we cook for dinner?","spanish":"¿Qué deberíamos cocinar para la cena?"},{"speaker":"Nico","english":"I like vegetables, but I don''t eat meat.","spanish":"Me gustan las verduras, pero no como carne."},{"speaker":"Marta","english":"Okay. How many vegetables do we need?","spanish":"Bien. ¿Cuántas verduras necesitamos?"},{"speaker":"Nico","english":"We need three tomatoes and two onions. I''d also like some rice.","spanish":"Necesitamos tres tomates y dos cebollas. También quisiera arroz."},{"speaker":"Marta","english":"Good. Can we share a fruit dessert?","spanish":"Bien. ¿Podemos compartir un postre de fruta?"},{"speaker":"Nico","english":"Yes, please. That sounds healthy.","spanish":"Sí, por favor. Suena saludable."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I like vegetables, but I don''t eat meat.","focus":"contraste like/don''t eat"},{"text":"We need three tomatoes and two onions.","focus":"números y plurales"},{"text":"I''d also like some rice.","focus":"I''d also like"}],"tip_es":"Practica primero las preferencias y después añade las cantidades como si estuvieras resolviendo un plan real."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Marta","english":"What should we cook for dinner?","spanish":"¿Qué deberíamos cocinar para la cena?"},{"speaker":"Nico","english":"I like vegetables, but I don''t eat meat.","spanish":"Me gustan las verduras, pero no como carne."},{"speaker":"Marta","english":"Okay. How many vegetables do we need?","spanish":"Bien. ¿Cuántas verduras necesitamos?"},{"speaker":"Nico","english":"We need three tomatoes and two onions. I''d also like some rice.","spanish":"Necesitamos tres tomates y dos cebollas. También quisiera arroz."},{"speaker":"Marta","english":"Good. Can we share a fruit dessert?","spanish":"Bien. ¿Podemos compartir un postre de fruta?"},{"speaker":"Nico","english":"Yes, please. That sounds healthy.","spanish":"Sí, por favor. Suena saludable."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A healthy dinner","text":"Marta and Nico plan a healthy dinner. Nico is vegetarian, so they choose vegetables and rice. They need three tomatoes, two onions and some rice. They also share a fruit dessert because it is light and fresh.","glossary":[{"term":"healthy dinner","meaning_es":"cena saludable"},{"term":"vegetarian","meaning_es":"vegetariano/a"},{"term":"light","meaning_es":"ligero/a"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Organizas una comida con otra persona teniendo en cuenta gustos y cantidades.","communication_goal":"Hablar de preferencias, comprar ingredientes y pedir una comida en una conversación integrada.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Planifica con la IA una cena completa: preferencias, alergias ficticias, ingredientes, cantidades y pedido final.","scenario":"Planning dinner safely with a friend and ordering at a restaurant.","ai_language":"English; treat allergy information seriously and clearly","prompt":"Planifica con la IA una cena completa: preferencias, alergias ficticias, ingredientes, cantidades y pedido final.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T05-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un diálogo de 90 segundos entre dos amigos que planifican una comida, compran ingredientes y hacen un pedido.","success_criteria":["expresa gustos y disgustos","usa how much/how many","usa some/any o unidades","incluye una petición cortés","conecta ideas"],"prompt":"Graba un diálogo de 90 segundos entre dos amigos que planifican una comida, compran ingredientes y hacen un pedido.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T05-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["hablar de preferencias y restricciones","usar cantidades y peticiones","resolver una comida completa en conversación"],"retry":"Si el resultado es menor de 80%, practica primero una lista de compras y luego conviértela en un pedido de restaurante."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para preguntar la hora usa What time is it? y responde It''s + hora. O''clock significa ''en punto''; half past = y media; a quarter past = y cuarto; a quarter to = menos cuarto. Para citas usa at + hora: meet at four o''clock. En conversaciones internacionales también es común decir three thirty o four fifteen.","communication_goal":"Preguntar y decir la hora en situaciones cotidianas.","language_focus":{"grammar":["What time is it?","It''s...","at + time","o''clock","half past","quarter past/to"],"function":"telling time"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"It is three o''clock.","word":"o''clock","meaning_es":"en punto"},{"english":"It is half past six.","word":"half past","meaning_es":"y media"},{"english":"It is a quarter past two.","word":"quarter past","meaning_es":"y cuarto"},{"english":"It is a quarter to five.","word":"quarter to","meaning_es":"menos cuarto"},{"english":"The class is in the morning.","word":"morning","meaning_es":"mañana"},{"english":"The meeting is in the evening.","word":"evening","meaning_es":"tarde/noche"}],"dialogue":[{"speaker":"Nora","english":"What time is it?","spanish":"¿Qué hora es?"},{"speaker":"Luis","english":"It''s half past three.","spanish":"Son las tres y media."},{"speaker":"Nora","english":"What time does the class finish?","spanish":"¿A qué hora termina la clase?"},{"speaker":"Luis","english":"It finishes at four o''clock.","spanish":"Termina a las cuatro en punto."},{"speaker":"Nora","english":"Can we meet at a quarter past four?","spanish":"¿Podemos encontrarnos a las cuatro y cuarto?"},{"speaker":"Luis","english":"Yes, see you then.","spanish":"Sí, nos vemos entonces."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"What time is it?","focus":"what time is it"},{"text":"It''s half past three.","focus":"half past"},{"text":"Let''s meet at four o''clock.","focus":"meet at y o''clock"}],"tip_es":"Di primero la hora digital y luego practica la forma con half o quarter."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Nora","english":"What time is it?","spanish":"¿Qué hora es?"},{"speaker":"Luis","english":"It''s half past three.","spanish":"Son las tres y media."},{"speaker":"Nora","english":"What time does the class finish?","spanish":"¿A qué hora termina la clase?"},{"speaker":"Luis","english":"It finishes at four o''clock.","spanish":"Termina a las cuatro en punto."},{"speaker":"Nora","english":"Can we meet at a quarter past four?","spanish":"¿Podemos encontrarnos a las cuatro y cuarto?"},{"speaker":"Luis","english":"Yes, see you then.","spanish":"Sí, nos vemos entonces."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A busy afternoon","text":"The English class finishes at four o''clock. Nora and Luis meet at a quarter past four. They study for half an hour, and then Nora goes home at five thirty.","glossary":[{"term":"busy afternoon","meaning_es":"tarde ocupada"},{"term":"for half an hour","meaning_es":"durante media hora"},{"term":"then","meaning_es":"entonces/después"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Coordinas una cita, llegas a una clase o preguntas cuándo empieza algo.","communication_goal":"Preguntar y decir la hora en situaciones cotidianas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero coordinando una cita. Pregunta y responde horas y confirma el momento.","scenario":"Arranging a meeting after class.","ai_language":"English; confirm each time in a second format","prompt":"La IA será un compañero coordinando una cita. Pregunta y responde horas y confirma el momento.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T06-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un mensaje con tres citas o actividades y sus horas. Incluye una pregunta What time...? y una confirmación.","success_criteria":["usa at con horas","pronuncia tres momentos","incluye una confirmación","mensaje claro"],"prompt":"Graba un mensaje con tres citas o actividades y sus horas. Incluye una pregunta What time...? y una confirmación.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T06-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["preguntar la hora","decir horas básicas y con quarter/half","coordinar una cita"],"retry":"Si confundes past y to, mira si los minutos están después de la hora o cerca de la siguiente."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Usa on con días y fechas: on Monday, on July twenty-first. Usa in con meses y años: in July, in 2026. Pregunta What day is it? por el día de la semana y What date is it? por la fecha. Las fechas usan números ordinales al hablar: first, second, third, twenty-first.","communication_goal":"Decir fechas, días de la semana y meses para hablar de eventos y citas.","language_focus":{"grammar":["What day is it?","What date is it?","on Monday","in July","My birthday is on...","ordinal dates"],"function":"dates and calendar events"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"The class is on Monday.","word":"Monday","meaning_es":"lunes"},{"english":"We meet on Friday.","word":"Friday","meaning_es":"viernes"},{"english":"My birthday is in January.","word":"January","meaning_es":"enero"},{"english":"The trip is in July.","word":"July","meaning_es":"julio"},{"english":"When is your birthday?","word":"birthday","meaning_es":"cumpleaños"},{"english":"I have an appointment on Tuesday.","word":"appointment","meaning_es":"cita"}],"dialogue":[{"speaker":"Mia","english":"What day is the English class?","spanish":"¿Qué día es la clase de inglés?"},{"speaker":"Leo","english":"It is on Monday and Wednesday.","spanish":"Es el lunes y miércoles."},{"speaker":"Mia","english":"When is your birthday?","spanish":"¿Cuándo es tu cumpleaños?"},{"speaker":"Leo","english":"It is on July twenty-first.","spanish":"Es el veintiuno de julio."},{"speaker":"Mia","english":"Do you have an appointment this week?","spanish":"¿Tienes una cita esta semana?"},{"speaker":"Leo","english":"Yes, I have one on Friday.","spanish":"Sí, tengo una el viernes."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"The class is on Monday.","focus":"on Monday"},{"text":"My birthday is in July.","focus":"birthday y in July"},{"text":"July twenty-first","focus":"ordinal twenty-first"}],"tip_es":"Practica primero días y meses por separado y después combínalos en fechas."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Mia","english":"What day is the English class?","spanish":"¿Qué día es la clase de inglés?"},{"speaker":"Leo","english":"It is on Monday and Wednesday.","spanish":"Es el lunes y miércoles."},{"speaker":"Mia","english":"When is your birthday?","spanish":"¿Cuándo es tu cumpleaños?"},{"speaker":"Leo","english":"It is on July twenty-first.","spanish":"Es el veintiuno de julio."},{"speaker":"Mia","english":"Do you have an appointment this week?","spanish":"¿Tienes una cita esta semana?"},{"speaker":"Leo","english":"Yes, I have one on Friday.","spanish":"Sí, tengo una el viernes."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A busy calendar","text":"Mia has English class on Monday and Wednesday. Her birthday is on July twenty-first. She has a doctor''s appointment on Friday. The family trip is in August.","glossary":[{"term":"calendar","meaning_es":"calendario"},{"term":"doctor''s appointment","meaning_es":"cita médica"},{"term":"family trip","meaning_es":"viaje familiar"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Indicas cuándo es una clase, cumpleaños, viaje o reunión.","communication_goal":"Decir fechas, días de la semana y meses para hablar de eventos y citas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será una persona organizando un calendario. Pregunta por días, fechas, meses y citas.","scenario":"Planning classes, appointments and a family trip.","ai_language":"English; repeat dates in a clear alternative format","prompt":"La IA será una persona organizando un calendario. Pregunta por días, fechas, meses y citas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T06-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Crea un calendario ficticio con cinco eventos y graba una explicación usando días, meses y dos fechas ordinales.","success_criteria":["usa on con días/fechas","usa in con meses","pronuncia dos ordinales","eventos coherentes"],"prompt":"Crea un calendario ficticio con cinco eventos y graba una explicación usando días, meses y dos fechas ordinales.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T06-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["decir días y meses","usar on/in correctamente","indicar una fecha o evento"],"retry":"Si confundes on e in, decide si hablas de un día/fecha exacta o de un mes/año."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para proponer una cita usa Are you free on...? o How about Friday at three? Para confirmar puedes decir That works for me o Let''s confirm. Usa on con el día y at con la hora. Si no puedes, responde I''m sorry, I can''t y ofrece otra opción.","communication_goal":"Proponer, confirmar y cambiar una cita usando días y horas.","language_focus":{"grammar":["Are you free on...?","Can we meet at...?","How about...?","That works for me","I''m sorry, I can''t","Let''s confirm"],"function":"arranging appointments"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Are you free on Friday?","word":"free","meaning_es":"libre/disponible"},{"english":"I am available at three.","word":"available","meaning_es":"disponible"},{"english":"I have an appointment.","word":"appointment","meaning_es":"cita"},{"english":"My schedule is busy.","word":"schedule","meaning_es":"horario"},{"english":"Let''s confirm the time.","word":"confirm","meaning_es":"confirmar"},{"english":"Three o''clock works for me.","word":"works for me","meaning_es":"me funciona"}],"dialogue":[{"speaker":"Maya","english":"Are you free on Thursday?","spanish":"¿Estás libre el jueves?"},{"speaker":"Leo","english":"I''m sorry, I can''t. I have an appointment.","spanish":"Lo siento, no puedo. Tengo una cita."},{"speaker":"Maya","english":"How about Friday at three?","spanish":"¿Qué tal el viernes a las tres?"},{"speaker":"Leo","english":"Yes, that works for me.","spanish":"Sí, me funciona."},{"speaker":"Maya","english":"Great. Let''s confirm: Friday at three.","spanish":"Perfecto. Confirmemos: viernes a las tres."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Are you free on Thursday?","focus":"free on Thursday"},{"text":"How about Friday at three?","focus":"how about y at three"},{"text":"That works for me.","focus":"works for me"}],"tip_es":"La entonación de una propuesta debe sonar abierta, y la confirmación debe sonar segura."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Maya","english":"Are you free on Thursday?","spanish":"¿Estás libre el jueves?"},{"speaker":"Leo","english":"I''m sorry, I can''t. I have an appointment.","spanish":"Lo siento, no puedo. Tengo una cita."},{"speaker":"Maya","english":"How about Friday at three?","spanish":"¿Qué tal el viernes a las tres?"},{"speaker":"Leo","english":"Yes, that works for me.","spanish":"Sí, me funciona."},{"speaker":"Maya","english":"Great. Let''s confirm: Friday at three.","spanish":"Perfecto. Confirmemos: viernes a las tres."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A rescheduled meeting","text":"Maya and Leo want to meet on Thursday, but Leo has an appointment. Maya suggests Friday at three. Leo says that time works for him, so they confirm the meeting.","glossary":[{"term":"rescheduled","meaning_es":"reprogramado"},{"term":"suggests","meaning_es":"sugiere"},{"term":"works for him","meaning_es":"le funciona"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Coordinas una reunión o clase y necesitas confirmar el momento correcto.","communication_goal":"Proponer, confirmar y cambiar una cita usando días y horas.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero con un horario ocupado. Propón una cita, responde a cambios y confirma un momento final.","scenario":"Scheduling a meeting with a busy classmate.","ai_language":"English; offer realistic alternatives","prompt":"La IA será un compañero con un horario ocupado. Propón una cita, responde a cambios y confirma un momento final.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T06-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un mensaje proponiendo dos horarios, rechazando uno con cortesía y confirmando el otro.","success_criteria":["usa on con días","usa at con horas","incluye una alternativa","confirma claramente"],"prompt":"Graba un mensaje proponiendo dos horarios, rechazando uno con cortesía y confirmando el otro.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T06-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["proponer una cita","aceptar o rechazar con cortesía","confirmar día y hora"],"retry":"Si mezclas las preposiciones, repite el bloque on + día y at + hora."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Un calendario combina periodo, día, fecha y hora: in December, on Tuesday, on December twenty-fifth, at two. Usa from...to... para bloques de tiempo y Are you available...? para coordinar. Antes de confirmar repite la información completa: Tuesday at two.","communication_goal":"Describir un calendario semanal y coordinar eventos usando fechas, horarios y disponibilidad.","language_focus":{"grammar":["days and months","on/in/at","What day/date/time...?","Are you free...?","from...to...","confirmation"],"function":"complete calendar communication"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Check my calendar.","word":"calendar","meaning_es":"calendario"},{"english":"I have class on Tuesday.","word":"class","meaning_es":"clase"},{"english":"The meeting is at ten.","word":"meeting","meaning_es":"reunión"},{"english":"The holiday is in December.","word":"holiday","meaning_es":"feriado/vacaciones"},{"english":"I am available on Saturday.","word":"available","meaning_es":"disponible"},{"english":"I am busy in the morning.","word":"busy","meaning_es":"ocupado"}],"dialogue":[{"speaker":"Ana","english":"Are you available on Tuesday morning?","spanish":"¿Estás disponible el martes por la mañana?"},{"speaker":"Ben","english":"No, I''m busy from nine to twelve. I''m free at two.","spanish":"No, estoy ocupado de nueve a doce. Estoy libre a las dos."},{"speaker":"Ana","english":"Can we have a meeting on Tuesday at two?","spanish":"¿Podemos tener una reunión el martes a las dos?"},{"speaker":"Ben","english":"Yes, that works for me. What date is the holiday?","spanish":"Sí, me funciona. ¿Qué fecha es el feriado?"},{"speaker":"Ana","english":"It is on December twenty-fifth.","spanish":"Es el veinticinco de diciembre."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I am busy from nine to twelve.","focus":"from nine to twelve"},{"text":"Can we meet on Tuesday at two?","focus":"on Tuesday at two"},{"text":"December twenty-fifth","focus":"ordinal twenty-fifth"}],"tip_es":"Al confirmar un evento, acentúa el día y la hora, y habla más despacio con fechas largas."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Ana","english":"Are you available on Tuesday morning?","spanish":"¿Estás disponible el martes por la mañana?"},{"speaker":"Ben","english":"No, I''m busy from nine to twelve. I''m free at two.","spanish":"No, estoy ocupado de nueve a doce. Estoy libre a las dos."},{"speaker":"Ana","english":"Can we have a meeting on Tuesday at two?","spanish":"¿Podemos tener una reunión el martes a las dos?"},{"speaker":"Ben","english":"Yes, that works for me. What date is the holiday?","spanish":"Sí, me funciona. ¿Qué fecha es el feriado?"},{"speaker":"Ana","english":"It is on December twenty-fifth.","spanish":"Es el veinticinco de diciembre."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Ben''s weekly calendar","text":"Ben is busy from nine to twelve on Tuesday, but he is available at two. He has a meeting then. On Thursday, he has English class from six to eight. The holiday is on December twenty-fifth.","glossary":[{"term":"weekly calendar","meaning_es":"calendario semanal"},{"term":"available","meaning_es":"disponible"},{"term":"then","meaning_es":"en ese momento"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Organizas una semana con clases, trabajo, citas y actividades personales.","communication_goal":"Describir un calendario semanal y coordinar eventos usando fechas, horarios y disponibilidad.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Coordina con la IA una semana completa. Consulta disponibilidad, propón eventos y confirma al menos dos citas.","scenario":"Building a shared weekly calendar.","ai_language":"English; repeat final arrangements clearly","prompt":"Coordina con la IA una semana completa. Consulta disponibilidad, propón eventos y confirma al menos dos citas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T06-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Crea un calendario ficticio con seis eventos y graba una explicación de 75 segundos, incluyendo un cambio de horario.","success_criteria":["usa on/in/at correctamente","incluye from/to","confirma dos eventos","pronuncia una fecha ordinal"],"prompt":"Crea un calendario ficticio con seis eventos y graba una explicación de 75 segundos, incluyendo un cambio de horario.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T06-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["hablar de días, fechas y horas","coordinar disponibilidad","confirmar eventos sin ambigüedad"],"retry":"Si el resultado es menor de 80%, practica cada evento con la fórmula día + hora + actividad y después añade fechas."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para preguntar por la existencia de un lugar usa Is there a...? o Are there any...? Para ubicarlo usa The bank is near the station. Las expresiones near, next to y across from describen relaciones entre lugares. Downtown significa en el centro de la ciudad.","communication_goal":"Nombrar lugares comunes de una ciudad y decir dónde están.","language_focus":{"grammar":["There is/are","The ... is near/next to...","Where is...?","I go to the..."],"function":"city places and locations"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"The bank is near the station.","word":"bank","meaning_es":"banco"},{"english":"I go to the supermarket.","word":"supermarket","meaning_es":"supermercado"},{"english":"The pharmacy is next to the bank.","word":"pharmacy","meaning_es":"farmacia"},{"english":"The hospital is on Main Street.","word":"hospital","meaning_es":"hospital"},{"english":"There is a library downtown.","word":"library","meaning_es":"biblioteca"},{"english":"We walk in the park.","word":"park","meaning_es":"parque"}],"dialogue":[{"speaker":"Visitor","english":"Is there a supermarket near here?","spanish":"¿Hay un supermercado cerca de aquí?"},{"speaker":"Resident","english":"Yes, there is. The supermarket is next to the pharmacy.","spanish":"Sí. El supermercado está al lado de la farmacia."},{"speaker":"Visitor","english":"Where is the bank?","spanish":"¿Dónde está el banco?"},{"speaker":"Resident","english":"It is across from the park, on Main Street.","spanish":"Está enfrente del parque, en la calle Main."},{"speaker":"Visitor","english":"Is there a library too?","spanish":"¿También hay una biblioteca?"},{"speaker":"Resident","english":"Yes, there is a library downtown.","spanish":"Sí, hay una biblioteca en el centro."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Is there a supermarket near here?","focus":"is there y near here"},{"text":"The pharmacy is next to the bank.","focus":"pharmacy y next to"},{"text":"It is across from the park.","focus":"across from"}],"tip_es":"Al pedir una dirección, empieza con Excuse me para llamar la atención de forma cortés."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Visitor","english":"Is there a supermarket near here?","spanish":"¿Hay un supermercado cerca de aquí?"},{"speaker":"Resident","english":"Yes, there is. The supermarket is next to the pharmacy.","spanish":"Sí. El supermercado está al lado de la farmacia."},{"speaker":"Visitor","english":"Where is the bank?","spanish":"¿Dónde está el banco?"},{"speaker":"Resident","english":"It is across from the park, on Main Street.","spanish":"Está enfrente del parque, en la calle Main."},{"speaker":"Visitor","english":"Is there a library too?","spanish":"¿También hay una biblioteca?"},{"speaker":"Resident","english":"Yes, there is a library downtown.","spanish":"Sí, hay una biblioteca en el centro."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A useful neighborhood","text":"There is a supermarket next to a pharmacy. The bank is across from a park on Main Street. There is also a library downtown. The hospital is near the park.","glossary":[{"term":"neighborhood","meaning_es":"barrio"},{"term":"across from","meaning_es":"enfrente de"},{"term":"downtown","meaning_es":"centro de la ciudad"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Preguntas por un servicio o describes un lugar cerca de tu casa.","communication_goal":"Nombrar lugares comunes de una ciudad y decir dónde están.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un visitante nuevo. Explica dónde están cuatro lugares de un barrio ficticio.","scenario":"Describing useful places in a neighborhood.","ai_language":"English; ask follow-up questions about nearby places","prompt":"La IA será un visitante nuevo. Explica dónde están cuatro lugares de un barrio ficticio.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T07-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Crea un mapa sencillo con seis lugares y graba ocho frases sobre sus ubicaciones.","success_criteria":["usa seis lugares","usa near/next to/across from","incluye there is/are","descripción verificable"],"prompt":"Crea un mapa sencillo con seis lugares y graba ocho frases sobre sus ubicaciones.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T07-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["nombrar lugares de la ciudad","usar there is y where is","describir relaciones espaciales"],"retry":"Si confundes los lugares, asocia cada uno con una necesidad concreta antes de describir el mapa."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para pedir direcciones usa How do I get to + lugar? Las indicaciones básicas son Go straight, Turn left y Turn right. Añade distancia con for two blocks y ubicación final con on your left/right. At the corner indica el punto donde debes girar.","communication_goal":"Pedir indicaciones básicas para llegar a un lugar.","language_focus":{"grammar":["How do I get to...?","Where is...?","go straight","turn left/right","at the corner","on your left/right"],"function":"asking for directions"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Go straight for two blocks.","word":"go straight","meaning_es":"seguir derecho"},{"english":"Turn left at the corner.","word":"turn left","meaning_es":"girar a la izquierda"},{"english":"Turn right after the bank.","word":"turn right","meaning_es":"girar a la derecha"},{"english":"The cafe is on the corner.","word":"corner","meaning_es":"esquina"},{"english":"Walk two blocks.","word":"block","meaning_es":"cuadra"},{"english":"Use the crosswalk.","word":"crosswalk","meaning_es":"paso de peatones"}],"dialogue":[{"speaker":"Traveler","english":"Excuse me. How do I get to the train station?","spanish":"Disculpe. ¿Cómo llego a la estación de tren?"},{"speaker":"Local","english":"Go straight for two blocks.","spanish":"Siga derecho dos cuadras."},{"speaker":"Traveler","english":"Do I turn left or right?","spanish":"¿Giro a la izquierda o a la derecha?"},{"speaker":"Local","english":"Turn right at the bank. The station is on your left.","spanish":"Gire a la derecha en el banco. La estación está a su izquierda."},{"speaker":"Traveler","english":"Thank you. Is it far?","spanish":"Gracias. ¿Está lejos?"},{"speaker":"Local","english":"No, it is very close.","spanish":"No, está muy cerca."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"How do I get to the train station?","focus":"how do I get to"},{"text":"Go straight for two blocks.","focus":"straight y blocks"},{"text":"Turn right at the bank.","focus":"turn right"}],"tip_es":"Acompaña cada indicación con un gesto o un mapa para fijar izquierda y derecha."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Traveler","english":"Excuse me. How do I get to the train station?","spanish":"Disculpe. ¿Cómo llego a la estación de tren?"},{"speaker":"Local","english":"Go straight for two blocks.","spanish":"Siga derecho dos cuadras."},{"speaker":"Traveler","english":"Do I turn left or right?","spanish":"¿Giro a la izquierda o a la derecha?"},{"speaker":"Local","english":"Turn right at the bank. The station is on your left.","spanish":"Gire a la derecha en el banco. La estación está a su izquierda."},{"speaker":"Traveler","english":"Thank you. Is it far?","spanish":"Gracias. ¿Está lejos?"},{"speaker":"Local","english":"No, it is very close.","spanish":"No, está muy cerca."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Walking to the station","text":"A traveler asks how to get to the train station. She goes straight for two blocks, turns right at the bank and sees the station on her left. The station is close to the bank.","glossary":[{"term":"train station","meaning_es":"estación de tren"},{"term":"walking","meaning_es":"caminando"},{"term":"close","meaning_es":"cerca"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Estás en una ciudad nueva y necesitas llegar a una estación, hotel o lugar público.","communication_goal":"Pedir indicaciones básicas para llegar a un lugar.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un viajero perdido. Dale indicaciones desde un lugar ficticio hasta una estación o hotel.","scenario":"Helping a traveler find a destination.","ai_language":"English; ask the traveler to repeat the route","prompt":"La IA será un viajero perdido. Dale indicaciones desde un lugar ficticio hasta una estación o hotel.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T07-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Crea un mapa con cinco lugares y graba una ruta de cuatro pasos entre dos de ellos.","success_criteria":["usa go straight","usa left y right","incluye distancia o referencia","ruta comprensible"],"prompt":"Crea un mapa con cinco lugares y graba una ruta de cuatro pasos entre dos de ellos.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T07-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["pedir direcciones","dar una ruta de tres pasos","distinguir left y right"],"retry":"Si confundes left/right, usa un mapa y señala físicamente la dirección mientras la dices."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para transporte usa How can I get to...? o How do I get to...? Las instrucciones comunes son Take the number five bus, Get on at this stop y Get off at Main Street. Pregunta Does it stop near...? para confirmar una parada. En inglés americano subway es metro; train station es estación de tren.","communication_goal":"Preguntar cómo llegar usando autobús, tren, metro o taxi y confirmar una ruta.","language_focus":{"grammar":["How can I get to...?","Which bus/train...?","Take the...","Get off at...","Does it stop at...?"],"function":"transport directions"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Where is the bus stop?","word":"bus stop","meaning_es":"parada de autobús"},{"english":"The train station is nearby.","word":"train station","meaning_es":"estación de tren"},{"english":"Take the subway downtown.","word":"subway","meaning_es":"metro"},{"english":"Let''s take a taxi.","word":"taxi","meaning_es":"taxi"},{"english":"Get on the bus here.","word":"get on","meaning_es":"subir a transporte"},{"english":"Get off at Main Street.","word":"get off","meaning_es":"bajarse"}],"dialogue":[{"speaker":"Traveler","english":"How can I get to the museum?","spanish":"¿Cómo puedo llegar al museo?"},{"speaker":"Agent","english":"Take the number five bus from this stop.","spanish":"Toma el autobús número cinco desde esta parada."},{"speaker":"Traveler","english":"Where do I get off?","spanish":"¿Dónde me bajo?"},{"speaker":"Agent","english":"Get off at Main Street. The museum is across from the station.","spanish":"Bájate en Main Street. El museo está enfrente de la estación."},{"speaker":"Traveler","english":"Does the bus stop near the museum?","spanish":"¿El autobús para cerca del museo?"},{"speaker":"Agent","english":"Yes, it does.","spanish":"Sí."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"How can I get to the museum?","focus":"how can I get to"},{"text":"Take the number five bus.","focus":"number five bus"},{"text":"Get off at Main Street.","focus":"get off at"}],"tip_es":"Repite la ruta completa y confirma el destino antes de empezar el viaje."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Traveler","english":"How can I get to the museum?","spanish":"¿Cómo puedo llegar al museo?"},{"speaker":"Agent","english":"Take the number five bus from this stop.","spanish":"Toma el autobús número cinco desde esta parada."},{"speaker":"Traveler","english":"Where do I get off?","spanish":"¿Dónde me bajo?"},{"speaker":"Agent","english":"Get off at Main Street. The museum is across from the station.","spanish":"Bájate en Main Street. El museo está enfrente de la estación."},{"speaker":"Traveler","english":"Does the bus stop near the museum?","spanish":"¿El autobús para cerca del museo?"},{"speaker":"Agent","english":"Yes, it does.","spanish":"Sí."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A bus route","text":"A traveler wants to go to the museum. She takes the number five bus, gets on at the station and gets off at Main Street. The museum is across from the station, so she walks there.","glossary":[{"term":"bus route","meaning_es":"ruta de autobús"},{"term":"gets on","meaning_es":"sube"},{"term":"walks there","meaning_es":"camina hasta allí"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Necesitas escoger un medio de transporte para llegar a un lugar.","communication_goal":"Preguntar cómo llegar usando autobús, tren, metro o taxi y confirmar una ruta.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un agente de transporte. Pregunta por una ruta y confirma número, parada de subida y bajada.","scenario":"Finding the correct bus or subway route.","ai_language":"English; repeat critical route details","prompt":"La IA será un agente de transporte. Pregunta por una ruta y confirma número, parada de subida y bajada.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T07-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una ruta desde una estación hasta un destino usando transporte y caminata final.","success_criteria":["usa take/get on/get off","indica dos lugares","confirma la parada final","ruta clara"],"prompt":"Graba una ruta desde una estación hasta un destino usando transporte y caminata final.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T07-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["preguntar por transporte","explicar subida y bajada","confirmar una ruta"],"retry":"Si confundes get on/get off, imagina el movimiento: entrar al transporte o salir de él."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Una tarea de navegación comienza con una petición cortés, sigue con una ruta y termina con una confirmación. Usa landmarks como the bank o the park para orientar. Pregunta Is it near...? o Can I walk there? si necesitas verificar distancia. Si usas transporte, añade Take..., Get on... y Get off....","communication_goal":"Pedir, comprender y dar indicaciones completas por calles o transporte.","language_focus":{"grammar":["How do/can I get to...?","go straight","turn left/right","take/get off","near/next to/across from","confirmation questions"],"function":"complete navigation task"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"What is your destination?","word":"destination","meaning_es":"destino"},{"english":"Can you show me on the map?","word":"map","meaning_es":"mapa"},{"english":"The entrance is on the left.","word":"entrance","meaning_es":"entrada"},{"english":"The train leaves from platform two.","word":"platform","meaning_es":"andén/plataforma"},{"english":"The bank is a landmark.","word":"landmark","meaning_es":"punto de referencia"},{"english":"I am lost.","word":"lost","meaning_es":"perdido/a"}],"dialogue":[{"speaker":"Tourist","english":"Excuse me, I am lost. How can I get to the hotel?","spanish":"Disculpe, estoy perdido. ¿Cómo llego al hotel?"},{"speaker":"Local","english":"Go straight for one block and turn left at the bank.","spanish":"Siga derecho una cuadra y gire a la izquierda en el banco."},{"speaker":"Tourist","english":"Is the hotel near the park?","spanish":"¿Está el hotel cerca del parque?"},{"speaker":"Local","english":"Yes, it is. The entrance is across from the park.","spanish":"Sí. La entrada está enfrente del parque."},{"speaker":"Tourist","english":"Thank you. Can I walk there?","spanish":"Gracias. ¿Puedo caminar hasta allí?"},{"speaker":"Local","english":"Yes. It is a short walk.","spanish":"Sí. Es una caminata corta."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Excuse me, I am lost.","focus":"excuse me y lost"},{"text":"Go straight for one block and turn left.","focus":"straight/turn left"},{"text":"The entrance is across from the park.","focus":"entrance across from"}],"tip_es":"En una situación real, repite la ruta en voz alta para confirmar que la entendiste."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Tourist","english":"Excuse me, I am lost. How can I get to the hotel?","spanish":"Disculpe, estoy perdido. ¿Cómo llego al hotel?"},{"speaker":"Local","english":"Go straight for one block and turn left at the bank.","spanish":"Siga derecho una cuadra y gire a la izquierda en el banco."},{"speaker":"Tourist","english":"Is the hotel near the park?","spanish":"¿Está el hotel cerca del parque?"},{"speaker":"Local","english":"Yes, it is. The entrance is across from the park.","spanish":"Sí. La entrada está enfrente del parque."},{"speaker":"Tourist","english":"Thank you. Can I walk there?","spanish":"Gracias. ¿Puedo caminar hasta allí?"},{"speaker":"Local","english":"Yes. It is a short walk.","spanish":"Sí. Es una caminata corta."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A tourist in the city","text":"A tourist is lost and asks for the hotel. She goes straight for one block and turns left at the bank. The hotel is across from the park. The entrance is on the left, and it is a short walk from the bank.","glossary":[{"term":"complete route","meaning_es":"ruta completa"},{"term":"short walk","meaning_es":"caminata corta"},{"term":"tourist","meaning_es":"turista"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Llegas a una ciudad nueva y necesitas resolver cómo llegar a un hotel, estación o lugar turístico.","communication_goal":"Pedir, comprender y dar indicaciones completas por calles o transporte.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Realiza con la IA una tarea de navegación: tú estás perdido, pides indicaciones, repites la ruta y confirmas el destino.","scenario":"Navigating from a station to a hotel in an unfamiliar city.","ai_language":"English; evaluate comprehension through route repetition","prompt":"Realiza con la IA una tarea de navegación: tú estás perdido, pides indicaciones, repites la ruta y confirmas el destino.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T07-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Crea un mapa urbano ficticio y graba una conversación de 90 segundos para llegar desde una estación hasta un destino.","success_criteria":["pide ayuda con cortesía","da cuatro pasos","usa landmark y preposiciones","confirma la ruta"],"prompt":"Crea un mapa urbano ficticio y graba una conversación de 90 segundos para llegar desde una estación hasta un destino.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T07-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["pedir indicaciones","comprender una ruta","dar y confirmar una ruta completa"],"retry":"Si el resultado es menor de 80%, usa un mapa simple y practica solo tres pasos antes de añadir transporte o landmarks."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para hablar de un plan cercano usa I am going to + destino: I am going to Boston. Para el medio de transporte usa travel by train/plane/bus. Pregunta Where are you going?, When are you leaving? y What time is your flight/train?. Passport y suitcase son objetos importantes del viaje.","communication_goal":"Hablar de un viaje básico, destino, transporte y equipaje.","language_focus":{"grammar":["I am going to...","I am traveling by...","I have...","Where are you going?","When are you leaving?"],"function":"basic travel planning"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I am planning a trip.","word":"trip","meaning_es":"viaje"},{"english":"My destination is Boston.","word":"destination","meaning_es":"destino"},{"english":"My flight is at ten.","word":"flight","meaning_es":"vuelo"},{"english":"I am traveling by train.","word":"train","meaning_es":"tren"},{"english":"My suitcase is small.","word":"suitcase","meaning_es":"maleta"},{"english":"I have my passport.","word":"passport","meaning_es":"pasaporte"}],"dialogue":[{"speaker":"Maya","english":"Where are you going this weekend?","spanish":"¿A dónde vas este fin de semana?"},{"speaker":"Leo","english":"I am going to Boston. I am traveling by train.","spanish":"Voy a Boston. Viajo en tren."},{"speaker":"Maya","english":"When are you leaving?","spanish":"¿Cuándo sales?"},{"speaker":"Leo","english":"I am leaving on Friday morning. I have my passport and suitcase.","spanish":"Salgo el viernes por la mañana. Tengo mi pasaporte y mi maleta."},{"speaker":"Maya","english":"What time is your train?","spanish":"¿A qué hora es tu tren?"},{"speaker":"Leo","english":"It is at nine thirty.","spanish":"Es a las nueve y media."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I am going to Boston.","focus":"going to Boston"},{"text":"I am traveling by train.","focus":"traveling by train"},{"text":"I am leaving on Friday morning.","focus":"leaving on Friday"}],"tip_es":"Practica la información esencial del viaje en bloques: destino, transporte, hora y documentos."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Maya","english":"Where are you going this weekend?","spanish":"¿A dónde vas este fin de semana?"},{"speaker":"Leo","english":"I am going to Boston. I am traveling by train.","spanish":"Voy a Boston. Viajo en tren."},{"speaker":"Maya","english":"When are you leaving?","spanish":"¿Cuándo sales?"},{"speaker":"Leo","english":"I am leaving on Friday morning. I have my passport and suitcase.","spanish":"Salgo el viernes por la mañana. Tengo mi pasaporte y mi maleta."},{"speaker":"Maya","english":"What time is your train?","spanish":"¿A qué hora es tu tren?"},{"speaker":"Leo","english":"It is at nine thirty.","spanish":"Es a las nueve y media."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Leo''s weekend trip","text":"Leo is going to Boston for the weekend. He is traveling by train on Friday morning. His train leaves at nine thirty. He has his passport, a small suitcase and a phone.","glossary":[{"term":"weekend trip","meaning_es":"viaje de fin de semana"},{"term":"leaves","meaning_es":"sale/parte"},{"term":"documents","meaning_es":"documentos"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Preparas un viaje y confirmas qué necesitas llevar y cómo vas a viajar.","communication_goal":"Hablar de un viaje básico, destino, transporte y equipaje.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un amigo preparando un viaje. Pregunta por destino, transporte, hora y equipaje.","scenario":"Planning a short weekend trip.","ai_language":"English with practical travel vocabulary","prompt":"La IA será un amigo preparando un viaje. Pregunta por destino, transporte, hora y equipaje.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T08-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una nota de voz de 30 segundos sobre un viaje ficticio: destino, fecha, transporte, hora y tres objetos.","success_criteria":["usa going to","usa travel by","incluye fecha/hora","nombra equipaje y documento"],"prompt":"Graba una nota de voz de 30 segundos sobre un viaje ficticio: destino, fecha, transporte, hora y tres objetos.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T08-L01"}]}'::jsonb,6);
