insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"En una estación o aeropuerto pregunta Where is...? por una ubicación, Which platform/gate...? por una puerta concreta y What time does it leave? por el horario. Para verificar usa Is this the train to Boston? o Do I need a ticket?. Empieza con Excuse me y agradece la ayuda.","communication_goal":"Pedir información y seguir instrucciones básicas en una estación o aeropuerto.","language_focus":{"grammar":["Where is...?","Which platform/gate...?","What time does it leave?","I need...","Is this...?"],"function":"travel information"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"The departure is at ten.","word":"departure","meaning_es":"salida"},{"english":"What time is the arrival?","word":"arrival","meaning_es":"llegada"},{"english":"The train leaves from platform three.","word":"platform","meaning_es":"andén"},{"english":"Where is gate five?","word":"gate","meaning_es":"puerta de embarque"},{"english":"I need a ticket to Boston.","word":"ticket","meaning_es":"billete/boleto"},{"english":"Where can I leave my luggage?","word":"luggage","meaning_es":"equipaje"}],"dialogue":[{"speaker":"Traveler","english":"Excuse me. Where is platform three?","spanish":"Disculpe. ¿Dónde está el andén tres?"},{"speaker":"Agent","english":"It is downstairs, next to the information desk.","spanish":"Está abajo, al lado del mostrador de información."},{"speaker":"Traveler","english":"What time does the train leave?","spanish":"¿A qué hora sale el tren?"},{"speaker":"Agent","english":"It leaves at ten fifteen.","spanish":"Sale a las diez y cuarto."},{"speaker":"Traveler","english":"Do I need a ticket for Boston?","spanish":"¿Necesito un billete para Boston?"},{"speaker":"Agent","english":"Yes, you do. The ticket office is over there.","spanish":"Sí. La taquilla está allí."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Where is platform three?","focus":"platform three"},{"text":"What time does the train leave?","focus":"does the train leave"},{"text":"Do I need a ticket?","focus":"do I need"}],"tip_es":"Repite el número de plataforma o puerta para confirmar que lo escuchaste bien."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Traveler","english":"Excuse me. Where is platform three?","spanish":"Disculpe. ¿Dónde está el andén tres?"},{"speaker":"Agent","english":"It is downstairs, next to the information desk.","spanish":"Está abajo, al lado del mostrador de información."},{"speaker":"Traveler","english":"What time does the train leave?","spanish":"¿A qué hora sale el tren?"},{"speaker":"Agent","english":"It leaves at ten fifteen.","spanish":"Sale a las diez y cuarto."},{"speaker":"Traveler","english":"Do I need a ticket for Boston?","spanish":"¿Necesito un billete para Boston?"},{"speaker":"Agent","english":"Yes, you do. The ticket office is over there.","spanish":"Sí. La taquilla está allí."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Finding the platform","text":"A traveler arrives at the train station. She needs a ticket to Boston and asks where platform three is. The train leaves at ten fifteen. The platform is downstairs, next to the information desk.","glossary":[{"term":"train station","meaning_es":"estación de tren"},{"term":"information desk","meaning_es":"mostrador de información"},{"term":"downstairs","meaning_es":"abajo"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Buscas una puerta, andén, billete o zona de salida antes de viajar.","communication_goal":"Pedir información y seguir instrucciones básicas en una estación o aeropuerto.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un agente de estación o aeropuerto. Pregunta por billete, horario, puerta y equipaje.","scenario":"Getting travel information before departure.","ai_language":"English; repeat important numbers and locations","prompt":"La IA será un agente de estación o aeropuerto. Pregunta por billete, horario, puerta y equipaje.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T08-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un diálogo de ocho turnos en una estación: saluda, pregunta plataforma, hora, billete y agradece.","success_criteria":["usa Excuse me","formula tres preguntas correctas","repite un número","cierra con Thank you"],"prompt":"Graba un diálogo de ocho turnos en una estación: saluda, pregunta plataforma, hora, billete y agradece.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T08-L02"}]}'::jsonb,6);
