insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"En un hotel empieza con I have a reservation y di tu nombre. El personal puede confirmar el tipo de habitación y las noches. Pregunta What floor is my room on? y What time is breakfast?. Para pedir algo usa Can I have...?; para informar un problema usa There is a problem with....","communication_goal":"Hacer check-in, confirmar una reserva y pedir información básica en un hotel.","language_focus":{"grammar":["I have a reservation","My name is...","Can I have...?","Where is my room?","What time is breakfast?","There is a problem"],"function":"hotel check-in and requests"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I have a reservation.","word":"reservation","meaning_es":"reserva"},{"english":"I booked a single room.","word":"single room","meaning_es":"habitación individual"},{"english":"I need a double room.","word":"double room","meaning_es":"habitación doble"},{"english":"Here is your room key.","word":"key","meaning_es":"llave"},{"english":"Your room is on the third floor.","word":"floor","meaning_es":"piso"},{"english":"Breakfast starts at seven.","word":"breakfast","meaning_es":"desayuno"}],"dialogue":[{"speaker":"Receptionist","english":"Good evening. How can I help you?","spanish":"Buenas noches. ¿Cómo puedo ayudarle?"},{"speaker":"Traveler","english":"I have a reservation. My name is Daniel Ruiz.","spanish":"Tengo una reserva. Me llamo Daniel Ruiz."},{"speaker":"Receptionist","english":"Yes, Mr. Ruiz. You have a single room for two nights.","spanish":"Sí, señor Ruiz. Tiene una habitación individual por dos noches."},{"speaker":"Traveler","english":"What floor is my room on?","spanish":"¿En qué piso está mi habitación?"},{"speaker":"Receptionist","english":"It is on the third floor. Here is your key.","spanish":"Está en el tercer piso. Aquí está su llave."},{"speaker":"Traveler","english":"What time is breakfast?","spanish":"¿A qué hora es el desayuno?"}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I have a reservation.","focus":"have a reservation"},{"text":"What floor is my room on?","focus":"floor y room on"},{"text":"What time is breakfast?","focus":"time is breakfast"}],"tip_es":"Practica primero frases de recepción y luego añade tu nombre o número de reserva ficticio."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Receptionist","english":"Good evening. How can I help you?","spanish":"Buenas noches. ¿Cómo puedo ayudarle?"},{"speaker":"Traveler","english":"I have a reservation. My name is Daniel Ruiz.","spanish":"Tengo una reserva. Me llamo Daniel Ruiz."},{"speaker":"Receptionist","english":"Yes, Mr. Ruiz. You have a single room for two nights.","spanish":"Sí, señor Ruiz. Tiene una habitación individual por dos noches."},{"speaker":"Traveler","english":"What floor is my room on?","spanish":"¿En qué piso está mi habitación?"},{"speaker":"Receptionist","english":"It is on the third floor. Here is your key.","spanish":"Está en el tercer piso. Aquí está su llave."},{"speaker":"Traveler","english":"What time is breakfast?","spanish":"¿A qué hora es el desayuno?"}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A hotel arrival","text":"Daniel has a reservation for a single room for two nights. His room is on the third floor. He receives a key at reception and asks what time breakfast starts. Breakfast starts at seven.","glossary":[{"term":"hotel arrival","meaning_es":"llegada al hotel"},{"term":"reception","meaning_es":"recepción"},{"term":"two nights","meaning_es":"dos noches"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Llegas a un hotel y necesitas encontrar tu habitación o solicitar un servicio.","communication_goal":"Hacer check-in, confirmar una reserva y pedir información básica en un hotel.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será recepcionista. Haz check-in con una reserva ficticia y pregunta por piso, desayuno y llave.","scenario":"Checking into a hotel after a trip.","ai_language":"English; never request real booking or payment information","prompt":"La IA será recepcionista. Haz check-in con una reserva ficticia y pregunta por piso, desayuno y llave.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T08-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba un diálogo de ocho turnos de check-in y pide un servicio adicional ficticio.","success_criteria":["usa I have a reservation","confirma noches/habitación","pregunta ubicación y horario","usa una petición cortés"],"prompt":"Graba un diálogo de ocho turnos de check-in y pide un servicio adicional ficticio.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T08-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["hacer check-in","preguntar por habitación y desayuno","comprender datos de una reserva"],"retry":"Si confundes floor y room, floor es el piso y room es la habitación."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para explicar un problema usa There is a problem with + objeto. Describe el estado con is broken, is missing o is wrong. Pide ayuda con I need help, Could you...? o Can you...?. Mantén un tono cortés, describe un hecho concreto y termina agradeciendo la ayuda.","communication_goal":"Explicar una necesidad o problema básico y pedir ayuda durante un viaje.","language_focus":{"grammar":["There is a problem with...","I need help","Could you...?","My ... is missing/broken","Where can I...?","Thank you for your help"],"function":"travel problem solving"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"My luggage is missing.","word":"missing","meaning_es":"perdido/faltante"},{"english":"The air conditioner is broken.","word":"broken","meaning_es":"roto"},{"english":"I have the wrong ticket.","word":"wrong","meaning_es":"equivocado"},{"english":"I lost my passport.","word":"lost","meaning_es":"perdido"},{"english":"Where is the help desk?","word":"help desk","meaning_es":"mostrador de ayuda"},{"english":"Can you change my room?","word":"change","meaning_es":"cambiar"}],"dialogue":[{"speaker":"Traveler","english":"Excuse me. There is a problem with my room.","spanish":"Disculpe. Hay un problema con mi habitación."},{"speaker":"Receptionist","english":"What is the problem?","spanish":"¿Cuál es el problema?"},{"speaker":"Traveler","english":"The air conditioner is broken, and the room is very hot.","spanish":"El aire acondicionado está roto y la habitación está muy caliente."},{"speaker":"Receptionist","english":"I''m sorry. Could you wait here, please?","spanish":"Lo siento. ¿Podría esperar aquí, por favor?"},{"speaker":"Traveler","english":"Yes. Can you change my room?","spanish":"Sí. ¿Puede cambiar mi habitación?"},{"speaker":"Receptionist","english":"Yes, we can help you.","spanish":"Sí, podemos ayudarle."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"There is a problem with my room.","focus":"problem with my room"},{"text":"The air conditioner is broken.","focus":"air conditioner y broken"},{"text":"Could you help me, please?","focus":"could you help me"}],"tip_es":"Practica el problema como una frase breve y clara antes de añadir detalles."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Traveler","english":"Excuse me. There is a problem with my room.","spanish":"Disculpe. Hay un problema con mi habitación."},{"speaker":"Receptionist","english":"What is the problem?","spanish":"¿Cuál es el problema?"},{"speaker":"Traveler","english":"The air conditioner is broken, and the room is very hot.","spanish":"El aire acondicionado está roto y la habitación está muy caliente."},{"speaker":"Receptionist","english":"I''m sorry. Could you wait here, please?","spanish":"Lo siento. ¿Podría esperar aquí, por favor?"},{"speaker":"Traveler","english":"Yes. Can you change my room?","spanish":"Sí. ¿Puede cambiar mi habitación?"},{"speaker":"Receptionist","english":"Yes, we can help you.","spanish":"Sí, podemos ayudarle."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A missing suitcase","text":"After a flight, Carla cannot find her suitcase. She goes to the help desk and says, ''My luggage is missing. I need help, please.''. The worker asks for her ticket and helps her complete a report.","glossary":[{"term":"missing suitcase","meaning_es":"maleta perdida"},{"term":"help desk","meaning_es":"mostrador de ayuda"},{"term":"report","meaning_es":"reporte/informe"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Tu equipaje, habitación, billete o transporte presenta un problema y necesitas solucionarlo.","communication_goal":"Explicar una necesidad o problema básico y pedir ayuda durante un viaje.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será personal de hotel o aeropuerto. Explica un problema ficticio, responde preguntas y pide una solución.","scenario":"Solving a simple travel problem at a help desk.","ai_language":"English; be calm, clear and supportive","prompt":"La IA será personal de hotel o aeropuerto. Explica un problema ficticio, responde preguntas y pide una solución.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T08-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba dos mini diálogos: uno sobre equipaje perdido y otro sobre una habitación con un problema.","success_criteria":["usa There is a problem with","describe el detalle","pide ayuda con Could you/Can you","agradece la solución"],"prompt":"Graba dos mini diálogos: uno sobre equipaje perdido y otro sobre una habitación con un problema.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T08-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["describir un problema","pedir ayuda con cortesía","comprender una solución básica"],"retry":"Si el resultado es menor de 80%, practica la fórmula problema + detalle + petición con tres situaciones distintas."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para preguntar por trabajo usa What do you do? y responde I am a teacher o I work as an engineer. Work in puede indicar un tipo de lugar o área: work in an office; work at puede indicar una institución o lugar concreto: work at a school. Do you like your job? pregunta si te gusta tu empleo.","communication_goal":"Decir a qué te dedicas, dónde trabajas y qué haces durante el día.","language_focus":{"grammar":["What do you do?","I am a...","I work as...","I work in/at...","I like my job"],"function":"jobs and workplaces"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I like my job.","word":"job","meaning_es":"trabajo/empleo"},{"english":"I work in an office.","word":"office","meaning_es":"oficina"},{"english":"She works at a store.","word":"store","meaning_es":"tienda"},{"english":"He is a teacher.","word":"teacher","meaning_es":"profesor/a"},{"english":"She works as a nurse.","word":"nurse","meaning_es":"enfermero/a"},{"english":"I am an engineer.","word":"engineer","meaning_es":"ingeniero/a"}],"dialogue":[{"speaker":"Nina","english":"What do you do?","spanish":"¿A qué te dedicas?"},{"speaker":"Omar","english":"I work as an engineer. I work in an office downtown.","spanish":"Trabajo como ingeniero. Trabajo en una oficina del centro."},{"speaker":"Nina","english":"Do you like your job?","spanish":"¿Te gusta tu trabajo?"},{"speaker":"Omar","english":"Yes, I do. What about you?","spanish":"Sí. ¿Y tú?"},{"speaker":"Nina","english":"I am a teacher. I work at a school.","spanish":"Soy profesora. Trabajo en una escuela."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"What do you do?","focus":"pregunta fija de profesión"},{"text":"I work as an engineer.","focus":"work as an engineer"},{"text":"I work at a school.","focus":"work at a school"}],"tip_es":"Practica la profesión dentro de una frase, no como una lista aislada."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Nina","english":"What do you do?","spanish":"¿A qué te dedicas?"},{"speaker":"Omar","english":"I work as an engineer. I work in an office downtown.","spanish":"Trabajo como ingeniero. Trabajo en una oficina del centro."},{"speaker":"Nina","english":"Do you like your job?","spanish":"¿Te gusta tu trabajo?"},{"speaker":"Omar","english":"Yes, I do. What about you?","spanish":"Sí. ¿Y tú?"},{"speaker":"Nina","english":"I am a teacher. I work at a school.","spanish":"Soy profesora. Trabajo en una escuela."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Nina and Omar at work","text":"Omar is an engineer. He works in an office downtown and likes his job. Nina is a teacher. She works at a school and enjoys helping students.","glossary":[{"term":"coworker","meaning_es":"compañero/a de trabajo"},{"term":"downtown","meaning_es":"centro de la ciudad"},{"term":"students","meaning_es":"estudiantes"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Conoces a alguien en un contexto profesional y hablas de tu ocupación.","communication_goal":"Decir a qué te dedicas, dónde trabajas y qué haces durante el día.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un nuevo compañero de trabajo. Pregunta por ocupación, lugar y gusto por el trabajo.","scenario":"Meeting a coworker in a new workplace.","ai_language":"English; use fictional professional details","prompt":"La IA será un nuevo compañero de trabajo. Pregunta por ocupación, lugar y gusto por el trabajo.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T09-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una presentación profesional de 30 segundos con profesión, lugar, actividad y opinión sobre el trabajo.","success_criteria":["usa What do you do? en una pregunta","usa a/an o work as","incluye lugar de trabajo","expresa like/dislike"],"prompt":"Graba una presentación profesional de 30 segundos con profesión, lugar, actividad y opinión sobre el trabajo.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T09-L01"}]}'::jsonb,6);
