insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para hablar de estudios usa I study + materia/lugar o I am taking a course. Para horarios usa I have class on Tuesday. Pregunta What are you studying? por el curso o materia y Do you study at home? por el lugar de estudio. Homework es no contable: do my homework, no homeworks.","communication_goal":"Describir qué estudias, dónde y cuándo tienes clases.","language_focus":{"grammar":["I study...","I am taking a course","I have class on...","I study at...","What are you studying?"],"function":"education and study routines"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I am taking an English course.","word":"course","meaning_es":"curso"},{"english":"I have class on Tuesday.","word":"class","meaning_es":"clase"},{"english":"English is my favorite subject.","word":"subject","meaning_es":"materia"},{"english":"I am a student.","word":"student","meaning_es":"estudiante"},{"english":"My teacher is kind.","word":"teacher","meaning_es":"profesor/a"},{"english":"I do my homework at night.","word":"homework","meaning_es":"tarea"}],"dialogue":[{"speaker":"Sara","english":"What are you studying?","spanish":"¿Qué estás estudiando?"},{"speaker":"Ben","english":"I am taking an English course. I have class on Tuesday and Thursday.","spanish":"Estoy haciendo un curso de inglés. Tengo clase los martes y jueves."},{"speaker":"Sara","english":"Do you study at home?","spanish":"¿Estudias en casa?"},{"speaker":"Ben","english":"Yes, I do. I do my homework at night.","spanish":"Sí. Hago mi tarea por la noche."},{"speaker":"Sara","english":"I study at a university. English is my favorite subject.","spanish":"Estudio en una universidad. Inglés es mi materia favorita."}]}'::jsonb,2);
