insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Hablas con un compañero sobre tu curso, materia y hábitos de estudio.","communication_goal":"Describir qué estudias, dónde y cuándo tienes clases.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero de clase. Hablen de materias, horario, profesor y tareas.","scenario":"Talking to a classmate about studies.","ai_language":"English; encourage What are you studying?","prompt":"La IA será un compañero de clase. Hablen de materias, horario, profesor y tareas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T09-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una presentación de 35 segundos sobre tus estudios o un curso ficticio: materia, lugar, días, profesor y tarea.","success_criteria":["usa I study o I am taking","incluye dos días","usa do homework","mensaje comprensible"],"prompt":"Graba una presentación de 35 segundos sobre tus estudios o un curso ficticio: materia, lugar, días, profesor y tarea.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T09-L02"}]}'::jsonb,6);
