insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Para hablar de una tarea actual usa I am working on + proyecto. Para necesidad usa I need to + verbo y para obligación cotidiana I have to + verbo. Pide ayuda con Can you help me? y propone colaboración con Let''s + verbo. Después de help puedes usar me: help me with the slide.","communication_goal":"Hablar de tareas simples, pedir ayuda y coordinar actividades con compañeros.","language_focus":{"grammar":["I need to...","I have to...","Can you help me?","Let''s...","Are you finished?","I am working on..."],"function":"tasks and teamwork"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I have a task for today.","word":"task","meaning_es":"tarea"},{"english":"We are working on a project.","word":"project","meaning_es":"proyecto"},{"english":"The meeting starts at ten.","word":"meeting","meaning_es":"reunión"},{"english":"I need to finish this task.","word":"finish","meaning_es":"terminar"},{"english":"Please send the file.","word":"send","meaning_es":"enviar"},{"english":"Can you help me?","word":"help","meaning_es":"ayuda/ayudar"}],"dialogue":[{"speaker":"Mia","english":"What are you working on?","spanish":"¿En qué estás trabajando?"},{"speaker":"Leo","english":"I am working on the presentation. I need to finish it today.","spanish":"Estoy trabajando en la presentación. Necesito terminarla hoy."},{"speaker":"Mia","english":"Can you send me the file?","spanish":"¿Puedes enviarme el archivo?"},{"speaker":"Leo","english":"Yes, I can. Can you help me with the last slide?","spanish":"Sí. ¿Puedes ayudarme con la última diapositiva?"},{"speaker":"Mia","english":"Sure. Let''s work on it together.","spanish":"Claro. Trabajemos juntos en eso."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"What are you working on?","focus":"working on"},{"text":"Can you send me the file?","focus":"send me the file"},{"text":"Let''s work on it together.","focus":"let''s y together"}],"tip_es":"Practica la petición con tono cooperativo, no como una orden aislada."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Mia","english":"What are you working on?","spanish":"¿En qué estás trabajando?"},{"speaker":"Leo","english":"I am working on the presentation. I need to finish it today.","spanish":"Estoy trabajando en la presentación. Necesito terminarla hoy."},{"speaker":"Mia","english":"Can you send me the file?","spanish":"¿Puedes enviarme el archivo?"},{"speaker":"Leo","english":"Yes, I can. Can you help me with the last slide?","spanish":"Sí. ¿Puedes ayudarme con la última diapositiva?"},{"speaker":"Mia","english":"Sure. Let''s work on it together.","spanish":"Claro. Trabajemos juntos en eso."}],"audio_text":null}'::jsonb,4);
