insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Trabajas o estudias con otras personas y necesitas explicar qué haces.","communication_goal":"Hablar de tareas simples, pedir ayuda y coordinar actividades con compañeros.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un compañero de trabajo o estudio. Explica tu tarea, pide un archivo y acuerden trabajar juntos.","scenario":"Collaborating on a simple project.","ai_language":"English; model concise workplace requests","prompt":"La IA será un compañero de trabajo o estudio. Explica tu tarea, pide un archivo y acuerden trabajar juntos.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T09-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una conversación de seis turnos sobre una tarea: qué haces, qué necesitas, una petición y una propuesta con Let''s.","success_criteria":["usa working on","usa need to/have to","pide ayuda","propone colaboración"],"prompt":"Graba una conversación de seis turnos sobre una tarea: qué haces, qué necesitas, una petición y una propuesta con Let''s.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T09-L03"}]}'::jsonb,6);
