insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Un perfil completo combina profesión/estudios, lugar, tareas, frecuencia y objetivo. Usa I work/I study para la actividad general, I usually... para rutina, I have to... para responsabilidades y My goal is... para un objetivo. Conecta la razón con because y contrasta con but.","communication_goal":"Describir tu trabajo o estudios, rutina, tareas y objetivos básicos.","language_focus":{"grammar":["I am/I work/I study","I usually...","I need to/have to...","because/but","questions and follow-up"],"function":"complete work and study profile"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I have experience in sales.","word":"experience","meaning_es":"experiencia"},{"english":"My goal is to improve my English.","word":"goal","meaning_es":"objetivo"},{"english":"I work with a small team.","word":"team","meaning_es":"equipo"},{"english":"I help customers.","word":"customer","meaning_es":"cliente"},{"english":"I want to improve my English.","word":"improve","meaning_es":"mejorar"},{"english":"In the future, I want to travel.","word":"future","meaning_es":"futuro"}],"dialogue":[{"speaker":"Coach","english":"Tell me about your work or studies.","spanish":"Háblame de tu trabajo o estudios."},{"speaker":"Student","english":"I work in a small office. I help customers and work with a team.","spanish":"Trabajo en una oficina pequeña. Ayudo a clientes y trabajo con un equipo."},{"speaker":"Coach","english":"What do you usually do?","spanish":"¿Qué haces normalmente?"},{"speaker":"Student","english":"I answer emails and work on projects. I have to finish tasks every day.","spanish":"Respondo correos y trabajo en proyectos. Tengo que terminar tareas todos los días."},{"speaker":"Coach","english":"What is your goal?","spanish":"¿Cuál es tu objetivo?"},{"speaker":"Student","english":"My goal is to improve my English because I want to travel.","spanish":"Mi objetivo es mejorar mi inglés porque quiero viajar."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I work with a small team.","focus":"work with a small team"},{"text":"I have to finish tasks every day.","focus":"have to finish"},{"text":"My goal is to improve my English.","focus":"goal improve English"}],"tip_es":"Divide tu perfil en cuatro bloques: actividad, tareas, responsabilidad y objetivo."}'::jsonb,3);
