insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A clear work profile","text":"Carlos works with a small team in an office. He helps customers and answers emails. He usually works on two projects and has to finish tasks every day. His goal is to improve his English for future travel.","glossary":[{"term":"work profile","meaning_es":"perfil laboral"},{"term":"answers emails","meaning_es":"responde correos"},{"term":"future travel","meaning_es":"viajes futuros"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Participas en una presentación personal académica o profesional.","communication_goal":"Describir tu trabajo o estudios, rutina, tareas y objetivos básicos.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un mentor. Presenta tu perfil de trabajo o estudios y responde preguntas de seguimiento sobre tareas y objetivos.","scenario":"A simple professional or academic introduction.","ai_language":"English; give concise feedback after the conversation","prompt":"La IA será un mentor. Presenta tu perfil de trabajo o estudios y responde preguntas de seguimiento sobre tareas y objetivos.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T09-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba una presentación de 90 segundos sobre tu trabajo o estudios, incluyendo tareas, horario, equipo, responsabilidad y objetivo.","success_criteria":["usa presente simple","incluye usually y have to","conecta una razón con because","habla con claridad"],"prompt":"Graba una presentación de 90 segundos sobre tu trabajo o estudios, incluyendo tareas, horario, equipo, responsabilidad y objetivo.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T09-L04"}]}'::jsonb,6);
