insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Comienza con Excuse me y pide ayuda con Can you help me? o Could you help me?. Explica la necesidad con I need help with + cosa o actividad. Para buscar un lugar pregunta Where can I find...? y cierra con Thank you for your help. Could suena más cortés; Can es muy común y directo.","communication_goal":"Pedir ayuda y explicar una necesidad básica con cortesía.","language_focus":{"grammar":["Excuse me","Can you help me?","Could you help me?","I need help with...","Where can I...?","Thank you"],"function":"asking for help"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"Can you help me?","word":"help","meaning_es":"ayuda/ayudar"},{"english":"I need help finding my bag.","word":"find","meaning_es":"encontrar"},{"english":"I don''t understand.","word":"understand","meaning_es":"entender"},{"english":"I need some information.","word":"information","meaning_es":"información"},{"english":"Could you explain this?","word":"explain","meaning_es":"explicar"},{"english":"I have a problem.","word":"problem","meaning_es":"problema"}],"dialogue":[{"speaker":"Visitor","english":"Excuse me. Can you help me?","spanish":"Disculpe. ¿Puede ayudarme?"},{"speaker":"Staff","english":"Sure. What do you need?","spanish":"Claro. ¿Qué necesita?"},{"speaker":"Visitor","english":"I need some information. Where can I find room four?","spanish":"Necesito información. ¿Dónde puedo encontrar la sala cuatro?"},{"speaker":"Staff","english":"Go upstairs and turn left.","spanish":"Suba y gire a la izquierda."},{"speaker":"Visitor","english":"Thank you for your help.","spanish":"Gracias por su ayuda."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"Excuse me. Can you help me?","focus":"excuse me y help me"},{"text":"I need some information.","focus":"need some information"},{"text":"Thank you for your help.","focus":"thank you for your help"}],"tip_es":"La cortesía incluye palabras y tono; una petición clara y amable facilita que te ayuden."}'::jsonb,3);
