insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Finding a room","text":"A visitor cannot find room four. She goes to the help desk and asks for information. The staff member tells her to go upstairs and turn left. She thanks the staff member for the help.","glossary":[{"term":"help desk","meaning_es":"mostrador de ayuda"},{"term":"staff member","meaning_es":"miembro del personal"},{"term":"upstairs","meaning_es":"arriba"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"No encuentras algo, necesitas información o no puedes resolver una tarea.","communication_goal":"Pedir ayuda y explicar una necesidad básica con cortesía.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será un miembro del personal. Pide ayuda para encontrar un lugar o entender una instrucción.","scenario":"Asking for help in a public building.","ai_language":"English; offer one clear answer and a follow-up","prompt":"La IA será un miembro del personal. Pide ayuda para encontrar un lugar o entender una instrucción.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T10-L01"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba dos peticiones de ayuda: una para encontrar un lugar y otra para entender algo.","success_criteria":["usa Excuse me","formula dos peticiones","explica la necesidad","agradece la ayuda"],"prompt":"Graba dos peticiones de ayuda: una para encontrar un lugar y otra para entender algo.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T10-L01"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["pedir ayuda con cortesía","explicar una necesidad","agradecer la ayuda"],"retry":"Si la petición no es clara, usa la estructura Excuse me + Can/Could you help me with...?"},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Distingue I need + sustantivo (I need a ticket) de I need to + verbo (I need to pay). Pregunta Do you have...? por algo disponible y Can I...? por permiso o posibilidad. En una necesidad urgente sé específico: I need medicine, I need a doctor, I need help. Para asuntos de salud graves, busca ayuda local inmediata.","communication_goal":"Expresar necesidades relacionadas con comida, salud, transporte y comunicación.","language_focus":{"grammar":["I need...","I need to...","I don''t have...","Can I...?","Do you have...?","Here you are"],"function":"everyday needs and requests"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I need some water.","word":"water","meaning_es":"agua"},{"english":"I need medicine.","word":"medicine","meaning_es":"medicina"},{"english":"Do you have a phone charger?","word":"phone charger","meaning_es":"cargador de teléfono"},{"english":"I need a ticket.","word":"ticket","meaning_es":"billete/entrada"},{"english":"Where is the restroom?","word":"restroom","meaning_es":"baño"},{"english":"This is urgent.","word":"urgent","meaning_es":"urgente"}],"dialogue":[{"speaker":"Traveler","english":"Excuse me. I need a ticket to Boston.","spanish":"Disculpe. Necesito un billete a Boston."},{"speaker":"Agent","english":"Sure. One way or return?","spanish":"Claro. ¿Solo ida o ida y vuelta?"},{"speaker":"Traveler","english":"Return, please. I also need a phone charger.","spanish":"De ida y vuelta, por favor. También necesito un cargador."},{"speaker":"Agent","english":"There is a shop near the restroom. It sells chargers.","spanish":"Hay una tienda cerca del baño. Vende cargadores."},{"speaker":"Traveler","english":"Thank you. Can I pay by card?","spanish":"Gracias. ¿Puedo pagar con tarjeta?"}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I need a ticket to Boston.","focus":"need a ticket to"},{"text":"I also need a phone charger.","focus":"phone charger"},{"text":"Can I pay by card?","focus":"pay by card"}],"tip_es":"En una necesidad, pronuncia primero la palabra clave y después añade detalles."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Traveler","english":"Excuse me. I need a ticket to Boston.","spanish":"Disculpe. Necesito un billete a Boston."},{"speaker":"Agent","english":"Sure. One way or return?","spanish":"Claro. ¿Solo ida o ida y vuelta?"},{"speaker":"Traveler","english":"Return, please. I also need a phone charger.","spanish":"De ida y vuelta, por favor. También necesito un cargador."},{"speaker":"Agent","english":"There is a shop near the restroom. It sells chargers.","spanish":"Hay una tienda cerca del baño. Vende cargadores."},{"speaker":"Traveler","english":"Thank you. Can I pay by card?","spanish":"Gracias. ¿Puedo pagar con tarjeta?"}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A day of small needs","text":"A traveler needs a return ticket to Boston and a phone charger. The travel agent tells her about a shop near the restroom. She also asks if she can pay by card. The agent says yes.","glossary":[{"term":"return ticket","meaning_es":"billete de ida y vuelta"},{"term":"travel desk","meaning_es":"mostrador de viajes"},{"term":"pay by card","meaning_es":"pagar con tarjeta"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Explicas qué necesitas en una situación cotidiana y respondes a la ayuda de otra persona.","communication_goal":"Expresar necesidades relacionadas con comida, salud, transporte y comunicación.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA será una persona que puede ayudarte en un viaje. Expresa tres necesidades y pregunta qué opciones hay.","scenario":"Solving practical needs while traveling.","ai_language":"English; prioritize clear functional communication","prompt":"La IA será una persona que puede ayudarte en un viaje. Expresa tres necesidades y pregunta qué opciones hay.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T10-L02"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba tres mini situaciones: pedir agua, pedir un cargador y pedir un billete. Incluye una pregunta de permiso o disponibilidad.","success_criteria":["usa I need + objeto","usa I need to + verbo","usa Do you have o Can I","mensaje claro"],"prompt":"Graba tres mini situaciones: pedir agua, pedir un cargador y pedir un billete. Incluye una pregunta de permiso o disponibilidad.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T10-L02"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["expresar necesidades concretas","distinguir need + objeto y need to + acción","hacer peticiones funcionales"],"retry":"Si añades o quitas to incorrectamente, identifica si después viene una cosa o una acción."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"En una situación urgente usa frases cortas y directas: I am lost, I can''t find my hotel, I need a doctor. Describe el problema y di qué ayuda necesitas. Para pedir una acción usa Please call... o Can you help me?. Si hay peligro inmediato, busca servicios de emergencia locales y no dependas solo de la aplicación.","communication_goal":"Comunicar un problema básico, describir una necesidad urgente y pedir la ayuda adecuada.","language_focus":{"grammar":["I have a problem","I need a doctor/police/help","I lost...","I can''t...","Where is...?","Please call..."],"function":"basic emergency communication"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"I need a doctor.","word":"doctor","meaning_es":"médico/a"},{"english":"Please call the police.","word":"police","meaning_es":"policía"},{"english":"Call an ambulance.","word":"ambulance","meaning_es":"ambulancia"},{"english":"My arm hurts.","word":"hurt","meaning_es":"doler/herir"},{"english":"I am lost.","word":"lost","meaning_es":"perdido/a"},{"english":"Are you safe?","word":"safe","meaning_es":"seguro/a"}],"dialogue":[{"speaker":"Helper","english":"Are you okay?","spanish":"¿Estás bien?"},{"speaker":"Traveler","english":"I am lost, and I can''t find my hotel.","spanish":"Estoy perdido y no encuentro mi hotel."},{"speaker":"Helper","english":"Do you have the address?","spanish":"¿Tienes la dirección?"},{"speaker":"Traveler","english":"Yes, but my phone is broken. Can you help me?","spanish":"Sí, pero mi teléfono está roto. ¿Puede ayudarme?"},{"speaker":"Helper","english":"Yes. Let''s go to the help desk.","spanish":"Sí. Vamos al mostrador de ayuda."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I am lost. I need help.","focus":"lost y need help"},{"text":"My phone is broken.","focus":"phone is broken"},{"text":"Please call the police.","focus":"please call"}],"tip_es":"Practica con voz clara y volumen suficiente; en una urgencia la otra persona necesita entenderte rápidamente."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Helper","english":"Are you okay?","spanish":"¿Estás bien?"},{"speaker":"Traveler","english":"I am lost, and I can''t find my hotel.","spanish":"Estoy perdido y no encuentro mi hotel."},{"speaker":"Helper","english":"Do you have the address?","spanish":"¿Tienes la dirección?"},{"speaker":"Traveler","english":"Yes, but my phone is broken. Can you help me?","spanish":"Sí, pero mi teléfono está roto. ¿Puede ayudarme?"},{"speaker":"Helper","english":"Yes. Let''s go to the help desk.","spanish":"Sí. Vamos al mostrador de ayuda."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"Finding help","text":"A traveler is lost in a city. Her phone is broken, but she has the hotel address. A helper takes her to an information desk. The staff member calls the hotel and helps her find a safe route.","glossary":[{"term":"urgent help","meaning_es":"ayuda urgente"},{"term":"hotel address","meaning_es":"dirección del hotel"},{"term":"safe route","meaning_es":"ruta segura"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Necesitas ayuda en la calle, en un edificio o durante un viaje.","communication_goal":"Comunicar un problema básico, describir una necesidad urgente y pedir la ayuda adecuada.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"Practica una situación ficticia de pérdida o problema. La IA preguntará qué ocurre y qué ayuda necesitas.","scenario":"Asking for help after losing your way or an item.","ai_language":"English; prioritize safety and concise communication","prompt":"Practica una situación ficticia de pérdida o problema. La IA preguntará qué ocurre y qué ayuda necesitas.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T10-L03"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba dos situaciones ficticias: estar perdido y tener un objeto roto. Explica el problema y pide una solución.","success_criteria":["usa frases cortas","describe el problema","pide ayuda adecuada","mantiene la calma y claridad"],"prompt":"Graba dos situaciones ficticias: estar perdido y tener un objeto roto. Explica el problema y pide una solución.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T10-L03"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["comunicar una necesidad urgente","describir un problema concreto","pedir ayuda adecuada"],"retry":"Si la situación te parece difícil, practica primero tres frases clave: I am lost, I have a problem, I need help."},"review":null}'::jsonb,7);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'explanation','Entiende la idea','{"explanation_es":"Resolver una situación sigue un ciclo práctico: saluda, explica el problema, di qué necesitas, escucha la solución y confirma si entendiste. Usa Could you explain/repeat...? cuando necesitas apoyo y I understand now cuando la explicación funciona. Si no entendiste, pide una repetición en lugar de adivinar.","communication_goal":"Usar inglés funcional para pedir ayuda, explicar necesidades y resolver una situación cotidiana completa.","language_focus":{"grammar":["Can/Could you...?","I need...","I need to...","Where can I...?","There is a problem with...","thank you/you''re welcome"],"function":"integrated everyday problem solving"}}'::jsonb,1);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'examples','Mira ejemplos','{"examples":[{"english":"We need a solution.","word":"solution","meaning_es":"solución"},{"english":"Is anyone available to help?","word":"available","meaning_es":"disponible"},{"english":"Let me explain the problem.","word":"explain","meaning_es":"explicar"},{"english":"Could you repeat that?","word":"repeat","meaning_es":"repetir"},{"english":"I understand now.","word":"understand","meaning_es":"entender"},{"english":"The problem is resolved.","word":"resolved","meaning_es":"resuelto"}],"dialogue":[{"speaker":"Student","english":"Excuse me. I have a problem with this form.","spanish":"Disculpe. Tengo un problema con este formulario."},{"speaker":"Staff","english":"What do you need?","spanish":"¿Qué necesita?"},{"speaker":"Student","english":"I don''t understand question four. Could you explain it, please?","spanish":"No entiendo la pregunta cuatro. ¿Podría explicarla, por favor?"},{"speaker":"Staff","english":"Sure. You need to write your address here.","spanish":"Claro. Debe escribir su dirección aquí."},{"speaker":"Student","english":"Thank you. Could you repeat the last part?","spanish":"Gracias. ¿Podría repetir la última parte?"},{"speaker":"Staff","english":"Of course. Write your address here.","spanish":"Por supuesto. Escriba su dirección aquí."}]}'::jsonb,2);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'pronunciation','Escucha y pronuncia','{"targets":[{"text":"I have a problem with this form.","focus":"problem with this form"},{"text":"Could you explain it, please?","focus":"could you explain it"},{"text":"I understand now.","focus":"understand now"}],"tip_es":"La estrategia más importante es no bloquearte: explica, pide repetición y confirma."}'::jsonb,3);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'listening','Comprende al escuchar','{"dialogue":[{"speaker":"Student","english":"Excuse me. I have a problem with this form.","spanish":"Disculpe. Tengo un problema con este formulario."},{"speaker":"Staff","english":"What do you need?","spanish":"¿Qué necesita?"},{"speaker":"Student","english":"I don''t understand question four. Could you explain it, please?","spanish":"No entiendo la pregunta cuatro. ¿Podría explicarla, por favor?"},{"speaker":"Staff","english":"Sure. You need to write your address here.","spanish":"Claro. Debe escribir su dirección aquí."},{"speaker":"Student","english":"Thank you. Could you repeat the last part?","spanish":"Gracias. ¿Podría repetir la última parte?"},{"speaker":"Staff","english":"Of course. Write your address here.","spanish":"Por supuesto. Escriba su dirección aquí."}],"audio_text":null}'::jsonb,4);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'reading','Lee con contexto','{"title":"A solved problem","text":"A student has a problem with a form. She does not understand question four, so she asks a staff member to explain it. The staff member gives an example and repeats the instruction. The student understands and finishes the form.","glossary":[{"term":"solved problem","meaning_es":"problema resuelto"},{"term":"form","meaning_es":"formulario"},{"term":"instruction","meaning_es":"instrucción"}]}'::jsonb,5);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'conversation','Usa lo aprendido','{"situation":"Te enfrentas a una necesidad en trabajo, estudio, viaje, compras o un lugar público.","communication_goal":"Usar inglés funcional para pedir ayuda, explicar necesidades y resolver una situación cotidiana completa.","activities":[{"id":"a8","type":"ai_roleplay","skill":"conversation","instruction":"La IA presentará un problema en un formulario, tienda, viaje o trabajo. Resuelve la situación sin abandonar el inglés.","scenario":"A flexible everyday help conversation.","ai_language":"English; use Spanish only as a last-resort safety support","prompt":"La IA presentará un problema en un formulario, tienda, viaje o trabajo. Resuelve la situación sin abandonar el inglés.","difficulty":null,"estimated_seconds":180,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T10-L04"},{"id":"a9","type":"transfer_mission","skill":"production","instruction":"Graba tres mini diálogos de 30 segundos: uno en trabajo/estudio, uno en viaje y uno en una tienda o lugar público.","success_criteria":["explica un problema","pide una solución","pide repetición si hace falta","confirma que entiende","usa cortesía"],"prompt":"Graba tres mini diálogos de 30 segundos: uno en trabajo/estudio, uno en viaje y uno en una tienda o lugar público.","difficulty":null,"estimated_seconds":120,"target_error":null,"evaluation":{"accepted_answers":[],"open_response":true,"status":"pending_rubric"},"feedback_correct":null,"feedback_incorrect":null,"hint":null,"source_lesson_id":"A1-M3-T10-L04"}]}'::jsonb,6);
insert into public.lesson_sections(lesson_id,section_type,title,content,sort_order) values(v_lesson_id,'review','Repasa y demuestra','{"mastery_criteria":{"minimum_score":0.8,"must_demonstrate":["explicar un problema","pedir ayuda o aclaración","comprender y confirmar una solución","mantener una conversación funcional"],"retry":"Si el resultado es menor de 80%, practica la secuencia problema + necesidad + petición + confirmación en tres contextos distintos."},"review":null}'::jsonb,7);
